(window.OFFY_GBOOK_PACKS=window.OFFY_GBOOK_PACKS||{})[2]={"g3-2-001":{"t":["คำเติมท้ายบอกทิศทาง: —面 (上面 / 下面 / 前面 / 后面 / 里面 / 外面)","Position suffix —面 (上面 / 下面 / 前面 / 后面 / 里面 / 外面)","后缀：面","Hậu tố phương vị —面 (上面 / 下面 / 前面 / 后面 / 里面 / 外面)","接尾辞「—面」（上面・下面・前面・后面・里面・外面）"],"f":["方位词 + 面（上面 / 下面 / 前面 / 后面 / 里面 / 外面）","名词 +（的）+ 上面 / 下面 / 前面 / 后面 / 里面 / 外面"],"why":["—面 เติมท้ายคำบอกทิศทาง (上, 下, 前, 后, 里, 外) เพื่อสร้างคำนามบอกตำแหน่ง 2 พยางค์ที่ยืนเป็นประธานหรือกรรมเดี่ยว ๆ ได้อย่างอิสระ (เช่น 外面下雨了, 里面很热) · ต่างจากคำพยางค์เดียว (上, 里) อย่างไร? คำ 2 พยางค์อย่าง 上面/里面 ใช้เดี่ยว ๆ ได้เลยและคั่นด้วย 的 หลังคำนามได้ (桌子的上面) แต่คำพยางค์เดียวต้องเกาะติดคำนามเสมอ (桌子上 ห้ามพูด 桌子的上!) · ข้อควรระวัง: หน้าคำว่า 左 และ 右 นิยมใช้ —边 (左边, 右边) ไม่ค่อยพูด 左面/右面 ในภาษาพูดทั่วไป","—面 attaches to direction morphemes (上, 下, 前, 后, 里, 外) to form standalone 2-syllable location nouns (外面下雨了, 里面很热). · Unlike 1-syllable 上/里, 2-syllable forms can stand alone as subject/object and allow 的 after a noun (桌子的上面, whereas 桌子的上 is wrong!). · Caution: for left/right, everyday Chinese uses 左边 / 右边 rather than 左面 / 右面.","“—面”加在“上、下、前、后、里、外”后构成双音节方位词，可独立作主语、宾语或状语（外面下雨了、里面很热）。 · 与单音节方位词区别：双音节可加“的”（桌子的上面），单音节不能加“的”（不说“桌子的上”）。 · 注意：左右日常多说“左边、右边”。","—面 thêm sau 上, 下, 前, 后, 里, 外 tạo danh từ phương vị 2 âm tiết đứng độc lập được (外面下雨了, 里面很热). · Khác loại 1 âm tiết: loại 2 âm tiết có thể có 的 (桌子的上面), còn loại 1 âm tiết thì KHÔNG (không nói 桌子的上). · Lưu ý: trái/phải hay dùng 左边 / 右边.","「—面」は「上・下・前・后・里・外」に付いて独立して使える2音節の方位詞を作る（外面下雨了・里面很热）。 · 1音節と違い名詞との間に「的」を入れられる（桌子的上面／「桌子的上」は不可）。 · 左右は日常では「左边・右边」を使う。"],"use":[{"ok":true,"zh":"外面下雨了，我们在里面吧。","fix":"","py":"Wàimiàn xià yǔ le, wǒmen zài lǐmiàn ba.","tr":["ข้างนอกฝนตกแล้ว พวกเราอยู่ข้างในกันเถอะ","It's raining outside; let's stay inside.","Bên ngoài mưa rồi, chúng ta ở bên trong đi.","外は雨が降ってきたので、中にいましょう。"],"h":["ใช้คำ 2 พยางค์ (外面 / 里面) ยืนเดี่ยวเป็นประธานหรือหลัง 在 ได้ทันที","Use 2-syllable 外面 / 里面 standalone as subject or after 在","双音节“外面、里面”可独立作主语或跟在“在”后","Dùng 外面 / 里面 đứng độc lập làm chủ ngữ hoặc sau 在","2音節の「外面・里面」は単独で主語や「在」の後ろに置ける"],"w":["ทำได้เพราะ 外面 และ 里面 เป็นคำนามสถานที่ 2 พยางค์สมบูรณ์ จึงยืนเดี่ยวโดยไม่ต้องมีคำนามอ้างอิงนำหน้า","Works because 外面 and 里面 are complete 2-syllable place nouns that need no reference noun in front.","“外面、里面”为双音节方位词，能独立充当主语或处所宾语。","Đúng vì 外面 và 里面 là danh từ phương vị 2 âm tiết độc lập.","「外面・里面」は2音節の方位詞なので単独で場所を表せる。"],"ref":"HSK 3.0 g3-2-001"},{"ok":true,"zh":"学校前面有一个公交车站。","fix":"","py":"Xuéxiào qiánmiàn yǒu yī ge gōngjiāo chēzhàn.","tr":["ด้านหน้าโรงเรียนมีป้ายรถเมล์อยู่ป้ายหนึ่ง","There is a bus stop in front of the school.","Phía trước trường có một bến xe buýt.","学校の前にバス停が一つあります。"],"h":["วาง คำนาม + 前面 / 后面 / 上面 / 下面 เป็นตำแหน่งหน้า 有","Place Noun + 前面/后面/上面/下面 directly before 有","“名词＋前面／后面／上面／下面”作处所主语","Danh từ + 前面 / 后面 / 上面 / 下面 đứng trước 有","「名詞＋前面／后面／上面／下面」を場所主語にする"],"w":["ทำได้ทั้งแบบไม่ใส่ 的 (学校前面) และใส่ 的 (学校的前面) ซึ่งแบบละ 的 จะกระชับและเป็นธรรมชาติที่สุด","Works both without 的 (学校前面) and with 的 (学校的前面); omitting 的 is tighter and very natural.","“学校前面”简洁自然，也可加“的”说“学校的前面”。","Đúng cả khi bỏ 的 (学校前面) lẫn có 的 (学校的前面).","「的」を省いた「学校前面」が簡潔で自然（「学校的前面」も可）。"],"ref":"HSK 3.0 g3-2-001"},{"ok":false,"zh":"书在桌子的上。","fix":"书在桌子的上面。","py":"Shū zài zhuōzi de shàngmiàn.","tr":["หนังสืออยู่บนโต๊ะ","The book is on the table.","Sách ở trên mặt bàn.","本は机の上にあります。"],"h":["ถ้าใส่ 的 คั่น ต้องใช้รูปเต็ม 2 พยางค์ (上面) ห้ามใช้ 上 ตัวเดียว","With 的, you MUST use 2-syllable 上面 — never bare 上","加“的”后必须用双音节“上面”，不能用单音节“上”","Đã có 的 thì bắt buộc dùng 2 âm tiết 上面, không dùng 上 lẻ","「的」を入れるなら必ず2音節の「上面」（裸の「上」は不可）"],"w":["ไม่ได้ เพราะคำบอกทิศพยางค์เดียว (上, 下, 里) ห้ามมี 的 คั่นกลาง (ต้องเลือก 桌子上 หรือ 桌子的上面 อย่างใดอย่างหนึ่ง)","Wrong because 1-syllable position words cannot take 的 — choose either 桌子上 OR 桌子的上面.","不行，单音节方位词前不能加“的”，要么说“桌子上”，要么说“桌子的上面”。","Không được vì phương vị 1 âm tiết không đi sau 的; chọn 桌子上 hoặc 桌子的上面.","1音節方位詞の前には「的」を置けない。「桌子上」か「桌子的上面」にする。"],"ref":"HSK 3.0 g3-2-001 · g3-1-003"},{"ok":false,"zh":"外下雨了。","fix":"外面下雨了。","py":"Wàimiàn xià yǔ le.","tr":["ข้างนอกฝนตกแล้ว","It's raining outside.","Bên ngoài mưa rồi.","外は雨が降ってきました。"],"h":["ห้ามใช้พยางค์เดียว 外 / 里 ยืนเดี่ยวเป็นประธานประโยค","Never use bare 1-syllable 外 / 里 alone as a sentence subject","单音节“外、里”不能独立作主语","Không dùng 外 / 里 đứng lẻ làm chủ ngữ","1音節の「外・里」を単独で主語にできない"],"w":["ไม่ได้ เพราะคำบอกทิศพยางค์เดียว (上, 下, 里, 外) ต้องเกาะหลังคำนามเสมอ ถ้าจะยืนเดี่ยวเป็นประธานต้องเติม 面 หรือ 边 เป็น 外面 / 外边","Wrong because 1-syllable 外/里 must attach to a noun; to stand alone as subject, add 面 or 边 → 外面 / 外边.","不行，单音节方位词不能独立作主语，必须加“面”或“边”：外面下雨了。","Không được vì 外/里 đứng một mình không làm chủ ngữ được; phải thêm 面 hoặc 边.","1音節の「外・里」は単独で主語になれず、「外面／外边」にする必要がある。"],"ref":"HSK 3.0 g3-2-001"}],"ex":[["外面下雨了。","Wàimiàn xià yǔ le.","ข้างนอกฝนตกแล้ว","It's raining outside.","Bên ngoài mưa rồi.","外は雨が降ってきました。","外面"],["书包里面有一本书。","Shūbāo lǐmiàn yǒu yī běn shū.","ข้างในกระเป๋านักเรียนมีหนังสือหนึ่งเล่ม","There is a book inside the schoolbag.","Bên trong cặp sách có một cuốn sách.","かばんの中に本が1冊あります。","里面"],["桌子上面有一杯咖啡。","Zhuōzi shàngmiàn yǒu yī bēi kāfēi.","บนโต๊ะมีกาแฟอยู่หนึ่งแก้ว","There is a cup of coffee on the table.","Trên bàn có một cốc cà phê.","机の上にコーヒーが1杯あります。","上面"],["学校前面有一个商场。","Xuéxiào qiánmiàn yǒu yī ge shāngchǎng.","หน้าโรงเรียนมีห้างสรรพสินค้าอยู่แห่งหนึ่ง","There is a shopping mall in front of the school.","Trước trường có một trung tâm thương mại.","学校の向かい（前）にモールがあります。","前面"],["他在我后面。","Tā zài wǒ hòumiàn.","เขาอยู่ข้างหลังฉัน","He is behind me.","Anh ấy ở phía sau tôi.","彼は私の後ろにいます。","后面"]],"err":[["书在桌子的上。","书在桌子的上面。","มี 的 คั่นต้องใช้รูปเต็ม 上面 (หรือตัด 的 เป็น 桌子上)","After 的 use full 上面 (or drop 的 → 桌子上).","加“的”后须用双音节“上面”（或省“的”说“桌子上”）。","Sau 的 phải dùng 上面 (hoặc bỏ 的 thành 桌子上).","「的」の後には2音節の「上面」を使う。"],["外下雨了。","外面下雨了。","ยืนเดี่ยวเป็นประธานต้องใช้รูป 2 พยางค์ (外面 / 外边)","Standalone subjects need 2-syllable 外面 / 外边.","独立作主语须用双音节“外面”。","Đứng độc lập làm chủ ngữ phải dùng 外面.","単独主語は2音節の「外面」にする。"]],"rel":["g3-1-003","g3-1-002","g3-2-002"]},"g3-2-002":{"t":["คำบอกตำแหน่งซ้าย–ขวา: 左 / 右 (左边 / 右边)","Position nouns: 左 (left) & 右 (right)","方位名词：左、右","Danh từ phương vị: 左 / 右 (trái / phải)","方位詞：左・右（左边・右边）"],"f":["在 +（名词/代词的）+ 左边 / 右边（我在他左边 / 洗手间在右边）","往 + 左 / 右 + 走 / 看（往左走 / 往右看）"],"why":["左 (ซ้าย) และ 右 (ขวา) ใช้บอกตำแหน่งและทิศทางได้ 2 แบบชัดเจน: (1) บอกตำแหน่งที่ตั้ง (อยู่ฝั่งซ้าย/ขวา) → เติม 边 เป็น 左边 / 右边 เสมอ เช่น 洗手间在右边, 小王在我左边 (2) บอกทิศทางที่เดินหรือมองไป → ใช้พยางค์เดียว 左 / 右 หลังบุพบท 往 ได้เลย เช่น 往左走 (เดินไปทางซ้าย), 往右看 (มองไปทางขวา) · ข้อควรระวัง: (1) ห้ามใช้ 左 หรือ 右 พยางค์เดียวตามหลัง 在 ตรง ๆ (洗手间在右 ผิด! ต้องเป็น 洗手间在右边) (2) บอกว่า 'ด้านซ้ายของ A' วาง A ขึ้นก่อนเสมอ: 学校的左边 (ตรงข้ามกับภาษาไทย!)","左 (left) and 右 (right) follow a clean 2-way rule: (1) For static location ('on the left/right'), attach 边 → 左边 / 右边 (洗手间在右边, 小王在我左边). (2) For direction of movement/gaze after 往, use bare 左 / 右 (往左走 'go left', 往右看 'look right'). · Cautions: (1) Never put bare 左/右 directly after 在 (never 洗手间在右). (2) Put the reference landmark FIRST: 学校左边.","“左、右”用法分工明确：（1）表示所处位置时须带“边”用“左边、右边”（洗手间在右边、他在我左边）；（2）跟在“往”后指移动或观看方向时可直接用单音节“左、右”（往左走、往右看）。 · 注意：不能说“在左／在右”；参照物放在前面（学校左边）。","左 (trái) và 右 (phải) có 2 cách dùng rõ ràng: (1) Chỉ vị trí dùng 左边 / 右边 (洗手间在右边, 他在我左边); (2) Chỉ hướng đi/nhìn sau 往 dùng 左 / 右 đơn âm tiết (往左走, 往右看). · Lưu ý: không nói 在左 / 在右; mốc địa điểm luôn đặt TRƯỚC (学校左边).","「左・右」の使い分け：（1）場所・位置を表すときは「左边・右边」（洗手间在右边・他在我左边）。（2）「往」の後ろで方向を表すときは1音節のまま「往左走・往右看」。 · 注意：「在左／在右」とは言えず、基準物は前に置く（学校左边）。"],"use":[{"ok":true,"zh":"洗手间在右边。","fix":"","py":"Xǐshǒujiān zài yòubian.","tr":["ห้องน้ำอยู่ทางขวามือ","The restroom is on the right.","Nhà vệ sinh ở bên phải.","トイレは右側にあります。"],"h":["บอกตำแหน่งที่ตั้งหลัง 在 ใช้ 左边 / 右边","Use 左边 / 右边 after 在 for location","表位置跟在“在”后用“左边／右边”","Chỉ vị trí sau 在 dùng 左边 / 右边","所在を表す「在」の後ろは「左边／右边」"],"w":["ทำได้เพราะหลังกริยา 在 ต้องการคำนามสถานที่สมบูรณ์ 2 พยางค์ (左边 / 右边) จะได้ความหมาย 'อยู่ฝั่งซ้าย/ขวา'","Works because 在 requires a complete 2-syllable place noun (左边 / 右边).","“在”后接双音节“左边／右边”，完整准确。","Đúng vì sau 在 cần danh từ phương vị 2 âm tiết 左边 / 右边.","「在」の後ろには2音節の「左边／右边」を置くのが正しい。"],"ref":"HSK 3.0 g3-2-002"},{"ok":true,"zh":"往前走，再往左走。","fix":"","py":"Wǎng qián zǒu, zài wǎng zuǒ zǒu.","tr":["เดินตรงไปข้างหน้า แล้วค่อยเดินไปทางซ้าย","Walk forward, then go left.","Đi thẳng về phía trước, rồi rẽ trái.","まっすぐ歩いて、それから左へ進んでください。"],"h":["บอกทิศทางหลังบุพบท 往 ใช้พยางค์เดียว 左 / 右 ได้เลย","After direction preposition 往, use bare 左 / 右 directly","介词“往”后指方向可直接用单音节“往左／往右”","Sau giới từ chỉ hướng 往 dùng thẳng 左 / 右","方向の前置詞「往」の後ろは1音節で「往左／往右」"],"w":["ทำได้และสั้นกระชับเป็นธรรมชาติที่สุดในการบอกทาง: 往左走 (เดินไปทางซ้าย), 往右走 (เดินไปทางขวา), 往左看 (มองไปทางซ้าย)","Works concisely as the standard Chinese way to give directions: 往左走, 往右走, 往左看.","指路时说“往左走、往右走、往右看”简洁地道。","Đúng và gọn nhất khi chỉ đường: 往左走, 往右走.","道案内では「往左走・往右走・往左看」が簡潔で最も自然。"],"ref":"HSK 3.0 g3-2-002 · g3-2-022"},{"ok":false,"zh":"洗手间在右。","fix":"洗手间在右边。","py":"Xǐshǒujiān zài yòubian.","tr":["ห้องน้ำอยู่ทางขวามือ","The restroom is on the right.","Nhà vệ sinh ở bên phải.","トイレは右側にあります。"],"h":["ห้ามวาง 左 / 右 ตัวเดียวโดด ๆ หลัง 在","NEVER put bare 左 / 右 directly after 在","不能单说“在左／在右”，须加“边”","Không nói 在左 / 在右 đứng lẻ, phải thêm 边","「在左／在右」は不可、必ず「边」を付ける"],"w":["ไม่ได้ เพราะ 左 และ 右 พยางค์เดียวไม่ยืนเป็นคำนามสถานที่หลัง 在 โดยลำพัง ต้องเติม 边 เป็น 在左边 / 在右边","Wrong because bare 左/右 cannot stand alone as a place noun after 在 — add 边 → 在左边 / 在右边.","不行，“在”后必须用双音节“左边／右边”，不能说“在右”。","Không được vì 左/右 đứng lẻ không làm nơi chốn sau 在 được; phải nói 在右边.","1音節の「左・右」は「在」の後ろに単独で置けない。必ず「在右边」にする。"],"ref":"HSK 3.0 g3-2-002"},{"ok":false,"zh":"右边学校有一家药店。","fix":"学校右边有一家药店。","py":"Xuéxiào yòubian yǒu yī jiā yàodiàn.","tr":["ทางขวาของโรงเรียนมีร้านขายยาอยู่ร้านหนึ่ง","To the right of the school is a pharmacy.","Bên phải trường có một hiệu thuốc.","学校の右側に薬局が一軒あります。"],"h":["ห้ามวาง 左边 / 右边 ไว้หน้าสถานที่อ้างอิงแบบภาษาไทย","Never put 左边 / 右边 before the reference landmark like Thai","参照物必须在“左边／右边”前面（学校右边）","Không đặt 左边/右边 trước mốc địa điểm như tiếng Việt/Thái","基準となる場所を必ず「左边／右边」の前に置く"],"w":["ไม่ได้ เพราะภาษาไทยพูด 'ขวา + ของโรงเรียน' แต่ภาษาจีนต้องเอาสถานที่อ้างอิง (学校) ขึ้นหน้า แล้วตามด้วย 右边 เสมอ: 学校右边","Wrong because Thai puts 'right of school', whereas Chinese ALWAYS puts the landmark first: 学校右边.","不行，汉语方位短语须将参照物放前面：学校右边（或学校的右边）。","Không được vì tiếng Trung luôn đặt mốc địa điểm lên trước: 学校右边.","基準物「学校」を前に置き「学校右边」（または「学校的右边」）とする。"],"ref":"HSK 3.0 g3-2-002 · g3-1-034"}],"ex":[["洗手间在右边。","Xǐshǒujiān zài yòubian.","ห้องน้ำอยู่ทางขวา","The restroom is on the right.","Nhà vệ sinh ở bên phải.","トイレは右側にあります。","右边"],["小王在我左边。","Xiǎo Wáng zài wǒ zuǒbian.","เสี่ยวหวังอยู่ทางซ้ายของฉัน","Xiao Wang is on my left.","Tiểu Vương ở bên trái tôi.","王さんは私の左側にいます。","左边"],["学校右边有一家药店。","Xuéxiào yòubian yǒu yī jiā yàodiàn.","ทางขวาของโรงเรียนมีร้านขายยาหนึ่งร้าน","To the right of the school there is a pharmacy.","Bên phải trường có một hiệu thuốc.","学校の右側に薬局が1軒あります。","右边"],["请往左走。","Qǐng wǎng zuǒ zǒu.","กรุณาเดินไปทางซ้ายครับ/ค่ะ","Please go left.","Xin hãy đi về bên trái.","左へお進みください。","左"],["你看右边的那个人。","Nǐ kàn yòubian de nàge rén.","คุณดูคนทางขวามือคนนั้นสิ","Look at that person on the right.","Bạn nhìn người ở bên phải kia kìa.","右側のあの人を見てください。","右边"]],"err":[["洗手间在右。","洗手间在右边。","บอกตำแหน่งหลัง 在 ต้องเติม 边 เป็น 在右边 / 在左边","After 在, always add 边 (在右边 / 在左边).","“在”后须说“在右边／在左边”。","Sau 在 luôn dùng 在右边 / 在左边.","「在」の後ろは必ず「在右边／在左边」。"],["右边学校有一家药店。","学校右边有一家药店。","วางสถานที่อ้างอิง (学校) ไว้หน้า 右边 เสมอ","Put the landmark (学校) before 右边.","参照物放前面：学校右边。","Đặt mốc địa điểm 学校 trước 右边.","基準物の「学校」を「右边」の前に置く。"]],"rel":["g3-2-001","g3-2-022","g3-1-003"]},"g3-2-003":{"t":["การซ้ำคำกริยา (动词重叠): AA / A一A / A了A / ABAB","Verb Reduplication (动词重叠): AA / A一A / A了A / ABAB","词类·动词重叠：AA、A一A、A了A、ABAB","Lặp động từ (动词重叠): AA / A一A / A了A / ABAB","動詞の重ね型（动词重叠）：AA・A一A・A了A・ABAB"],"f":["单音节：AA（看看）/ A一A（看一看）/ A了A（看了看，已发生）","双音节：ABAB（休息休息 / 介绍介绍，绝不是 AABB！）"],"why":["การซ้ำคำกริยาในภาษาจีนสื่อความหมายว่า 'ทำแป๊บเดียว / ลองทำดูหน่อย / ทำแบบสบาย ๆ ไม่เป็นทางการ' (คล้ายเติม 一下) ทำให้น้ำเสียงสุภาพและเป็นกันเองมาก · รูปแบบแบ่งตามจำนวนพยางค์: (1) กริยา 1 พยางค์: 看看, 看一看 (อนาคต/ชวน), 看了看 (ทำไปแล้วแป๊บหนึ่ง) (2) กริยา 2 พยางค์: ซ้ำทั้งคำเป็น ABAB เช่น 休息休息 (พักสักหน่อย), 介绍介绍 (แนะนำหน่อย), 运动运动 (ออกกำลังกายสักหน่อย) · ข้อควรระวังเด็ดขาด 3 ข้อ: (1) กริยา 2 พยางค์ต้องซ้ำแบบ ABAB เท่านั้น ห้ามซ้ำแบบคุณศัพท์ AABB (休休息息 ผิด!) (2) ห้ามใช้กับกริยาสภาวะ (是, 有, 认识, 知道, 喜欢) (3) ห้ามใส่ 正在 หรือ 一下 ซ้ำซ้อนกับกริยาที่ซ้ำอยู่แล้ว (看看一下 ผิด!)","Verb reduplication conveys 'briefly / casually / give it a try' (similar to 一下) and makes requests sound friendly and polite. · Forms by length: (1) 1-syllable verbs: AA (看看), A一A (看一看), and past A了A (看了看); (2) 2-syllable verbs: ALWAYS ABAB (休息休息, 介绍介绍). · Three strict cautions: (1) NEVER use AABB for verbs (休休息息 is wrong — AABB is for adjectives!). (2) Never reduplicate stative verbs (是, 有, 认识, 知道, 喜欢). (3) Never stack 一下 or 正在 onto a reduplicated verb (never 看看一下).","动词重叠表示动作时间短、尝试一下或语气轻松委婉（类似“一下”）。 · 形式：（1）单音节：AA（看看）、A一A（看一看）、A了A（看了看，表已发生）；（2）双音节：ABAB（休息休息、介绍介绍）。 · 三条铁律：（1）双音节动词只能 ABAB，绝不能 AABB（那是形容词重叠）；（2）静态动词（是、有、认识、喜欢）不能重叠；（3）重叠后不能再加“一下”或“正在”。","Lặp động từ biểu thị làm nhanh/thử một chút/nhẹ nhàng (giống 一下). · Dạng thức: (1) 1 âm tiết: AA (看看), A一A (看一看), A了A (看了看 — đã làm); (2) 2 âm tiết: LUÔN là ABAB (休息休息, 介绍介绍). · 3 lưu ý: (1) Không dùng AABB cho động từ; (2) Không lặp động từ trạng thái (是, 有, 认识, 喜欢); (3) Không thêm 一下 hay 正在 chung với động từ lặp.","動詞の重ね型は「ちょっと〜してみる・軽く〜する」（「一下」に近い）を表し、口調を柔らかくする。 · 形：（1）1音節は AA（看看）・A一A（看一看）・過去は A了A（看了看）、（2）2音節は必ず ABAB（休息休息・介绍介绍）。 · 3大注意：（1）動詞に AABB は不可（形容詞専用）。（2）状態動詞（是・有・认识・喜欢）は重ねない。（3）「一下」や「正在」と重ねない。"],"use":[{"ok":true,"zh":"你累了，休息休息吧。","fix":"","py":"Nǐ lèi le, xiūxi xiūxi ba.","tr":["คุณเหนื่อยแล้ว พักผ่อนสักหน่อยเถอะ","You're tired — take a little rest.","Bạn mệt rồi, nghỉ ngơi chút đi.","疲れたでしょう、ちょっと休んでください。"],"h":["กริยา 2 พยางค์ซ้ำแบบ ABAB (休息休息 / 介绍介绍)","2-syllable verbs reduplicate as ABAB (休息休息 / 介绍介绍)","双音节动词重叠用 ABAB（休息休息、介绍介绍）","Động từ 2 âm tiết lặp kiểu ABAB (休息休息)","2音節動詞は ABAB 型で重ねる（休息休息）"],"w":["ทำได้เพราะ 休息 เป็นกริยาการกระทำ 2 พยางค์ที่ทำได้ชั่วคราว การซ้ำเป็น 休息休息 + 吧 ฟังนุ่มนวลอบอุ่นมาก","Works warmly because 休息 is a 2-syllable dynamic verb, and ABAB + 吧 makes the advice gentle.","“休息”是双音节动作动词，用 ABAB 重叠（休息休息）语气亲切自然。","Đúng vì 休息 là động từ 2 âm tiết, lặp ABAB kèm 吧 nghe rất nhẹ nhàng.","「休息」は2音節の動作動詞なので ABAB 型で重ねると優しい勧めになる。"],"ref":"HSK 3.0 g3-2-003"},{"ok":true,"zh":"他看了看手表，就走了。","fix":"","py":"Tā kànle kàn shǒubiǎo, jiù zǒu le.","tr":["เขามองดูนาฬิกาข้อมือแวบหนึ่ง แล้วก็เดินไปเลย","He glanced at his watch and left.","Anh ấy liếc nhìn đồng hồ rồi đi ngay.","彼は腕時計をちらっと見て、すぐ立ち去りました。"],"h":["การกระทำสั้น ๆ ที่ 'เกิดขึ้นไปแล้ว' ใช้ A了A (看了看 / 听了听)","Use A了A (看了看 / 听了听) for a brief action that ALREADY happened","已发生的短暂动作用“A了A”（看了看、想了想）","Hành động ngắn ĐÃ xảy ra dùng A了A (看了看)","すでに起きた短い動作は「A了A」（看了看・想了想）"],"w":["ทำได้เพราะ 看了看 ระบุชัดว่ามองเพียงแวบเดียวและเกิดขึ้นไปแล้วในอดีต (ต่างจาก 看看 / 看一看 ที่มักใช้กับอนาคตหรือชวนให้ทำ)","Works cleanly because 看了看 signals a quick past glance (whereas 看看/看一看 are for requests or future actions).","“看了看”表示已经完成的短暂动作，常接后续动作。","Đúng vì 看了看 diễn tả động tác ngắn đã xảy ra trong quá khứ.","「看了看」は過去にさっと行った動作を表し、次の行動につながる。"],"ref":"HSK 3.0 g3-2-003"},{"ok":false,"zh":"你休休息息吧。","fix":"你休息休息吧。","py":"Nǐ xiūxi xiūxi ba.","tr":["คุณพักผ่อนสักหน่อยเถอะ","Take a little rest.","Bạn nghỉ ngơi một chút đi.","ちょっと休んでください。"],"h":["ห้ามซ้ำกริยา 2 พยางค์แบบ AABB (AABB ใช้กับคำคุณศัพท์เท่านั้น!)","NEVER use AABB for 2-syllable verbs (AABB is for adjectives!)","双音节动词不能用 AABB，必须用 ABAB","Không lặp động từ 2 âm tiết theo kiểu AABB (chỉ dùng ABAB)","2音節動詞に AABB は不可（必ず ABAB）"],"w":["ไม่ได้ เพราะ AABB เป็นรูปแบบซ้ำคำคุณศัพท์ (เช่น 高高兴兴, 漂漂亮亮) ส่วนคำกริยา 2 พยางค์ต้องซ้ำแบบ ABAB เสมอ: 休息休息, 介绍介绍, 学习学习","Wrong because AABB is strictly for adjectives (高高兴兴); 2-syllable verbs ALWAYS use ABAB (休息休息, 介绍介绍).","不行，AABB 是形容词重叠（高高兴兴），动词重叠只能用 ABAB（休息休息）。","Không được vì AABB là của tính từ (高高兴兴), động từ 2 âm tiết bắt buộc dùng ABAB (休息休息).","AABB は形容詞専用（高高兴兴）。2音節動詞は必ず ABAB（休息休息）にする。"],"ref":"HSK 3.0 g3-2-003 · g3-2-009"},{"ok":false,"zh":"你看看一下这本书。","fix":"你看看这本书。","py":"Nǐ kànkan zhè běn shū.","tr":["คุณลองดูหนังสือเล่มนี้หน่อย","Take a look at this book.","Bạn xem thử cuốn sách này đi.","この本をちょっと見てください。"],"h":["ห้ามใช้กริยาซ้ำ (看看) คู่กับ 一下 ซ้ำซ้อนกัน","Never combine a reduplicated verb (看看) with 一下","动词重叠不能再加“一下”（看看一下×）","Không dùng lặp động từ chung với 一下","重ね型（看看）に「一下」を重ねない"],"w":["ไม่ได้ เพราะทั้ง 看看 และ 看一下 ต่างแปลว่า 'ลองดูหน่อย/ดูแป๊บเดียว' เหมือนกัน เลือกใช้อย่างใดอย่างหนึ่งเท่านั้น","Wrong because 看看 and 看一下 already express the exact same 'quick look' meaning — pick ONE, never both.","不行，“看看”和“看一下”语义重复，只能二选一。","Không được vì 看看 và 看一下 trùng nghĩa 'xem một chút'; chỉ chọn một.","「看看」と「看一下」は意味が重複するため、どちらか一方だけ使う。"],"ref":"HSK 3.0 g3-2-003 · g3-1-041"}],"ex":[["你看看这件衣服漂亮不漂亮。","Nǐ kànkan zhè jiàn yīfu piàoliang bù piàoliang.","คุณลองดูสิว่าเสื้อตัวนี้สวยไหม","Take a look at whether this piece of clothing is pretty.","Bạn xem thử chiếc áo này có đẹp không.","この服がきれいかちょっと見てください。","看看"],["你听一听这是什么。","Nǐ tīng yī tīng zhè shì shénme.","คุณลองฟังดูสิว่านี่คือเสียงอะไร","Listen for a moment to what this is.","Bạn nghe thử xem đây là gì.","これが何かちょっと聞いてみてください。","听一听"],["他看了看手表。","Tā kànle kàn shǒubiǎo.","เขามองนาฬิกาข้อมือแวบหนึ่ง","He glanced at his watch.","Anh ấy liếc nhìn đồng hồ.","彼は腕時計をちらっと見ました。","看了看"],["你累了，休息休息吧。","Nǐ lèi le, xiūxi xiūxi ba.","คุณเหนื่อยแล้ว พักสักหน่อยเถอะ","You're tired; take a little rest.","Bạn mệt rồi, nghỉ ngơi chút đi.","疲れたでしょう、少し休んでください。","休息休息"],["请你介绍介绍北京吧。","Qǐng nǐ jièshào jièshào Běijīng ba.","ช่วยเล่าแนะนำเกี่ยวกับปักกิ่งให้ฟังหน่อยสิ","Please tell us a little about Beijing.","Xin bạn giới thiệu đôi chút về Bắc Kinh đi.","北京についてちょっと紹介してください。","介绍介绍"]],"err":[["你休休息息吧。","你休息休息吧。","กริยา 2 พยางค์ซ้ำแบบ ABAB (休息休息) ไม่ใช่ AABB","2-syllable verbs reduplicate as ABAB (休息休息), not AABB.","双音节动词重叠用 ABAB（休息休息），不用 AABB。","Động từ 2 âm tiết lặp ABAB (休息休息), không phải AABB.","2音節動詞は AABB でなく ABAB（休息休息）。"],["你看看一下这本书。","你看看这本书。","ซ้ำกริยา (看看) แล้วห้ามใส่ 一下 ซ้ำซ้อน","Don't add 一下 after a reduplicated verb.","动词重叠后不再加“一下”。","Đã lặp động từ thì không thêm 一下.","動詞を重ねたら「一下」は付けない。"]],"rel":["g3-2-009","g3-1-041","g3-2-005"]},"g3-2-004":{"t":["กริยานำ 可能: อาจจะ / เป็นไปได้ว่า","Modal verb 可能: 'maybe / probably / might'","能愿动词：可能","Động từ năng nguyện 可能: có thể / có lẽ","助動詞「可能」：〜かもしれない・可能性"],"f":["主语 + 可能 + 动词 / 形容词（他可能不来了 / 明天可能下雨）","可能 + 主语 + 动词（可能他忘了）","否定：可能不 / 可能没（也许不）vs 不可能（绝对不会）"],"why":["可能 แปลว่า 'อาจจะ / คงจะ / มีความเป็นไปได้' ใช้คาดเดาเหตุการณ์ที่ไม่แน่ใจ 100% · จุดยืดหยุ่นของ 可能: วางได้ทั้ง 'หลังประธาน' (他可能忘了) และ 'หน้าประธาน' (可能他忘了) · จุดตายที่ต้องแยกความหมายให้ขาดระหว่าง 2 รูปปฏิเสธ: (1) 可能不 / 可能没 = 'อาจจะไม่…' (เดาว่าไม่เกิด เช่น 他可能不来了 = เขาอาจจะไม่มาแล้ว) (2) 不可能 = 'เป็นไปไม่ได้เด็ดขาด!' (มั่นใจ 100% ว่าไม่มีทางเกิด เช่น 这不可能！/ 他不可能忘！) · ระวัง: อย่าใช้ 可能 แทน 可以 ตอนขออนุญาต (ห้ามพูด 我可能坐这儿吗？)","可能 ('might / probably') expresses likelihood or guessing when you are not 100% certain. · Flexible position: it can sit AFTER the subject (他可能忘了) or BEFORE it (可能他忘了). · Crucial distinction between two negatives: (1) 可能不 / 可能没 = 'might not' (他可能不来了); (2) 不可能 = 'impossible / no way!' (他不可能忘). · Caution: NEVER use 可能 to ask permission (use 可以: 我可以坐这儿吗？).","“可能”表示推测某种情况大概会发生，既可放主语后（他可能忘了），也可放主语前（可能他忘了）。 · 两种否定语义截然不同：（1）“可能不／可能没”＝也许不（他可能不来了）；（2）“不可能”＝绝对不会（他不可能忘）。 · 注意：请求许可用“可以”，绝不能用“可能”。","可能 ('có lẽ / có thể') dùng để phỏng đoán, đặt trước hay sau chủ ngữ đều được (他可能忘了 / 可能他忘了). · Phân biệt 2 phủ định: (1) 可能不 / 可能没 = 'có lẽ không'; (2) 不可能 = 'không đời nào / không thể nào!'. · Lưu ý: xin phép phải dùng 可以, không dùng 可能.","「可能」は推量「〜かもしれない」を表し、主語の前後どちらにも置ける（他可能忘了／可能他忘了）。 · 2つの否定の意味が大きく異なる：（1）「可能不／可能没」＝〜ないかもしれない、（2）「不可能」＝あり得ない。 · 注意：許可を求めるのに「可能」は使えない（「可以」を使う）。"],"use":[{"ok":true,"zh":"明天可能下雨。","fix":"","py":"Míngtiān kěnéng xià yǔ.","tr":["พรุ่งนี้อาจจะฝนตก","It might rain tomorrow.","Ngày mai có thể trời sẽ mưa.","明日は雨が降るかもしれません。"],"h":["คาดเดาเหตุการณ์ที่ยังไม่แน่ใจ ใช้ 可能 + กริยา","Use 可能 + verb to express an uncertain prediction","推测可能发生的事用“可能＋动词”","Phỏng đoán việc chưa chắc chắn dùng 可能 + động từ","不確かな推量には「可能＋動詞」"],"w":["ทำได้เพราะเป็นการคาดการณ์สภาพอากาศล่วงหน้าด้วยความเป็นไปได้ ไม่ใช่การขออนุญาตหรือความสามารถ","Works cleanly as a weather prediction expressing likelihood rather than ability or permission.","用于推测未来天气，准确表达可能性。","Đúng vì đây là dự đoán khả năng xảy ra thời tiết.","未来の天気の推量として「可能」がぴったり当てはまる。"],"ref":"HSK 3.0 g3-2-004"},{"ok":true,"zh":"他可能不来了。","fix":"","py":"Tā kěnéng bù lái le.","tr":["เขาอาจจะไม่มาแล้ว","He probably isn't coming anymore.","Anh ấy có lẽ không đến nữa rồi.","彼はもう来ないかもしれません。"],"h":["'อาจจะไม่…' วาง 可能 ไว้หน้า 不 / 没 (ต่างจาก 不可能 = เป็นไปไม่ได้!)","Put 可能 BEFORE 不/没 for 'might not' (vs 不可能 'impossible!')","“可能不／可能没”表“也许不”，区别于强烈否定“不可能”","'Có lẽ không' đặt 可能 TRƯỚC 不/没 (khác 不可能 = không đời nào)","「〜ないかもしれない」は「可能不／可能没」（「不可能」はあり得ない）"],"w":["ทำได้เพราะผู้พูดกำลังเดาว่าเขาอาจจะไม่มา จึงวาง 可能 หน้า 不 (ถ้าสลับเป็น 他不可能来 จะแปลแรงมากว่า 'ไม่มีทางที่เขาจะมาได้!')","Works because placing 可能 before 不 softens it to 'might not come', whereas 不可能 means 'no way he can come!'.","“可能”在“不”前表委婉推测；若说“不可能来”则是断定绝对不会来。","Đúng vì 可能 đứng trước 不 mang nghĩa phỏng đoán; đảo thành 不可能 sẽ thành phủ định tuyệt đối.","「可能不」は控えめな推量。「不可能」にすると「絶対に来ない」という強い否定になる。"],"ref":"HSK 3.0 g3-2-004"},{"ok":false,"zh":"我可能坐这儿吗？","fix":"我可以坐这儿吗？","py":"Wǒ kěyǐ zuò zhèr ma?","tr":["ฉันขอนั่งตรงนี้ได้ไหม","May I sit here?","Tôi có thể ngồi đây không?","ここに座ってもいいですか。"],"h":["ห้ามใช้ 可能 แทน 可以 เวลาขออนุญาต","NEVER use 可能 instead of 可以 to ask permission","请求许可必须用“可以”，不能用“可能”","Xin phép phải dùng 可以, không dùng 可能","許可を求めるのに「可能」は使えない（「可以」を使う）"],"w":["ไม่ได้ เพราะคำว่า 'ได้ / may' ในภาษาไทยและอังกฤษมีสองความหมาย แต่ภาษาจีนแยกชัด: ขออนุญาตใช้ 可以 ส่วนคาดเดาโอกาสใช้ 可能","Wrong because English 'may/can' covers both permission and probability, while Chinese separates them: 可以 (permission) vs 可能 (probability).","不行，请求允许用“可以”，表推测才用“可能”。","Không được vì tiếng Trung tách rõ: xin phép dùng 可以, phỏng đoán khả năng dùng 可能.","許可には必ず「可以」を使い、推量の「可能」は使えない。"],"ref":"HSK 3.0 g3-2-004 · g3-1-006"}],"ex":[["明天可能下雨。","Míngtiān kěnéng xià yǔ.","พรุ่งนี้อาจจะฝนตก","It might rain tomorrow.","Ngày mai có thể sẽ mưa.","明日は雨が降るかもしれません。","可能"],["他今天可能很忙。","Tā jīntiān kěnéng hěn máng.","วันนี้เขาอาจจะยุ่งมาก","He is probably very busy today.","Hôm nay anh ấy có lẽ rất bận.","彼は今日とても忙しいかもしれません。","可能"],["可能他忘了。","Kěnéng tā wàng le.","บางทีเขาอาจจะลืมไปแล้ว","Maybe he forgot.","Có lẽ anh ấy quên rồi.","もしかしたら彼は忘れたのかもしれません。","可能"],["他可能不来了。","Tā kěnéng bù lái le.","เขาอาจจะไม่มาแล้ว","He might not be coming anymore.","Anh ấy có lẽ không đến nữa.","彼はもう来ないかもしれません。","可能"],["这不可能！","Zhè bù kěnéng!","นี่เป็นไปไม่ได้เด็ดขาด!","That's impossible!","Điều này không thể nào!","そんなことはあり得ません！","不可能"]],"err":[["我可能坐这儿吗？","我可以坐这儿吗？","ขออนุญาตใช้ 可以 ไม่ใช่ 可能 (可能 ใช้คาดเดาความเป็นไปได้)","Asking permission takes 可以, not 可能 (probability).","请求许可用“可以”，不用“可能”。","Xin phép dùng 可以, không dùng 可能.","許可を求めるのは「可能」ではなく「可以」。"]],"rel":["g3-1-004","g3-1-006"]},"g3-2-005":{"t":["กริยาแยกได้ (离合词): 帮忙 / 游泳 / 跳舞 / 跑步","Separable verbs (离合词): 帮忙 / 游泳 / 跳舞 / 跑步","词类·离合词：帮忙、游泳、跳舞、跑步","Động từ ly hợp (离合词): 帮忙 / 游泳 / 跳舞 / 跑步","離合詞（离合词）：帮忙・游泳・跳舞・跑步"],"f":["离合词不可直接带宾语（不说“帮忙我”，要说“帮我的忙”或“帮我”）","带时长/次数/了/过插在中间：游了一会儿泳 / 跑了一个小时步 / 跳一次舞"],"why":["帮忙 (ช่วย), 游泳 (ว่ายน้ำ), 跳舞 (เต้นรำ), 跑步 (วิ่งออกกำลังกาย) ล้วนเป็นกริยาแยกได้ (离合词) เพราะข้างในเป็นโครงสร้าง 'กริยา + กรรม' อยู่แล้ว (帮+忙, 游+泳, 跳+舞, 跑+步) · กฎทอง 2 ข้อที่ออกสอบบ่อยสุด ๆ: (1) ห้ามเอาคนหรือกรรมมาวางต่อท้ายตรง ๆ! เช่น ห้ามพูด 帮忙我 (ผิด 100%!) ต้องแยกเอาคนไปไว้ตรงกลางเป็น 帮我的忙 / 帮我一个忙 หรือตัด 忙 ออกเหลือ 帮我 (2) เวลาบอกระยะเวลา จำนวนครั้ง หรือเติม 了/过 ให้ 'แทรกไว้ตรงกลาง' ระหว่างพยางค์ 1 กับ 2 เช่น 游了一个小时泳, 跑了一次步, 跳了舞","帮忙 ('help'), 游泳 ('swim'), 跳舞 ('dance'), and 跑步 ('jog') are separable verb-object words (帮+忙, 游+泳, 跳+舞, 跑+步). · Two top exam rules: (1) NEVER put a direct object after them! Never say 帮忙我 — split it as 帮我的忙 / 帮我一个忙, or use bare 帮我. (2) Insert durations, counts, or 了/过 IN THE MIDDLE: 游了一个小时泳, 跑了一会儿步, 跳了一次舞.","“帮忙、游泳、跳舞、跑步”都是动宾式离合词（帮＋忙、游＋泳、跳＋舞、跑＋步）。 · 两条必考铁律：（1）绝不能直接带宾语，不说“帮忙我”，要说“帮我的忙／帮我一个忙”或用“帮我”；（2）带时量、动量、了、过时要插在中间：游了一个小时泳、跑了一会儿步。","帮忙, 游泳, 跳舞, 跑步 đều là động từ ly hợp (gồm sẵn Động + Tân). · 2 quy tắc vàng: (1) KHÔNG thêm tân ngữ trực tiếp phía sau (không nói 帮忙我! Phải tách thành 帮我的忙 / 帮我一个忙 hoặc dùng 帮我); (2) Thời lượng, số lần, 了/过 chèn VÀO GIỮA: 游了一个小时泳, 跑了一会儿步.","「帮忙・游泳・跳舞・跑步」はいずれも「動詞＋目的語」構造の離合詞。 · 2大鉄則：（1）後ろに直接目的語を置けない（「帮忙我」は絶対不可→「帮我的忙／帮我」）。（2）期間・回数・「了／过」は間に挟む：游了一个小时泳、跑了一会儿步。"],"use":[{"ok":true,"zh":"请你帮我一个忙，好吗？","fix":"","py":"Qǐng nǐ bāng wǒ yī ge máng, hǎo ma?","tr":["ช่วยฉันหน่อยสักเรื่องได้ไหม","Could you do me a favor, please?","Bạn giúp tôi một việc được không?","ちょっと一つ手伝ってもらえませんか。"],"h":["แทรกผู้รับและจำนวนไว้ตรงกลาง 帮 + คน + 一个 + 忙","Split 帮忙 by putting person + 一个 in the middle: 帮我一个忙","把对象插进“帮忙”中间：帮我一个忙／帮我的忙","Chèn người và số lượng vào giữa 帮 + người + 一个 + 忙","「帮忙」を割って間に人と数量を挟む：帮我一个忙"],"w":["ทำได้และสุภาพเป็นธรรมชาติมาก เพราะแยก 帮 (กริยา) ออกจาก 忙 (กรรม) แล้วแทรก 我一个 ไว้ตรงกลางได้ลงตัว (หรือใช้ 帮我 สั้น ๆ ก็ได้)","Works politely and naturally by splitting verb 帮 from object 忙 and placing 我一个 inside (or simply 帮我).","拆分“帮忙”把“我一个”插入中间，是最地道自然的请求表达。","Đúng và rất tự nhiên khi tách 帮 và 忙 rồi chèn 我一个 vào giữa.","「帮」と「忙」の間に「我一个」を挟む最も自然な依頼表現。"],"ref":"HSK 3.0 g3-2-005 · g3-1-007"},{"ok":true,"zh":"我游了一个小时泳。","fix":"","py":"Wǒ yóule yī ge xiǎoshí yǒng.","tr":["ฉันว่ายน้ำไปหนึ่งชั่วโมง","I swam for an hour.","Tôi đã bơi một tiếng đồng hồ.","1時間泳ぎました。"],"h":["บอกระยะเวลาของ 离合词 ให้แทรกไว้ตรงกลาง (游 + 了一个小时 + 泳)","Insert duration in the middle of a separable verb (游 + 了一个小时 + 泳)","带时量补语时插在离合词中间：游了一个小时泳","Chèn thời lượng vào giữa động từ ly hợp (游了一个小时泳)","期間補語は離合詞の間に挟む（游了一个小时泳）"],"w":["ทำได้เพราะ 游 เป็นกริยา 泳 เป็นกรรม เวลาใส่ 了 และระยะเวลา 一个小时 จึงต้องวางหลังกริยา 游 หน้ากรรม 泳 (เช่นเดียวกับ 跑了一会儿步, 跳了一会儿舞)","Works because 游 is the verb and 泳 is its object, so 了 + 一个小时 goes between them (just like 跑了一会儿步).","“游”是动词、“泳”是宾语，“了一个小时”插在动宾之间完全合乎语法。","Đúng vì 游 là động từ, 泳 là tân ngữ nên 了一个小时 đứng ngay giữa.","「游」（動詞）と「泳」（目的語）の間に「了一个小时」を挟むのが正しい語順。"],"ref":"HSK 3.0 g3-2-005 · g3-2-053"},{"ok":false,"zh":"请你帮忙我。","fix":"请你帮我。","py":"Qǐng nǐ bāng wǒ.","tr":["กรุณาช่วยฉันหน่อย","Please help me.","Xin bạn giúp tôi.","どうか私を助けてください。"],"h":["ห้ามเอาชื่อคนต่อท้าย 帮忙 ตรง ๆ (帮忙我 ผิด 100%!)","NEVER put a person directly after 帮忙 (帮忙我 is 100% wrong!)","绝不能说“帮忙我／帮忙他”","Tuyệt đối không nói 帮忙我 / 帮忙他","「帮忙我／帮忙他」は100%誤用"],"w":["ไม่ได้ เพราะ 忙 ใน 帮忙 เป็นกรรมอยู่แล้ว จึงต่อกรรม 我 ซ้อนอีกไม่ได้ ต้องตัด 忙 ออกเหลือ 帮我 หรือแยกเป็น 帮我的忙 / 帮我一个忙","Wrong because 忙 already fills the object slot of 帮 — drop 忙 (帮我) or split it (帮我的忙 / 帮我一个忙).","不行，“帮忙”自带宾语“忙”，不能再带“我”，应改说“帮我”或“帮我的忙”。","Không được vì 忙 đã là tân ngữ rồi; phải sửa thành 帮我 hoặc 帮我的忙.","「忙」がすでに目的語なので後ろに「我」を置けない。「帮我」か「帮我的忙」にする。"],"ref":"HSK 3.0 g3-2-005"},{"ok":false,"zh":"我游泳了一个小时。","fix":"我游了一个小时泳。","py":"Wǒ yóule yī ge xiǎoshí yǒng.","tr":["ฉันว่ายน้ำไปหนึ่งชั่วโมง","I swam for an hour.","Tôi đã bơi một tiếng.","1時間泳ぎました。"],"h":["ห้ามวางระยะเวลาไว้ท้าย 游泳 / 跑步 / 跳舞 ตรง ๆ","Don't tack duration onto the end of 游泳 / 跑步 / 跳舞","时量补语不能直接放在“游泳了”后面","Không đặt thời lượng sau cả cụm 游泳了","「游泳了」の後ろに期間を直結しない"],"w":["ไม่ได้ในภาษาจีนมาตรฐาน เพราะ 游泳 เป็นกริยาแยกได้ ต้องแทรกระยะเวลาไว้ตรงกลางเป็น 游了一个小时泳 (หรือซ้ำกริยาว่า 游泳游了一个小时)","Wrong in standard Chinese: split 游泳 with the duration inside (游了一个小时泳), never 游泳了一个小时.","不行，规范表达须拆分插在中间：游了一个小时泳（或重动“游泳游了一个小时”）。","Không chuẩn vì 游泳 là động từ ly hợp, phải tách ra: 游了一个小时泳.","離合詞なので間に挟んで「游了一个小时泳」とする。"],"ref":"HSK 3.0 g3-2-005 · g3-2-053"}],"ex":[["谢谢你来帮忙。","Xièxie nǐ lái bāngmáng.","ขอบคุณที่คุณมาช่วย","Thank you for coming to help.","Cảm ơn bạn đã đến giúp.","手伝いに来てくれてありがとう。","帮忙"],["请你帮我一个忙。","Qǐng nǐ bāng wǒ yī ge máng.","กรุณาช่วยฉันสักเรื่องหน่อย","Please do me a favor.","Xin bạn giúp tôi một việc.","ちょっと一つお願いがあるのですが。","帮我一个忙"],["我喜欢游泳。","Wǒ xǐhuan yóuyǒng.","ฉันชอบว่ายน้ำ","I like swimming.","Tôi thích bơi lội.","私は泳ぐのが好きです。","游泳"],["她每天晚上都跳舞。","Tā měi tiān wǎnshang dōu tiàowǔ.","เธอเต้นรำทุกคืนเลย","She dances every evening.","Tối nào cô ấy cũng nhảy múa.","彼女は毎晩踊ります。","跳舞"],["我每天早上跑步。","Wǒ měi tiān zǎoshang pǎobù.","ทุกเช้าฉันไปวิ่งออกกำลังกาย","I jog every morning.","Mỗi sáng tôi đều chạy bộ.","毎朝ジョギングをします。","跑步"]],"err":[["请你帮忙我。","请你帮我。","帮忙 เป็นกริยาแยกได้ ห้ามต่อกรรมคนตรง ๆ ใช้ 帮我 หรือ 帮我的忙","Never put a person after 帮忙; say 帮我 or 帮我的忙.","不能说“帮忙我”，要说“帮我”或“帮我的忙”。","Không nói 帮忙我, phải nói 帮我 hoặc 帮我的忙.","「帮忙我」は不可。「帮我」か「帮我的忙」にする。"],["我游泳了一个小时。","我游了一个小时泳。","แทรกระยะเวลาไว้ตรงกลางกริยาแยกได้: 游了一个小时泳","Split 游泳 to insert duration in the middle: 游了一个小时泳.","时量补语插在离合词中间：游了一个小时泳。","Chèn thời lượng vào giữa 游 và 泳: 游了一个小时泳.","期間は間に挟んで「游了一个小时泳」。"]],"rel":["g3-1-007","g3-2-053","g3-2-013"]},"g3-2-006":{"t":["คำถาม 为什么: ทำไม / เพราะอะไร","Question word 为什么: 'why?'","疑问代词：为什么","Đại từ nghi vấn 为什么: tại sao?","疑問代名詞「为什么」：なぜ・どうして"],"f":["主语 + 为什么 + 动词 / 形容词？（你为什么不吃？）","为什么 + 主语 + 动词 / 形容词？（为什么你不来？）","回答：因为……（所以……）"],"why":["为什么 แปลว่า 'ทำไม / เพราะอะไร' ใช้ถามหาเหตุผล และมักตอบกลับด้วย 因为… (เพราะว่า…) · จุดเด่นของ 为什么 ต่างจากคำถามตัวอื่น (อย่าง 什么/哪儿): สามารถวางได้ทั้ง 'หลังประธาน' (你为什么不来？ — พบบ่อยสุด) และ 'ต้นประโยคหน้าประธาน' (为什么你不来？ — เน้นน้ำเสียงสงสัย/ถามเหตุผลแรงขึ้น) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ห้ามเติม 吗 ท้ายประโยคที่มี 为什么 (你为什么不去吗？ ผิด!) (2) ห้ามวาง 为什么 ไว้ท้ายประโยคหลังกริยาแบบภาษาไทย ('คุณไม่ไปทำไม?' → ห้ามพูด 你不去为什么!)","为什么 ('why') asks for a reason and is typically answered with 因为… ('because…'). · Unlike 什么 or 哪儿, 为什么 can sit EITHER after the subject (你为什么不来？ — most common) OR before the subject (为什么你不来？ — more emphatic). · Two strict cautions: (1) NEVER add 吗 at the end. (2) NEVER put 为什么 at the end of a clause like Thai 'ไม่ไปทำไม' (never 你不去为什么？).","“为什么”用于询问原因，回答常配“因为……”。 · 位置灵活：常放主语后、谓语前（你为什么不来？），也可放主语前强调发问（为什么你不来？）。 · 两条铁律：（1）句末绝不能加“吗”；（2）不能按泰语语序放在句尾（不说“你不去为什么？”）。","为什么 ('tại sao') hỏi nguyên nhân, thường đáp bằng 因为…. · Vị trí linh hoạt: sau chủ ngữ (你为什么不来？) hoặc đầu câu (为什么你不来？). · 2 quy tắc cứng: (1) KHÔNG thêm 吗; (2) KHÔNG đặt 为什么 cuối câu như tiếng Thái (không nói 你不去为什么？).","「为什么」は理由を尋ね、「因为…」で答えるのが定番。 · 主語の後ろ（你为什么不来？）にも文頭（为什么你不来？）にも置ける。 · 鉄則2つ：（1）文末に「吗」を付けない。（2）文末に「为什么」を置かない。"],"use":[{"ok":true,"zh":"你为什么今天没来上课？","fix":"","py":"Nǐ wèishénme jīntiān méi lái shàngkè?","tr":["ทำไมวันนี้คุณไม่ได้มาเข้าเรียน","Why didn't you come to class today?","Tại sao hôm nay bạn không đến lớp?","どうして今日授業に来なかったのですか。"],"h":["วาง 为什么 หลังประธานและหน้าภาคแสดง (พบบ่อยและเป็นธรรมชาติสุด)","Place 为什么 right after the subject and before the predicate","最常用语序：主语＋为什么＋谓语","Đặt 为什么 sau chủ ngữ và trước vị ngữ (tự nhiên nhất)","最も自然な語順：「主語＋为什么＋述語」"],"w":["ทำได้และเป็นลำดับมาตรฐานที่สุดของภาษาจีน สามารถวาง 为什么 ได้ทั้งหน้าและหลังคำบอกเวลา 今天 (你今天为什么… หรือ 你为什么今天…)","Works as the most natural standard order (and can sit either before or after 今天).","“主语＋为什么＋谓语”最自然，也可说“你今天为什么没来上课？”。","Đúng và tự nhiên nhất (cũng có thể nói 你今天为什么没来上课？).","「主語＋为什么＋述語」が標準的（「你今天为什么…」も可）。"],"ref":"HSK 3.0 g3-2-006"},{"ok":true,"zh":"为什么大家都笑了？","fix":"","py":"Wèishénme dàjiā dōu xiào le?","tr":["ทำไมทุกคนถึงหัวเราะกันหมดเลยล่ะ","Why did everyone laugh?","Tại sao mọi người đều cười thế?","どうして皆笑ったんですか。"],"h":["วาง 为什么 ไว้หน้าประธานเพื่อเน้นความสงสัย/ประหลาดใจ","Put 为什么 at the very start before the subject to emphasize curiosity","“为什么”放句首强调疑问语气","Đặt 为什么 đầu câu để nhấn mạnh sự thắc mắc","文頭に「为什么」を置いて疑問の気持ちを強調する"],"w":["ทำได้และเหมาะมากเมื่อผู้พูดรู้สึกสงสัยหรือประหลาดใจกับสิ่งที่เพิ่งเห็นตรงหน้า (และไม่มี 吗 ท้ายประโยค)","Works vividly when reacting with curiosity or surprise to what just happened (and with no trailing 吗).","把“为什么”置于句首更能突出惊讶或追问语气。","Đúng và rất hay khi bày tỏ sự ngạc nhiên, thắc mắc.","驚きや強い疑問を表すとき文頭に「为什么」を置くと自然。"],"ref":"HSK 3.0 g3-2-006"},{"ok":false,"zh":"你不喝咖啡为什么？","fix":"你为什么不喝咖啡？","py":"Nǐ wèishénme bù hē kāfēi?","tr":["ทำไมคุณไม่ดื่มกาแฟ","Why don't you drink coffee?","Tại sao bạn không uống cà phê?","どうしてコーヒーを飲まないんですか。"],"h":["ห้ามวาง 为什么 ไว้ท้ายประโยคแบบภาษาไทย ('ไม่ดื่มกาแฟทำไม?')","NEVER put 为什么 at the end of a clause like Thai","“为什么”作状语不能放在句尾","Không đặt 为什么 ở cuối câu như tiếng Thái","「为什么」を文末に置けない"],"w":["ไม่ได้ เพราะในภาษาไทยพูดว่า 'คุณไม่ดื่มกาแฟทำไม' ได้ แต่ในภาษาจีน 为什么 เป็นส่วนขยายกริยา (状语) ต้องวางหน้ากริยาหรือต้นประโยคเท่านั้น","Wrong because 为什么 is an adverbial that MUST come before the predicate (or sentence-initially), never at the end.","不行，“为什么”作状语必须放谓语前或句首：你为什么不喝咖啡？","Không được vì 为什么 là trạng ngữ phải đứng trước vị ngữ hoặc đầu câu.","「为什么」は連用修飾語なので必ず述語の前か文頭に置く。"],"ref":"HSK 3.0 g3-2-006"},{"ok":false,"zh":"你为什么不高兴吗？","fix":"你为什么不高兴？","py":"Nǐ wèishénme bù gāoxìng?","tr":["ทำไมคุณถึงไม่มีความสุข","Why are you unhappy?","Tại sao bạn không vui?","どうして嬉しくないのですか。"],"h":["ห้ามใส่ 吗 ท้ายประโยคที่มี 为什么","NEVER add 吗 at the end of a 为什么 question","有“为什么”时句末绝不能加“吗”","Tuyệt đối không thêm 吗 cuối câu có 为什么","「为什么」のある文末に「吗」は付けない"],"w":["ไม่ได้ เพราะ 为什么 เป็นคำแสดงคำถามเจาะจงอยู่แล้ว จึงใช้ร่วมกับ 吗 ไม่ได้เด็ดขาด","Wrong because 为什么 already forms a wh-question — adding 吗 is always ungrammatical.","不行，“为什么”本身已构成特指问，绝不能再加“吗”。","Không được vì 为什么 đã là từ để hỏi rồi, không thể kèm 吗.","「为什么」自体が疑問詞なので「吗」を重ねてはいけない。"],"ref":"HSK 3.0 g3-2-006 · g3-1-048"}],"ex":[["你为什么不喝咖啡？","Nǐ wèishénme bù hē kāfēi?","ทำไมคุณไม่ดื่มกาแฟ","Why don't you drink coffee?","Tại sao bạn không uống cà phê?","どうしてコーヒーを飲まないのですか。","为什么"],["他为什么今天没来？","Tā wèishénme jīntiān méi lái?","ทำไมวันนี้เขาไม่ได้มา","Why didn't he come today?","Tại sao hôm nay anh ấy không đến?","彼はどうして今日来なかったのですか。","为什么"],["为什么大家都笑了？","Wèishénme dàjiā dōu xiào le?","ทำไมทุกคนถึงหัวเราะกันหมด","Why did everyone laugh?","Tại sao mọi người đều cười?","どうして皆笑ったのですか。","为什么"],["你为什么喜欢学习汉语？","Nǐ wèishénme xǐhuan xuéxí Hànyǔ?","ทำไมคุณถึงชอบเรียนภาษาจีน","Why do you like studying Chinese?","Tại sao bạn thích học tiếng Trung?","どうして中国語の勉強が好きなのですか。","为什么"],["为什么这里这么冷？","Wèishénme zhèlǐ zhème lěng?","ทำไมที่นี่ถึงหนาวขนาดนี้","Why is it so cold here?","Tại sao ở đây lại lạnh thế này?","どうしてここはこんなに寒いのですか。","为什么"]],"err":[["你不喝咖啡为什么？","你为什么不喝咖啡？","为什么 ต้องวางหน้าภาคแสดงหรือต้นประโยค ห้ามวางท้ายประโยค","Place 为什么 before the predicate or sentence-initially, never at the end.","“为什么”放在谓语前或句首，不放句尾。","Đặt 为什么 trước vị ngữ hoặc đầu câu, không đặt cuối câu.","「为什么」は述語の前か文頭に置き、文末には置かない。"],["你为什么不高兴吗？","你为什么不高兴？","มี 为什么 แล้วห้ามเติม 吗 ท้ายประโยค","Never add 吗 when 为什么 is already in the sentence.","有“为什么”时不能再加“吗”。","Đã có 为什么 thì không thêm 吗.","「为什么」がある文末に「吗」は付けない。"]],"rel":["g3-2-027","g3-2-070","g3-1-048"]},"g3-2-007":{"t":["สรรพนามสะท้อน 自己: ตัวเอง / ด้วยตัวเอง","Reflexive pronoun 自己: 'oneself / by oneself / own'","人称代词：自己","Đại từ phản thân 自己: tự mình / của bản thân","再帰代名詞「自己」：自分自身・自分で"],"f":["人称代词 + 自己（我自己 / 你自己 / 他自己）","自己 + 动词（自己做饭 / 自己去）· 自己的 + 名词（自己的书）"],"why":["自己 แปลว่า 'ตัวเอง / ด้วยตัวเอง / ของตัวเอง' ใช้ได้ 3 บทบาทหลัก: (1) ต่อท้ายสรรพนามบุคคลเพื่อเน้นย้ำตัวคนนั้น: 我自己 (ตัวฉันเอง), 你自己 (ตัวคุณเอง), 他自己 (ตัวเขาเอง) (2) วางหน้ากริยาแปลว่า 'ทำด้วยตัวเองโดยไม่พึ่งคนอื่น': 我自己做饭, 他自己去机场 (3) วางเป็นส่วนขยายคำนามแปลว่า 'ของตัวเอง': 自己的房间, 自己的事情 · ข้อควรระวัง: (1) ห้ามเอา 自己 ไปวางหน้าสรรพนาม (ห้ามพูด 自己我 ต้องพูด 我自己!) (2) ห้ามเติม 们 ท้าย 自己 (ห้ามพูด 自己们 ให้ใช้ 我们自己 / 他们自己)","自己 ('oneself / by oneself / one's own') has three core roles: (1) After a pronoun for emphasis: 我自己, 你自己, 他自己; (2) Before a verb to mean 'by oneself': 我自己做饭, 他自己去机场; (3) Before 的 + noun to mean 'one's own': 自己的房间, 自己的事情. · Cautions: (1) NEVER put 自己 before the pronoun (say 我自己, never 自己我). (2) NEVER add 们 to 自己 (say 我们自己 / 他们自己, never 自己们).","“自己”可复指主语或泛指自身，有三大用法：（1）跟在人称代词后加强语气（我自己、你自己、他自己）；（2）放动词前表示“亲自／独自”（我自己做饭）；（3）作定语表“属于自己的”（自己的房间、自己的事情）。 · 注意：不能说“自己我”，也不能加“们”（不说“自己们”）。","自己 ('tự mình / bản thân') có 3 cách dùng chính: (1) sau đại từ để nhấn mạnh (我自己, 他自己), (2) trước động từ nghĩa là 'tự làm một mình' (我自己做饭), (3) trước 的 + danh từ nghĩa là 'của riêng mình' (自己的房间). · Lưu ý: KHÔNG nói 自己我 hay 自己们 (phải nói 我们自己).","「自己」には3つの用法がある：（1）人称代名詞の後ろで強調（我自己・他自己）、（2）動詞の前で「自分で」（我自己做饭）、（3）「自己的＋名詞」で「自分の〜」（自己的房间）。 · 注意：「自己我」「自己们」は不可（複数は「我们自己」）。"],"use":[{"ok":true,"zh":"我自己去机场，你别送我。","fix":"","py":"Wǒ zìjǐ qù jīchǎng, nǐ bié sòng wǒ.","tr":["ฉันไปสนามบินเอง คุณไม่ต้องไปส่งฉันหรอก","I'll go to the airport myself; don't see me off.","Tôi tự ra sân bay, bạn đừng tiễn tôi.","自分で空港へ行くから、見送らなくていいよ。"],"h":["สรรพนาม + 自己 + กริยา = ทำด้วยตัวเอง","Pronoun + 自己 + Verb = 'do something by oneself'","“代词＋自己＋动词”表示独自／亲自做","Đại từ + 自己 + động từ = tự làm một mình","「代名詞＋自己＋動詞」＝自分で〜する"],"w":["ทำได้และเป็นธรรมชาติมาก โดยวาง 我 ไว้หน้า 自己 เสมอ แล้วต่อกริยา 去机场 ทันที","Works naturally with pronoun 我 directly before 自己 and then verb 去机场.","“我自己”放在动词前，清楚表达独自前往，不麻烦别人。","Đúng và tự nhiên khi đặt 我 trước 自己 rồi nối động từ 去机场.","「我自己」を動詞の前に置き、他の人の手を借りず自分で行動することを表す。"],"ref":"HSK 3.0 g3-2-007"},{"ok":true,"zh":"每个人都有自己的爱好。","fix":"","py":"Měi ge rén dōu yǒu zìjǐ de àihào.","tr":["ทุกคนต่างก็มีงานอดิเรกของตัวเอง","Everyone has their own hobbies.","Mỗi người đều có sở thích của riêng mình.","誰にでも自分の趣味があります。"],"h":["自己的 + คำนาม = ของตัวเอง (ใช้คู่ประธานทั่วไปได้)","自己的 + Noun = 'one's own…'","“自己的＋名词”作定语表“属于本人的”","自己的 + danh từ = của riêng bản thân","「自己的＋名詞」＝自分の〜"],"w":["ทำได้เพราะ 自己 สะท้อนกลับไปหาประธาน 每个人 โดยตรง (แปลว่า 'ของแต่ละคนเอง') ไม่ต้องระบุเพศหรือพหูพจน์","Works cleanly because 自己 refers straight back to 每个人 regardless of gender or number.","“自己”灵活回指主语“每个人”，不受性别和单复数限制。","Đúng vì 自己 phản thân trực tiếp về chủ ngữ 每个人.","「自己」は主語「每个人」を受け、性や単複を問わず「自分の」を表せる。"],"ref":"HSK 3.0 g3-2-007 · g3-2-008"},{"ok":false,"zh":"自己我做饭。","fix":"我自己做饭。","py":"Wǒ zìjǐ zuòfàn.","tr":["ฉันทำกับข้าวเอง","I cook by myself.","Tôi tự nấu cơm.","私は自分で料理を作ります。"],"h":["ห้ามวาง 自己 ไว้หน้าสรรพนาม (ต้องเป็น 我自己 ไม่ใช่ 自己我)","NEVER put 自己 before the pronoun — always 我自己","必须说“我自己”，不能颠倒成“自己我”","Luôn nói 我自己, không đảo thành 自己我","「自己我」は不可、必ず「我自己」"],"w":["ไม่ได้ เพราะเวลาใช้คู่กับสรรพนามบุคคล ภาษาจีนบังคับวางสรรพนามขึ้นก่อนแล้วตามด้วย 自己 เสมอ: 我自己, 你自己, 他自己, 我们自己","Wrong because when paired with a pronoun, 自己 MUST follow it: 我自己, 你自己, 他自己, 我们自己.","不行，人称代词与“自己”同位使用时，“自己”只能在后：我自己、他自己。","Không được vì 自己 bắt buộc đứng SAU đại từ: 我自己, 你自己, 他自己.","人称代名詞と並べるとき「自己」は必ず後ろ（我自己・他自己）。"],"ref":"HSK 3.0 g3-2-007"},{"ok":false,"zh":"自己们都很高兴。","fix":"我们自己都很高兴。","py":"Wǒmen zìjǐ dōu hěn gāoxìng.","tr":["พวกเราเองก็ดีใจกันมาก","We ourselves are all very happy.","Chính chúng tôi cũng đều rất vui.","私たち自身もみんなとても嬉しいです。"],"h":["ห้ามเติม 们 ท้าย 自己 (ใช้ 我们自己 / 他们自己)","NEVER add 们 after 自己 — use 我们自己 / 他们自己","“自己”后绝不能加“们”","Không bao giờ thêm 们 sau 自己 (dùng 我们自己)","「自己」に「们」は付けられない（我们自己にする）"],"w":["ไม่ได้ เพราะ 自己 ไม่ผันเป็นพหูพจน์ด้วย 们 ต้องแสดงพหูพจน์ที่สรรพนามข้างหน้าแทน (我们自己, 你们自己, 他们自己)","Wrong because 自己 never takes 们; put the plural on the preceding pronoun: 我们自己 / 他们自己.","不行，“自己”不能加“们”，须在前面加复数代词：我们自己、他们自己。","Không được vì 自己 không thêm 们; phải đặt số nhiều ở đại từ phía trước: 我们自己.","「自己」に「们」は付かない。前の代名詞を複数にして「我们自己」とする。"],"ref":"HSK 3.0 g3-2-007 · g3-1-002"}],"ex":[["我自己做饭。","Wǒ zìjǐ zuòfàn.","ฉันทำกับข้าวเอง","I cook by myself.","Tôi tự nấu cơm.","自分でご飯を作ります。","自己"],["这是我自己的房间。","Zhè shì wǒ zìjǐ de fángjiān.","นี่คือห้องของฉันเอง","This is my own room.","Đây là phòng của riêng tôi.","これは私自身の部屋です。","自己"],["自己的事情自己做。","Zìjǐ de shìqing zìjǐ zuò.","เรื่องของตัวเองก็ทำด้วยตัวเอง","Do your own things yourself.","Việc của mình tự mình làm.","自分のことは自分でやる。","自己"],["每个人都有自己的爱好。","Měi ge rén dōu yǒu zìjǐ de àihào.","ทุกคนต่างมีงานอดิเรกของตัวเอง","Everyone has their own hobby.","Mỗi người đều có sở thích riêng.","誰にでも自分の趣味があります。","自己"],["他自己去机场了。","Tā zìjǐ qù jīchǎng le.","เขาไปสนามบินด้วยตัวเองแล้ว","He went to the airport by himself.","Anh ấy tự đi sân bay rồi.","彼は一人で空港へ行きました。","自己"]],"err":[["自己我做饭。","我自己做饭。","สรรพนามต้องอยู่หน้า 自己 เสมอ (我自己 / 他自己)","Put the pronoun before 自己 (我自己 / 他自己).","人称代词放“自己”前（我自己）。","Đặt đại từ trước 自己 (我自己).","代名詞は「自己」の前（我自己）。"],["自己们去吧。","我们自己去吧。","ห้ามเติม 们 ท้าย 自己 ให้ใช้ 我们自己 แทน","Never say 自己们; use 我们自己 instead.","不能说“自己们”，要说“我们自己”。","Không nói 自己们, dùng 我们自己.","「自己们」は不可、「我们自己」にする。"]],"rel":["g3-1-009","g3-2-008"]},"g3-2-008":{"t":["คำชี้เฉพาะ: 这么 / 那么 / 这样 / 那样 / 每","Demonstratives: 这么 / 那么 / 这样 / 那样 / 每","指示代词：那么、那样、这么、这样、每","Đại từ chỉ định: 这么 / 那么 / 这样 / 那样 / 每","指示代名詞：这么・那么・这样・那样・每"],"f":["这么 / 那么 + 形容词（这么快 / 那么远）","这样 / 那样 + 动词 / 的 + 名词（这样做 / 那样的人）","每 +（量词）+ 名词 + 都……（每天都去 / 每个人都有）"],"why":["ชุดคำชี้เฉพาะ HSK 2 แบ่งเป็น 2 กลุ่มสำคัญ: (1) 这么/那么 vs 这样/那样: 这么 (ขนาดนี้ — ใกล้ตัว) และ 那么 (ขนาดนั้น — ไกลตัว) นิยมวาง 'หน้าคุณศัพท์' (这么冷, 那么高, 那么远) ส่วน 这样 (แบบนี้) และ 那样 (แบบนั้น) นิยมวาง 'หน้ากริยา' หรือ 'ขยายคำนามด้วย 的' (这样做, 那样写, 这样的人) (2) 每 (ทุก ๆ): ใช้โครงสร้าง '每 + ลักษณนาม + คำนาม + 都' เช่น 每个人都有, 每本书都很好看 (ยกเว้น 天, 年 ซึ่งเป็นลักษณนามเวลาในตัวจึงไม่ใส่ 个: 每天, 每年) · ข้อควรระวังเด็ดขาด: (1) มี 每 อยู่ข้างหน้า มักต้องมี 都 รับข้างหลังเสมอ! (2) ห้ามเติม 个 หน้า 天/年 (ห้ามพูด 每一个天!)","These HSK 2 demonstratives split into two handy groups: (1) 这么/那么 ('this/that + Adj': 这么冷, 那么远) vs 这样/那样 ('in this/that way + Verb' or 'this/that kind of + Noun': 这样做, 那样的人). (2) 每 ('every'): follows 每 + Measure Word + Noun + 都 (每个人都有; note 天/年 take no 个 → 每天, 每年). · Two cautions: (1) Always pair 每 with 都 in the predicate! (2) Never put 个 before 天/年 (never 每一个天).","这组指示代词分两类：（1）“这么／那么”多修饰形容词表程度（这么冷、那么远）；“这样／那样”多修饰动词表方式（这样做）或加“的”修饰名词（那样的人）。（2）“每＋量词＋名词”常与“都”呼应（每个人都有、每天都跑步；“天、年”不加“个”）。 · 注意：有“每”句中通常须配“都”；不说“每一个天”。","Gồm 2 nhóm: (1) 这么 / 那么 ('thế này / thế kia') thường đứng trước tính từ (这么冷, 那么远); 这样 / 那样 ('như thế này / như thế kia') đứng trước động từ (这样做) hoặc + 的 + danh từ (那样的人). (2) 每 ('mỗi') luôn đi cùng 都 (每个人都有, 每天都跑步; không thêm 个 trước 天/年).","（1）「这么／那么＋形容詞」（こんなに／あんなに：这么冷・那么远）、「这样／那样＋動詞／的＋名詞」（このように：这样做・那样的人）。（2）「每＋量詞＋名詞＋都」（毎〜：每个人都有・每天都跑步。「天・年」に「个」は不要）。 · 注意：「每」には通常「都」を呼応させる。"],"use":[{"ok":true,"zh":"我每天都去跑步。","fix":"","py":"Wǒ měi tiān dōu qù pǎobù.","tr":["ฉันไปวิ่งออกกำลังกายทุกวัน","I go jogging every day.","Mỗi ngày tôi đều đi chạy bộ.","私は毎日ジョギングに行きます。"],"h":["ใช้ 每…都 คู่กันเสมอ (และ 每天 / 每年 ไม่ต้องมี 个)","Pair 每…都 together (and omit 个 in 每天 / 每年)","“每……都……”前后呼应，“每天／每年”不加“个”","Luôn kết hợp 每…都 (và 每天/每年 không thêm 个)","「每…都…」で呼応させ、「每天・每年」に「个」は入れない"],"w":["ทำได้และสมบูรณ์ 100% เพราะมี 都 มารับ 每 และ 每天 ไม่มี 个 คั่นกลาง","Works 100% cleanly: 都 echoes 每, and self-measuring 天 takes no 个.","“每”与“都”搭配严密，“天”本身是时量词不加“个”。","Đúng 100% vì có 都 hô ứng với 每 và 每天 không có 个.","「每」を「都」で受け、「天」は時間量詞なので「个」不要。"],"ref":"HSK 3.0 g3-2-008 · g3-1-016"},{"ok":true,"zh":"这个字这样写，不对吗？","fix":"","py":"Zhège zì zhèyàng xiě, bù duì ma?","tr":["อักษรตัวนี้เขียนแบบนี้ ไม่ถูกเหรอ","Writing this character like this — isn't it right?","Chữ này viết như thế này, không đúng sao?","この字はこう書くので合っていないのですか。"],"h":["บอกวิธีทำ 'แบบนี้ / แบบนั้น' ใช้ 这样 / 那样 + กริยา","Use 这样 / 那样 + verb to mean 'do it this/that way'","表动作方式用“这样／那样＋动词”（这样写、那样做）","Chỉ cách làm dùng 这样 / 那样 + động từ (这样写)","動作の方法「このように／そのように」は「这样／那样＋動詞」"],"w":["ทำได้เพราะ 这样 แปลว่า 'วิธีแบบนี้' จึงวางหน้ากริยา 写 ได้ตรงความหมาย (ต่างจาก 这么 ที่มักวางหน้าคุณศัพท์อย่าง 这么快)","Works because 这样 means 'this way' before verbs like 写/做, whereas 这么 prefers adjectives (这么快).","“这样写、这样做”准确指代方式方法。","Đúng vì 这样 đứng trước động từ 写 để chỉ 'cách như thế này'.","動作のやり方を指すときは「这样／那样＋動詞」（这样写）を使う。"],"ref":"HSK 3.0 g3-2-008"},{"ok":false,"zh":"每人都喜欢他。","fix":"每个人都喜欢他。","py":"Měi ge rén dōu xǐhuan tā.","tr":["ทุกคนต่างก็ชอบเขา","Everyone likes him.","Mỗi người đều thích anh ấy.","誰もが彼のことを好きです。"],"h":["ระหว่าง 每 กับคำนามทั่วไป (人 / 书 / 苹果) ห้ามลืมลักษณนาม!","Don't drop the measure word between 每 and an ordinary noun!","“每”修饰一般名词时不能省量词（每个人、每本书）","Không bỏ lượng từ giữa 每 và danh từ thường (每个人)","「每」と一般名詞の間の量詞を省かない（每个人・每本书）"],"w":["ไม่ได้ เพราะ 人 เป็นคำนามทั่วไป (ไม่ใช่ 天/年) จึงต้องมีลักษณนาม 个 คั่นเป็น 每个人 (เช่นเดียวกับ 每本书, 每位老师)","Wrong because 人 is an ordinary noun (unlike 天/年) and requires 个: 每个人 (also 每本书, 每位老师).","不行，“人、书”等名词前跟“每”必须加量词：每个人、每本书。","Không được vì 人 là danh từ thường nên bắt buộc có 个: 每个人.","「人・书」などの一般名詞には「每」の後ろに必ず量詞を入れる（每个人・每本书）。"],"ref":"HSK 3.0 g3-2-008"},{"ok":false,"zh":"我每个天都跑步。","fix":"我每天都跑步。","py":"Wǒ měi tiān dōu pǎobù.","tr":["ฉันวิ่งออกกำลังกายทุกวัน","I jog every day.","Tôi chạy bộ mỗi ngày.","毎日ジョギングをします。"],"h":["ห้ามใส่ 个 หน้า 天 และ 年 ใน 每天 / 每年","NEVER put 个 before 天 or 年 (每天 / 每年)","“每天、每年”中间绝不能加“个”","Không thêm 个 trước 天 / 年 (phải nói 每天 / 每年)","「每天・每年」の間に「个」を入れない"],"w":["ไม่ได้ เพราะ 天 และ 年 เป็นลักษณนามเวลาในตัวอยู่แล้ว (เหมือน 两天/三年 ที่ไม่ใส่ 个) จึงต้องพูด 每天 / 每年 ส่วนเดือนและสัปดาห์ต้องมี 个 (每个月, 每个星期)","Wrong because 天 and 年 are self-measuring (每天, 每年), whereas 月 and 星期 DO take 个 (每个月, 每个星期).","不行，“天、年”本身是量词，说“每天、每年”；“月、星期”才加“个”（每个月）。","Không được vì 天 và 年 vốn là lượng từ sẵn (每天, 每年), còn 月/星期 mới thêm 个.","「天・年」は時間量詞なので「每天・每年」。一方「每个月・每个星期」には「个」が要る。"],"ref":"HSK 3.0 g3-2-008 · g3-1-014"}],"ex":[["今天怎么这么冷！","Jīntiān zěnme zhème lěng!","ทำไมวันนี้หนาวขนาดนี้!","Why is it so cold today!","Sao hôm nay lạnh thế này!","今日どうしてこんなに寒いんだろう！","这么"],["机场那么远，我们打车吧。","Jīchǎng nàme yuǎn, wǒmen dǎchē ba.","สนามบินไกลขนาดนั้น พวกเรานั่งแท็กซี่กันเถอะ","The airport is so far; let's take a taxi.","Sân bay xa thế kia, chúng ta bắt taxi đi.","空港はあんなに遠いからタクシーで行きましょう。","那么"],["这样做很好。","Zhèyàng zuò hěn hǎo.","ทำแบบนี้ดีมากเลย","Doing it this way is very good.","Làm như thế này rất tốt.","こうやるのはとても良いです。","这样"],["我也想要那样的一件衣服。","Wǒ yě xiǎng yào nàyàng de yī jiàn yīfu.","ฉันก็อยากได้เสื้อผ้าแบบนั้นสักตัวเหมือนกัน","I also want a piece of clothing like that.","Tôi cũng muốn một chiếc áo như thế kia.","私もあんな服が一着欲しいです。","那样"],["我每天都学习汉语。","Wǒ měi tiān dōu xuéxí Hànyǔ.","ฉันเรียนภาษาจีนทุกวัน","I study Chinese every day.","Mỗi ngày tôi đều học tiếng Trung.","私は毎日中国語を勉強しています。","每"]],"err":[["每人都喜欢他。","每个人都喜欢他。","每 + คำนามทั่วไปต้องมีลักษณนามคั่นเสมอ (每个人)","Insert a measure word between 每 and ordinary nouns (每个人).","“每”修饰一般名词须加量词（每个人）。","Giữa 每 và danh từ thường phải có lượng từ (每个人).","「每」と一般名詞の間には量詞が必要（每个人）。"],["我每个天都跑步。","我每天都跑步。","每天 / 每年 ไม่ใส่ 个 คั่น","Never insert 个 in 每天 / 每年.","“每天、每年”不加“个”。","每天 / 每年 không thêm 个.","「每天・每年」に「个」は入れない。"]],"rel":["g3-1-010","g3-1-016","g3-2-063"]},"g3-2-009":{"t":["การซ้ำคำคุณศัพท์ (形容词重叠): AA / AABB","Adjective Reduplication (形容词重叠): AA / AABB","词类·形容词重叠：AA、AABB","Lặp tính từ (形容词重叠): AA / AABB","形容詞の重ね型（形容词重叠）：AA・AABB"],"f":["单音节：AA（+ 的 / 地）：慢慢地走 / 大大的眼睛 / 远远的","双音节：AABB（高高兴兴 / 漂漂亮亮 / 快快乐乐，绝不是 ABAB！）"],"why":["การซ้ำคำคุณศัพท์ช่วย 'เพิ่มอารมณ์ความรู้สึกและความมีชีวิตชีวา' ให้ภาพชัดขึ้นกว่าคุณศัพท์ธรรมดา เช่น 大大的眼睛 (ตาโต๊โต), 慢慢地走 (เดินช้า ๆ สบาย ๆ), 高高兴兴地回家 (กลับบ้านอย่างดีอกดีใจ) · รูปแบบแบ่งชัดเจน: (1) คุณศัพท์ 1 พยางค์ → AA + 的 (ขยายนาม/ภาคแสดง) หรือ AA + 地 (ขยายกริยา) เช่น 红红的苹果, 慢慢地走 (2) คุณศัพท์ 2 พยางค์ → AABB เช่น 高兴 → 高高兴兴, 漂亮 → 漂漂亮亮, 快乐 → 快快乐乐 · กฎเหล็กเด็ดขาด 2 ข้อ: (1) ห้ามใส่คำวิเศษณ์ระดับ (很, 非常, 太, 真) หน้าคำคุณศัพท์ที่ซ้ำแล้ว! (很高高兴兴 ผิด 100% เพราะการซ้ำก็เพิ่มระดับในตัวแล้ว) (2) ห้ามซ้ำคุณศัพท์ 2 พยางค์แบบ ABAB (高兴高兴 จะกลายเป็นการใช้แบบกริยา ไม่ใช่คุณศัพท์ AABB!)","Adjective reduplication adds vividness and emotional warmth: 大大的眼睛 ('nice big eyes'), 慢慢地走 ('walk nice and slowly'), 高高兴兴 ('happily'). · Forms: (1) 1-syllable → AA + 的 (noun/predicate) or AA + 地 (verb): 红红的苹果, 慢慢地走; (2) 2-syllable → AABB: 高高兴兴, 漂漂亮亮, 快快乐乐. · Two iron rules: (1) NEVER add degree adverbs (很, 非常, 太, 真) before a reduplicated adjective (很高高兴兴 is 100% wrong!). (2) Adjectives use AABB — NOT verb-style ABAB.","形容词重叠可加强描写色彩和生动感：大大的眼睛、慢慢地走、高高兴兴。 · 形式：（1）单音节：AA（常带“的／地”：红红的、慢慢地）；（2）双音节：AABB（高高兴兴、漂漂亮亮、快快乐乐）。 · 两条铁律：（1）重叠后本身已含程度加深义，绝不能再加“很、非常、太、真”等程度副词（不说“很高高兴兴”）；（2）状态形容词重叠用 AABB，区别于动词 ABAB。","Lặp tính từ tăng sắc thái sinh động, dễ thương: 大大的眼睛, 慢慢地走, 高高兴兴. · Dạng thức: (1) 1 âm tiết: AA + 的/地 (红红的, 慢慢地); (2) 2 âm tiết: AABB (高高兴兴, 漂漂亮亮, 快快乐乐). · 2 quy tắc thép: (1) KHÔNG thêm 很 / 非常 / 太 / 真 trước tính từ đã lặp (không nói 很高高兴兴); (2) Tính từ dùng AABB, khác động từ ABAB.","形容詞の重ね型は生き生きとした描写・情感を加える（大大的眼睛・慢慢地走・高高兴兴）。 · 形：（1）1音節は AA＋的／地（红红的・慢慢地）、（2）2音節は AABB（高高兴兴・漂漂亮亮・快快乐乐）。 · 鉄則2つ：（1）重ね型自体に程度の強調があるため「很・非常・太・真」は絶対不可（很高高兴兴×）。（2）動詞の ABAB ではなく AABB。"],"use":[{"ok":true,"zh":"这个女孩儿的眼睛大大的。","fix":"","py":"Zhège nǚháir de yǎnjing dàdà de.","tr":["ตาของเด็กผู้หญิงคนนี้โต๊โต (กลมโตน่ารัก)","This girl has nice big eyes.","Đôi mắt của cô bé này to tròn thật.","この女の子の目はぱっちり大きいです。"],"h":["คุณศัพท์ 1 พยางค์ซ้ำเป็นภาคแสดง: ประธาน + AA 的 (ไม่ใส่ 很)","1-syllable AA predicate: Subject + AA 的 (no 很)","单音节形容词重叠作谓语须加“的”，不加“很”","Tính từ 1 âm tiết lặp làm vị ngữ: AA 的 (không thêm 很)","1音節形容詞の重ね型が述語になるときは「AA的」（「很」不要）"],"w":["ทำได้และให้ความรู้สึกน่ารักมีชีวิตชีวามากกว่า 很大 โดยต้องมี 的 ปิดท้ายและห้ามเติม 很 นำหน้า","Works vividly (warmer than plain 很大), requiring final 的 and NO 很 in front.","“大大的”带“的”作谓语，生动可爱，前面不加“很”。","Đúng và sinh động hơn 很大 nhiều, cần có 的 ở cuối và không có 很.","「大大的」は「很大」より生き生きとしており、文末に「的」を付け「很」は入れない。"],"ref":"HSK 3.0 g3-2-009"},{"ok":true,"zh":"大家高高兴兴地回家了。","fix":"","py":"Dàjiā gāogāo-xìngxìng de huí jiā le.","tr":["ทุกคนกลับบ้านกันอย่างดีอกดีใจ","Everyone went home happily.","Mọi người vui vẻ về nhà rồi.","みんなウキウキと帰っていきました。"],"h":["คุณศัพท์ 2 พยางค์ซ้ำ AABB + 地 ขยายกริยา","2-syllable AABB + 地 modifies a verb smoothly","双音节形容词 AABB＋“地”作状语修饰动词","Tính từ 2 âm tiết AABB + 地 bổ nghĩa động từ","2音節形容詞「AABB＋地」で動詞を修飾する"],"w":["ทำได้เพราะ 高兴 ซ้ำเป็น AABB (高高兴兴) แล้วเชื่อมกับกริยา 回家 ด้วย 地 เพื่อบรรยายอารมณ์ขณะกลับบ้าน","Works naturally: 高兴 reduplicates as AABB (高高兴兴) and links to verb 回家 with adverbial marker 地.","“高高兴兴地”作状语生动描写“回家”时的神态心情。","Đúng vì 高兴 lặp AABB (高高兴兴) rồi nối với động từ 回家 bằng 地.","「高高兴兴」に「地」を付けて「帰る」ときの様子を生き生きと描いている。"],"ref":"HSK 3.0 g3-2-009 · g3-2-030"},{"ok":false,"zh":"今天大家很高高兴兴。","fix":"今天大家高高兴兴的。","py":"Jīntiān dàjiā gāogāo-xìngxìng de.","tr":["วันนี้ทุกคนดีอกดีใจกันมาก","Everyone is nice and cheerful today.","Hôm nay mọi người ai cũng vui vẻ.","今日はみんなウキウキしています。"],"h":["ห้ามใส่ 很 / 非常 / 太 หน้าคุณศัพท์ที่ซ้ำแล้ว (很高高兴兴 ผิด!)","NEVER put 很 / 非常 / 太 before a reduplicated adjective!","形容词重叠后绝不能再加“很、非常、太”","Tuyệt đối không thêm 很 / 非常 / 太 trước tính từ đã lặp","重ね型の形容詞の前に「很・非常・太」は絶対に置けない"],"w":["ไม่ได้ เพราะการซ้ำคำคุณศัพท์ (高高兴兴 / 漂漂亮亮 / 大大的) มีน้ำหนักความเข้มข้นสูงในตัวอยู่แล้ว การเติม 很 ซ้ำเข้าไปผิดกฎไวยากรณ์จีน 100%","Wrong because reduplication already intensifies the adjective — adding 很/非常/太 is always ungrammatical.","不行，形容词重叠本身已表程度加深，前面绝不能加“很、非常、太”。","Không được vì bản thân lặp tính từ đã tăng mức độ sẵn, thêm 很 là sai 100%.","重ね型自体が程度を強めているため、「很・非常・太」は絶対に併用できない。"],"ref":"HSK 3.0 g3-2-009"},{"ok":false,"zh":"大家高兴高兴地回家了。","fix":"大家高高兴兴地回家了。","py":"Dàjiā gāogāo-xìngxìng de huí jiā le.","tr":["ทุกคนกลับบ้านกันอย่างดีอกดีใจ","Everyone went home happily.","Mọi người vui vẻ về nhà rồi.","みんな嬉しそうに帰りました。"],"h":["คุณศัพท์ 2 พยางค์ต้องซ้ำแบบ AABB (高高兴兴) ไม่ใช่ ABAB","2-syllable adjectives reduplicate as AABB (高高兴兴), NOT ABAB","双音节形容词重叠用 AABB，不用 ABAB","Tính từ 2 âm tiết lặp AABB (高高兴兴), không dùng ABAB","2音節形容詞は ABAB ではなく AABB（高高兴兴）"],"w":["ไม่ได้ เพราะรูปแบบ ABAB ใช้กับคำกริยา (休息休息) ส่วนคำคุณศัพท์ 2 พยางค์ต้องแยกซ้ำทีละตัวเป็น AABB: 高高兴兴, 漂漂亮亮, 快快乐乐","Wrong because ABAB is for verbs (休息休息); adjectives split and double each character as AABB: 高高兴兴.","不行，形容词重叠固定为 AABB（高高兴兴、漂漂亮亮），ABAB 是动词重叠形式。","Không được vì ABAB là của động từ; tính từ 2 âm tiết phải dùng AABB (高高兴兴).","ABAB は動詞用。形容詞は1文字ずつ重ねて AABB（高高兴兴）にする。"],"ref":"HSK 3.0 g3-2-009 · g3-2-003"}],"ex":[["这条路长长的。","Zhè tiáo lù chángcháng de.","ถนนสายนี้ยาวเหยียดเลย","This road is nice and long.","Con đường này dài tít tắp.","この道は長々と続いています。","长长的"],["女孩儿的眼睛大大的。","Nǚháir de yǎnjing dàdà de.","ตาของเด็กหญิงกลมโตน่ารัก","The girl's eyes are nice and big.","Đôi mắt cô bé to tròn.","女の子の目はぱっちり大きいです。","大大的"],["你慢慢地走，别跑。","Nǐ mànmàn de zǒu, bié pǎo.","คุณค่อย ๆ เดินช้า ๆ อย่าวิ่งนะ","Walk nice and slowly; don't run.","Bạn đi từ từ thôi, đừng chạy.","ゆっくり歩いてね、走らないで。","慢慢"],["大家高高兴兴地回家了。","Dàjiā gāogāo-xìngxìng de huí jiā le.","ทุกคนกลับบ้านอย่างดีอกดีใจ","Everyone went home happily.","Mọi người vui vẻ về nhà rồi.","みんな嬉しそうに帰りました。","高高兴兴"],["今天大家高高兴兴的。","Jīntiān dàjiā gāogāo-xìngxìng de.","วันนี้ทุกคนต่างดีอกดีใจกันมาก","Everyone is nice and happy today.","Hôm nay mọi người ai cũng vui vẻ.","今日はみんなウキウキしています。","高高兴兴"]],"err":[["今天大家很高高兴兴。","今天大家高高兴兴的。","ห้ามใส่ 很 / 非常 / 太 หน้าคุณศัพท์ที่ซ้ำแล้ว","Never put 很 / 非常 / 太 before a reduplicated adjective.","形容词重叠前不能加“很、非常、太”。","Không thêm 很 / 非常 / 太 trước tính từ lặp.","重ね型形容詞の前に「很・非常・太」は置けない。"],["大家高兴高兴地回家了。","大家高高兴兴地回家了。","คุณศัพท์ 2 พยางค์ซ้ำแบบ AABB (高高兴兴) ไม่ใช่ ABAB","2-syllable adjectives use AABB (高高兴兴), not ABAB.","双音节形容词用 AABB（高高兴兴），不用 ABAB。","Tính từ 2 âm tiết dùng AABB (高高兴兴).","2音節形容詞は ABAB ではなく AABB（高高兴兴）。"]],"rel":["g3-2-003","g3-2-030","g3-1-015"]},"g3-2-010":{"t":["จำนวนมากและประมาณการ: 万 (หมื่น) / 好多 (เยอะมาก) / 多 (กว่า)","Numbers: 万 (10,000), 好多 (lots of) & 多 (over/more than)","词类·数词：万、好多、多","Số từ: 万 (vạn/10 nghìn), 好多 (rất nhiều), 多 (hơn)","数詞：万・好多・多"],"f":["数词 + 万（一万 = 10,000 / 两万 = 20,000）","好多 +（量词）+ 名词（好多人 / 好多书，口语）","整十数 + 多 + 量词（十多个人）· 数词 + 量词 + 多（两年多）"],"why":["คำบอกจำนวนสำคัญ 3 ตัวใน HSK 2: (1) 万 = 'หมื่น' (10,000) — ภาษาจีนนับแบ่งทีละ 4 หลัก (个十百千 → 万) จึงต้องระวังเวลาแปลจากอังกฤษหรือไทย เช่น 20,000 = 两万, 15,000 = 一万五千 (2) 好多 = 'เยอะแยะเลย' (ภาษาพูดคล้าย 很多) วางหน้าคำนามหรือลักษณนามได้ (好多人, 好多本书) (3) 多 = 'กว่า / เศษ' ใช้บอกจำนวนโดยประมาณ 2 ตำแหน่ง: หลังเลขลงท้ายศูนย์วางหน้าลักษณนาม (十多个人 = สิบกว่าคน) แต่เลข 1–9 วางหลังลักษณนาม (两年多 = สองปีกว่า) · ข้อควรระวัง: (1) ห้ามใส่ 很 หน้า 好多 (很好多人 ผิด!) (2) เลข 1–9 ห้ามวาง 多 หน้าลักษณนาม (三多本书 ผิด! ต้องเป็น 三本书 ไม่ใช่ — ต้องวางหลังหน่วยต่อเนื่องเช่น 三个多小时 / 两块多)","Three key HSK 2 number words: (1) 万 = 10,000 (Chinese groups digits in fours: 20,000 = 两万, 15,000 = 一万五千). (2) 好多 = 'lots of / so many' (colloquial synonym of 很多: 好多人, 好多书). (3) 多 = 'over / more than' for approximations: after round tens put 多 BEFORE the measure word (十多个人), while for 1–9 put 多 AFTER a divisible measure word (两年多, 三块多). · Cautions: (1) NEVER put 很 before 好多 (never 很好多人). (2) Never put 多 before a measure word after 1–9.","三个核心数词：（1）“万”＝10,000（汉语按四位分节：两万＝20,000）；（2）“好多”＝很多，口语色彩强（好多人、好多书）；（3）“多”表概数：整十数后“多”放量词前（十多个人），1～9后“多”放可分量词后（两年多、三块多）。 · 注意：“好多”前绝不能加“很”（不说“很好多人”）。","3 số từ HSK 2: (1) 万 = 10.000 (tiếng Trung tách 4 chữ số: 两万 = 20.000); (2) 好多 = 'rất nhiều' (khẩu ngữ: 好多人, 好多书); (3) 多 = 'hơn': sau số tròn chục đặt TRƯỚC lượng từ (十多个人), sau 1–9 đặt SAU lượng từ chia nhỏ được (两年多). · Lưu ý: KHÔNG thêm 很 trước 好多.","3つの重要数詞：（1）「万」＝10,000（中国語は4桁区切り：两万＝20,000）、（2）「好多」＝たくさんの（口語：好多人・好多书）、（3）「多」＝〜余り：十の倍数の後は量詞の前（十多个人）、1〜9の後は量詞の後ろ（两年多）。 · 注意：「好多」の前に「很」は付けられない。"],"use":[{"ok":true,"zh":"这个商场今天有好多人。","fix":"","py":"Zhège shāngchǎng jīntiān yǒu hǎoduō rén.","tr":["วันนี้ห้างสรรพสินค้านี้มีคนเยอะแยะเลย","There are so many people at this mall today.","Hôm nay trung tâm thương mại này có rất nhiều người.","このモールは今日たくさんの人がいます。"],"h":["ใช้ 好多 แทน 很多 ในภาษาพูดได้เลย (ไม่ต้องใส่ 很 ข้างหน้า)","Use colloquial 好多 ('so many') directly before a noun — no 很 needed","口语直接用“好多＋名词”，前不加“很”","Khẩu ngữ dùng thẳng 好多 + danh từ, không thêm 很","口語では「好多＋名詞」をそのまま使う（「很」不要）"],"w":["ทำได้และเป็นธรรมชาติมาก เพราะ 好 ใน 好多 ทำหน้าที่เน้นความมากอยู่แล้ว (เทียบเท่า 很多 แต่ให้ความรู้สึกภาษาพูดใกล้ชิดกว่า)","Works very naturally because 好 in 好多 already carries the emphatic 'so' — no extra 很 allowed.","“好多”本身已含程度强调，直接修饰名词，口语非常地道。","Đúng vì chữ 好 trong 好多 đã nhấn mạnh mức độ rồi, không cần 很.","「好多」の「好」自体が強い程度を表すため、「很」なしで自然に名詞を修飾する。"],"ref":"HSK 3.0 g3-2-010"},{"ok":true,"zh":"我学了两年多汉语。","fix":"","py":"Wǒ xuéle liǎng nián duō Hànyǔ.","tr":["ฉันเรียนภาษาจีนมาสองปีกว่าแล้ว","I have studied Chinese for over two years.","Tôi đã học tiếng Trung hơn hai năm rồi.","中国語を2年余り勉強しました。"],"h":["ตัวเลข 1–9 + หน่วยที่แบ่งย่อยได้ + 多 (两年多 / 五块多)","Digits 1–9 + divisible unit + 多 (两年多 / 五块多)","1～9＋可分量词＋“多”（两年多、五块多）","Số 1–9 + đơn vị chia nhỏ được + 多 (两年多)","1〜9＋分割可能な量詞＋「多」（两年多・五块多）"],"w":["ทำได้เพราะ ปี (年), ชั่วโมง (小时), เงินหยวน (块) แบ่งเป็นเศษย่อยได้ (เช่น 2 ปี 3 เดือน) จึงวาง 多 ไว้หลังลักษณนามเป็น 两年多","Works because 年 (year), 小时 (hour), and 块 (yuan) can be subdivided (e.g., 2.3 years), so 多 follows the unit: 两年多.","“年、小时、块”可以有小数零头，数字小于10时“多”放在量词后：两年多。","Đúng vì 年, 小时, 块 có thể chia lẻ nên 多 đặt SAU lượng từ: 两年多.","「年・小时・块」は端数が出せるため、1〜9のときは量詞の後ろに「多」を置く（两年多）。"],"ref":"HSK 3.0 g3-2-010 · g3-2-078"},{"ok":false,"zh":"商场里有很好多人。","fix":"商场里有好多人。","py":"Shāngchǎng lǐ yǒu hǎoduō rén.","tr":["ในห้างมีคนเยอะแยะเลย","There are lots of people in the mall.","Trong trung tâm thương mại có rất nhiều người.","モールにはたくさんの人がいます。"],"h":["ห้ามใส่ 很 หน้า 好多 (很好多 ผิด!)","NEVER put 很 before 好多 (很好多 is wrong!)","“好多”前面绝不能再加“很”","Tuyệt đối không thêm 很 trước 好多","「好多」の前に「很」は絶対に付けない"],"w":["ไม่ได้ เพราะ 好 ใน 好多 เป็นคำเน้นระดับอยู่แล้ว (เหมือน 很) ถ้าใส่ 很 นำหน้าอีกจะซ้อนระดับคำวิเศษณ์ผิดไวยากรณ์ ให้เลือก 很多人 หรือ 好多人","Wrong because 好 in 好多 already acts as the intensifier; choose EITHER 很多人 OR 好多人, never 很好多人.","不行，“好多”里的“好”已相当于“很”，不能叠用成“很好多”。","Không được vì 好 đã tương đương 很 rồi; chỉ chọn 很多人 hoặc 好多人.","「好多」の「好」がすでに「很」に相当するため「很好多」は重複エラー。"],"ref":"HSK 3.0 g3-2-010"},{"ok":false,"zh":"我学了两多年汉语。","fix":"我学了两年多汉语。","py":"Wǒ xuéle liǎng nián duō Hànyǔ.","tr":["ฉันเรียนภาษาจีนมาสองปีกว่าแล้ว","I studied Chinese for over two years.","Tôi đã học tiếng Trung hơn hai năm.","中国語を2年余り勉強しました。"],"h":["เลข 1–9 ห้ามวาง 多 ไว้หน้าลักษณนาม (ต้องเป็น 两年多 ไม่ใช่ 两多年!)","For numbers 1–9, NEVER put 多 before the measure word (两年多, not 两多年!)","个位数后“多”只能放量词后（两年多），不能放量词前","Với số 1–9, KHÔNG đặt 多 trước lượng từ (phải là 两年多)","1〜9のとき「多」を量詞の前に置けない（两多年×→两年多○）"],"w":["ไม่ได้ เพราะ 多 วางหน้าลักษณนามได้เฉพาะเลขหลักสิบขึ้นไปที่ลงท้ายด้วยศูนย์เท่านั้น (เช่น 十多年 = สิบกว่าปี, 二十多块) ส่วนเลข 1–9 ต้องวาง 多 หลังลักษณนามเสมอ: 两年多","Wrong because 多 goes BEFORE the unit only after round tens/hundreds (十多年, 二十多块); after 1–9 it MUST follow the unit: 两年多.","不行，只有整十、整百等数词后“多”才放量词前（十多年）；个位数只能放量词后（两年多）。","Không được vì 多 chỉ đứng trước lượng từ sau số tròn chục (十多年); số lẻ 1–9 bắt buộc đặt sau lượng từ (两年多).","量詞の前に「多」が来るのは十の倍数以上のみ（十多年）。1〜9は必ず量詞の後ろ（两年多）。"],"ref":"HSK 3.0 g3-2-010 · g3-2-077 · g3-2-078"}],"ex":[["这里有一万人。","Zhèlǐ yǒu yī wàn rén.","ที่นี่มีคนหนึ่งหมื่นคน","There are ten thousand people here.","Ở đây có một vạn (10 nghìn) người.","ここには1万人います。","万"],["两万块钱太贵了。","Liǎng wàn kuài qián tài guì le.","สองหมื่นหยวนแพงเกินไปแล้ว","Twenty thousand yuan is too expensive.","Hai vạn tệ đắt quá rồi.","2万元は高すぎます。","两万"],["今天商场里有好多人。","Jīntiān shāngchǎng lǐ yǒu hǎoduō rén.","วันนี้ในห้างมีคนเยอะแยะเลย","There are so many people in the mall today.","Hôm nay trong trung tâm thương mại có rất nhiều người.","今日モールにはたくさんの人がいます。","好多"],["教室里有十多个学生。","Jiàoshì lǐ yǒu shí duō ge xuésheng.","ในห้องเรียนมีนักเรียนสิบกว่าคน","There are over ten students in the classroom.","Trong phòng học có hơn mười học sinh.","教室に10人以上の学生がいます。","十多"],["我在中国住了两年多。","Wǒ zài Zhōngguó zhùle liǎng nián duō.","ฉันอยู่ประเทศจีนมาสองปีกว่าแล้ว","I lived in China for over two years.","Tôi đã sống ở Trung Quốc hơn hai năm.","中国に2年余り住みました。","两年多"]],"err":[["商场里有很好多人。","商场里有好多人。","ห้ามใส่ 很 หน้า 好多 (เลือก 很多人 หรือ 好多人)","Never put 很 before 好多 (pick 很多人 or 好多人).","“好多”前不能加“很”。","Không thêm 很 trước 好多.","「好多」の前に「很」は付けない。"],["我学了两多年汉语。","我学了两年多汉语。","เลข 1–9 วาง 多 หลังลักษณนามเสมอ (两年多 ไม่ใช่ 两多年)","For 1–9, place 多 AFTER the measure word (两年多).","1～9后“多”放量词后：两年多。","Số 1–9 đặt 多 SAU lượng từ: 两年多.","1〜9のときは量詞の後ろに「多」（两年多）。"]],"rel":["g3-2-077","g3-2-078","g3-1-011"]},"g3-2-011":{"t":["ลักษณนามเฉพาะ HSK 2: 条 / 位 / 间 / 名","Measure words: 条 / 位 / 间 / 名","专用名量词：条、位、间、名","Lượng từ chuyên dụng: 条 / 位 / 间 / 名","名量詞：条・位・间・名"],"f":["条（长条形/鱼/狗/裤子/路）：一条裤子 / 一条鱼 / 一条路","位（敬称人）：一位老师 · 间（房间/教室）：一间房间 · 名（正式人数）：两名学生"],"why":["ลักษณนามเฉพาะ 4 ตัวหลักใน HSK 2 ที่ช่วยอัปเกรดภาษาให้แม่นและสุภาพขึ้นมาก: (1) 条 ใช้กับสิ่งยาว ๆ/โค้งงอ (裤子 กางเกง, 路 ถนน) รวมถึงปลา (鱼) และหมา (狗) (2) 位 ใช้นับบุคคลอย่าง 'ให้เกียรติ/สุภาพ' (一位老师, 这位先生) (3) 间 ใช้นับห้อง (一间房间, 两间教室) (4) 名 ใช้นับบุคคลแบบเป็นทางการในสถิติ/ประกาศ/โรงเรียน (一名医生, 十名学生) · ข้อควรระวังสำคัญ: (1) ห้ามใช้ 位 เรียกตัวเองเด็ดขาด! (我是一位学生 ผิดมารยาท ต้องใช้ 我是一名学生 หรือ 我是一个学生) (2) กางเกงใช้ 条 (一条裤子) ต่างจากเสื้อที่ใช้ 件 (一件衣服)!","Four essential HSK 2 classifiers: (1) 条 for long/winding things (裤子 pants, 路 road) plus fish (鱼) and dogs (狗); (2) 位 polite classifier for people (一位老师, 这位先生); (3) 间 for rooms (一间房间, 两间教室); (4) 名 formal/official headcount for people (一名医生, 十名学生). · Key cautions: (1) NEVER use polite 位 for yourself (never 我是一位学生 — use 一个 or 一名). (2) Pants take 条 (一条裤子), whereas upper clothes take 件 (一件衣服).","HSK 2 四个核心名量词：（1）条：细长物（裤子、路）及鱼、狗；（2）位：敬称人物（一位老师、这位先生）；（3）间：房屋房间（一间房间、两间教室）；（4）名：正式书面统计人数（一名医生、十名学生）。 · 注意：（1）“位”表敬意，绝不能用于自己（不说“我是一位学生”）；（2）衣服用“件”，裤子用“条”。","4 lượng từ chuyên dụng HSK 2: (1) 条 cho vật dài/uốn (裤子 quần, 路 đường) và cá/chó (鱼, 狗); (2) 位 kính trọng người (一位老师); (3) 间 cho phòng (一间房间, 两间教室); (4) 名 trang trọng chỉ số lượng người (一名医生, 十名学生). · Lưu ý: KHÔNG dùng 位 tự xưng bản thân (không nói 我是一位学生); quần dùng 条 còn áo dùng 件.","HSK2の4つの名量詞：（1）「条」細長いもの（裤子・路）や魚・犬、（2）「位」人への敬称（一位老师）、（3）「间」部屋（一间房间・两间教室）、（4）「名」公的・フォーマルな人数（一名医生・十名学生）。 · 注意：（1）自分に敬称「位」は絶対に使えない（「我是一个／一名学生」）。（2）ズボンは「条」、上着は「件」。"],"use":[{"ok":true,"zh":"我买了一条黑色的裤子。","fix":"","py":"Wǒ mǎile yī tiáo hēisè de kùzi.","tr":["ฉันซื้อกางเกงสีดำมาหนึ่งตัว","I bought a pair of black pants.","Tôi đã mua một chiếc quần màu đen.","黒いズボンを1本買いました。"],"h":["กางเกง (裤子), ปลา (鱼), ถนน (路) ใช้ลักษณนาม 条","Pants (裤子), fish (鱼), and roads (路) take 条","裤子、鱼、路、狗常用量词“条”","Quần (裤子), cá (鱼), đường (路) dùng lượng từ 条","ズボン・魚・道は量詞「条」を使う"],"w":["ทำได้เพราะกางเกงมีรูปทรงเรียวยาวจึงใช้ 条 (一条裤子) ต่างจากเสื้อท่อนบนที่ใช้ 件 (一件衣服)","Works because pants have a long shape taking 条 (一条裤子), contrasting with upper garments taking 件 (一件衣服).","“裤子”呈长条形用量词“条”，区别于上衣用的“件”。","Đúng vì quần có hình dáng dài dùng 条 (khác áo dùng 件).","ズボンは細長い形なので「条」を使い、上着の「件」と区別する。"],"ref":"HSK 3.0 g3-2-011 · VOL 10 量词"},{"ok":true,"zh":"这位是我们的王老师。","fix":"","py":"Zhè wèi shì wǒmen de Wáng lǎoshī.","tr":["ท่านนี้คืออาจารย์หวังของพวกเรา","This is our Teacher Wang.","Vị này là thầy Vương của chúng tôi.","こちらは私たちの王先生です。"],"h":["แนะนำครู/ผู้ใหญ่/แขกอย่างสุภาพใช้ 位 (这位 / 一位老师)","Use 位 (这位 / 一位老师) politely for teachers, elders & guests","介绍或称呼老师、长辈、宾客用敬词“位”","Giới thiệu thầy cô/người lớn lịch sự dùng 位 (这位)","先生・目上の人・客の紹介には敬称の「位」"],"w":["ทำได้และให้เกียรติผู้ถูกแนะนำมาก สุภาพกว่า 这个 / 一个 อย่างเห็นได้ชัด","Works respectfully and sounds far more courteous than 这个 / 一个 when introducing teachers or guests.","用“这位”介绍老师和来宾，比“这个”礼貌得体得多。","Đúng và lịch sự hơn hẳn 这个 khi giới thiệu thầy cô hoặc khách.","「这个」よりずっと丁寧で礼儀正しい紹介表現になる。"],"ref":"HSK 3.0 g3-2-011 · VOL 10 量词"},{"ok":false,"zh":"我是一位学生。","fix":"我是一名学生。","py":"Wǒ shì yī míng xuésheng.","tr":["ฉันเป็นนักเรียนคนหนึ่ง","I am a student.","Tôi là một học sinh.","私は一人の学生です。"],"h":["ห้ามใช้ 位 (คำยกย่อง) เรียกตัวเอง!","NEVER use respectful 位 to refer to yourself!","“位”是敬称，绝不能用于自己","Tuyệt đối không dùng 位 để tự xưng bản thân!","敬称の「位」を自分自身には絶対に使えない"],"w":["ไม่ได้ตามมารยาทภาษาจีน เพราะ 位 มีความหมายยกย่องให้เกียรติผู้อื่น (แปลว่า 'ท่าน') จึงใช้กับตัวเองไม่ได้ ให้ใช้ 我是一个学生 หรือ 我是一名学生","Impolite/wrong because 位 elevates the person ('esteemed'), so you never apply it to yourself — use 一个 or 一名.","不行，“位”只用来敬称别人，说自己要用“一个”或书面“一名”。","Không được vì 位 mang nghĩa kính trọng người khác; tự nói về mình dùng 一个 hoặc 一名.","「位」は相手への敬意を表すため、自分には「一个」または「一名」を使う。"],"ref":"HSK 3.0 g3-2-011 · VOL 10 量词"},{"ok":false,"zh":"我买了一件裤子。","fix":"我买了一条裤子。","py":"Wǒ mǎile yī tiáo kùzi.","tr":["ฉันซื้อกางเกงมาหนึ่งตัว","I bought a pair of pants.","Tôi đã mua một chiếc quần.","ズボンを1本買いました。"],"h":["กางเกงใช้ 条 ไม่ใช้ 件","Pants take 条, NOT 件","裤子用量词“条”，不用“件”","Quần dùng lượng từ 条, không dùng 件","ズボンには「件」でなく「条」を使う"],"w":["ไม่ได้ เพราะในภาษาไทยใช้ 'ตัว' เหมือนกันทั้งเสื้อและกางเกง แต่ภาษาจีนแยกชัด: เสื้อใช้ 件 (一件衣服) ส่วนกางเกงใช้ 条 (一条裤子)","Wrong because Thai uses 'ตัว' for both, while Chinese separates 件 (upper clothes) from 条 (pants).","不行，上衣用“件”，裤子固定用量词“条”（一条裤子）。","Không được vì áo dùng 件 còn quần bắt buộc dùng 条 (一条裤子).","上着は「件」、ズボンは「条」（一条裤子）と明確に使い分ける。"],"ref":"VOL 10 量词"}],"ex":[["我买了一条黑色的裤子。","Wǒ mǎile yī tiáo hēisè de kùzi.","ฉันซื้อกางเกงสีดำมาหนึ่งตัว","I bought a pair of black pants.","Tôi mua một chiếc quần màu đen.","黒いズボンを1本買いました。","条"],["他买了一条鱼。","Tā mǎile yī tiáo yú.","เขาซื้อปลามาหนึ่งตัว","He bought a fish.","Anh ấy đã mua một con cá.","彼は魚を1匹買いました。","条"],["这位是我们的王老师。","Zhè wèi shì wǒmen de Wáng lǎoshī.","ท่านนี้คืออาจารย์หวังของพวกเรา","This is our Teacher Wang.","Vị này là thầy Vương của chúng tôi.","こちらは私たちの王先生です。","位"],["这里有两间教室。","Zhèlǐ yǒu liǎng jiān jiàoshì.","ที่นี่มีห้องเรียนสองห้อง","There are two classrooms here.","Ở đây có hai phòng học.","ここに教室が2つあります。","间"],["我们班有二十名学生。","Wǒmen bān yǒu èrshí míng xuésheng.","ห้องเรียนพวกเรามีนักเรียนยี่สิบคน","Our class has twenty students.","Lớp chúng tôi có 20 học sinh.","私たちのクラスには20名の学生がいます。","名"]],"err":[["我是一位学生。","我是一名学生。","位 ใช้ยกย่องผู้อื่นเท่านั้น ห้ามใช้กับตัวเอง (ใช้ 一个 หรือ 一名)","位 is respectful for others only — never for yourself (use 一个 or 一名).","“位”不能用于自己，说“我是一名／一个学生”。","Không dùng 位 cho bản thân (dùng 一个 hoặc 一名).","敬称「位」は自分に使えない（「一名／一个」にする）。"],["我买了一件裤子。","我买了一条裤子。","กางเกงใช้ลักษณนาม 条 ไม่ใช่ 件","Pants take 条, not 件.","裤子用量词“条”，不用“件”。","Quần dùng lượng từ 条, không dùng 件.","ズボンの量詞は「件」ではなく「条」。"]],"rel":["g3-1-012","g3-2-012","g3-1-032"]},"g3-2-012":{"t":["ลักษณนามยืมจากภาชนะ: 包 (ห่อ / ซอง / ถุง)","Container measure word: 包 (pack / bag / packet)","借用名量词：包","Lượng từ mượn từ đồ chứa: 包 (gói / túi)","借用量詞（容器）：包（1袋・1パック）"],"f":["数词 / 这 / 那 + 包 + 物品（一包药 / 两包茶 / 一包面包）"],"why":["包 เดิมเป็นคำนามแปลว่า 'กระเป๋า/ห่อ' (เช่น 书包 = กระเป๋านักเรียน) ที่ยืมมาใช้เป็นลักษณนามนับของที่บรรจุเป็นห่อ เป็นซอง หรือเป็นถุง (เช่น 一包药 = ยาหนึ่งห่อ/ซอง, 两包红茶 = ชาแดงสองห่อ, 一包面包 = ขนมปังหนึ่งถุง) · กฎเหมือน 杯 ใน HSK 1 เป๊ะ: (1) วางตรงหน้าคำนามสิ่งของได้เลยโดยไม่ต้องใส่ 的 หรือ 个 คั่น (一包药 ไม่ใช่ 一包个药) (2) ถ้านับตัวกระเป๋าจริง ๆ (คำนาม 书包) ให้ใช้ 个 ตามปกติ (一个书包)","包 ('bag/pack') is borrowed as a container measure word for packaged items: 一包药 ('a packet of medicine'), 两包红茶 ('two packs of black tea'), 一包面包 ('a bag of bread'). · Same rule as 杯: (1) Place bare 包 directly before the contents with no 个 or 的 (一包药). (2) When counting physical bags (书包), use 个 as usual (一个书包).","“包”借用作量词，计量成包、成袋包装的物品：一包药、两包红茶、一包面包。 · 与“杯”同理：（1）直接修饰物品名词，不加“个”或“的”；（2）指书包物体本身时用量词“个”（一个书包）。","包 được mượn làm lượng từ cho đồ đóng gói/túi: 一包药 (một gói thuốc), 两包红茶 (hai gói hồng trà), 一包面包 (một túi bánh mì). · Lưu ý: nối thẳng danh từ không thêm 个/的; còn đếm bản thân chiếc cặp dùng 一个书包.","「包」は袋・パック入りのものを数える借用量詞：一包药（薬1袋）、两包红茶（紅茶2パック）、一包面包（パン1袋）。 · 「杯」と同じく直接名詞の前に置き「个・的」不要。かばん自体を数えるときは「一个书包」。"],"use":[{"ok":true,"zh":"我在药店买了两包药。","fix":"","py":"Wǒ zài yàodiàn mǎile liǎng bāo yào.","tr":["ฉันซื้อยามาจากร้านขายยาสองซอง","I bought two packets of medicine at the pharmacy.","Tôi đã mua hai gói thuốc ở hiệu thuốc.","薬局で薬を2袋買いました。"],"h":["นับของที่บรรจุเป็นซอง/ถุง ใช้ ตัวเลข + 包 + ชื่อของ (ไม่ใส่ 的)","Count packaged goods with Number + 包 + item (no 的)","“数词＋包＋物品”计量成包物品（不加“的”）","Đếm đồ đóng gói: Số + 包 + đồ vật (không thêm 的)","袋詰めのものは「数詞＋包＋物」（「的」不要）"],"w":["ทำได้เพราะ 包 ทำหน้าที่เป็นลักษณนามบอกปริมาณเป็นห่อ/ซอง จึงวางเชื่อมเลข 两 กับ 药 ได้ทันที","Works directly because 包 measures the packets of medicine cleanly between 两 and 药.","“包”直接作容器量词计量成包药品，自然规范。","Đúng vì 包 làm lượng từ đo gói thuốc nối thẳng 两 với 药.","「包」が量詞として「两」と「药」を直接つないでいる。"],"ref":"HSK 3.0 g3-2-012 · VOL 10 量词"},{"ok":true,"zh":"我买了一个新书包。","fix":"","py":"Wǒ mǎile yī ge xīn shūbāo.","tr":["ฉันซื้อกระเป๋านักเรียนใบใหม่หนึ่งใบ","I bought a new schoolbag.","Tôi đã mua một chiếc cặp sách mới.","新しいかばんを1つ買いました。"],"h":["ถ้านับ 'ตัวกระเป๋า' (คำนาม 书包) ใช้ลักษณนาม 个","When counting a physical bag (书包), use measure word 个","指书包本身时用“一个书包”","Đếm bản thân chiếc cặp (书包) dùng lượng từ 个","かばん自体（书包）を数えるときは量詞「个」"],"w":["ทำได้เพราะ 书包 เป็นคำนามสิ่งของ ไม่ใช่ลักษณนามนับของข้างใน จึงใช้ 个 (一个书包) เหมือน 一个杯子","Works because 书包 is the bag noun itself (not a classifier), so it takes 个 just like 一个杯子.","此处计量的是物体“书包”本身，所以配量词“个”。","Đúng vì đây là đếm chiếc cặp sách chứ không phải đồ bên trong.","ここではかばん本体を数えているため「一个书包」になる。"],"ref":"HSK 3.0 g3-2-012"},{"ok":false,"zh":"我买了二包绿茶。","fix":"我买了两包绿茶。","py":"Wǒ mǎile liǎng bāo lǜchá.","tr":["ฉันซื้อชาเขียวมาสองห่อ","I bought two packs of green tea.","Tôi mua hai gói trà xanh.","緑茶を2パック買いました。"],"h":["จำนวน 2 ห่อต้องใช้ 两包 ห้ามใช้ 二包","Always use 两包 (never 二包) for two packs","2包必须说“两包”，不说“二包”","2 gói luôn là 两包, không nói 二包","2袋は「二包」ではなく必ず「两包」"],"w":["ไม่ได้ เพราะเมื่อ 包 ทำหน้าที่เป็นลักษณนาม เลข 2 โดด ๆ หน้าลักษณนามบังคับใช้ 两 เสมอ (两包绿茶)","Wrong because 包 is acting as a measure word here, so standalone 2 MUST use 两 (两包绿茶).","不行，“包”作量词时前面的2必须用“两”：两包绿茶。","Không được vì 包 đang làm lượng từ nên số 2 bắt buộc dùng 两 (两包绿茶).","量詞「包」の前の2は必ず「两」（两包绿茶）にする。"],"ref":"กลุ่มเทียบคำ g9 · HSK 3.0 g3-2-012"}],"ex":[["我在药店买了两包药。","Wǒ zài yàodiàn mǎile liǎng bāo yào.","ฉันซื้อยาสองซองที่ร้านขายยา","I bought two packets of medicine at the pharmacy.","Tôi mua hai gói thuốc ở hiệu thuốc.","薬局で薬を2袋買いました。","包"],["妈妈买了一包红茶。","Māma mǎile yī bāo hóngchá.","แม่ซื้อชาแดงมาหนึ่งห่อ","Mom bought a pack of black tea.","Mẹ mua một gói hồng trà.","母は紅茶を1パック買いました。","包"],["桌子上有一包面包。","Zhuōzi shàng yǒu yī bāo miànbāo.","บนโต๊ะมีขนมปังอยู่หนึ่งถุง","There is a bag of bread on the table.","Trên bàn có một túi bánh mì.","机の上にパンが1袋あります。","包"],["这包绿茶很便宜。","Zhè bāo lǜchá hěn piányi.","ชาเขียวห่อนี้ถูกมาก","This pack of green tea is very cheap.","Gói trà xanh này rất rẻ.","この緑茶のパックはとても安いです。","包"],["我想买三包包子。","Wǒ xiǎng mǎi sān bāo bāozi.","ฉันอยากซื้อซาลาเปาสามถุง","I want to buy three bags of steamed buns.","Tôi muốn mua ba túi bánh bao.","肉まんを3袋買いたいです。","包"]],"err":[["我买了二包绿茶。","我买了两包绿茶。","หน้าลักษณนาม 包 เลข 2 ใช้ 两 เสมอ (两包)","Always use 两 before measure word 包 (两包).","量词“包”前用“两”不用“二”。","Trước lượng từ 包 luôn dùng 两 (两包).","量詞「包」の前の2は必ず「两」（两包）。"]],"rel":["g3-1-013","g3-2-011","g3-1-011"]},"g3-2-013":{"t":["ลักษณนามกริยา 次: ครั้ง (บอกจำนวนครั้งที่ทำ)","Verbal measure word 次: 'times'","动量词：次","Động lượng từ 次: lần","動量詞「次」：〜回"],"f":["主语 + 动词 +（了/过）+ 数词 + 次 + 普通名词（我去过一次北京 / 看了一次电影）","人称代词宾语放“次”前：我找过他两次（绝不是“找过两次他”！）"],"why":["次 แปลว่า 'ครั้ง' เป็นลักษณนามนับจำนวนครั้งของการกระทำ (动量词) วาง 'หลังกริยา' เสมอ เช่น 去过一次北京 (เคยไปปักกิ่ง 1 ครั้ง), 看了两次电影 (ดูหนังไป 2 ครั้ง) · จุดตายเรื่องตำแหน่งกรรมกับ 次 ที่ออกสอบบ่อยมาก: (1) กรรมเป็นสิ่งของทั่วไป (电影, 饭, 书) → วาง 'หลัง' จำนวน+次 (看了两次电影) (2) กรรมเป็น 'สรรพนามบุคคล (他, 我, 你)' → บังคับวาง 'หน้า' จำนวน+次 เสมอ! (我找过他两次 — ห้ามพูด 我找过两次他!) (3) กรรมเป็นชื่อสถานที่/ชื่อคน (北京, 王老师) → วางหน้าหรือหลังก็ได้ (去过一次北京 หรือ 去过北京一次 ถูกทั้งคู่!) · ระวัง: ห้ามวาง 一次 ไว้หน้ากริยา (ห้ามพูด 我一次去过北京)","次 ('times') counts how many times an action happens and ALWAYS follows the verb (去过一次北京, 看了两次电影). · Exam-critical object placement rule: (1) Ordinary noun object → AFTER 次 (看了两次电影); (2) Personal pronoun object (他/我/你) → MUST come BEFORE 次 (找过他两次, NEVER 找过两次他!); (3) Place/person proper name → EITHER before or after (去过一次北京 / 去过北京一次). · Caution: never put 一次 before the verb.","“次”是动量词，表示动作发生的次数，必须放在动词后面。 · 宾语位置铁律：（1）普通事物名词放“次”后（看了两次电影）；（2）人称代词宾语必须放“次”前（找过他两次，绝不说“找过两次他”）；（3）地名、人名放前放后均可（去过一次北京／去过北京一次）。 · 注意：绝不能把“一次”放动词前。","次 ('lần') đếm số lần hành động, LUÔN đứng SAU động từ (去过一次北京, 看了两次电影). · Quy tắc vị trí tân ngữ cực quan trọng: (1) Danh từ thường đặt SAU 次 (看了两次电影); (2) Đại từ nhân xưng (他/我/你) BẮT BUỘC đặt TRƯỚC 次 (找过他两次, không nói 找过两次他); (3) Địa danh đặt trước hay sau đều được.","「次」は動作の回数「〜回」を表し必ず動詞の後ろに置く。 · 目的語の位置ルール：（1）一般名詞は「次」の後ろ（看了两次电影）、（2）人称代名詞（他・我・你）は必ず「次」の前（找过他两次、「找过两次他」は不可）、（3）地名は前後どちらでも可（去过一次北京／去过北京一次）。"],"use":[{"ok":true,"zh":"我去过一次北京。","fix":"","py":"Wǒ qùguo yī cì Běijīng.","tr":["ฉันเคยไปปักกิ่งหนึ่งครั้ง","I have been to Beijing once.","Tôi đã từng đi Bắc Kinh một lần.","北京へ一度行ったことがあります。"],"h":["กริยา (+ 了/过) + จำนวน + 次 + สถานที่/สิ่งของ","Verb (+ 了/过) + Number + 次 + place/noun","“动词（＋了／过）＋数词＋次＋宾语”","Động từ (+ 了/过) + Số + 次 + tân ngữ","「動詞（＋了／过）＋数詞＋次＋目的語」"],"w":["ทำได้และเป็นธรรมชาติมากตามกลุ่มเทียบคำ g38 (ชื่อสถานที่อย่าง 北京 จะพูดว่า 去过北京一次 ก็ถูกทั้งคู่)","Works cleanly per comparison group g38 (for place names like 北京, 去过北京一次 is equally valid).","“去过一次北京”规范自然；地名宾语说“去过北京一次”同样正确。","Đúng chuẩn theo nhóm g38 (với địa danh 北京 nói 去过北京一次 cũng đúng).","「去过一次北京」も「去过北京一次」もどちらも正しい。"],"ref":"กลุ่มเทียบคำ g38 · HSK 3.0 g3-2-013"},{"ok":true,"zh":"我昨天找过他两次。","fix":"","py":"Wǒ zuótiān zhǎoguo tā liǎng cì.","tr":["เมื่อวานฉันไปหาเขาสองครั้ง","I looked for him twice yesterday.","Hôm qua tôi đã tìm anh ấy hai lần.","昨日彼を2回訪ねました。"],"h":["กรรมเป็นสรรพนามคน (他 / 我 / 你) บังคับวาง 'หน้า' จำนวน + 次 เสมอ!","Personal pronoun objects (他/我/你) MUST go BEFORE Number + 次!","人称代词宾语必须放在“数词＋次”前面（找过他两次）","Đại từ nhân xưng BẮT BUỘC đặt TRƯỚC số + 次 (找过他两次)","人称代名詞は必ず「数詞＋次」の前に置く（找过他两次）"],"w":["ทำได้เพราะวางสรรพนาม 他 ชิดหลังกริยา 找过 ก่อน แล้วค่อยตามด้วยจำนวนครั้ง 两次 ตามกฎลำดับกรรมของภาษาจีน","Works strictly per Chinese word order: put pronoun 他 right after 找过 before 两次.","人称代词“他”紧跟动词“找过”，再接动量补语“两次”。","Đúng vì đại từ 他 đứng sát động từ 找过 rồi mới đến 两次.","人称代名詞「他」を動詞の直後に置き、その後に「两次」を続ける。"],"ref":"HSK 3.0 g3-2-013"},{"ok":false,"zh":"我昨天找过两次他。","fix":"我昨天找过他两次。","py":"Wǒ zuótiān zhǎoguo tā liǎng cì.","tr":["เมื่อวานฉันไปหาเขาสองครั้ง","I looked for him twice yesterday.","Hôm qua tôi đã tìm anh ấy hai lần.","昨日彼を2回訪ねました。"],"h":["ห้ามวางสรรพนามบุคคล (他 / 你 / 我) ไว้หลัง จำนวน + 次!","NEVER place a personal pronoun (他/你/我) after Number + 次!","绝不能说“找过两次他／见过一次你”","Không bao giờ đặt đại từ nhân xưng sau 次 (không nói 找过两次他)","人称代名詞を「次」の後ろに置けない（找过两次他×）"],"w":["ไม่ได้ เพราะสรรพนามคน (我, 你, 他, 她) ในภาษาจีนต้องเกาะติดหลังกริยาก่อนจำนวนครั้งเสมอ: 找过他两次, 问过你一次","Wrong because personal pronouns MUST precede the verbal measure phrase: 找过他两次, 问过你一次.","不行，人称代词宾语不能放动量词后，必须说“找过他两次”。","Không được vì đại từ nhân xưng phải đứng TRƯỚC số + 次: 找过他两次.","人称代名詞は動量補語の前に置く決まり。「找过他两次」にする。"],"ref":"HSK 3.0 g3-2-013"},{"ok":false,"zh":"我一次去过北京。","fix":"我去过一次北京。","py":"Wǒ qùguo yī cì Běijīng.","tr":["ฉันเคยไปปักกิ่งหนึ่งครั้ง","I have been to Beijing once.","Tôi đã đi Bắc Kinh một lần.","北京へ一度行ったことがあります。"],"h":["ห้ามวาง 一次 / 两次 ไว้หน้ากริยา (ยกเว้นประโยคปฏิเสธ 一次也没…)","Do not place 一次 / 两次 before the verb in affirmative sentences","肯定句中“一次／两次”作动量补语不能放动词前","Câu khẳng định không đặt 一次 / 两次 trước động từ","肯定文で「一次／两次」を動詞の前に置けない"],"w":["ไม่ได้ในประโยคบอกเล่า เพราะ 一次 เป็นส่วนเสริมบอกจำนวนครั้ง (补语) ต้องวางหลังกริยาเสมอ: 我去过一次北京","Wrong in affirmative statements: 一次 is a complement and must follow the verb: 我去过一次北京.","不行，肯定句中动量补语须在动词后：我去过一次北京。","Không được trong câu khẳng định vì 一次 là bổ ngữ phải đứng sau động từ.","肯定文では補語なので必ず動詞の後ろ（我去过一次北京）に置く。"],"ref":"HSK 3.0 g3-2-013"}],"ex":[["我去过一次北京。","Wǒ qùguo yī cì Běijīng.","ฉันเคยไปปักกิ่งหนึ่งครั้ง","I have been to Beijing once.","Tôi đã từng đi Bắc Kinh một lần.","北京へ一度行ったことがあります。","次"],["这个电影我看了两次。","Zhège diànyǐng wǒ kànle liǎng cì.","หนังเรื่องนี้ฉันดูไปสองครั้งแล้ว","I have watched this movie twice.","Bộ phim này tôi xem hai lần rồi.","この映画は2回見ました。","次"],["我昨天找过他两次。","Wǒ zuótiān zhǎoguo tā liǎng cì.","เมื่อวานฉันไปหาเขาสองครั้ง","I looked for him twice yesterday.","Hôm qua tôi đã tìm anh ấy hai lần.","昨日彼を2回訪ねました。","两次"],["你去过几次中国？","Nǐ qùguo jǐ cì Zhōngguó?","คุณเคยไปเมืองจีนกี่ครั้งแล้ว","How many times have you been to China?","Bạn đã đi Trung Quốc mấy lần rồi?","中国へ何回行ったことがありますか。","几次"],["这次考试我考得不错。","Zhè cì kǎoshì wǒ kǎo de bùcuò.","การสอบครั้งนี้ฉันทำได้ดีทีเดียว","I did pretty well on this exam.","Kỳ thi lần này tôi thi khá tốt.","今回の試験はなかなかうまくいきました。","这次"]],"err":[["我昨天找过两次他。","我昨天找过他两次。","สรรพนามคน (他/我/你) ต้องวางหน้า 两次 เสมอ","Personal pronouns MUST go before 两次 (找过他两次).","人称代词宾语必须放“次”前（找过他两次）。","Đại từ nhân xưng luôn đứng trước 两次 (找过他两次).","人称代名詞は必ず「两次」の前（找过他两次）。"],["我一次去过北京。","我去过一次北京。","จำนวนครั้ง (一次) ต้องวางหลังกริยาเสมอในประโยคบอกเล่า","Put 一次 after the verb in affirmative sentences.","肯定句中“一次”须放在动词后。","Đặt 一次 sau động từ trong câu khẳng định.","肯定文では「一次」を動詞の後ろに置く。"]],"rel":["g3-2-074","g3-1-041","g3-2-053"]},"g3-2-014":{"t":["คำวิเศษณ์ระดับ: 多 / 好 (อุทาน) / 最 (ที่สุด)","Degree adverbs: 多 / 好 (exclamatory) & 最 (superlative)","程度副词：多、好、最","Phó từ mức độ: 多 / 好 (cảm thán) / 最 (nhất)","程度副詞：多・好・最"],"f":["最 + 形容词 / 心理动词（最好吃 / 最喜欢 / 最高）","多（么）+ 形容词 + 啊！（多漂亮啊！）· 好 + 形容词 + 啊！（好累啊！）"],"why":["คำวิเศษณ์ระดับ 3 ตัวใหม่ใน HSK 2: (1) 最 = 'ที่สุด' (ขั้นสุด) วางหน้าคุณศัพท์หรือกริยาความรู้สึก (最喜欢, 最好吃, 最近 = ใกล้ที่สุด) และใช้เป็นส่วนขยายคำนามได้ (我最好的朋友) (2) 好 = 'มากจริง ๆ / จังเลย!' ใช้อุทานภาษาพูด (好累啊！= เหนื่อยจัง!, 好冷啊！= หนาวจัง!) (3) 多 = 'ช่าง…เหลือเกิน!' ในประโยคอุทาน (这里多漂亮啊！) หรือใช้ถามระดับ '…เท่าไร?' (你多高？= คุณสูงเท่าไร?, 学校离这儿多远？= ไกลแค่ไหน?) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ห้ามซ้อน 最 กับคำบอกระดับอื่น เช่น 很最喜欢 หรือ 最很好吃 (ผิด!) (2) 好 และ 多 (เชิงอุทาน) ไม่ใช้ในประโยคปฏิเสธหรือประโยคคำถามธรรมดา (ไม่พูด 今天不好冷 หรือ 今天多冷吗？)","Three new HSK 2 degree adverbs: (1) 最 = 'most / -est' (superlative before adjectives or mental verbs: 最喜欢, 最好吃, 我最好的朋友). (2) 好 = colloquial exclamatory 'so…!' (好累啊!, 好冷啊!). (3) 多 = exclamatory 'how…!' (多漂亮啊!) or asking extent (你多高？ 'How tall are you?', 多远？ 'How far?'). · Two cautions: (1) NEVER stack 最 with 很/太/非常 (never 很最喜欢!). (2) Do not use exclamatory 好 in negatives (never 不好冷).","三个程度副词：（1）“最”表最高级，修饰形容词或心理动词（最喜欢、最好吃、我最好的朋友）；（2）“好”口语感叹“非常”（好累啊！好冷啊！）；（3）“多”表感叹（多漂亮啊！）或询问程度（你多高？多远？）。 · 注意：（1）“最”不能与“很、非常、太”叠用；（2）感叹副词“好”不用于否定句。","3 phó từ mức độ HSK 2: (1) 最 = 'nhất' (最喜欢, 最好吃, 我最好的朋友); (2) 好 = cảm thán khẩu ngữ 'quá / lắm!' (好累啊!, 好冷啊!); (3) 多 = cảm thán (多漂亮啊!) hoặc hỏi mức độ (你多高？多远？). · Lưu ý: (1) KHÔNG ghép 最 với 很/非常/太; (2) Không dùng 好 cảm thán trong câu phủ định.","3つの程度副詞：（1）「最」最上級「一番〜」（最喜欢・最好吃・我最好的朋友）、（2）「好」口語の感嘆「すごく〜！」（好累啊！・好冷啊！）、（3）「多」感嘆「なんて〜！」（多漂亮啊！）や程度質問（你多高？・多远？）。 · 注意：（1）「最」と「很・非常・太」は重ねない。（2）感嘆の「好」は否定文に使えない。"],"use":[{"ok":true,"zh":"我最喜欢喝奶茶。","fix":"","py":"Wǒ zuì xǐhuan hē nǎichá.","tr":["ฉันชอบดื่มชานมที่สุด","I like drinking milk tea the most.","Tôi thích uống trà sữa nhất.","私はタピオカミルクティーを飲むのが一番好きです。"],"h":["ขั้นสุด 'ที่สุด' วาง 最 หน้าคุณศัพท์หรือกริยาความรู้สึก (喜欢 / 爱 / 想)","Put 最 right before an adjective or mental verb (喜欢/爱/想) for superlative","“最＋形容词／心理动词”表最高级","Đặt 最 trước tính từ hoặc động từ tâm lý (喜欢/爱) để so sánh nhất","最上級は「最＋形容詞／心理動詞」"],"w":["ทำได้เพราะ 喜欢 เป็นกริยาความรู้สึกที่บอกระดับได้ จึงวาง 最 ไว้ข้างหน้าโดยตรงไม่ต้องใส่ 很","Works because 喜欢 is a gradable mental verb that takes 最 directly without 很.","“喜欢”是心理动词，可直接受“最”修饰，不加“很”。","Đúng vì 喜欢 là động từ tâm lý có mức độ, nhận thẳng 最 mà không cần 很.","心理動詞「喜欢」に直接「最」を付けて最上級を表す。"],"ref":"HSK 3.0 g3-2-014"},{"ok":true,"zh":"今天好累啊！","fix":"","py":"Jīntiān hǎo lèi a!","tr":["วันนี้เหนื่อยจังเลย!","I'm so tired today!","Hôm nay mệt quá đi mất!","今日はすごく疲れたなあ！"],"h":["อุทานภาษาพูดที่เป็นกันเอง: 好 + คุณศัพท์ + 啊！","Colloquial exclamation: 好 + Adj + 啊!","口语感叹“好＋形容词＋啊！”生动亲切","Cảm thán khẩu ngữ: 好 + tính từ + 啊!","口語の感嘆：「好＋形容詞＋啊！」"],"w":["ทำได้และเป็นภาษาพูดที่คนจีนใช้ทุกวัน (เช่น 好冷啊！, 好贵啊！, 好漂亮啊！) โดยมักลงท้ายด้วย 啊 เพื่อเพิ่มอารมณ์","Works as super-natural everyday speech (好冷啊!, 好贵啊!, 好漂亮啊!), usually paired with final 啊.","“好累啊、好冷啊”是口语高频感叹句，配句尾“啊”语气自然。","Đúng và cực kỳ tự nhiên trong khẩu ngữ (好冷啊!, 好贵啊!).","日常会話でよく使う感嘆表現。文末の「啊」と相性抜群。"],"ref":"HSK 3.0 g3-2-014 · g3-2-033"},{"ok":false,"zh":"我最很喜欢喝奶茶。","fix":"我最喜欢喝奶茶。","py":"Wǒ zuì xǐhuan hē nǎichá.","tr":["ฉันชอบดื่มชานมที่สุด","I like drinking milk tea the most.","Tôi thích uống trà sữa nhất.","ミルクティーを飲むのが一番好きです。"],"h":["ห้ามใช้ 最 คู่กับ 很 / 非常 / 太 ในตำแหน่งเดียวกัน","NEVER combine 最 with 很 / 非常 / 太","“最”绝不能与“很、非常、太”连用","Không ghép 最 với 很 / 非常 / 太","「最」と「很・非常・太」は併用不可"],"w":["ไม่ได้ เพราะคำวิเศษณ์ระดับ 2 ตัวอย่าง 最 ('ที่สุด') กับ 很 ('มาก') ขัดและซ้ำซ้อนกัน เลือกใช้อย่างใดอย่างหนึ่ง: 我最喜欢 หรือ 我很喜欢","Wrong because 最 ('most') and 很 ('very') are competing degree adverbs — pick ONLY ONE: 最喜欢 or 很喜欢.","不行，程度副词不能叠用，只能选“最喜欢”或“很喜欢”。","Không được vì hai phó từ mức độ không đi chung; chọn 最喜欢 hoặc 很喜欢.","程度副詞の重複は誤用。「最喜欢」か「很喜欢」のどちらか一つにする。"],"ref":"HSK 3.0 g3-2-014"},{"ok":false,"zh":"你最去北京。","fix":"我最想去北京。","py":"Wǒ zuì xiǎng qù Běijīng.","tr":["ฉันอยากไปปักกิ่งที่สุด","I want to go to Beijing the most.","Tôi muốn đi Bắc Kinh nhất.","一番北京に行きたいです。"],"h":["ห้ามวาง 最 หน้ากริยาการกระทำทั่วไปโดยตรง (ต้องผ่านคุณศัพท์หรือกริยาความรู้สึกอย่าง 想/喜欢)","Never put 最 directly before an ordinary action verb (use 想/喜欢)","“最”不能直接修饰一般动作动词（须加心理动词如“最想去”）","Không đặt 最 trực tiếp trước động từ hành động (phải qua 想/喜欢)","一般動作動詞の直前に「最」は置けない（「最想去」のように心理動詞を挟む）"],"w":["ไม่ได้ เพราะ 去 เป็นกริยาการกระทำที่ไม่มีระดับ 'ไปที่สุด' ต้องมีกริยาความรู้สึกอย่าง 想 (อยาก) หรือ 喜欢 (ชอบ) มารับเป็น 最想去 / 最喜欢去","Wrong because action verb 去 isn't gradable; pair 最 with a mental verb like 想 or 喜欢: 最想去.","不行，“去”不是心理动词，不能说“最去”，要说“最想去／最喜欢去”。","Không được vì 去 là động từ hành động không có mức độ; phải thêm 想/喜欢: 最想去.","一般動詞「去」には程度がないため「最想去／最喜欢去」のように心理動詞を補う。"],"ref":"HSK 3.0 g3-2-014"}],"ex":[["我最喜欢喝奶茶。","Wǒ zuì xǐhuan hē nǎichá.","ฉันชอบดื่มชานมที่สุด","I like drinking milk tea the most.","Tôi thích uống trà sữa nhất.","ミルクティーが一番好きです。","最"],["她是我在中国最好的朋友。","Tā shì wǒ zài Zhōngguó zuì hǎo de péngyou.","เธอคือเพื่อนที่ดีที่สุดของฉันในจีน","She is my best friend in China.","Cô ấy là người bạn tốt nhất của tôi ở Trung Quốc.","彼女は中国で一番の親友です。","最"],["今天好累啊！","Jīntiān hǎo lèi a!","วันนี้เหนื่อยจังเลย!","I'm so tired today!","Hôm nay mệt quá đi!","今日はすごく疲れたなあ！","好"],["这里多漂亮啊！","Zhèlǐ duō piàoliang a!","ที่นี่ช่างสวยเหลือเกิน!","How pretty it is here!","Ở đây đẹp biết bao!","ここはなんてきれいなんだろう！","多"],["学校离这儿多远？","Xuéxiào lí zhèr duō yuǎn?","โรงเรียนอยู่ห่างจากที่นี่ไกลแค่ไหน","How far is the school from here?","Trường cách đây bao xa?","学校はここからどのくらい遠いですか。","多"]],"err":[["我最很喜欢喝奶茶。","我最喜欢喝奶茶。","ห้ามซ้อน 最 กับ 很 / 非常 / 太","Never stack 最 with 很 / 非常 / 太.","程度副词“最”和“很”不能连用。","Không ghép 最 với 很.","「最」と「很」は重ねられない。"],["今天不好冷。","今天不太冷。","好 (เชิงอุทาน) ไม่ใช้ในรูปปฏิเสธ ให้ใช้ 不冷 หรือ 不太冷","Exclamatory 好 isn't used in negatives — say 不冷 or 不太冷.","感叹副词“好”不用于否定，用“不太冷”。","Không dùng 好 cảm thán ở dạng phủ định (dùng 不太冷).","感嘆の「好」は否定に使えず「不太冷」にする。"]],"rel":["g3-1-015","g3-1-051","g3-2-033"]},"g3-2-015":{"t":["คำวิเศษณ์ขอบเขต 一起: ด้วยกัน / พร้อมกัน","Scope adverb 一起: 'together'","范围副词：一起","Phó từ phạm vi 一起: cùng nhau","範囲副詞「一起」：一緒に"],"f":["复数主语 + 一起 + 动词（我们一起去吃饭吧）","A + 跟 / 和 + B + 一起 + 动词（我跟朋友一起去旅游）"],"why":["一起 แปลว่า 'ด้วยกัน / ร่วมกัน' เป็นคำวิเศษณ์ที่บังคับวาง 'หน้ากริยา' เสมอ — ตรงข้ามกับภาษาไทยที่วาง 'ด้วยกัน' ไว้ท้ายประโยค! · ใช้ได้ 2 โครงสร้างหลัก: (1) ประธานพหูพจน์ + 一起 + กริยา: 我们一起去学校, 大家一起吃饭 (2) A + 跟/和 + B + 一起 + กริยา: 我跟朋友一起去旅游 (ฉันไปเที่ยวด้วยกันกับเพื่อน) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ห้ามวาง 一起 ไว้ท้ายประโยค (我们去吃饭一起 ผิด 100%!) (2) ห้ามใช้ 一起 กับประธานคนเดียวโดยไม่มี 跟/和+อีกคน (我一起去 ผิด!)","一起 ('together') is an adverb that ALWAYS sits BEFORE the verb — the exact opposite of Thai/English 'go together'! · Two main patterns: (1) Plural subject + 一起 + Verb (我们一起去吃饭); (2) A + 跟/和 + B + 一起 + Verb (我跟朋友一起去旅游). · Two strict cautions: (1) NEVER put 一起 at the end of a sentence (never 我们去吃饭一起). (2) NEVER use 一起 with a singular subject unless paired with 跟/和 + someone else.","“一起”作副词表示共同做某事，必须放在动词前面（与泰语、英语相反）。 · 两大句式：（1）复数主语＋一起＋动词（我们一起去）；（2）A＋跟／和＋B＋一起＋动词（我跟朋友一起旅游）。 · 注意：（1）绝不能放句尾（不说“我们去吃饭一起”）；（2）不能单用单数主语（不说“我一起去”）。","一起 ('cùng nhau') là phó từ LUÔN đứng TRƯỚC động từ — ngược tiếng Việt/Anh! · 2 mẫu chính: (1) Chủ ngữ số nhiều + 一起 + động từ (我们一起去); (2) A + 跟/和 + B + 一起 + động từ (我跟朋友一起旅游). · Lưu ý: KHÔNG đặt 一起 cuối câu; không dùng với chủ ngữ số ít đứng một mình.","「一起」は副詞で必ず動詞の前に置く。 · 2つの型：（1）複数主語＋一起＋動詞（我们一起去）、（2）A＋跟／和＋B＋一起＋動詞（我跟朋友一起旅游）。 · 注意：（1）文末に置けない。（2）単数主語だけでは使えない（「我一起去」は不可）。"],"use":[{"ok":true,"zh":"我跟朋友一起去旅游。","fix":"","py":"Wǒ gēn péngyou yīqǐ qù lǚyóu.","tr":["ฉันไปเที่ยวด้วยกันกับเพื่อน","I go traveling together with my friend.","Tôi đi du lịch cùng với bạn.","友達と一緒に旅行に行きます。"],"h":["ทำกิจกรรมร่วมกับใคร: ประธาน + 跟/和 + คน + 一起 + กริยา","Do something with someone: Subject + 跟/和 + person + 一起 + Verb","“主语＋跟／和＋人＋一起＋动词”最地道","Chủ ngữ + 跟/和 + người + 一起 + động từ","「主語＋跟／和＋人＋一起＋動詞」"],"w":["ทำได้และเป็นสำนวนที่คนจีนใช้บ่อยที่สุด โดยเรียงลำดับบุพบท 跟朋友 ก่อน แล้วค่อยตามด้วย 一起 หน้ากริยา 去旅游","Works as the most idiomatic Chinese pattern: place 跟朋友 first, then 一起 right before 去旅游.","“跟朋友”引出同行对象，“一起”紧跟其后放动词前，非常地道。","Đúng và tự nhiên nhất: 跟朋友 trước rồi 一起 ngay trước động từ 去旅游.","「跟朋友」の後ろ・動詞の前に「一起」を置くのが最も自然な語順。"],"ref":"HSK 3.0 g3-2-015 · g3-2-026"},{"ok":true,"zh":"我们一起打篮球吧！","fix":"","py":"Wǒmen yīqǐ dǎ lánqiú ba!","tr":["พวกเราไปเล่นบาสเกตบอลด้วยกันเถอะ!","Let's play basketball together!","Chúng ta cùng chơi bóng rổ đi!","一緒にバスケットボールをしましょう！"],"h":["ประธานพหูพจน์ (我们 / 大家) + 一起 + กริยา","Plural subject (我们 / 大家) + 一起 + Verb","复数主语直接接“一起＋动词”","Chủ ngữ số nhiều + 一起 + động từ","複数主語＋「一起＋動詞」"],"w":["ทำได้เพราะ 我们 เป็นพหูพจน์ตั้งแต่ 2 คนขึ้นไป จึงวาง 一起 หน้ากริยา 打篮球 ได้ทันที","Works cleanly because 我们 already refers to 2+ people, placing 一起 right before 打篮球.","主语“我们”是复数，直接用“一起打篮球”简洁自然。","Đúng vì 我们 đã là số nhiều nên nối thẳng 一起打篮球.","主語「我们」が複数なのでそのまま「一起打篮球」と続けられる。"],"ref":"HSK 3.0 g3-2-015"},{"ok":false,"zh":"我们去吃饭一起吧。","fix":"我们一起去吃饭吧。","py":"Wǒmen yīqǐ qù chīfàn ba.","tr":["พวกเราไปกินข้าวด้วยกันเถอะ","Let's go eat together.","Chúng ta cùng đi ăn cơm đi.","一緒にご飯を食べに行きましょう。"],"h":["ห้ามวาง 一起 ไว้ท้ายประโยคแบบภาษาไทย/อังกฤษ ('กินข้าวด้วยกัน')","NEVER put 一起 at the end of the sentence like Thai/English","“一起”是副词，绝不能放在动词后或句尾","Tuyệt đối không đặt 一起 ở cuối câu","「一起」は副詞なので文末に置けない"],"w":["ไม่ได้ เพราะในภาษาไทยพูด 'ไปกินข้าว + ด้วยกัน' แต่ในภาษาจีน 一起 เป็นคำวิเศษณ์ ต้องอยู่หน้ากริยาเสมอ: 我们一起去吃饭吧","Wrong because unlike English 'eat together' at the end, Chinese 一起 MUST precede the verb: 我们一起去吃饭吧.","不行，“一起”必须放动词“去吃饭”前面，绝不能放句尾。","Không được vì 一起 là phó từ phải đứng TRƯỚC động từ: 我们一起去吃饭吧.","「一起」は必ず動詞「去吃饭」の前に置き、文末には置けない。"],"ref":"HSK 3.0 g3-2-015"}],"ex":[["我们一起去饭馆吧。","Wǒmen yīqǐ qù fànguǎn ba.","พวกเราไปร้านอาหารด้วยกันเถอะ","Let's go to the restaurant together.","Chúng ta cùng đi quán ăn đi.","一緒にレストランへ行きましょう。","一起"],["我跟朋友一起去旅游。","Wǒ gēn péngyou yīqǐ qù lǚyóu.","ฉันไปเที่ยวด้วยกันกับเพื่อน","I go traveling together with my friend.","Tôi đi du lịch cùng bạn.","友達と一緒に旅行に行きます。","一起"],["大家一起打篮球吧。","Dàjiā yīqǐ dǎ lánqiú ba.","ทุกคนมาเล่นบาสด้วยกันเถอะ","Let's all play basketball together.","Mọi người cùng chơi bóng rổ đi.","みんなで一緒にバスケをしましょう。","一起"],["哥哥和弟弟一起踢足球。","Gēge hé dìdi yīqǐ tī zúqiú.","พี่ชายกับน้องชายเตะฟุตบอลด้วยกัน","Older and younger brother play soccer together.","Anh trai và em trai cùng đá bóng.","兄と弟は一緒にサッカーをします。","一起"],["我们每天一起去上班。","Wǒmen měi tiān yīqǐ qù shàngbān.","พวกเราไปทำงานด้วยกันทุกวัน","We go to work together every day.","Mỗi ngày chúng tôi đều cùng đi làm.","私たちは毎日一緒に出勤します。","一起"]],"err":[["我们去吃饭一起吧。","我们一起去吃饭吧。","一起 ต้องวางหน้ากริยาเสมอ ห้ามวางท้ายประโยค","Always put 一起 BEFORE the verb, never at the end.","“一起”必须放在动词前面。","Luôn đặt 一起 TRƯỚC động từ, không đặt cuối câu.","「一起」は常に動詞の前に置く。"],["我一起去学校。","我跟朋友一起去学校。","一起 ต้องมีตั้งแต่ 2 คนขึ้นไป (ประธานพหูพจน์ หรือมี 跟/和 + อีกคน)","一起 requires 2+ people (plural subject or 跟/和 + someone).","“一起”要求涉及两人以上，单数主语须加“跟／和＋人”。","一起 cần từ 2 người trở lên (chủ ngữ số nhiều hoặc 跟/和 + người).","「一起」には2人以上が必要（複数主語または「跟／和＋人」）。"]],"rel":["g3-2-026","g3-1-022","g3-1-016"]},"g3-2-016":{"t":["คำวิเศษณ์เวลา: 已经 / 快 / 快要 / 正 / 有时候 / 还2","Time adverbs: 已经 / 快 / 快要 / 正 / 有时候 / 还2","时间副词：还2、已经、有时（候）、快、快要、正","Phó từ thời gian: 已经 / 快 / 快要 / 正 / 有时候 / 还2","時間副詞：已经・快・快要・正・有时（候）・还2"],"f":["已经 + 动词 / 形容词 + 了（我已经吃饭了 / 已经十点了）","快 / 快要 + 动词 / 形容词 + 了（快下雨了 / 火车快要来了）","正 + 动词（+ 呢）· 有时（候）+ 动词 · 还2（还早 / 还行）"],"why":["คำวิเศษณ์เวลา 6 ตัวหลักใน HSK 2 ที่ทำให้เล่าจังหวะเวลาได้เป๊ะมาก: (1) 已经…了 = '…ไปแล้วเรียบร้อย' (我已经吃完了, 已经十点了) (2) 快…了 / 快要…了 = 'ใกล้จะ…แล้ว' (快下雨了, 飞机快要到了) (3) 正 = 'กำลัง…อยู่พอดี' (คล้าย 正在 แต่สั้นกว่า: 他正看书呢) (4) 有时(候) = 'บางครั้งบางคราว' วางหน้าหรือหลังประธานก็ได้ (有时候我坐地铁) (5) 还2 = 'ก็ยัง… / ก็ถือว่า…พอสมควร' (现在还早 = ตอนนี้ยังเช้าอยู่, 这件衣服还不错 = ตัวนี้ก็โอเคนะ) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ห้ามใส่เวลาเจาะจง (เช่น 明天八点 / 下个月) หน้า 快要…了! (ถ้ามีเวลาชัดเจนให้ใช้ 就要…了 แทน) (2) ห้ามใช้ 已经 คู่กับ 没 (ห้ามพูด 我已经没吃饭 ต้องพูด 我还没吃饭!)","Six essential HSK 2 time adverbs: (1) 已经…了 = 'already' (我已经吃完了); (2) 快…了 / 快要…了 = 'about to' (快下雨了); (3) 正 = 'right in the middle of' (他正看书呢); (4) 有时(候) = 'sometimes' (before or after subject); (5) 还2 = 'still / fairly' (现在还早, 还不错). · Two strict cautions: (1) NEVER put a specific future time (like 明天八点) before 快要…了 — use 就要…了 instead! (2) NEVER pair 已经 with 没 (say 还没吃饭, never 已经没吃饭).","HSK 2 六个高频时间副词：（1）已经……了（早已完成）；（2）快／快要……了（即将发生）；（3）正（此刻正在）；（4）有时（候）（偶尔，可放主语前后）；（5）还2（尚且、还算：现在还早、还不错）。 · 两条铁律：（1）“快／快要……了”前不能带具体时间点（如“明天八点”），有具体时间须用“就要……了”；（2）不说“已经没吃饭”，要说“还没吃饭”。","6 phó từ thời gian HSK 2: (1) 已经…了 ('đã…rồi'); (2) 快/快要…了 ('sắp…rồi'); (3) 正 ('đang đúng lúc'); (4) 有时(候) ('thỉnh thoảng'); (5) 还2 ('vẫn còn / khá ổn': 现在还早, 还不错). · 2 quy tắc cứng: (1) KHÔNG đặt mốc giờ cụ thể trước 快要…了 (phải dùng 就要…了); (2) KHÔNG nói 已经没吃饭 (dùng 还没吃饭).","HSK2の6つの時間副詞：（1）「已经…了」（すでに〜した）、（2）「快／快要…了」（もうすぐ〜だ）、（3）「正」（ちょうど〜している）、（4）「有时（候）」（ときどき）、（5）「还2」（まだ・まずまず：现在还早・还不错）。 · 鉄則：（1）具体的な時刻があるときは「快要…了」不可（「就要…了」を使う）。（2）「已经没…」は不可（「还没…」）。"],"use":[{"ok":true,"zh":"我已经吃完早饭了。","fix":"","py":"Wǒ yǐjīng chīwán zǎofàn le.","tr":["ฉันกินข้าวเช้าเสร็จเรียบร้อยแล้ว","I have already finished breakfast.","Tôi đã ăn sáng xong rồi.","私はもう朝ご飯を食べ終わりました。"],"h":["เกิด/เสร็จไปแล้วใช้ 已经 + กริยา + 了 (ต้องมี 了 ปิดท้าย)","Use 已经 + verb + 了 for 'already' (keep closing 了)","“已经”常与句尾“了”配合使用","Dùng 已经 + động từ + 了 cho 'đã…rồi'","「すでに〜した」は「已经＋動詞＋了」で呼応させる"],"w":["ทำได้เพราะ 已经 (แล้ว/เรียบร้อยแล้ว) จับคู่กับ 了 ปิดท้ายประโยคครบสูตรอย่างเป็นธรรมชาติ","Works cleanly with 已经 paired with sentence-final 了 to mark completion.","“已经”与“了”前后呼应，准确表达动作早已完成。","Đúng vì 已经 luôn hô ứng tự nhiên với 了 ở cuối câu.","「已经」と文末の「了」が呼応して完了をしっかり表している。"],"ref":"HSK 3.0 g3-2-016"},{"ok":true,"zh":"天阴了，快要下雨了。","fix":"","py":"Tiān yīn le, kuàiyào xià yǔ le.","tr":["ฟ้าครึ้มแล้ว ใกล้จะฝนตกแล้ว","The sky is overcast; it's about to rain.","Trời âm u rồi, sắp mưa rồi.","空が曇ってきた、もうすぐ雨が降りそうだ。"],"h":["เหตุการณ์ใกล้จะเกิดในไม่ช้า (ไม่ระบุเวลาเป๊ะ) ใช้ 快 / 快要…了","Use 快 / 快要…了 when something is imminent without an exact timestamp","无具体时间点、表示即将发生用“快／快要……了”","Sắp xảy ra (không nêu giờ cụ thể) dùng 快 / 快要…了","具体的な時刻なしで「もうすぐ〜」は「快／快要…了」"],"w":["ทำได้เพราะดูจากท้องฟ้าครึ้มจึงคาดว่าฝนจะตกในไม่ช้า โดยไม่มีตัวเลขเวลาเจาะจงข้างหน้า","Works naturally for imminent rain inferred from overcast skies with no exact clock time.","根据“天阴了”推断即将下雨，用“快要……了”十分地道。","Đúng vì nhìn trời âm u đoán sắp mưa, không có mốc giờ cụ thể.","曇り空からもうすぐ降ると推測する場面に「快要…了」がぴったり。"],"ref":"HSK 3.0 g3-2-016 · g3-2-043"},{"ok":false,"zh":"明天八点快要上课了。","fix":"明天八点就要上课了。","py":"Míngtiān bā diǎn jiùyào shàngkè le.","tr":["พรุ่งนี้แปดโมงก็จะเข้าเรียนแล้ว","Class is about to start at 8:00 tomorrow.","8 giờ sáng mai là sắp vào học rồi.","明日の8時にはもう授業が始まります。"],"h":["มีเวลาเจาะจง (明天八点 / 下个月) ห้ามใช้ 快要…了 ให้ใช้ 就要…了 แทน!","With a specific time (明天八点), NEVER use 快要…了 — use 就要…了!","句中有具体时间词时不能用“快要……了”，必须改用“就要……了”","Có mốc thời gian cụ thể không dùng 快要…了 mà dùng 就要…了","具体的な時刻があるときは「快要…了」不可、「就要…了」を使う"],"w":["ไม่ได้ตามกฎเหล็กของภาษาจีน: 快要…了 ใช้ได้เฉพาะเหตุการณ์ 'อีกแป๊บเดียว' โดยไม่ระบุเวลาชัดเจน พอมีเวลาเจาะจงอย่าง 明天八点 ต้องเปลี่ยนเป็น 就要…了 เท่านั้น","Wrong per a classic Chinese rule: 快要…了 never takes a specific timestamp — switch to 就要…了 when a specific time like 明天八点 appears.","不行，带具体时间点（明天八点、下星期一）时绝不能用“快要……了”，只能用“就要……了”。","Không được vì có mốc thời gian cụ thể (明天八点) bắt buộc phải đổi sang 就要…了.","具体的な時刻（明天八点）があるときは「快要…了」は使えず必ず「就要…了」にする。"],"ref":"HSK 3.0 g3-2-016 · g3-2-043"},{"ok":false,"zh":"我已经没吃饭。","fix":"我还没吃饭。","py":"Wǒ hái méi chīfàn.","tr":["ฉันยังไม่ได้กินข้าวเลย","I haven't eaten yet.","Tôi vẫn chưa ăn cơm.","まだご飯を食べていません。"],"h":["ห้ามใช้ 已经 คู่กับ 没 (ใช้ 还没 แทน!)","NEVER combine 已经 with 没 — use 还没 instead!","不能说“已经没吃饭”，要说“还没吃饭”","Không nói 已经没吃饭 — phải dùng 还没吃饭","「已经没…」は不可、「还没…」を使う"],"w":["ไม่ได้ เพราะ 已经 แปลว่า 'เกิดขึ้นไปแล้ว' ขัดกับ 没 ('ยังไม่ได้เกิด') ถ้าจะบอกว่า 'ยังไม่ได้ทำ' ต้องใช้ 还没 เท่านั้น","Wrong because 已经 ('already happened') contradicts 没 ('not yet'); always say 还没.","不行，“已经”表已完成，与“没”冲突；表示至今未做必须用“还没”。","Không được vì 已经 (đã rồi) mâu thuẫn với 没 (chưa); phải dùng 还没.","「已经」と「没」は矛盾するため、「まだ〜していない」は必ず「还没」にする。"],"ref":"HSK 3.0 g3-2-016"}],"ex":[["我已经到机场了。","Wǒ yǐjīng dào jīchǎng le.","ฉันมาถึงสนามบินเรียบร้อยแล้ว","I have already arrived at the airport.","Tôi đã đến sân bay rồi.","もう空港に着きました。","已经"],["快要下雨了，我们回家吧。","Kuàiyào xià yǔ le, wǒmen huí jiā ba.","ใกล้จะฝนตกแล้ว พวกเรากลับบ้านกันเถอะ","It's about to rain; let's go home.","Sắp mưa rồi, chúng ta về nhà đi.","もうすぐ雨が降るので帰りましょう。","快要"],["他正看书呢。","Tā zhèng kàn shū ne.","เขากำลังอ่านหนังสืออยู่พอดีเลย","He is reading right now.","Anh ấy đang đọc sách đấy.","彼はちょうど本を読んでいるところです。","正"],["我有时候坐地铁上班。","Wǒ yǒushíhou zuò dìtiě shàngbān.","บางครั้งฉันก็นั่งรถไฟใต้ดินไปทำงาน","Sometimes I take the subway to work.","Thỉnh thoảng tôi đi tàu điện ngầm đi làm.","ときどき地下鉄で出勤します。","有时候"],["现在还早，再休息一会儿吧。","Xiànzài hái zǎo, zài xiūxi yīhuìr ba.","ตอนนี้ยังเช้าอยู่เลย พักอีกแป๊บหนึ่งเถอะ","It's still early; rest a little longer.","Bây giờ còn sớm, nghỉ thêm một lát đi.","まだ早いから、もう少し休んでください。","还"]],"err":[["明天八点快要上课了。","明天八点就要上课了。","มีเวลาเจาะจง (明天八点) ต้องใช้ 就要…了 ห้ามใช้ 快要…了","With a specific time (明天八点), use 就要…了 instead of 快要…了.","带具体时间点须用“就要……了”，不用“快要……了”。","Có mốc thời gian cụ thể phải dùng 就要…了, không dùng 快要…了.","具体的な時刻があるときは「快要…了」ではなく「就要…了」。"],["我已经没吃饭。","我还没吃饭。","'ยังไม่ได้ทำ' ใช้ 还没 ไม่ใช่ 已经没","Use 还没 ('not yet'), never 已经没.","表示“还没做”用“还没”，不说“已经没”。","Chưa làm dùng 还没, không nói 已经没.","「まだ〜していない」は「已经没」ではなく「还没」。"]],"rel":["g3-2-043","g3-1-017","g3-1-019"]},"g3-2-017":{"t":["คำวิเศษณ์ความถี่: 常 / 经常 (บ่อย ๆ / เป็นประจำ)","Frequency adverbs: 常 / 经常 ('often / frequently')","频率副词：常、经常","Phó từ tần suất: 常 / 经常 (thường xuyên)","頻度副詞：常・经常（よく・しょっちゅう）"],"f":["主语 + 常 / 经常 + 动词（我经常去跑步 / 他常喝咖啡）","否定：主语 + 不常 / 不经常 + 动词（我不经常看电视）"],"why":["常 และ 经常 แปลว่า 'บ่อย ๆ / เป็นประจำ' วางไว้ 'หลังประธาน หน้ากริยา' เสมอ (เหมือนภาษาอังกฤษ often) · ต่างกันเล็กน้อย: 经常 เป็นคำ 2 พยางค์จึงใช้คู่กับกริยาได้ทั้ง 1 และ 2 พยางค์อย่างลื่นไหล (经常去, 经常打篮球, 经常去旅游) ส่วน 常 สั้นกระชับนิยมในภาษาพูด (常来, 常去, 不常吃) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ห้ามใส่ 了1 หลังกริยาที่มี 经常/常 เพราะเป็นนิสัยทำประจำ ไม่ใช่เหตุการณ์ทำจบครั้งเดียว (我经常去了公园 ผิด!) (2) ปฏิเสธวาง 不 หน้า 常/经常 (不常 / 不经常 — ห้ามพูด 经常不 ในความหมายว่า 'ไม่ค่อยได้ทำ')","常 and 经常 ('often / frequently') sit after the subject and before the verb. · Nuance: 2-syllable 经常 pairs smoothly with any verb (经常去, 经常打篮球), while 1-syllable 常 is crisp in speech (常来, 不常吃). · Two strict cautions: (1) NEVER add completed 了1 to habitual 经常/常 sentences (never 我经常去了商店!). (2) Negate as 不常 / 不经常 ('not often').","“常、经常”表示动作反复高频发生，位于主语后、动词前。 · “经常”适用面广，“常”简短口语化。 · 两条注意：（1）表示经常性习惯动作时，动词后绝不能加“了1”（不说“我经常去了那家饭馆”）；（2）否定“不常做”说“不常／不经常”，而“经常不”表示“常常不做某事”。","常 và 经常 ('thường xuyên') đứng sau chủ ngữ, trước động từ. · 2 lưu ý: (1) KHÔNG thêm 了1 sau động từ chỉ thói quen với 常/经常 (không nói 我经常去了…); (2) Phủ định 'không thường làm' là 不常 / 不经常 (còn 经常不 nghĩa là 'thường xuyên không làm').","「常・经常」（よく・頻繁に）は主語の後・動詞の前に置く。 · 2大注意：（1）習慣・反復を表すため完了の「了1」は付けられない（我经常去了…×）。（2）「あまりしない」は「不常／不经常」（「经常不」は「よく〜しない」で意味が違う）。"],"use":[{"ok":true,"zh":"我经常去那家饭馆吃饭。","fix":"","py":"Wǒ jīngcháng qù nà jiā fànguǎn chīfàn.","tr":["ฉันไปกินข้าวที่ร้านอาหารร้านนั้นเป็นประจำ","I often go to that restaurant to eat.","Tôi thường xuyên đến quán ăn đó ăn cơm.","私はよくあのレストランへご飯を食べに行きます。"],"h":["นิสัยทำประจำใช้ 经常 + กริยา (โดยไม่ใส่ 了)","Use 经常 + verb for regular habits (with NO 了)","表示习惯高频动作：主语＋经常＋动词（不加“了”）","Thói quen lặp lại: Chủ ngữ + 经常 + động từ (không thêm 了)","習慣には「主語＋经常＋動詞」（「了」は付けない）"],"w":["ทำได้และเป็นธรรมชาติ 100% เพราะเล่าถึงนิสัยที่เกิดขึ้นซ้ำ ๆ เป็นประจำ จึงวาง 经常 หน้ากริยา 去 และไม่เติม 了","Works 100% naturally for a recurring habit, with 经常 before 去 and no completed 了.","“经常”放在动词前描述日常习惯，句中不加完成助词“了”。","Đúng 100% vì kể thói quen thường xuyên, không dùng 了.","日常の習慣を述べる文で、「了」を付けず「经常」を動詞の前に置いている。"],"ref":"HSK 3.0 g3-2-017"},{"ok":true,"zh":"我不常喝咖啡，我常喝绿茶。","fix":"","py":"Wǒ bù cháng hē kāfēi, wǒ cháng hē lǜchá.","tr":["ฉันไม่ค่อยดื่มกาแฟ ฉันดื่มชาเขียวเป็นประจำ","I don't drink coffee often; I often drink green tea.","Tôi không hay uống cà phê, tôi hay uống trà xanh.","コーヒーはあまり飲みません、緑茶をよく飲みます。"],"h":["'ไม่ค่อยได้ทำ' ใช้ 不常 / 不经常 (วาง 不 หน้า 常)","'Not often' puts 不 before 常/经常 (不常 / 不经常)","表示“不常做”说“不常／不经常＋动词”","'Không hay làm' đặt 不 trước 常/经常 (不常 / 不经常)","「あまり〜しない」は「不常／不经常」"],"w":["ทำได้เพราะ 不常 (ไม่บ่อย) ตรงข้ามกับ 常 (บ่อย) ได้ชัดเจน (ต่างจาก 常不 ที่แปลว่า 'มักจะไม่…เป็นประจำ' เช่น 他常不吃早饭 = เขามักไม่กินข้าวเช้า)","Works cleanly: 不常 ('not often') contrasts directly with 常 ('often'), unlike 常不 ('often fail to').","“不常”否定频率高，“常不”则表“常常不做”，语义清晰有别。","Đúng vì 不常 ('không hay') đối lập rõ với 常 ('hay').","「不常」（あまり〜ない）と「常」（よく〜する）の対比が明快。"],"ref":"HSK 3.0 g3-2-017"},{"ok":false,"zh":"我去年经常去了北京。","fix":"我去年经常去北京。","py":"Wǒ qùnián jīngcháng qù Běijīng.","tr":["ปีที่แล้วฉันไปปักกิ่งบ่อยมาก","Last year I often went to Beijing.","Năm ngoái tôi thường xuyên đi Bắc Kinh.","昨年はよく北京へ行きました。"],"h":["แม้จะเป็นเรื่องในอดีต (去年) พอมี 经常 ก็ห้ามเติม 了1!","Even in the past (去年), NEVER add 了1 with 经常!","即使说过去（去年），带“经常”的习惯动作也不能加“了1”","Kể cả quá khứ (去年), có 经常 cũng KHÔNG thêm 了1!","過去（去年）でも「经常」があれば「了1」は絶対に付けない"],"w":["ไม่ได้ เพราะผู้เรียนมักเผลอใส่ 了 เพราะเห็นคำว่า 去年 (ปีที่แล้ว) แต่ภาษาจีนถือว่า 经常 เป็นการกระทำซ้ำ ๆ เป็นประจำ จึงห้ามใส่ 了1 หลังกริยาเด็ดขาด","Wrong because learners often add 了 after seeing 去年 ('last year'), but Chinese treats past habits with 经常 as non-single completions — drop 了1!","不行，虽然有“去年”，但“经常”表反复习惯，动词后绝不能加“了1”。","Không được vì dù có 去年 nhưng 经常 là thói quen lặp lại nên tuyệt đối bỏ 了1.","「去年」があっても「经常」は反復習慣なので完了の「了1」は付けられない。"],"ref":"HSK 3.0 g3-2-017 · g3-1-062"}],"ex":[["我经常去打篮球。","Wǒ jīngcháng qù dǎ lánqiú.","ฉันไปเล่นบาสเกตบอลเป็นประจำ","I often go play basketball.","Tôi thường xuyên đi chơi bóng rổ.","私はよくバスケをしに行きます。","经常"],["他常来我家吃饭。","Tā cháng lái wǒ jiā chīfàn.","เขามากินข้าวที่บ้านฉันบ่อย ๆ","He often comes to my house to eat.","Anh ấy hay đến nhà tôi ăn cơm.","彼はよくうちへご飯を食べに来ます。","常"],["我去年经常去北京。","Wǒ qùnián jīngcháng qù Běijīng.","ปีที่แล้วฉันไปปักกิ่งบ่อยมาก","I often went to Beijing last year.","Năm ngoái tôi thường xuyên đi Bắc Kinh.","昨年よく北京へ行きました。","经常"],["妈妈经常在网上买东西。","Māma jīngcháng zài wǎngshàng mǎi dōngxi.","แม่ซื้อของออนไลน์เป็นประจำ","Mom often shops online.","Mẹ thường xuyên mua đồ trên mạng.","母はよくネットショッピングをします。","经常"],["我不常喝咖啡。","Wǒ bù cháng hē kāfēi.","ฉันไม่ค่อยดื่มกาแฟ","I don't drink coffee often.","Tôi không hay uống cà phê.","コーヒーはあまり飲みません。","不常"]],"err":[["我去年经常去了北京。","我去年经常去北京。","มี 经常 / 常 บอกนิสัยทำประจำ ห้ามใส่ 了1 แม้เป็นอดีต","Never add 了1 with habitual 经常/常, even for the past.","带“经常／常”的习惯句不能加“了1”。","Có 经常 / 常 thì không thêm 了1 kể cả quá khứ.","「经常・常」のある習慣文には過去でも「了1」を付けない。"]],"rel":["g3-2-016","g3-1-062"]},"g3-2-018":{"t":["คำปฏิเสธห้ามปราม 别: อย่า…!","Prohibition adverb 别: 'don't…!'","否定副词：别","Phó từ cấm đoán 别: đừng…!","禁止の副詞「别」：〜するな・〜しないで"],"f":["别 + 动词（+ 了）！（别说话！/ 别忘了！/ 别跑了！）"],"why":["别 แปลว่า 'อย่า…!' เป็นรูปย่อภาษาพูดที่สั้น กระชับ และใช้บ่อยที่สุดแทน 不要 ในประโยคคำสั่งห้ามหรือเตือนด้วยความห่วงใย (别说话！= อย่าพูด!, 别忘了！= อย่าลืมนะ!, 别累坏了! → 别太累了！) · เติม 了 ท้ายประโยคเป็น '别 + กริยา + 了' แปลว่า 'พอได้แล้ว / หยุดทำได้แล้ว!' (别看手机了！= เลิกเล่นมือถือได้แล้ว!) · ข้อควรระวังเด็ดขาดตามกลุ่มเทียบคำ g7: 别 ใช้ห้ามหน้ากริยาหรือคุณศัพท์เท่านั้น ห้ามใช้ 别 + คำนาม เพื่อแปลว่า 'ไม่เอา' เด็ดขาด (ห้ามพูด 我别这个 ต้องพูด 我不要这个!)","别 ('don't!') is the crisp, everyday spoken equivalent of 不要 for prohibitions and caring reminders (别说话!, 别忘了!). · Adding 了 (别 + Verb + 了) means 'stop doing that now!' (别看手机了!). · Iron rule from comparison group g7: 别 is strictly for forbidding actions — NEVER use 别 + noun to mean 'I don't want' (say 我不要这个, NEVER 我别这个!).","“别”相当于口语的“不要”，用于祈使句表禁止或关切劝阻（别说话！别忘了！）。 · “别……了”表示劝人停止正在进行的动作（别看手机了！）。 · 铁律（对比 g7）：“别”只能修饰动词或形容词，绝不能接名词表“不想要”（说“我不要这个”，不说“我别这个”）。","别 ('đừng!') là dạng khẩu ngữ gọn của 不要 dùng để cấm hoặc nhắc nhở (别说话!, 别忘了!). · 别…了 nghĩa là 'đừng làm nữa / thôi đi!' (别看手机了!). · Quy tắc thép (nhóm g7): KHÔNG dùng 别 + danh từ để nói 'không lấy' (phải dùng 我不要这个, không nói 我别这个!).","「别」（〜するな／〜しないで）は「不要」のくだけた口語形（别说话！・别忘了！）。 · 「别…了」は「もう〜するのはやめなさい」（别看手机了！）。 · 鉄則（g7）：「别」は禁止専用で名詞の前に置き「要らない」の意味にはできない（「我不要这个」、我别这个×）。"],"use":[{"ok":true,"zh":"别看手机了，快睡觉吧！","fix":"","py":"Bié kàn shǒujī le, kuài shuìjiào ba!","tr":["เลิกดูมือถือได้แล้ว รีบนอนเถอะ!","Stop looking at your phone; go to sleep!","Đừng xem điện thoại nữa, mau đi ngủ đi!","もうスマホを見るのをやめて、早く寝なさい！"],"h":["สั่งให้หยุดสิ่งที่กำลังทำอยู่ ใช้ 别 + กริยา + 了","Use 别 + Verb + 了 to tell someone to stop doing what they're doing","劝阻停止正在做的事用“别……了”","Bảo dừng việc đang làm dùng 别 + động từ + 了","今していることをやめさせるときは「别＋動詞＋了」"],"w":["ทำได้และเป็นธรรมชาติมากเพราะ 了 สื่อว่า 'เปลี่ยนจากทำอยู่เป็นหยุดทำได้แล้ว' เหมือนภาษาไทยว่า 'อย่าดูแล้วนะ!'","Works very naturally because final 了 signals stopping an ongoing action ('don't keep doing it anymore').","句尾加“了”表示改变当前状态，即“别再继续做了”。","Đúng và rất tự nhiên vì 了 cuối câu mang nghĩa 'thôi đừng làm nữa'.","文末の「了」で「今やっていることをもうやめなさい」という変化を表す。"],"ref":"กลุ่มเทียบคำ g7 · HSK 3.0 g3-2-018"},{"ok":true,"zh":"别忘了给妈妈打电话。","fix":"","py":"Bié wàngle gěi māma dǎ diànhuà.","tr":["อย่าลืมโทรหาแม่นะ","Don't forget to call Mom.","Đừng quên gọi điện cho mẹ nhé.","お母さんに電話するのを忘れないでね。"],"h":["เตือนความจำอย่างเป็นกันเองใช้ 别忘了 + กริยา","Use 别忘了 + verb for friendly reminders ('don't forget to…')","善意提醒用“别忘了……”","Nhắc nhở thân thiện dùng 别忘了 + động từ","親切な注意喚起は「别忘了＋動詞」"],"w":["ทำได้เพราะ 别 ไม่ใช่แค่สั่งห้ามดุ ๆ แต่ใช้เตือนด้วยความห่วงใยอย่าง 别忘了 (อย่าลืมนะ), 别累着 (อย่าหักโหม) ได้บ่อยมาก","Works warmly because 别 isn't just strict forbidding — it's widely used for caring reminders like 别忘了.","“别”常用于善意提醒（别忘了、别客气），语气亲切自然。","Đúng vì 别 không chỉ cấm mà còn dùng để nhắc nhở quan tâm như 别忘了.","「别」は厳しい禁止だけでなく「别忘了」「别客气」など温かい気遣いにも使う。"],"ref":"HSK 3.0 g3-2-018 · g3-2-057"},{"ok":false,"zh":"我别这个苹果。","fix":"我不要这个苹果。","py":"Wǒ bùyào zhège píngguǒ.","tr":["ฉันไม่เอาแอปเปิลลูกนี้","I don't want this apple.","Tôi không lấy quả táo này.","このりんごは要りません。"],"h":["ห้ามใช้ 别 แปลว่า 'ไม่เอา' หน้าคำนาม (ต้องใช้ 不要 เท่านั้น!)","NEVER use 别 + noun for 'I don't want' — ONLY 不要 works!","表“不想要某物”只能用“不要”，绝不能用“别”","Nói 'không lấy' trước danh từ chỉ dùng 不要, TUYỆT ĐỐI không dùng 别","「要らない」の意味で名詞の前に「别」は絶対不可（必ず「不要」）"],"w":["ไม่ได้ตามกลุ่มเทียบคำ g7 เพราะ 别 เป็นคำวิเศษณ์ห้ามปราม (ไม่ใช่กริยา) จึงรับกรรมคำนามตรง ๆ ไม่ได้ ต้องใช้ 不要 เท่านั้น: 我不要这个苹果","Wrong per comparison group g7: 别 is strictly an adverb ('don't!') and cannot take a noun object — use 我不要这个苹果.","不行，“别”是副词不能带名词宾语，表示不想要必须说“我不要这个苹果”。","Không được theo nhóm g7: 别 là phó từ không nhận tân ngữ danh từ; phải dùng 我不要这个苹果.","「别」は副詞なので名詞を目的語に取れない。「要らない」は必ず「我不要…」にする。"],"ref":"กลุ่มเทียบคำ g7"},{"ok":false,"zh":"你别去吗？","fix":"你别去！","py":"Nǐ bié qù!","tr":["คุณอย่าไปนะ!","Don't go!","Bạn đừng đi nhé!","行かないで！"],"h":["ห้ามเติม 吗 ท้ายประโยคคำสั่งห้าม 别","Never add question marker 吗 after a 别 prohibition","“别”构成祈使句，句末不能加“吗”","Không thêm 吗 vào cuối câu cấm đoán với 别","禁止の「别」の文末に「吗」は付けない"],"w":["ไม่ได้ เพราะ 别 เป็นประโยคคำสั่งห้าม (祈使句) ไม่ใช่คำถาม จึงลงท้ายด้วย 吧 (ให้นุ่มนวล) หรือ ！ ได้ แต่ห้ามใส่ 吗","Wrong because 别 forms an imperative, not a question — end with 吧 (softer) or !, never 吗.","不行，“别……”是祈使句，可加“吧”缓和语气，但绝不能加“吗”。","Không được vì 别 là câu cầu khiến (có thể thêm 吧 cho nhẹ nhàng), không thêm 吗.","「别」は祈使句なので疑問の「吗」は不可（和らげるなら「吧」を付ける）。"],"ref":"HSK 3.0 g3-2-018 · g3-2-057"}],"ex":[["别说话！","Bié shuōhuà!","อย่าพูดคุย!","Don't talk!","Đừng nói chuyện!","話さないで！","别"],["别忘了给妈妈打电话。","Bié wàngle gěi māma dǎ diànhuà.","อย่าลืมโทรหาแม่นะ","Don't forget to call Mom.","Đừng quên gọi điện cho mẹ nhé.","お母さんに電話するのを忘れないで。","别"],["别看手机了，快睡觉吧！","Bié kàn shǒujī le, kuài shuìjiào ba!","เลิกดูมือถือได้แล้ว รีบนอนเถอะ!","Stop looking at your phone and go to sleep!","Đừng xem điện thoại nữa, mau ngủ đi!","もうスマホをやめて早く寝なさい！","别"],["路很远，你别走路了。","Lù hěn yuǎn, nǐ bié zǒulù le.","ทางไกลมาก คุณอย่าเดินไปเลยนะ","It's very far; don't walk.","Đường xa lắm, bạn đừng đi bộ nữa.","道が遠いから歩かないでね。","别"],["外面很冷，别出门了！","Wàimiàn hěn lěng, bié chūmén le!","ข้างนอกหนาวมาก อย่าออกไปข้างนอกเลย!","It's very cold outside; don't go out!","Ngoài trời lạnh lắm, đừng ra ngoài nữa!","外はとても寒いから、もう出かけないで！","别"]],"err":[["我别这个苹果。","我不要这个苹果。","别 ใช้ห้ามหน้ากริยาเท่านั้น ถ้าแปลว่า 'ไม่เอา' ต้องใช้ 不要","别 is only for prohibitions; 'don't want' MUST use 不要.","“不想要”用“不要”，不用“别”。","Không lấy dùng 不要, không dùng 别.","「要らない」は「别」ではなく必ず「不要」。"],["你别去吗？","你别去！","ประโยคคำสั่งห้าม 别 ไม่ใส่ 吗 ท้ายประโยค","Never put 吗 at the end of a 别 imperative.","“别”字祈使句末尾不加“吗”。","Câu cầu khiến 别 không thêm 吗.","禁止文「别」の文末に「吗」は付けない。"]],"rel":["g3-2-057","g3-1-020","g3-1-050"]},"g3-2-019":{"t":["คำวิเศษณ์เชื่อมลำดับ: 再2 (ค่อย…ทีหลัง) / 就1 (ก็…ทันที)","Linking adverbs: 再2 ('then / after that') & 就1 ('then right away / early')","关联副词：再2、就1","Phó từ liên kết: 再2 (rồi mới) / 就1 (liền / đã sớm)","関連副詞：再2（それから）・就1（すぐ・もう）"],"f":["动作1 + 再2 + 动作2（吃完饭再走 / 休息一会儿再学习）","时间 / 条件 + 主语 + 就1 + 动词（他七点就来了 / 一下课我就回家）"],"why":["คำวิเศษณ์เชื่อมลำดับเหตุการณ์ 2 ตัวสุดสำคัญใน HSK 2: (1) 再2 แปลว่า 'แล้วค่อย…' ใช้เชื่อมกริยา 2 อย่างที่ยังไม่เกิด โดยทำอย่างแรกให้จบก่อนแล้วจึงค่อยทำอย่างที่สอง (吃完饭再去, 休息一会儿再学习) (2) 就1 มี 2 อารมณ์หลัก: (ก) ต่อเนื่องทันควัน 'พอ…ก็…ทันที' (一下课我就回家) (ข) เร็วกว่าที่คาด / ง่ายกว่าที่คิด (他七点就来了 = แค่เจ็ดโมงเขาก็มาแล้ว!) · ข้อควรระวังเด็ดขาด: (1) ทั้ง 再2 และ 就1 ต้องวาง 'หลังประธาน หน้ากริยา' เสมอ (ห้ามวาง 就 หน้าประธาน เช่น 一下课就我回家 ผิด!) (2) 再2 ใช้เฉพาะลำดับในอนาคตหรือนิสัย ไม่ใช้เล่าลำดับ 2 เหตุการณ์ที่จบไปแล้วในอดีต (อดีตใช้ 就 เช่น 昨天吃完饭我就走了)","Two essential sequence adverbs in HSK 2: (1) 再2 ('and then') connects two future/planned actions in order — finish #1 before doing #2 (吃完饭再去). (2) 就1 ('right away / already early') marks quick succession (一下课我就回家) or earlier-than-expected timing (他七点就来了). · Two strict cautions: (1) Always put 再2 / 就1 AFTER the subject and BEFORE the verb (never 一下课就我回家!). (2) 再2 is for future/planned sequences — for completed past sequences, use 就 (昨天吃完饭我就走了).","两个关键关联副词：（1）“再2”表示未发生动作的先后衔接，即“做完1然后才做2”（吃完饭再去）；（2）“就1”表示紧接着发生（一下课我就回家）或比预期更早、更快（他七点就来了）。 · 两条铁律：（1）“再、就”必须放主语后、动词前（不说“一下课就我回家”）；（2）叙述过去已完成的两件事先后，不用“再2”，常用“就”。","2 phó từ liên kết HSK 2: (1) 再2 ('rồi hãy / rồi mới') nối 2 việc chưa xảy ra theo thứ tự (吃完饭再去); (2) 就1 ('liền / đã sớm') chỉ sự nối tiếp tức thì (一下课我就回家) hoặc sớm hơn dự kiến (他七点就来了). · Lưu ý: luôn đặt 再/就 SAU chủ ngữ, TRƯỚC động từ; chuỗi việc đã xong trong quá khứ dùng 就, không dùng 再2.","2つの重要関連副詞：（1）「再2」（〜してから…する）はまだ起きていない2動作の順序をつなぐ（吃完饭再去）。（2）「就1」（すぐ〜する／もう〜も早く）は直後の動作（一下课我就回家）や早さ（他七点就来了）を表す。 · 鉄則：（1）「再・就」は必ず主語の後・動詞の前。（2）すでに完了した過去の順序には「再2」ではなく「就」を使う。"],"use":[{"ok":true,"zh":"我们吃完饭再去商场吧。","fix":"","py":"Wǒmen chīwán fàn zài qù shāngchǎng ba.","tr":["พวกเรากินข้าวให้เสร็จก่อนแล้วค่อยไปห้างกันเถอะ","Let's finish eating first, then go to the mall.","Chúng ta ăn cơm xong rồi hãy đi trung tâm thương mại nhé.","ご飯を食べ終わってからモールへ行きましょう。"],"h":["วางแผนทำกริยา 1 ให้จบแล้วค่อยทำกริยา 2 ใช้ กริยา1 + 再2 + กริยา2","Sequence two planned actions with Action 1 + 再2 + Action 2","未发生动作先后衔接：动作1＋再2＋动作2","Xếp thứ tự 2 việc dự định: Việc 1 + 再2 + Việc 2","予定の2動作の順序は「動作1＋再2＋動作2」"],"w":["ทำได้เพราะทั้ง 'กินข้าว' และ 'ไปห้าง' ยังไม่เกิด เป็นการนัดแนะลำดับก่อน-หลังอย่างชัดเจนและเป็นธรรมชาติ","Works cleanly because both eating and going to the mall are planned future actions in sequence.","两件事均尚未发生，“再”清楚标示先吃完饭再去商场的先后顺序。","Đúng vì cả hai việc đều chưa xảy ra, 再 nối thứ tự trước–sau rất tự nhiên.","どちらもこれからの予定なので「再」で「食べてから行く」順序を明確に示せる。"],"ref":"HSK 3.0 g3-2-019"},{"ok":true,"zh":"他七点就到教室了。","fix":"","py":"Tā qī diǎn jiù dào jiàoshì le.","tr":["แค่เจ็ดโมงเขาก็มาถึงห้องเรียนแล้ว (มาเร็วมาก!)","He arrived at the classroom as early as 7:00!","Mới 7 giờ anh ấy đã đến phòng học rồi!","彼は7時にはもう教室に着いていました！"],"h":["เร็วกว่าที่คิด / แป๊บเดียวก็เสร็จ ใช้ เวลา + 就1 + กริยา + 了","Use Time + 就1 + Verb + 了 for 'as early as / already'","表示时间早、速度快用“时间＋就1＋动词＋了”","Nhấn mạnh sớm/nhanh dùng Thời gian + 就1 + động từ + 了","予想より早い・すぐのときは「時間＋就1＋動詞＋了」"],"w":["ทำได้เพราะ 就1 ช่วยใส่อารมณ์ของผู้พูดว่า '7 โมงถือว่าเร็วมาก!' (ต่างจากบอกข้อเท็จจริงเฉย ๆ ว่า 他七点到教室)","Works expressively because 就1 adds the speaker's nuance that 7:00 is notably early.","“就”带有说话人觉得“时间很早”的主观评价，并常配句尾“了”。","Đúng vì 就1 nhấn mạnh cảm nhận của người nói là 7 giờ rất sớm.","「就」を入れることで話し手が「7時は早い」と感じているニュアンスが伝わる。"],"ref":"HSK 3.0 g3-2-019"},{"ok":false,"zh":"一下课就我回家了。","fix":"一下课我就回家了。","py":"Yī xiàkè wǒ jiù huí jiā le.","tr":["พอเลิกเรียนฉันก็กลับบ้านทันทีเลย","As soon as class ended, I went straight home.","Vừa tan học là tôi về nhà ngay.","授業が終わるやいなや私はすぐ帰りました。"],"h":["ห้ามวาง 就 หน้าประธาน! (ต้องเป็น ประธาน + 就 + กริยา)","NEVER put 就 before the subject — always Subject + 就 + Verb!","“就”作副词绝不能放在主语前（不说“就我回家”）","Không bao giờ đặt 就 trước chủ ngữ (phải là 我就回家)","「就」は副詞なので主語の前に置けない（我就回家にする）"],"w":["ไม่ได้ เพราะ 就 เป็นคำวิเศษณ์ที่เกาะติดหน้ากริยาเท่านั้น ไม่ใช่คำสันธานแบบ 'then' ในภาษาอังกฤษ จึงต้องวางหลังประธาน 我 เสมอ: 一下课我就回家了","Wrong because 就 is an adverb, not a conjunction like 'then' — always put it AFTER subject 我: 一下课我就回家了.","不行，“就”是副词必须放主语“我”后、动词前：一下课我就回家了。","Không được vì 就 là phó từ phải đứng SAU chủ ngữ 我: 一下课我就回家了.","「就」は副詞なので主語「我」の後ろ・動詞の前に置く。"],"ref":"HSK 3.0 g3-2-019 · g3-2-071"},{"ok":false,"zh":"昨天我吃完饭再回家了。","fix":"昨天我吃完饭就回家了。","py":"Zuótiān wǒ chīwán fàn jiù huí jiā le.","tr":["เมื่อวานพอกินข้าวเสร็จฉันก็กลับบ้านเลย","Yesterday after finishing dinner I went home.","Hôm qua tôi ăn cơm xong liền về nhà.","昨日ご飯を食べ終えてすぐ帰りました。"],"h":["ลำดับ 2 เหตุการณ์ที่จบไปแล้วในอดีต ใช้ 就 (ไม่ใช้ 再2!)","For two COMPLETED past events in sequence, use 就 (not 再2!)","过去已完成的两件事衔接用“就”，不用“再2”","Chuỗi 2 việc ĐÃ xong trong quá khứ dùng 就, không dùng 再2","すでに終わった過去の連続動作には「再2」ではなく「就」"],"w":["ไม่ได้ เพราะ 昨天…了 บอกชัดว่าเหตุการณ์ทั้งหมดจบลงไปแล้วในอดีต ส่วน 再2 ใช้ได้เฉพาะสิ่งที่ยังไม่เกิดหรือพูดถึงแผนการในอนาคตเท่านั้น","Wrong because 昨天…了 is already finished in the past, whereas 再2 only links unrealized/future sequences — use 就.","不行，“再2”只用于未实现的计划或将来，叙述过去已发生的顺承须用“就”。","Không được vì 再2 chỉ dùng cho kế hoạch chưa xảy ra; quá khứ đã xong phải dùng 就.","「再2」は未実現の予定専用。完了した過去の順序は「就」を使う。"],"ref":"HSK 3.0 g3-2-019"}],"ex":[["你休息一会儿再学习吧。","Nǐ xiūxi yīhuìr zài xuéxí ba.","คุณพักสักครู่แล้วค่อยเรียนต่อนะ","Rest a little while, then study.","Bạn nghỉ một lát rồi hãy học tiếp nhé.","少し休んでから勉強してください。","再"],["我们吃完饭再去商场。","Wǒmen chīwán fàn zài qù shāngchǎng.","พวกเรากินข้าวเสร็จก่อนแล้วค่อยไปห้าง","Let's finish eating, then go to the mall.","Chúng ta ăn cơm xong rồi đi trung tâm thương mại.","ご飯を食べてからモールへ行きます。","再"],["他七点就到学校了。","Tā qī diǎn jiù dào xuéxiào le.","แค่เจ็ดโมงเขาก็ถึงโรงเรียนแล้ว","He arrived at school as early as 7:00.","Mới 7 giờ anh ấy đã đến trường rồi.","彼は7時にはもう学校に着きました。","就"],["我一下课就回家。","Wǒ yī xiàkè jiù huí jiā.","พอเลิกเรียนฉันก็กลับบ้านทันที","As soon as class ends, I go right home.","Vừa tan học là tôi về nhà ngay.","授業が終わったらすぐ帰ります。","就"],["我坐地铁十分钟就到了。","Wǒ zuò dìtiě shí fēnzhōng jiù dào le.","ฉันนั่งรถไฟใต้ดินแค่สิบนาทีก็ถึงแล้ว","Taking the subway, I arrived in just ten minutes.","Đi tàu điện ngầm chỉ 10 phút là tôi đến rồi.","地下鉄でたった10分で着きました。","就"]],"err":[["一下课就我回家了。","一下课我就回家了。","就 เป็นคำวิเศษณ์ ต้องวางหลังประธาน (我就回家)","就 is an adverb and must go AFTER the subject (我就回家).","“就”放在主语后、动词前（我就回家）。","就 đứng sau chủ ngữ, trước động từ (我就回家).","「就」は主語の後・動詞の前（我就回家）。"],["昨天我吃完饭再回家了。","昨天我吃完饭就回家了。","เล่าลำดับอดีตที่จบไปแล้วใช้ 就 ไม่ใช้ 再2","Past completed sequences take 就, not 再2.","过去已完成动作的衔接用“就”，不用“再2”。","Quá khứ đã hoàn thành dùng 就, không dùng 再2.","過去の連続動作には「再2」でなく「就」を使う。"]],"rel":["g3-2-071","g3-1-018","g3-2-020"]},"g3-2-020":{"t":["คำวิเศษณ์บอกน้ำเสียง: 都2 (ตั้ง…แล้ว) / 就2 (เน้น/แค่) / 还是1 (…ดีกว่า)","Modal adverbs: 都2 ('already'), 就2 ('just/only/really') & 还是1 ('had better')","语气副词：都2、就2、还是1","Phó từ ngữ khí: 都2 (đã…rồi) / 就2 (chỉ/chính là) / 还是1 (vẫn cứ/thà…đi)","語気副詞：都2（もう）・就2（まさに・ただ）・还是1（やはり〜しよう）"],"f":["都2 + 时间 / 年龄 / 数量 + 了（都十点了！/ 都三天了！）","就2 + 动词 / 数量（我就喜欢喝茶 / 教室里就我一个人）","还是1 + 动词 + 吧（外面冷，你还是在家休息吧）"],"why":["คำวิเศษณ์บอกน้ำเสียง (语气副词) 3 ตัวใน HSK 2 ที่เปลี่ยนความหมายไปจากเดิมสิ้นเชิง: (1) 都2 ไม่ได้แปลว่า 'ทั้งหมด' แต่แปลว่า 'ตั้ง…แล้ว / ป่านนี้แล้ว!' (เทียบเท่า 已经 แต่น้ำเสียงย้ำแรงกว่า มักคู่กับ 了 ท้ายประโยค เช่น 都十点了！= ตั้งสี่ทุ่มแล้วนะ!) (2) 就2 ใช้เน้นย้ำเจตนาแน่วแน่ ('ก็จะ… / ก็ชอบ…จริง ๆ') หรือแปลว่า 'แค่/มีอยู่แค่' (我就喜欢他, 就我一个人) (3) 还是1 ไม่ได้แปลว่า 'หรือ' ในคำถาม แต่ใช้ในประโยคบอกเล่า/ชวนแปลว่า 'ยังไงก็…ดีกว่า / เอาเป็นว่า…เถอะ' มักจบด้วย 吧 (还是坐地铁吧 = นั่งรถไฟใต้ดินดีกว่านะ) · ข้อควรระวัง: (1) 都2 ต้องมี 了 ปิดท้ายเสมอ (都十点 ผิด!) (2) 还是1 แนะนำทางเลือกที่ดีกว่า ให้ลงท้ายด้วย 吧 ห้ามใส่ 吗","Three HSK 2 modal adverbs with new emphatic meanings: (1) 都2 means 'already!' (stronger than 已经, paired with 了: 都十点了! 'It's already 10 o'clock!'). (2) 就2 adds firm emphasis ('just / really') or means 'only' (我就喜欢喝茶; 就我一个人). (3) 还是1 means 'had better / might as well' after weighing options (often ending in 吧: 还是坐地铁吧). · Cautions: (1) 都2 requires closing 了 (never bare 都十点). (2) 还是1 is a recommendation, not a yes-no question (never add 吗).","三个高频语气副词：（1）“都2”表“已经”（语气比“已经”更强调，须配“了”：都十点了！）；（2）“就2”表坚决强调（我就喜欢喝茶）或“仅仅”（就我一个人）；（3）“还是1”表比较权衡后的建议“最好、干脆”，常配“吧”（还是坐地铁吧）。 · 注意：“都2”句末不可省“了”；“还是1”表建议不加“吗”。","3 phó từ ngữ khí HSK 2: (1) 都2 = 'đã…rồi đấy!' (nhấn mạnh hơn 已经, cần 了: 都十点了!); (2) 就2 = nhấn mạnh kiên quyết ('chỉ/cứ': 我就喜欢喝茶) hoặc 'chỉ có' (就我一个人); (3) 还是1 = 'vẫn nên…thì hơn' (thường kèm 吧: 还是坐地铁吧). · Lưu ý: 都2 không được bỏ 了; 还是1 không thêm 吗.","3つの語気副詞：（1）「都2」は「もう〜だ！」（「已经」より強調、文末に「了」必須：都十点了！）、（2）「就2」は強い強調「まさに〜」や限定「ただ〜だけ」（我就喜欢喝茶／就我一个人）、（3）「还是1」は比較した上の提案「やはり〜した方がいい」（还是坐地铁吧）。"],"use":[{"ok":true,"zh":"都十点了，你怎么还没起床？","fix":"","py":"Dōu shí diǎn le, nǐ zěnme hái méi qǐchuáng?","tr":["ตั้งสิบโมงแล้วนะ ทำไมคุณยังไม่ตื่นอีก","It's already 10 o'clock — why aren't you up yet?","Đã 10 giờ rồi, sao bạn vẫn chưa dậy?","もう10時なのに、どうしてまだ起きないの？"],"h":["เน้นว่า 'ดึก/สาย/นานขนาดนี้แล้ว!' ใช้ 都2 + เวลา/จำนวน + 了","Use 都2 + time/amount + 了 to emphasize 'it's already so late/long!'","“都……了”强调时间已晚或持续很久","Nhấn mạnh đã muộn/lâu rồi dùng 都2 + thời gian + 了","「もうこんなに遅い／長い！」は「都2＋時間＋了」"],"w":["ทำได้และได้อารมณ์ธรรมชาติมาก เพราะ 都2 ให้ความรู้สึกทักท้วงหรือแปลกใจมากกว่า 已经 十点了 เสียอีก","Works expressively because 都2…了 conveys surprise or mild scolding far more vividly than neutral 已经十点了.","“都十点了”比“已经十点了”更有催促、惊讶的语气色彩。","Đúng và giàu cảm xúc nhắc nhở/ngạc nhiên hơn hẳn 已经十点了.","「已经十点了」より驚きや催促の感情が生き生きと伝わる。"],"ref":"HSK 3.0 g3-2-020 · g3-2-044"},{"ok":true,"zh":"外面下雨了，我们还是打车吧。","fix":"","py":"Wàimiàn xià yǔ le, wǒmen háishi dǎchē ba.","tr":["ข้างนอกฝนตกแล้ว พวกเรานั่งแท็กซี่กันดีกว่านะ","It's raining outside; we'd better take a taxi.","Bên ngoài mưa rồi, chúng ta vẫn nên bắt taxi đi.","外は雨が降ってきたから、やはりタクシーに乗ろう。"],"h":["ชั่งใจแล้วแนะนำทางเลือกที่ดีกว่า ใช้ 还是1 + กริยา + 吧","Recommend the better option after weighing conditions with 还是1…吧","权衡后提出建议用“还是……吧”","Cân nhắc rồi đề xuất phương án tốt hơn dùng 还是1…吧","比較した上で良い方を選ぶ提案は「还是1…吧」"],"w":["ทำได้เพราะสถานการณ์เปลี่ยน (ฝนตก) จึงชั่งใจเลือกวิธีที่ดีกว่า (นั่งแท็กซี่แทนเดิน) แล้วชวนด้วย 吧","Works naturally when conditions shift (rain), suggesting the better choice (taxi) softly with 吧.","因为下雨，权衡利弊后提议“还是打车吧”，自然委婉。","Đúng vì trời mưa nên cân nhắc chọn đi taxi sẽ hợp lý hơn.","雨という状況を踏まえてタクシーの方が良いと柔らかく提案している。"],"ref":"HSK 3.0 g3-2-020 · g3-2-042"},{"ok":false,"zh":"都十点，快起床！","fix":"都十点了，快起床！","py":"Dōu shí diǎn le, kuài qǐchuáng!","tr":["ตั้งสิบโมงแล้วนะ รีบตื่นได้แล้ว!","It's already 10 o'clock — get up quick!","Đã 10 giờ rồi, mau dậy đi!","もう10時だよ、早く起きて！"],"h":["ใช้ 都2 บอก 'ตั้ง…แล้ว' ห้ามลืม 了 ปิดท้าย!","Never omit final 了 in the 都2…了 ('already!') frame!","“都2”表“已经”时句末不能漏掉“了”","Dùng 都2 nghĩa 'đã…rồi' không được bỏ quên 了!","「もう〜だ」の「都2」では文末の「了」を落とせない"],"w":["ไม่ได้ เพราะโครงสร้างคงที่คือ 都……了 ถ้าตัด 了 ออกจะฟังขาดห้วนและเสียความหมาย 'ถึงเวลา…แล้ว'","Wrong because 都…了 is a fixed paired frame; dropping 了 breaks the 'already' sense.","不行，“都……了”是固定搭配，缺少“了”句子不完整。","Không được vì 都…了 là cấu trúc cố định, thiếu 了 sẽ cụt và sai.","「都…了」は固定の呼応構文なので文末の「了」が不可欠。"],"ref":"HSK 3.0 g3-2-020 · g3-2-044"},{"ok":false,"zh":"我们还是打车吗？","fix":"我们还是打车吧。","py":"Wǒmen háishi dǎchē ba.","tr":["พวกเรานั่งแท็กซี่กันดีกว่านะ","Let's take a taxi instead.","Chúng ta bắt taxi đi nhé.","やはりタクシーに乗りましょう。"],"h":["还是1 เชิงแนะนำใช้คู่ 吧 ไม่ใส่ 吗 (ถ้าจะถามให้เลือกใช้ A 还是 B)","Recommendation 还是1 pairs with 吧, NOT 吗 (choice questions use A 还是 B)","建议用“还是……吧”，不加“吗”；选择问用“A还是B”","Gợi ý dùng 还是…吧, không thêm 吗 (hỏi lựa chọn dùng A 还是 B)","提案は「还是…吧」（「吗」不可）。選択疑問は「A 还是 B」"],"w":["ไม่ได้ เพราะ 还是 + กริยา + 吗 เป็นโครงสร้างที่ขัดกัน (ถ้าจะถามให้เลือกต้องมี 2 ทางเลือก เช่น 我们走路还是打车？ ถ้าจะเสนอความเห็นใช้ 还是打车吧)","Wrong because 还是1 with a single action is a suggestion (taking 吧), while question 还是 needs two choices (走路还是打车？) and no 吗.","不行，表建议说“还是打车吧”；要问选择须给出两项（走路还是打车？）且不加“吗”。","Không được: đề xuất dùng 还是打车吧; hỏi chọn phải có 2 vế (走路还是打车？) và không có 吗.","提案なら「还是打车吧」。質問なら選択肢を2つ並べて「走路还是打车？」（吗不要）。"],"ref":"HSK 3.0 g3-2-020 · g3-2-042"}],"ex":[["都十点了，快起床吧！","Dōu shí diǎn le, kuài qǐchuáng ba!","ตั้งสิบโมงแล้วนะ รีบตื่นเถอะ!","It's already 10 o'clock — get up!","Đã 10 giờ rồi, mau dậy đi!","もう10時だよ、早く起きて！","都"],["教室里就我一个人。","Jiàoshì lǐ jiù wǒ yī ge rén.","ในห้องเรียนมีแค่ฉันคนเดียวเท่านั้น","There's only me in the classroom.","Trong phòng học chỉ có một mình tôi.","教室には私一人しかいません。","就"],["我就喜欢喝绿茶。","Wǒ jiù xǐhuan hē lǜchá.","ฉันก็ชอบดื่มแต่ชาเขียวนี่แหละ","I simply love drinking green tea.","Tôi cứ thích uống trà xanh thôi.","私は緑茶を飲むのが大好きなんです。","就"],["外面冷，你还是在家休息吧。","Wàimiàn lěng, nǐ háishi zài jiā xiūxi ba.","ข้างนอกหนาว คุณพักอยู่บ้านดีกว่านะ","It's cold outside; you'd better rest at home.","Ngoài trời lạnh, bạn vẫn nên ở nhà nghỉ đi.","外は寒いから、やはり家で休んだ方がいいよ。","还是"],["我们还是坐地铁去吧。","Wǒmen háishi zuò dìtiě qù ba.","พวกเรานั่งรถไฟใต้ดินไปกันดีกว่านะ","Let's take the subway instead.","Chúng ta cứ đi tàu điện ngầm đi.","やはり地下鉄で行きましょう。","还是"]],"err":[["都十点，快起床！","都十点了，快起床！","โครงสร้าง 都2 (ตั้ง…แล้ว) ต้องมี 了 ปิดท้ายเสมอ","The 都2…了 ('already!') pattern always needs closing 了.","“都……了”句末不能省“了”。","Cấu trúc 都2…了 luôn phải có 了 cuối câu.","「都2…了」では文末の「了」を省けない。"],["我们还是打车吗？","我们还是打车吧。","还是1 เชิงแนะนำใช้ 还是…吧 ไม่ใส่ 吗","Use 还是…吧 for recommendations, never 还是…吗.","建议用“还是……吧”，不加“吗”。","Gợi ý dùng 还是…吧, không thêm 吗.","提案は「还是…吧」で「吗」は付けない。"]],"rel":["g3-2-042","g3-2-044","g3-2-056"]},"g3-2-021":{"t":["คำบุพบท 从1: ตั้งแต่… / จาก… (จุดเริ่มต้นเวลาหรือสถานที่)","Preposition 从1: 'from / starting from' (time or place)","介词：从1（引出时间、处所）","Giới từ 从1: từ (thời gian / địa điểm)","前置詞「从1」：〜から（時間・場所の起点）"],"f":["从 + 起点 + 到 + 终点（从星期一到星期五 / 从家到学校）","主语 + 从 + 时间 / 处所 + 动词（从明天开始 / 他从北京来）"],"why":["从1 แปลว่า 'จาก / ตั้งแต่' ใช้บอกจุดเริ่มต้นทั้งด้านเวลา (从明天开始 = เริ่มตั้งแต่พรุ่งนี้, 从八点到十点) และด้านสถานที่ (他从中国来 = เขามาจากจีน, 从家到学校 = จากบ้านถึงโรงเรียน) · ตำแหน่งสำคัญ: ก้อน '从 + จุดเริ่มต้น' ต้องวาง 'หน้ากริยา' เสมอ! (他从北京来 ไม่ใช่ 他来从北京!) · ข้อควรระวัง: แยก 从 (จุดเริ่มต้นการเคลื่อนที่หรือช่วงเวลา เช่น 从家到学校) ออกจาก 离 (วัดระยะห่างคงที่ เช่น 我家离学校很近 — ห้ามพูด 我家从学校很近!)","从1 ('from') introduces a starting point in time (从明天开始, 从八点到十点) or space (他从北京来, 从家到学校). · Word order: ALWAYS put 从 + origin BEFORE the verb (他从北京来, NEVER 他来从北京!). · Crucial distinction: use 从 for starting points/ranges (从…到…) vs 离 for static distance (我家离学校很近 — NEVER 我家从学校很近!).","介词“从1”引出时间或空间的起点（从明天开始、他从北京来），常与“到”呼应构成“从……到……”（从星期一到星期五、从家到学校）。 · 注意：（1）介宾短语必须放动词前（不说“他来从北京”）；（2）表示静态距离远近用“离”（我家离学校很近），绝不用“从”。","Giới từ 从1 ('từ') nêu điểm bắt đầu về thời gian (从明天开始) hoặc nơi chốn (他从北京来), hay đi với 到 (从…到…). · Lưu ý: luôn đặt 从… TRƯỚC động từ (không nói 他来从北京); đo khoảng cách tĩnh dùng 离 (我家离学校很近), không dùng 从.","前置詞「从1」（〜から）は時間・場所の起点を示し、「从…到…」でもよく使う（从明天开始・从家到学校）。 · 注意：（1）必ず動詞の前に置く（他来从北京×）。（2）2点間の距離には「离」（我家离学校很近）を使い「从」は使えない。"],"use":[{"ok":true,"zh":"我从星期一到星期五都上班。","fix":"","py":"Wǒ cóng xīngqīyī dào xīngqīwǔ dōu shàngbān.","tr":["ฉันทำงานตั้งแต่วันจันทร์ถึงวันศุกร์เลย","I work from Monday to Friday.","Tôi đi làm từ thứ Hai đến thứ Sáu.","月曜日から金曜日まで仕事です。"],"h":["บอกช่วงเวลาหรือระยะทางเริ่มต้น–สิ้นสุด ใช้ 从…到…","Express a range from start to end with 从…到…","表示起止范围用“从……到……”","Chỉ khoảng từ đầu đến cuối dùng 从…到…","起点から終点の範囲は「从…到…」"],"w":["ทำได้และเป็นโครงสร้างมาตรฐานสำหรับทั้งเวลา (从八点到十点) และสถานที่ (从我家到学校)","Works cleanly for both time ranges (从八点到十点) and routes (从我家到学校).","“从……到……”适用于时间段和空间起止，清晰地道。","Đúng chuẩn cho cả khoảng thời gian lẫn quãng đường.","時間の範囲にも場所の区間にも使える標準的な「从…到…」構文。"],"ref":"HSK 3.0 g3-2-021"},{"ok":true,"zh":"他从外国回来了。","fix":"","py":"Tā cóng wàiguó huílai le.","tr":["เขากลับมาจากต่างประเทศแล้ว","He came back from abroad.","Anh ấy đã từ nước ngoài trở về rồi.","彼は外国から帰ってきました。"],"h":["วางก้อน 从 + สถานที่ต้นทาง ไว้ 'หน้ากริยา' เสมอ","ALWAYS put 从 + origin BEFORE the verb","“从＋处所”必须放在动词前面","Luôn đặt 从 + điểm xuất phát TRƯỚC động từ","「从＋起点」は必ず動詞の前に置く"],"w":["ทำได้เพราะวาง 从外国 หน้ากริยา 回来 ตรงตามกฎวลีบุพบทภาษาจีน 100%","Works per strict Chinese prepositional order: 从外国 precedes the verb 回来.","“从外国”作状语位于动词“回来”前，语序完全正确。","Đúng vì cụm giới từ 从外国 đứng trước động từ 回来.","前置詞句「从外国」を動詞「回来」の前に置く正しい語順。"],"ref":"HSK 3.0 g3-2-021"},{"ok":false,"zh":"他回来从外国了。","fix":"他从外国回来了。","py":"Tā cóng wàiguó huílai le.","tr":["เขากลับมาจากต่างประเทศแล้ว","He came back from abroad.","Anh ấy từ nước ngoài về rồi.","彼は外国から戻りました。"],"h":["ห้ามวาง 从 + สถานที่ หลังกริยาแบบภาษาไทย/อังกฤษ ('กลับมาจากต่างประเทศ')","NEVER put 从 + place after the verb like English 'came back from abroad'","“从＋处所”绝不能放在动词后面","Không đặt 从 + nơi chốn sau động từ như tiếng Việt/Anh","「从＋場所」を動詞の後ろに置けない"],"w":["ไม่ได้ เพราะในภาษาไทยพูดว่า 'กลับ + มาจากต่างประเทศ' แต่ในภาษาจีนกลุ่มบุพบท 从外国 ต้องอยู่หน้ากริยา 回来 เสมอ","Wrong because Chinese prepositional phrases like 从外国 MUST precede the verb 回来.","不行，汉语介宾短语“从外国”必须放动词“回来”之前。","Không được vì cụm giới từ 从外国 bắt buộc đặt trước động từ 回来.","前置詞句「从外国」は必ず動詞「回来」の前に置く。"],"ref":"HSK 3.0 g3-2-021"},{"ok":false,"zh":"我家从学校很近。","fix":"我家离学校很近。","py":"Wǒ jiā lí xuéxiào hěn jìn.","tr":["บ้านฉันอยู่ใกล้โรงเรียนมาก","My home is very close to the school.","Nhà tôi rất gần trường học.","私の家は学校からとても近いです。"],"h":["บอกความใกล้–ไกล (远 / 近) ต้องใช้ 离 ห้ามใช้ 从!","For static distance (远 / 近), use 离 — NEVER 从!","表两地距离远近用“离”，不用“从”","Nói khoảng cách gần/xa (远/近) phải dùng 离, không dùng 从","距離の遠近（远・近）には「从」でなく「离」を使う"],"w":["ไม่ได้ เพราะ 很近 / 很远 เป็นการวัดระยะห่างคงที่ระหว่างจุด A กับ B ต้องใช้บุพบท 离 เท่านั้น (我家离学校很近 / 机场离这儿很远)","Wrong because static distance with 近/远 always takes 离 (我家离学校很近), never 从.","不行，说两地相距远近固定用“A离B很近／很远”，不能用“从”。","Không được vì đo khoảng cách cố định (近/远) bắt buộc dùng 离 (我家离学校很近).","2地点間の距離（近・远）は必ず「A离B…」を使い「从」は不可。"],"ref":"HSK 3.0 g3-2-021"}],"ex":[["我从星期一到星期五都上班。","Wǒ cóng xīngqīyī dào xīngqīwǔ dōu shàngbān.","ฉันทำงานตั้งแต่วันจันทร์ถึงวันศุกร์","I work from Monday to Friday.","Tôi đi làm từ thứ Hai đến thứ Sáu.","月曜から金曜まで仕事です。","从"],["从明天开始，我每天跑步。","Cóng míngtiān kāishǐ, wǒ měi tiān pǎobù.","เริ่มตั้งแต่พรุ่งนี้ ฉันจะวิ่งทุกวัน","Starting tomorrow, I'll jog every day.","Bắt đầu từ ngày mai, ngày nào tôi cũng chạy bộ.","明日から毎日ジョギングします。","从"],["他从外国回来了。","Tā cóng wàiguó huílai le.","เขากลับมาจากต่างประเทศแล้ว","He came back from abroad.","Anh ấy đã từ nước ngoài về rồi.","彼は外国から帰ってきました。","从"],["从我家到机场要一个小时。","Cóng wǒ jiā dào jīchǎng yào yī ge xiǎoshí.","จากบ้านฉันถึงสนามบินใช้เวลาหนึ่งชั่วโมง","It takes one hour from my home to the airport.","Từ nhà tôi đến sân bay mất một tiếng.","家から空港まで1時間かかります。","从"],["他从小就喜欢游泳。","Tā cóngxiǎo jiù xǐhuan yóuyǒng.","เขาชอบว่ายน้ำมาตั้งแต่เด็กแล้ว","He has loved swimming since childhood.","Từ nhỏ anh ấy đã thích bơi lội rồi.","彼は小さい頃から水泳が好きです。","从小"]],"err":[["他回来从外国了。","他从外国回来了。","บุพบท 从 + สถานที่ ต้องวางหน้ากริยาเสมอ","Always put 从 + origin BEFORE the verb.","“从＋处所”必须放在动词前面。","Luôn đặt 从 + nơi chốn TRƯỚC động từ.","「从＋場所」は必ず動詞の前に置く。"],["我家从学校很近。","我家离学校很近。","บอกระยะใกล้–ไกล (近 / 远) ใช้ 离 ไม่ใช้ 从","Use 离 (not 从) for static distance (近 / 远).","表示距离远近用“离”，不用“从”。","Chỉ khoảng cách gần/xa dùng 离, không dùng 从.","距離の遠近は「从」ではなく「离」を使う。"]],"rel":["g3-2-023","g3-2-022","g3-1-033"]},"g3-2-022":{"t":["คำบุพบท 往: ไปทาง… / มุ่งหน้าไปทาง…","Preposition 往: 'toward / to' (direction)","介词：往（引出方向、路径）","Giới từ 往: về phía / hướng về","前置詞「往」：〜の方へ（方向）"],"f":["往 + 方向 / 处所 + 动词（往左走 / 往前走 / 往上面看）"],"why":["往 แปลว่า 'ไปทาง / มุ่งหน้าไปทาง' ใช้ระบุทิศทางของการเคลื่อนที่หรือการมอง โดยวาง '往 + ทิศทาง/สถานที่' ไว้หน้ากริยาเสมอ (往左走 = เดินไปทางซ้าย, 往前看 = มองไปข้างหน้า, 往学校走 = เดินมุ่งหน้าไปทางโรงเรียน) · ข้อควรระวังสำคัญ 2 ข้อ: (1) 往 ใช้กับทิศทางหรือสถานที่เท่านั้น ห้ามใช้กับ 'คน' เด็ดขาด! (ห้ามพูด 往我走 หรือ 往他笑 — กับคนใช้ 对 / 跟!) (2) ห้ามเอา 往 + ทิศทาง ไปวางหลังกริยา (走往左 ผิด!)","往 ('toward') introduces a direction of movement or gaze BEFORE the verb: 往左走 ('walk left'), 往前看 ('look ahead'), 往学校走 ('walk toward the school'). · Two strict cautions: (1) 往 only takes directions or places — NEVER people (never 往我说 or 往我笑!). (2) NEVER put 往 + direction after the verb (never 走往左!).","介词“往”引出动作的方向，格式为“往＋方向／处所＋动词”（往左走、往前看、往学校走）。 · 两条注意：（1）“往”的宾语只能是方位词或处所词，不能是人（不能说“往我说”）；（2）绝不能放动词后面（不说“走往左”）。","Giới từ 往 ('về phía / hướng tới') đặt TRƯỚC động từ: 往左走 (đi về bên trái), 往前看 (nhìn về phía trước). · 2 lưu ý: (1) Sau 往 chỉ là phương hướng/địa điểm, KHÔNG phải người (không nói 往我说); (2) KHÔNG đặt 往 + hướng sau động từ.","前置詞「往」（〜の方へ）は「往＋方向・場所＋動詞」の順で使う（往左走・往前看・往学校走）。 · 2大注意：（1）「往」の目的語は方位・場所のみで人は不可（往我说×）。（2）動詞の後ろには置けない（走往左×）。"],"use":[{"ok":true,"zh":"你往前走，药店就在左边。","fix":"","py":"Nǐ wǎng qián zǒu, yàodiàn jiù zài zuǒbian.","tr":["คุณเดินตรงไปข้างหน้า ร้านขายยาก็อยู่ทางซ้ายมือเลย","Walk straight ahead; the pharmacy is right on the left.","Bạn đi thẳng về phía trước, hiệu thuốc ở ngay bên trái.","まっすぐ歩くと、薬局がすぐ左側にあります。"],"h":["บอกทางด้วย 往 + ทิศ (前/后/左/右/上/下) + กริยา","Give directions with 往 + direction (前/后/左/右/上/下) + Verb","指路常用“往＋方位词＋走／看”","Chỉ đường dùng 往 + phương vị + động từ (往前走)","道案内は「往＋方位詞＋走／看」"],"w":["ทำได้และเป็นสำนวนบอกทางมาตรฐานที่สุดในภาษาจีน โดยวาง 往前 ชิดหน้ากริยา 走","Works as the standard Chinese way to give walking directions, putting 往前 directly before 走.","“往前走、往左走、往右走”是最地道的指路表达。","Đúng chuẩn khi chỉ đường: 往前走, 往左走, 往右走.","道案内の定番フレーズ「往前走・往左走・往右走」。"],"ref":"HSK 3.0 g3-2-022 · g3-2-002"},{"ok":true,"zh":"大家都在往外面看。","fix":"","py":"Dàjiā dōu zài wǎng wàimiàn kàn.","tr":["ทุกคนต่างก็กำลังมองออกไปข้างนอก","Everyone is looking outside.","Mọi người đều đang nhìn ra bên ngoài.","みんな外を見ています。"],"h":["บอกทิศทางสายตา/การเคลื่อนไหวด้วย 往 + ทิศ + 看 / 跑 / 飞","Use 往 + direction with gaze/motion verbs (看 / 跑 / 飞)","“往”也可配“看、跑、飞”等表朝向","Dùng 往 + hướng với 看 / 跑 / 飞","視線や動きの方向にも「往＋方向＋看／跑／飞」"],"w":["ทำได้เพราะ 往 ไม่จำกัดแค่กริยา 走 แต่ใช้กับกริยาที่มีทิศทางได้หลายตัว เช่น 往上面看 (มองขึ้นข้างบน), 往家里跑 (วิ่งกลับเข้าบ้าน), 往天上飞 → 往外面飞","Works smoothly with any directional verb like 看, 跑, 飞 (往外面看, 往上面飞).","除“走”外，“往”常与“看、跑、飞”等有方向性的动词搭配。","Đúng vì 往 đi được với nhiều động từ có phương hướng như 看, 跑, 飞.","「走」だけでなく「看・跑・飞」など方向性のある動詞と広く組み合わせられる。"],"ref":"HSK 3.0 g3-2-022"},{"ok":false,"zh":"你走往左边。","fix":"你往左走。","py":"Nǐ wǎng zuǒ zǒu.","tr":["คุณเดินไปทางซ้าย","Walk to the left.","Bạn đi về bên trái.","左へ歩いてください。"],"h":["ห้ามวาง 往 + ทิศทาง ไว้หลังกริยา 走!","NEVER place 往 + direction after the verb 走!","“往＋方向”必须放在动词前面（往左走）","Không đặt 往 + hướng sau động từ (phải là 往左走)","「往＋方向」を動詞の後ろに置けない（往左走にする）"],"w":["ไม่ได้ เพราะในภาษาไทยเรียง 'เดิน + ไปทางซ้าย' แต่ในภาษาจีนกลุ่มบุพบท 往左 ต้องอยู่หน้ากริยา 走 เสมอ","Wrong because Chinese prepositional phrases MUST precede the verb: 往左走 (never 走往左).","不行，介宾短语“往左”作状语只能放在动词“走”前。","Không được vì cụm giới từ 往左 luôn phải đứng TRƯỚC động từ 走.","前置詞句「往左」は必ず動詞「走」の前に置く。"],"ref":"HSK 3.0 g3-2-022"},{"ok":false,"zh":"他往我说再见。","fix":"他对我说再见。","py":"Tā duì wǒ shuō zàijiàn.","tr":["เขาพูดลาก่อนกับฉัน","He said goodbye to me.","Anh ấy nói tạm biệt với tôi.","彼は私にさようならと言いました。"],"h":["พูดกับ 'คน' ใช้ 对 / 跟 ห้ามใช้ 往!","When addressing a PERSON, use 对 / 跟 — NEVER 往!","“往”后不能接人称对象，对人说话用“对／跟”","Nói với NGƯỜI dùng 对 / 跟, KHÔNG dùng 往!","人に向けて話すときは「往」ではなく「对／跟」"],"w":["ไม่ได้ เพราะ 往 รับเฉพาะทิศทางหรือสถานที่ ไม่รับบุคคลเป็นกรรม ถ้าพูดกับใครให้ใช้ 对 หรือ 跟 (对我说 / 跟我说)","Wrong because 往 takes places/directions, never people; speaking to someone requires 对 or 跟.","不行，“往”只引方向处所，不能接人；对某人说话用“对”或“跟”。","Không được vì 往 không đi với người; nói với ai phải dùng 对 hoặc 跟.","「往」は方向・場所専用で人は取れない。人へ話すときは「对／跟」を使う。"],"ref":"HSK 3.0 g3-2-022 · g3-1-022"}],"ex":[["请往左走。","Qǐng wǎng zuǒ zǒu.","กรุณาเดินไปทางซ้าย","Please go left.","Xin đi về bên trái.","左へ進んでください。","往"],["往前走五分钟就到了。","Wǎng qián zǒu wǔ fēnzhōng jiù dào le.","เดินตรงไปข้างหน้าห้านาทีก็ถึงแล้ว","Walk straight ahead for 5 minutes and you're there.","Đi thẳng 5 phút là tới rồi.","まっすぐ5分歩けば着きます。","往"],["大家都在往外面看。","Dàjiā dōu zài wǎng wàimiàn kàn.","ทุกคนต่างกำลังมองออกไปข้างนอก","Everyone is looking outside.","Mọi người đều đang nhìn ra ngoài.","みんな外を見ています。","往"],["鸟往上面飞了。","Niǎo wǎng shàngmiàn fēi le.","นกบินขึ้นไปข้างบนแล้ว","The bird flew upward.","Con chim bay lên trên rồi.","鳥が上の方へ飛びました。","往"],["他们正往学校走呢。","Tāmen zhèng wǎng xuéxiào zǒu ne.","พวกเขากำลังเดินมุ่งหน้าไปทางโรงเรียนอยู่พอดี","They are walking toward the school right now.","Họ đang đi về phía trường học đấy.","彼らはちょうど学校の方へ歩いているところです。","往"]],"err":[["你走往左。","你往左走。","往 + ทิศทาง ต้องวางหน้ากริยาเสมอ (往左走)","Put 往 + direction BEFORE the verb (往左走).","“往＋方向”必须放在动词前（往左走）。","Đặt 往 + hướng TRƯỚC động từ (往左走).","「往＋方向」は必ず動詞の前（往左走）。"],["他往我说再见。","他对我说再见。","往 ใช้กับทิศ/สถานที่เท่านั้น พูดกับคนใช้ 对 หรือ 跟","往 only takes directions/places; speaking to a person uses 对 or 跟.","对人说话用“对／跟”，不能用“往”。","Nói với người dùng 对 / 跟, không dùng 往.","人に対して話すときは「往」でなく「对／跟」。"]],"rel":["g3-2-002","g3-2-023","g3-1-033"]},"g3-2-023":{"t":["คำบุพบท 从2: ผ่านทาง… / ออกทาง… (ระบุเส้นทางหรือช่องทาง)","Preposition 从2: 'through / via' (path or route)","介词：从2（引出方向、路径）","Giới từ 从2: đi qua / theo đường (lộ trình)","前置詞「从2」：〜を通って（経路・通り道）"],"f":["主语 + 从 + 路径 / 门口 + 动词（从这儿出去 / 从这条路走）"],"why":["นอกจากบอกจุดเริ่มต้น (从1) แล้ว 从2 ยังใช้ระบุ 'เส้นทางหรือช่องทางที่เดินผ่าน' เช่น 从门口进来 (เข้ามาทางประตู), 从这儿出去 (ออกไปทางนี้), 从这条路走 (เดินไปตามถนนเส้นนี้) · แยกความต่างกับ 往 ให้ชัด: 往 บอก 'ทิศที่หันหน้าไป' (往左走 = มุ่งไปทางซ้าย) ส่วน 从2 บอก 'ช่องทาง/เส้นทางที่เดินทะลุผ่าน' (从左边出去 = ออกไปทางฝั่งซ้าย / 从这条路走 = เดินผ่านถนนเส้นนี้) · ข้อควรระวัง: ก้อน 从 + เส้นทาง ต้องวางหน้ากริยาเสมอ ห้ามวางท้ายประโยค","Besides starting points (从1), 从2 indicates the PATH or ROUTE you pass through: 从门口进来 ('enter through the doorway'), 从这儿出去 ('go out this way'), 从这条路走 ('take this road'). · Contrast with 往: 往 points toward a direction (往左走 'head left'), whereas 从2 specifies the passage/route traveled (从这条路走 'go via this road'). · Caution: always put 从 + route BEFORE the verb.","“从2”用于引出经过的路线、通道或门户：从门口进来、从这儿出去、从这条路走。 · 与“往”区分：“往”指朝向（往左走），“从2”指经过的路径（从这条路走、从前门进）。 · 注意：“从＋路径”必须放在动词前面。","Ngoài điểm bắt đầu (从1), 从2 còn chỉ LỐI ĐI / TUYẾN ĐƯỜNG đi qua: 从门口进来 (vào qua cổng), 从这儿出去 (ra lối này), 从这条路走 (đi theo con đường này). · Lưu ý: luôn đặt 从 + lối đi TRƯỚC động từ.","「从2」は経由する道・出入口を表す：从门口进来（入口から入ってくる）、从这儿出去（ここから出ていく）、从这条路走（この道を通って行く）。 · 「往」（方向）と異なり通過する経路を示す。必ず動詞の前に置く。"],"use":[{"ok":true,"zh":"我们从这条路走吧，很近。","fix":"","py":"Wǒmen cóng zhè tiáo lù zǒu ba, hěn jìn.","tr":["พวกเราเดินไปทางถนนเส้นนี้กันเถอะ ใกล้มากเลย","Let's take this road — it's very close.","Chúng ta đi theo con đường này đi, rất gần.","この道を通って行きましょう、とても近いですよ。"],"h":["ระบุเส้นทางที่เดินผ่าน ใช้ 从 + เส้นทาง + 走 / 进 / 出","Specify a route/passage with 从 + path + 走 / 进 / 出","表经过路径用“从＋路径＋动词”（从这条路走）","Chỉ lối đi qua dùng 从 + đường + động từ (从这条路走)","経由する道は「从＋道・出入口＋動詞」"],"w":["ทำได้เพราะ 这条路 เป็นเส้นทางที่เดินผ่าน จึงวาง 从这条路 หน้ากริยา 走 ได้อย่างชัดเจนและเป็นธรรมชาติ","Works cleanly because 这条路 is the path taken, placed directly before 走.","“从这条路”交代经过的路线，置于动词“走”前十分地道。","Đúng vì 这条路 là tuyến đường đi qua, đặt trước 走 rất tự nhiên.","通る道「这条路」を「从」で導き動詞「走」の前に置く自然な表現。"],"ref":"HSK 3.0 g3-2-023"},{"ok":true,"zh":"请从这个门进去。","fix":"","py":"Qǐng cóng zhège mén jìnqu.","tr":["กรุณาเข้าไปทางประตูนี้ครับ/ค่ะ","Please go in through this door.","Xin hãy đi vào từ cửa này.","こちらのドアからお入りください。"],"h":["เข้า/ออกผ่านประตูหรือช่องทางไหน ใช้ 从 + ประตู/จุด + 进/出","Enter/exit via a doorway using 从 + doorway + 进/出","指明出入口用“从＋门／这儿＋进／出”","Chỉ cửa ra vào dùng 从 + cửa + 进/出","出入口の案内は「从＋ドア＋进／出」"],"w":["ทำได้และใช้บ่อยมากเวลาแนะนำทางเข้าออกอาคาร เช่น 从这儿出去 (ออกไปทางนี้), 从前面进来 (เข้ามาทางด้านหน้า)","Works frequently for guiding people through entrances/exits (从这儿出去, 从前面进来).","指引出入通道最常用的句式：从这个门进去、从这儿出去。","Đúng và rất thông dụng khi hướng dẫn lối ra vào.","建物への出入りを案内するときの定番表現。"],"ref":"HSK 3.0 g3-2-023 · g3-2-051"},{"ok":false,"zh":"请进去从这个门。","fix":"请从这个门进去。","py":"Qǐng cóng zhège mén jìnqu.","tr":["กรุณาเข้าไปทางประตูนี้ครับ/ค่ะ","Please go in through this door.","Xin vào qua cửa này.","こちらのドアからお入りください。"],"h":["ห้ามวาง 从 + ช่องทาง ไว้หลังกริยา 进/出/走","NEVER put 从 + passage after 进/出/走","“从＋路径”必须放在动词前面，不能放句尾","Không đặt 从 + lối đi sau động từ","「从＋経路」を動詞の後ろに置けない"],"w":["ไม่ได้ เพราะในภาษาไทยพูด 'เข้าไป + ทางประตูนี้' แต่ภาษาจีนต้องวางก้อนบุพบท 从这个门 ไว้หน้ากริยา 进去 เสมอ","Wrong because Chinese requires the prepositional phrase 从这个门 BEFORE the verb 进去.","不行，介宾短语“从这个门”须在动词“进去”前。","Không được vì cụm giới từ 从这个门 bắt buộc đứng trước 进去.","前置詞句「从这个门」は必ず動詞「进去」の前に置く。"],"ref":"HSK 3.0 g3-2-023"}],"ex":[["请从这个门进去。","Qǐng cóng zhège mén jìnqu.","กรุณาเข้าไปทางประตูนี้","Please go in through this door.","Xin đi vào qua cửa này.","このドアからお入りください。","从"],["大家从这儿出去吧。","Dàjiā cóng zhèr chūqu ba.","ทุกคนออกไปทางนี้กันเถอะ","Everyone, let's go out this way.","Mọi người đi ra lối này nhé.","皆さんこちらから出ましょう。","从"],["我们从这条路走吧，很近。","Wǒmen cóng zhè tiáo lù zǒu ba, hěn jìn.","พวกเราเดินไปทางถนนเส้นนี้เถอะ ใกล้มาก","Let's take this road; it's very close.","Chúng ta đi đường này đi, rất gần.","この道を通って行きましょう、近いですよ。","从"],["他从门口进来了。","Tā cóng ménkǒu jìnlai le.","เขาเดินเข้ามาทางประตูแล้ว","He came in through the doorway.","Anh ấy từ cửa đi vào rồi.","彼は入口から入ってきました。","从"],["小猫从下面跑出来了。","Xiǎo māo cóng xiàmiàn pǎo chūlai le.","ลูกแมววิ่งออกมาจากข้างล่างแล้ว","The kitten ran out from underneath.","Mèo con từ bên dưới chạy ra rồi.","子猫が下から走り出てきました。","从"]],"err":[["请进去从这个门。","请从这个门进去。","วลีบุพบท 从 + ช่องทาง ต้องวางหน้ากริยาเสมอ","Always put 从 + route BEFORE the verb.","“从＋路径”必须放在动词前面。","Luôn đặt 从 + lối đi TRƯỚC động từ.","「从＋経路」は必ず動詞の前に置く。"]],"rel":["g3-2-021","g3-2-022","g3-2-051"]},"g3-2-024":{"t":["คำบุพบท 给: ให้ / แก่ / เพื่อ (ทำอะไรให้ใคร)","Preposition 给: 'to / for' (beneficiary or recipient)","介词：给（引出对象）","Giới từ 给: cho / giúp (đối tượng tiếp nhận)","前置詞「给」：〜に・〜のために"],"f":["主语 + 给 + 人 + 动词（我给妈妈打电话 / 我给朋友买咖啡 / 老师给我们上课）"],"why":["ใน HSK 1 เราเรียน 给 ในฐานะกริยา ('ให้': 他给我一本书) แต่ใน HSK 2 给 ทำหน้าที่เป็น 'คำบุพบท' นำหน้าผู้รับประโยชน์หรือเป้าหมายของการกระทำ โดยมีโครงสร้างทองคือ 'ประธาน + 给 + คน + กริยา' เช่น 我给妈妈打电话 (ฉันโทรหาแม่), 我给朋友买了一杯咖啡 (ฉันซื้อกาแฟให้เพื่อน), 请给我介绍一下 (ช่วยแนะนำให้ฉันหน่อย) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ห้ามเอาชื่อคนต่อท้าย 打电话 ตรง ๆ ตามเอกสาร เสริม w3-00024 (我打电话妈妈 ผิด 100%! ต้องเป็น 我给妈妈打电话) (2) ห้ามวาง 给 + คน ไว้ท้ายประโยคแบบภาษาไทย (ซื้อกาแฟ + ให้เพื่อน → ห้ามพูด 我买咖啡给朋友 ต้องย้ายมาหน้า 买 เป็น 我给朋友买咖啡!)","In HSK 1, 给 is a main verb ('give'), whereas in HSK 2, 给 is a key PREPOSITION introducing the recipient/beneficiary BEFORE the verb: Subject + 给 + Person + Verb (我给妈妈打电话 'call Mom', 我给朋友买咖啡 'buy coffee for a friend', 给我介绍一下 'introduce to me'). · Two top cautions: (1) NEVER put a person straight after 打电话 (never 我打电话妈妈 — always 我给妈妈打电话!). (2) Put 给 + person BEFORE action verbs like 买/做/介绍.","介词“给”引出动作的接受者或受益对象，必须放在动词前：“主语＋给＋人＋动词”（我给妈妈打电话、我给朋友买咖啡、老师给我们上课）。 · 两条铁律：（1）绝不能说“我打电话妈妈”，必须说“我给妈妈打电话”；（2）为某人买／做／介绍某物时，“给＋人”放动词前。","Giới từ 给 nêu đối tượng nhận/hưởng lợi, luôn đặt TRƯỚC động từ: Chủ ngữ + 给 + Người + Động từ (我给妈妈打电话, 我给朋友买咖啡, 给我介绍). · 2 quy tắc cứng: (1) TUYỆT ĐỐI không nói 我打电话妈妈 (phải là 我给妈妈打电话); (2) Đặt 给 + người TRƯỚC động từ 买/做/介绍.","前置詞「给」は動作の相手・受益者を導き、動詞の前に置く：「主語＋给＋人＋動詞」（我给妈妈打电话・我给朋友买咖啡・给我介绍）。 · 鉄則2つ：（1）「我打电话妈妈」は絶対不可（必ず「我给妈妈打电话」）。（2）「〜のために買う・作る」は「给＋人」を動詞の前に置く。"],"use":[{"ok":true,"zh":"我给妈妈打电话。","fix":"","py":"Wǒ gěi māma dǎ diànhuà.","tr":["ฉันโทรศัพท์หาแม่","I call Mom on the phone.","Tôi gọi điện cho mẹ.","母に電話をかけます。"],"h":["โทรหาใครใช้ ประธาน + 给 + คน + 打电话 เสมอ","To call someone, ALWAYS use Subject + 给 + Person + 打电话","“给＋人＋打电话”是固定搭配","Gọi điện cho ai luôn dùng Chủ ngữ + 给 + người + 打电话","「〜に電話する」は必ず「给＋人＋打电话」"],"w":["ทำได้และเป็นสำนวนมาตรฐานตามเอกสาร เสริม w3-00024 โดยวาง 给妈妈 ไว้หน้ากริยา 打电话 เสมอ","Works as the standard pattern verified in reference doc w3-00024: place 给妈妈 before 打电话.","介宾短语“给妈妈”放在“打电话”前，地道规范。","Đúng chuẩn theo tài liệu w3-00024: 给妈妈 đặt trước 打电话.","「给妈妈」を「打电话」の前に置く定番表現。"],"ref":"เสริม w3-00024 · HSK 3.0 g3-2-024"},{"ok":true,"zh":"妈妈给我做了很好吃的菜。","fix":"","py":"Māma gěi wǒ zuòle hěn hǎochī de cài.","tr":["แม่ทำกับข้าวอร่อยมากให้ฉันกิน","Mom cooked very delicious dishes for me.","Mẹ đã nấu món rất ngon cho tôi.","母が私にとてもおいしい料理を作ってくれました。"],"h":["ทำสิ่งใดให้ใคร (ซื้อ/ทำกับข้าว/แนะนำ/สอน) วาง 给 + คน หน้ากริยา","For doing something for someone (买/做/介绍), put 给 + Person BEFORE the verb","为某人做某事：给＋人＋买／做／介绍","Làm gì cho ai đặt 给 + người TRƯỚC động từ (买/做/介绍)","「〜のためにする」は「给＋人」を動詞の前に置く"],"w":["ทำได้เพราะ 给我 ระบุชัดเจนว่าฉันคือผู้รับประโยชน์จากการทำอาหารของแม่ และวางหน้ากริยา 做了 ถูกต้อง","Works cleanly because 给我 marks the beneficiary right before the verb 做了.","“给我”引出受益对象，放在动词“做”前面自然地道。","Đúng vì 给我 chỉ người hưởng lợi, đứng ngay trước 做了.","受益者「给我」を動詞「做了」の前に置く自然な語順。"],"ref":"HSK 3.0 g3-2-024"},{"ok":false,"zh":"我打电话妈妈。","fix":"我给妈妈打电话。","py":"Wǒ gěi māma dǎ diànhuà.","tr":["ฉันโทรศัพท์หาแม่","I call Mom.","Tôi gọi điện cho mẹ.","母に電話します。"],"h":["ห้ามเอาชื่อคนต่อท้าย 打电话 ตรง ๆ (我打电话妈妈 ผิด 100%!)","NEVER put a person directly after 打电话 (我打电话妈妈 is wrong!)","绝不能说“我打电话妈妈”，必须用“给妈妈打电话”","Không bao giờ nói 我打电话妈妈 (phải nói 我给妈妈打电话)","「我打电话妈妈」は絶対不可、必ず「我给妈妈打电话」"],"w":["ไม่ได้ตามเอกสาร เสริม w3-00024 เพราะ 打电话 มีกรรม 电话 อยู่แล้วจึงต่อคนข้างหลังไม่ได้ ต้องดึงคนขึ้นหน้ากริยาด้วย 给: 我给妈妈打电话","Wrong per doc w3-00024 because 打电话 already holds the object 电话 — introduce Mom before the verb with 给.","不行，“打电话”已有宾语“电话”，对象必须用介词“给”引出放前面。","Không được vì 打电话 đã có sẵn tân ngữ 电话; phải đưa mẹ lên trước bằng 给.","「打电话」はすでに目的語「电话」を含むため、相手は「给妈妈」で動詞の前に出す。"],"ref":"เสริม w3-00024"},{"ok":false,"zh":"我买一杯咖啡给朋友。","fix":"我给朋友买一杯咖啡。","py":"Wǒ gěi péngyou mǎi yī bēi kāfēi.","tr":["ฉันซื้อกาแฟหนึ่งแก้วให้เพื่อน","I buy a cup of coffee for my friend.","Tôi mua một cốc cà phê cho bạn.","友達にコーヒーを1杯買います。"],"h":["ห้ามวาง 给 + คน ไว้ท้ายประโยคหลังกริยา 买 / 做 / 介绍","Don't put 给 + person at the end after 买 / 做 / 介绍","“给＋人＋买／做／介绍”不能把“给＋人”放句尾","Không đặt 给 + người cuối câu sau 买 / 做 / 介绍","「买・做・介绍」の後ろに「给＋人」を置かない"],"w":["ไม่ได้ในรูปแบบกริยาทั่วไป เพราะภาษาไทยเรียง 'ซื้อกาแฟ + ให้เพื่อน' แต่ภาษาจีนต้องเอา 给朋友 มาวางหน้า 买 เสมอ: 我给朋友买一杯咖啡","Wrong order: Chinese places the beneficiary 给朋友 BEFORE 买 → 我给朋友买一杯咖啡.","不行，“为某人买某物”要把“给朋友”放在动词“买”前。","Không đúng trật tự: phải đưa 给朋友 lên trước động từ 买.","「〜のために買う」は「给朋友」を動詞「买」の前に置く。"],"ref":"HSK 3.0 g3-2-024"}],"ex":[["我给妈妈打电话。","Wǒ gěi māma dǎ diànhuà.","ฉันโทรศัพท์หาแม่","I call Mom.","Tôi gọi điện cho mẹ.","母に電話をします。","给"],["我给朋友买了一杯咖啡。","Wǒ gěi péngyou mǎile yī bēi kāfēi.","ฉันซื้อกาแฟหนึ่งแก้วให้เพื่อน","I bought a cup of coffee for my friend.","Tôi đã mua một cốc cà phê cho bạn.","友達にコーヒーを1杯買いました。","给"],["请你给我介绍一下吧。","Qǐng nǐ gěi wǒ jièshào yīxià ba.","กรุณาช่วยแนะนำให้ฉันฟังหน่อยนะ","Please introduce it to me a little.","Xin bạn giới thiệu cho tôi một chút nhé.","私にちょっと紹介してください。","给"],["王老师给我们上课。","Wáng lǎoshī gěi wǒmen shàngkè.","อาจารย์หวังสอนหนังสือให้พวกเรา","Teacher Wang teaches class for us.","Thầy Vương dạy học cho chúng tôi.","王先生が私たちに授業をしてくれます。","给"],["妈妈给我做了很好吃的菜。","Māma gěi wǒ zuòle hěn hǎochī de cài.","แม่ทำกับข้าวอร่อยมากให้ฉัน","Mom cooked very delicious dishes for me.","Mẹ đã nấu món rất ngon cho tôi.","母がおいしい料理を作ってくれました。","给"]],"err":[["我打电话妈妈。","我给妈妈打电话。","โทรหาใครต้องใช้ 给 + คน + 打电话 เสมอ","Always use 给 + person + 打电话 to call someone.","说“给某人打电话”，不说“打电话某人”。","Gọi điện cho ai luôn dùng 给 + người + 打电话.","「〜に電話する」は必ず「给＋人＋打电话」。"],["我买一杯咖啡给朋友。","我给朋友买一杯咖啡。","ซื้อ/ทำให้ใคร วาง 给 + คน หน้ากริยาเสมอ","Put 给 + person BEFORE 买/做/介绍.","“给＋人”放在动词“买”前面。","Đặt 给 + người TRƯỚC động từ 买.","「给＋人」は動詞「买」の前に置く。"]],"rel":["g3-1-058","g3-2-067","g3-1-033"]},"g3-2-025":{"t":["คำบุพบท 比: กว่า (เปรียบเทียบสองสิ่ง)","Preposition 比: 'than' (making comparisons)","介词：比（引出对象）","Giới từ 比: hơn (so sánh)","前置詞「比」：〜より（比較）"],"f":["肯定：A + 比 + B + 形容词（我比他高 / 今天比昨天冷）","否定：A + 没有 + B +（这么/那么）+ 形容词（我没有他高）"],"why":["比 เป็นคำบุพบทใช้เปรียบเทียบว่า 'A … กว่า B' โดยลำดับต่างจากภาษาไทยและอังกฤษ: จีนวาง '比 + B' ไว้ 'หน้าคำคุณศัพท์' เสมอ! (我比他高 = ฉัน + เทียบกับเขา + สูงกว่า) · กฎเหล็กอันดับ 1 ที่คนเรียนผิดบ่อยสุดใน HSK 2: ห้ามใส่ 很, 非常, 真, 太 หน้าคุณศัพท์ในประโยค 比 เด็ดขาด!! (ห้ามพูด 我比他很高 หรือ 今天比昨天非常冷!) ถ้าอยากเน้นว่า 'กว่ามาก / กว่านิดหน่อย' ให้วางไว้ 'หลังคุณศัพท์' แทน เช่น 高得多 / 高一点儿 · ปฏิเสธประโยค 比 นิยมใช้ A + 没有 + B + คุณศัพท์ (我没有他高 = ฉันไม่สูงเท่าเขา)","比 ('than') compares A against B, placing 比 + B BEFORE the adjective (opposite to English/Thai): 我比他高 ('I am taller than him'). · #1 iron rule of 比 sentences: NEVER put 很, 非常, 真, or 太 before the adjective (NEVER 我比他很高!). To show how much more, put a complement AFTER the adjective (高一点儿, 高得多). · To negate, usually use A + 没有 + B + Adj (我没有他高).","介词“比”构成比较句，语序为“A＋比＋B＋形容词”（我比他高、今天比昨天冷），“比＋B”必须放在形容词前面。 · 第一铁律：形容词前绝不能加“很、非常、真、太”等程度副词（不说“我比他很高”）；要表差距放在形容词后面（高一点儿、高三岁）。 · 否定一般用“A没有B＋形容词”。","Giới từ 比 ('hơn') luôn đặt '比 + B' TRƯỚC tính từ — ngược tiếng Việt/Thái: 我比他高 (tôi cao hơn anh ấy). · Quy tắc thép số 1: TUYỆT ĐỐI không thêm 很 / 非常 / 真 / 太 trước tính từ trong câu 比 (không nói 我比他很高!); muốn nói hơn bao nhiêu đặt SAU tính từ (高一点儿). · Phủ định thường dùng 没有.","前置詞「比」（〜より）は必ず「A＋比＋B＋形容詞」の順（我比他高）。 · 最大の鉄則：「比」の文の形容詞の前に「很・非常・真・太」は絶対に入れない（我比他很高×）。差の程度は形容詞の後ろに置く（高一点儿）。 · 否定は通常「A没有B＋形容詞」。"],"use":[{"ok":true,"zh":"今天比昨天冷一点儿。","fix":"","py":"Jīntiān bǐ zuótiān lěng yīdiǎnr.","tr":["วันนี้หนาวกว่าเมื่อวานนิดหน่อย","Today is a bit colder than yesterday.","Hôm nay lạnh hơn hôm qua một chút.","今日は昨日より少し寒いです。"],"h":["เปรียบเทียบ A กว่า B (และบอกความต่าง 'นิดหน่อย' ไว้หลังคุณศัพท์)","Compare A > B and place the degree (一点儿) AFTER the adjective","“A比B＋形容词（＋一点儿）”，不加“很”","A 比 B + tính từ (+ 一点儿), không thêm 很","「A比B＋形容詞（＋一点儿）」（「很」は入れない）"],"w":["ทำได้เพราะวาง 比昨天 หน้าคุณศัพท์ 冷 และไม่ใส่ 很 แต่เติม 一点儿 หลัง 冷 เพื่อบอกความต่างอย่างเป็นธรรมชาติ","Works cleanly: 比昨天 sits before 冷 (no 很), with 一点儿 placed after 冷 for the margin.","“比昨天”在“冷”前，差距“一点儿”放“冷”后，完全规范。","Đúng vì 比昨天 đứng trước 冷 (không có 很) và 一点儿 đứng sau 冷.","「比昨天」を「冷」の前に置き、「一点儿」を後ろに添えた模範的な比較文。"],"ref":"HSK 3.0 g3-2-025 · g3-2-062"},{"ok":true,"zh":"坐地铁比打车便宜。","fix":"","py":"Zuò dìtiě bǐ dǎchē piányi.","tr":["นั่งรถไฟใต้ดินถูกกว่านั่งแท็กซี่","Taking the subway is cheaper than taking a taxi.","Đi tàu điện ngầm rẻ hơn bắt taxi.","地下鉄に乗る方がタクシーより安いです。"],"h":["เปรียบเทียบได้ทั้งคน สิ่งของ และกิจกรรม (วลีกริยาทั้งก้อน)","Compare not just nouns, but whole verb phrases too","“比”前后既可比较名词，也可比较动词短语","So sánh được cả danh từ lẫn cụm động từ","名詞だけでなく動詞句同士も「比」で比較できる"],"w":["ทำได้เพราะทั้ง 坐地铁 (นั่งรถไฟใต้ดิน) และ 打车 (เรียกแท็กซี่) เป็นกิจกรรมคู่ขนานที่เทียบราคาด้วย 便宜 ได้ชัดเจน","Works smoothly because 坐地铁 and 打车 are parallel activities compared cleanly by 便宜.","“坐地铁”和“打车”两个动词短语对称比较，自然流畅。","Đúng vì 坐地铁 và 打车 là hai cụm động từ song song so sánh giá cả.","「坐地铁」と「打车」という動詞句同士をきれいに比較している。"],"ref":"HSK 3.0 g3-2-025 · g3-2-061"},{"ok":false,"zh":"我比他很高。","fix":"我比他高。","py":"Wǒ bǐ tā gāo.","tr":["ฉันสูงกว่าเขา","I am taller than him.","Tôi cao hơn anh ấy.","私は彼より背が高いです。"],"h":["ห้ามใส่ 很 / 非常 / 太 / 真 หน้าคุณศัพท์ในประโยค 比 เด็ดขาด!","NEVER put 很 / 非常 / 太 / 真 before the adjective in a 比 sentence!","“比”字句形容词前绝不能加“很、非常、太、真”","Tuyệt đối không thêm 很 / 非常 / 太 / 真 trước tính từ trong câu 比!","「比」構文の形容詞の前に「很・非常・太・真」は絶対不可"],"w":["ไม่ได้ เพราะประโยค 比 มีความหมายเปรียบเทียบชัดเจนอยู่แล้ว จึงไม่ต้องพึ่ง 很 เหมือนประโยคคุณศัพท์ทั่วไป ถ้าจะบอกว่า 'สูงกว่ามาก' ให้พูดว่า 高得多 หรือ 高多了 หลังคุณศัพท์","Wrong because 比 already carries comparison, so bare adjectives are complete without 很 (for 'much taller', add 多了 after the adjective).","不行，“比”字句本身已表比较，形容词前绝不能加“很、非常、太”；程度大要放后面（高多了）。","Không được vì câu 比 vốn đã so sánh rồi, không được thêm 很; muốn nói 'hơn nhiều' đặt 多了 sau tính từ.","「比」の文は比較自体が成立しているため「很」は不要（誤用）。差が大きいときは後ろに「多了」を置く。"],"ref":"HSK 3.0 g3-2-025 · g3-2-061"},{"ok":false,"zh":"我高比他。","fix":"我比他高。","py":"Wǒ bǐ tā gāo.","tr":["ฉันสูงกว่าเขา","I am taller than him.","Tôi cao hơn anh ấy.","私は彼より背が高いです。"],"h":["ห้ามวาง 比 + B ไว้หลังคุณศัพท์แบบภาษาไทย ('สูงกว่าเขา')","NEVER put 比 + B after the adjective like English 'taller than him'","“比＋B”必须放在形容词前面（我比他高）","Không đặt 比 + B sau tính từ như tiếng Việt/Anh","「比＋B」を形容詞の後ろに置けない（我比他高にする）"],"w":["ไม่ได้ เพราะในภาษาไทยเรียง 'ฉัน + สูง + กว่าเขา' แต่ในภาษาจีนบุพบท 比 + B ต้องวางหน้าคุณศัพท์เสมอ: 我比他高","Wrong because unlike English 'taller than him', Chinese places 比他 BEFORE 高: 我比他高.","不行，介宾短语“比他”必须放形容词“高”前：我比他高。","Không được vì 比他 phải đứng TRƯỚC tính từ 高: 我比他高.","「比他」は必ず形容詞「高」の前に置く（我比他高）。"],"ref":"HSK 3.0 g3-2-025"}],"ex":[["我比他高。","Wǒ bǐ tā gāo.","ฉันสูงกว่าเขา","I am taller than him.","Tôi cao hơn anh ấy.","私は彼より背が高いです。","比"],["今天比昨天冷。","Jīntiān bǐ zuótiān lěng.","วันนี้หนาวกว่าเมื่อวาน","Today is colder than yesterday.","Hôm nay lạnh hơn hôm qua.","今日は昨日より寒いです。","比"],["坐地铁比打车便宜。","Zuò dìtiě bǐ dǎchē piányi.","นั่งรถไฟใต้ดินถูกกว่านั่งแท็กซี่","Taking the subway is cheaper than a taxi.","Đi tàu điện ngầm rẻ hơn đi taxi.","地下鉄はタクシーより安いです。","比"],["苹果比面包好吃。","Píngguǒ bǐ miànbāo hǎochī.","แอปเปิลอร่อยกว่าขนมปัง","Apples are more delicious than bread.","Táo ngon hơn bánh mì.","りんごはパンよりおいしいです。","比"],["哥哥比我大三岁。","Gēge bǐ wǒ dà sān suì.","พี่ชายแก่กว่าฉันสามปี","Older brother is three years older than me.","Anh trai hơn tôi ba tuổi.","兄は私より3歳年上です。","比"]],"err":[["我比他很高。","我比他高。","ประโยค 比 ห้ามใส่ 很 / 非常 / 太 หน้าคุณศัพท์เด็ดขาด","Never put 很 / 非常 / 太 before the adjective in a 比 sentence.","“比”字句形容词前绝不能加“很”。","Không thêm 很 trước tính từ trong câu 比.","「比」の文の形容詞の前に「很」は絶対に入れない。"],["我高比他。","我比他高。","วาง 比 + B ไว้หน้าคุณศัพท์เสมอ (我比他高)","Always put 比 + B BEFORE the adjective (我比他高).","“比＋B”必须放在形容词前。","Luôn đặt 比 + B TRƯỚC tính từ.","「比＋B」は常に形容詞の前に置く。"]],"rel":["g3-2-061","g3-2-062","g3-2-063"]},"g3-2-026":{"t":["คำบุพบท 跟1: กับ… (ทำร่วมกัน / พูดคุยกับ / ตาม…)","Preposition 跟1: 'with' (doing together / speaking with)","介词：跟1（引出对象）","Giới từ 跟1: cùng với / với (đối tượng)","前置詞「跟1」：〜と（一緒に・〜に話す）"],"f":["主语 + 跟1 + 人 +（一起）+ 动词（我跟你一起去 / 他跟我说话）","否定：主语 + 不 / 没 + 跟 + 人 + 动词（我没跟他说）"],"why":["跟1 เป็นคำบุพบทภาษาพูดที่คนจีนใช้บ่อยกว่า 和 ในชีวิตประจำวัน แปลว่า 'กับ / ด้วยกันกับ' วางหน้ากริยาเสมอ: 我跟你一起去 (ฉันไปกับคุณ), 他跟我说话 (เขาคุยกับฉัน), 我跟老师学汉语 (ฉันเรียนภาษาจีนกับครู) · จุดต่างสำคัญตามกลุ่มเทียบคำ g37 ระหว่าง 跟 กับ 和: (1) ทำกิจกรรมร่วมกันในภาษาพูดนิยมใช้ 跟 มากกว่า 和 (2) 跟 ยังเป็นกริยาแปลว่า 'เดินตาม / ทำตาม' ได้ด้วย เช่น 请跟我来 (เชิญตามฉันมา!) ซึ่ง 和 แปลว่า 'ตาม' ไม่ได้เด็ดขาด! (3) ปฏิเสธวาง 不/没 หน้า 跟 เสมอ (我没跟他说)","跟1 ('with') is the everyday spoken go-to preposition for doing something with someone — always placed BEFORE the verb: 我跟你一起去, 他跟我说话, 我跟老师学汉语. · Key contrast with 和 (group g37): (1) Spoken Chinese strongly prefers 跟 over 和 before verbs; (2) 跟 also works as a main verb meaning 'follow' (请跟我来 'Please follow me!'), which 和 can NEVER do! (3) Put negation 不/没 BEFORE 跟 (我没跟他说).","介词“跟1”在口语中比“和”更常用，引出共同动作或交谈对象，位于动词前（我跟你一起去、他跟我说话）。 · 与“和”区分（g37）：“跟”还可作动词表“跟随”（请跟我来），“和”绝无此义。 · 注意：否定词“不／没”放在“跟”前面（我没跟他说）。","Giới từ 跟1 ('cùng với / với') rất phổ biến trong khẩu ngữ, đặt TRƯỚC động từ (我跟你一起去, 他跟我说话). · Khác 和 (nhóm g37): 跟 còn là động từ nghĩa là 'đi theo' (请跟我来), còn 和 thì KHÔNG! · Phủ định đặt 不/没 TRƯỚC 跟 (我没跟他说).","前置詞「跟1」（〜と）は口語で「和」よりよく使われ、動詞の前に置く（我跟你一起去・他跟我说话）。 · 「和」との違い（g37）：「跟」は動詞「付いていく」（请跟我来）としても使えるが「和」は不可。 · 否定詞「不・没」は「跟」の前に置く。"],"use":[{"ok":true,"zh":"我跟你一起去商场吧。","fix":"","py":"Wǒ gēn nǐ yīqǐ qù shāngchǎng ba.","tr":["ฉันไปห้างด้วยกันกับคุณนะ","I'll go to the mall together with you.","Tôi đi trung tâm thương mại cùng với bạn nhé.","あなたと一緒にモールへ行きましょう。"],"h":["ทำกิจกรรมด้วยกันในภาษาพูด ใช้ ประธาน + 跟 + คน + 一起 + กริยา","In everyday speech, use Subject + 跟 + Person + 一起 + Verb","口语同行常用“主语＋跟＋人＋一起＋动词”","Khẩu ngữ làm cùng ai dùng Chủ ngữ + 跟 + người + 一起 + động từ","口語で一緒に行動するときは「主語＋跟＋人＋一起＋動詞」"],"w":["ทำได้และเป็นธรรมชาติกว่า 和 ในบทสนทนาประจำวัน โดยเฉพาะเมื่อจับคู่กับ 一起 หน้ากริยา","Works even more naturally than 和 in everyday speech, especially paired with 一起 before the verb.","口语中“跟……一起……”比“和”更亲切地道。","Đúng và tự nhiên hơn 和 trong giao tiếp hằng ngày.","会話では「跟…一起…」の方が「和」よりずっと自然で親しみやすい。"],"ref":"กลุ่มเทียบคำ g37 · HSK 3.0 g3-2-026"},{"ok":true,"zh":"请跟我来！","fix":"","py":"Qǐng gēn wǒ lái!","tr":["เชิญตามฉันมาครับ/ค่ะ!","Please follow me!","Mời đi theo tôi!","どうぞ私に付いて来てください！"],"h":["'ตามฉันมา' ใช้ 跟 (ห้ามใช้ 和!)","'Follow me' uses 跟 — NEVER 和!","表示“跟随”只能用“跟”（请跟我来），不能用“和”","'Đi theo tôi' dùng 跟, KHÔNG dùng 和!","「付いて来る」には必ず「跟」（「和」は不可）"],"w":["ทำได้ตามกลุ่มเทียบคำ g37 เพราะตัวอักษร 跟 มีราก 足 (เท้า) แปลว่า 'ส้นเท้า / เดินตาม' จึงใช้เป็นกริยา/บุพบทนำทางได้ว่า 请跟我来","Works per comparison group g37: 跟 has the foot radical 足 ('heel / follow'), so 请跟我来 means 'follow me'.","“跟”本义有“跟随”之意（足字旁），所以“请跟我来”地道准确。","Đúng theo nhóm g37 vì 跟 có bộ túc (chân) mang nghĩa 'đi theo'.","「跟」は足へんを持ち「付いていく」の意味があるため「请跟我来」が自然。"],"ref":"กลุ่มเทียบคำ g37"},{"ok":false,"zh":"请和我来！","fix":"请跟我来！","py":"Qǐng gēn wǒ lái!","tr":["เชิญตามฉันมาครับ/ค่ะ!","Please follow me!","Mời đi theo tôi!","私に付いて来てください！"],"h":["ห้ามใช้ 和 แทน 跟 เมื่อแปลว่า 'เดินตาม / ทำตาม'","NEVER substitute 和 for 跟 when meaning 'follow'","表示“跟随”绝不能用“和”代替“跟”","Không thay 跟 bằng 和 khi mang nghĩa 'đi theo'","「付いていく」の意味で「和」は使えない"],"w":["ไม่ได้ตามกลุ่มเทียบคำ g37 เพราะ 和 ไม่มีความหมายว่า 'ตาม' ถ้าจะชวนหรือนำทางให้ตามมาต้องใช้ 跟 เท่านั้น: 请跟我来","Wrong per group g37: 和 never means 'follow' — always use 跟: 请跟我来.","不行，“和”没有“跟随”义，领路必须说“请跟我来”。","Không được vì 和 không có nghĩa 'đi theo'; phải dùng 请跟我来.","「和」には「付いていく」という意味がないため「请跟我来」にする。"],"ref":"กลุ่มเทียบคำ g37"},{"ok":false,"zh":"我跟朋友不去。","fix":"我不跟朋友去。","py":"Wǒ bù gēn péngyou qù.","tr":["ฉันไม่ไปกับเพื่อน","I'm not going with my friend.","Tôi không đi cùng bạn.","友達とは行きません。"],"h":["ปฏิเสธต้องวาง 不 / 没 ไว้ 'หน้า 跟' เสมอ","Put negation 不 / 没 BEFORE 跟, not after it","否定词“不／没”放在介词“跟”前面（不跟／没跟）","Đặt 不 / 没 TRƯỚC giới từ 跟 (不跟 / 没跟)","否定詞「不・没」は「跟」の前に置く（不跟／没跟）"],"w":["ไม่เป็นธรรมชาติในประโยคปฏิเสธทั่วไป เพราะภาษาจีนวางคำปฏิเสธ 不 / 没 หน้าบุพบท 跟 เพื่อปฏิเสธการไปด้วยกันทั้งก้อน: 我不跟朋友去 / 我没跟他说","Unnatural: standard negation puts 不 / 没 BEFORE the preposition 跟 → 我不跟朋友去 / 我没跟他说.","不自然，正常否定须将“不／没”放在介词“跟”前：我不跟朋友去。","Không tự nhiên: phủ định thông thường đặt 不/没 trước 跟 (我不跟朋友去).","通常の否定では「不・没」を前置詞「跟」の前に置く（我不跟朋友去）。"],"ref":"HSK 3.0 g3-2-026"}],"ex":[["我跟你一起去。","Wǒ gēn nǐ yīqǐ qù.","ฉันไปกับคุณด้วยกัน","I'll go together with you.","Tôi đi cùng với bạn.","あなたと一緒に行きます。","跟"],["请跟我来！","Qǐng gēn wǒ lái!","เชิญตามฉันมา!","Please follow me!","Mời đi theo tôi!","私に付いて来てください！","跟"],["他正在跟老师说话呢。","Tā zhèngzài gēn lǎoshī shuōhuà ne.","เขากำลังคุยอยู่กับคุณครูพอดี","He is talking with the teacher right now.","Anh ấy đang nói chuyện với thầy giáo đấy.","彼は今先生と話しているところです。","跟"],["我没跟他说这件事。","Wǒ méi gēn tā shuō zhè jiàn shì.","ฉันไม่ได้เล่าเรื่องนี้ให้เขาฟัง","I didn't tell him about this matter.","Tôi đã không nói chuyện này với anh ấy.","彼にはこのことを話していません。","跟"],["她跟王老师学习汉语。","Tā gēn Wáng lǎoshī xuéxí Hànyǔ.","เธอเรียนภาษาจีนกับอาจารย์หวัง","She studies Chinese with Teacher Wang.","Cô ấy học tiếng Trung với thầy Vương.","彼女は王先生に中国語を習っています。","跟"]],"err":[["请和我来！","请跟我来！","แปลว่า 'เดินตาม / ตามมา' ต้องใช้ 跟 เท่านั้น ห้ามใช้ 和","'Follow' takes 跟, never 和.","表“跟随”用“跟”，不用“和”。","Nghĩa 'đi theo' dùng 跟, không dùng 和.","「付いていく」には「和」ではなく「跟」。"],["我去商场跟朋友。","我跟朋友去商场。","วลีบุพบท 跟 + คน ต้องวางหน้ากริยาเสมอ","Put 跟 + person BEFORE the verb.","“跟＋人”必须放在动词前。","Đặt 跟 + người TRƯỚC động từ.","「跟＋人」は必ず動詞の前に置く。"]],"rel":["g3-2-028","g3-2-015","g3-1-022"]},"g3-2-027":{"t":["คำบุพบท 因为1: เพราะ… (นำหน้าคำนาม/เหตุผลสั้น ๆ)","Preposition 因为1: 'because of' (introducing a noun/reason)","介词：因为1（引出原因）","Giới từ 因为1: vì / bởi vì (trước danh từ)","前置詞「因为1」：〜のせいで・〜のために（原因）"],"f":["因为1 + 名词性短语，主语 + 谓语（因为这件事，他很高兴）","主语 + 因为1 + 原因 + 谓语（我因为工作去北京）"],"why":["因为1 ในฐานะ 'คำบุพบท' ใช้ตามด้วยคำนามหรือวลีสั้น ๆ (ตรงกับ 'because of' ในภาษาอังกฤษ) เพื่อบอกสาเหตุ เช่น 因为这件事 (เพราะเรื่องนี้), 因为天气 (เพราะสภาพอากาศ), 因为工作 (เพราะเรื่องงาน) · ต่างจาก 因为2 (คำสันธานใน เพราะ…ดังนั้น…) ตรงที่ 因为1 ตามด้วย 'คำนาม/กลุ่มคำนาม' และสามารถวางได้ทั้งต้นประโยค (因为这件事，他没来) หรือหลังประธาน (他因为工作去北京) · ข้อควรระวัง: ห้ามเอา 因为 ไปใช้คู่กับ 但是 (ขัดแย้ง) ในประโยคเดียวกัน — เหตุผลต้องคู่กับผล (所以) เท่านั้น!","As a preposition (因为1, like English 'because of'), 因为 takes a noun or noun phrase to state a cause: 因为这件事 ('because of this matter'), 因为天气 ('because of the weather'), 因为工作 ('for work'). · It sits either sentence-initially (因为这件事，他很高兴) or right after the subject (他因为工作去北京). · Caution: never mismatch 因为 with 但是 (contrast) — cause leads to result (所以).","介词“因为1”后接名词或名词性短语引出原因（因为这件事、因为工作、因为天气），可放句首，也可放主语后、动词前（他因为工作去北京）。 · 注意：“因为”表原因，不能与表转折的“但是”混搭。","Giới từ 因为1 ('vì / do' — giống 'because of') đứng trước danh từ/cụm danh từ (因为这件事, 因为工作, 因为天气), đặt đầu câu hoặc sau chủ ngữ đều được (他因为工作去北京). · Lưu ý: không ghép 因为 với 但是.","前置詞「因为1」（〜のために／〜のせいで）は名詞・名詞句を導く（因为这件事・因为工作・因为天气）。文頭にも主語の後ろにも置ける（他因为工作去北京）。 · 注意：逆接の「但是」とは組み合わせない。"],"use":[{"ok":true,"zh":"他因为工作去了北京。","fix":"","py":"Tā yīnwèi gōngzuò qùle Běijīng.","tr":["เขาไปปักกิ่งเพราะเรื่องงาน","He went to Beijing for work.","Anh ấy vì công việc mà đi Bắc Kinh.","彼は仕事のために北京へ行きました。"],"h":["ประธาน + 因为1 + คำนามเหตุผล + กริยา","Subject + 因为1 + noun reason + Verb","主语＋“因为1＋名词”＋动词","Chủ ngữ + 因为1 + danh từ nguyên nhân + động từ","「主語＋因为1＋名詞＋動詞」"],"w":["ทำได้และกระชับมาก โดยวาง 因为工作 (เพราะงาน) ไว้หน้ากริยา 去了北京 เป็นส่วนขยายบอกสาเหตุโดยตรง","Works concisely with 因为工作 ('because of work') right before the verb 去了北京.","“因为工作”直接作状语放在动词前，简练地道。","Đúng và rất gọn vì 因为工作 đứng ngay trước 去了北京.","「因为工作」を動詞の前に置き簡潔に原因を示している。"],"ref":"HSK 3.0 g3-2-027"},{"ok":true,"zh":"因为这件事，大家都很高兴。","fix":"","py":"Yīnwèi zhè jiàn shì, dàjiā dōu hěn gāoxìng.","tr":["เพราะเรื่องนี้ ทุกคนต่างก็ดีใจมาก","Because of this matter, everyone is very happy.","Vì chuyện này mà mọi người đều rất vui.","この件のおかげでみんなとても喜んでいます。"],"h":["วาง 因为1 + วลีนาม ไว้ต้นประโยคแล้วคั่นด้วยจุลภาค","Place 因为1 + noun phrase at the start with a comma","“因为1＋名词短语，……”置句首引出原因","Đặt 因为1 + cụm danh từ ở đầu câu rồi phẩy","文頭に「因为1＋名詞句，…」を置く"],"w":["ทำได้และเน้นสาเหตุให้เด่นชัดตั้งแต่ต้นประโยค โดยไม่ต้องใส่ 所以 ตามหลังก็ได้","Works cleanly to spotlight the cause upfront without even needing 所以.","放句首突出原因，后半句不必强加“所以”。","Đúng và nhấn mạnh nguyên nhân ngay đầu câu, không bắt buộc có 所以.","文頭で原因を強調でき、後半に「所以」を付けなくても自然。"],"ref":"HSK 3.0 g3-2-027"},{"ok":false,"zh":"他去了北京因为工作。","fix":"他因为工作去了北京。","py":"Tā yīnwèi gōngzuò qùle Běijīng.","tr":["เขาไปปักกิ่งเพราะเรื่องงาน","He went to Beijing because of work.","Anh ấy đi Bắc Kinh vì công việc.","彼は仕事で北京へ行きました。"],"h":["ห้ามวาง 因为1 + คำนาม ไว้ท้ายประโยคแบบภาษาอังกฤษ/ไทย","Don't place 因为1 + noun at the end like English 'for work'","介宾短语“因为＋名词”不能放在动词后","Không đặt 因为1 + danh từ cuối câu như tiếng Việt/Anh","「因为＋名詞」を文末に置けない"],"w":["ไม่ได้ เพราะในภาษาไทยเรียง 'ไปปักกิ่ง + เพราะงาน' แต่ในภาษาจีนวลีบุพบท 因为工作 ต้องวางหน้ากริยา 去了北京 หรือวางต้นประโยคเสมอ","Wrong because Chinese prepositional phrases like 因为工作 MUST precede the verb (or stand at the start), never trail at the end.","不行，介宾短语“因为工作”必须放在动词“去”前或句首。","Không được vì cụm giới từ 因为工作 phải đứng TRƯỚC động từ hoặc đầu câu.","前置詞句「因为工作」は必ず動詞の前か文頭に置く。"],"ref":"HSK 3.0 g3-2-027"}],"ex":[["他因为工作去了北京。","Tā yīnwèi gōngzuò qùle Běijīng.","เขาไปปักกิ่งเพราะเรื่องงาน","He went to Beijing because of work.","Anh ấy vì công việc nên đi Bắc Kinh.","彼は仕事のために北京へ行きました。","因为"],["因为这件事，大家都很高兴。","Yīnwèi zhè jiàn shì, dàjiā dōu hěn gāoxìng.","เพราะเรื่องนี้ ทุกคนต่างก็ดีใจมาก","Because of this matter, everyone is very happy.","Vì chuyện này mà mọi người đều rất vui.","この件でみんなとても喜んでいます。","因为"],["因为天气，我们今天没去旅游。","Yīnwèi tiānqì, wǒmen jīntiān méi qù lǚyóu.","เพราะสภาพอากาศ วันนี้พวกเราเลยไม่ได้ไปเที่ยว","Because of the weather, we didn't go traveling today.","Vì thời tiết nên hôm nay chúng tôi không đi du lịch.","天気のせいで今日旅行に行きませんでした。","因为"],["他因为身体不舒服没来上班。","Tā yīnwèi shēntǐ bù shūfu méi lái shàngbān.","เขาไม่ได้มาทำงานเพราะร่างกายไม่สบาย","He didn't come to work because he wasn't feeling well.","Anh ấy không đi làm vì trong người không khỏe.","彼は体調不良で出勤しませんでした。","因为"],["我因为考试很忙。","Wǒ yīnwèi kǎoshì hěn máng.","ฉันยุ่งมากเพราะเรื่องสอบ","I am very busy because of exams.","Tôi rất bận vì kỳ thi.","試験のためにとても忙しいです。","因为"]],"err":[["他去了北京因为工作。","他因为工作去了北京。","วลีบุพบท 因为 + คำนาม วางหน้ากริยาหรือต้นประโยคเสมอ","Put 因为 + noun before the verb or at the start of the sentence.","“因为＋名词”须放动词前或句首。","Đặt 因为 + danh từ trước động từ hoặc đầu câu.","「因为＋名詞」は動詞の前か文頭に置く。"]],"rel":["g3-2-070","g3-2-006","g3-2-029"]},"g3-2-028":{"t":["คำสันธาน 跟2: และ / กับ (เชื่อมคำนามในภาษาพูด)","Conjunction 跟2: 'and' (linking nouns in speech)","连词：跟2（连接词或短语）","Liên từ 跟2: và / với (nối danh từ trong khẩu ngữ)","接続詞「跟2」：〜と（口語で名詞・句を並列）"],"f":["名词 A + 跟2 + 名词 B（爸爸跟妈妈 / 红茶跟绿茶，口语）"],"why":["跟2 ในฐานะ 'คำสันธาน' ทำหน้าที่เหมือน 和2 เป๊ะ คือเชื่อมคำนามหรือกลุ่มคำนามที่มีฐานะเท่ากัน (爸爸跟妈妈, 猫跟狗, 咖啡跟奶茶) แต่มีความเป็นภาษาพูดและเป็นกันเองมากกว่า 和 · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) เหมือน 和 เป๊ะ — ห้ามใช้ 跟2 เชื่อมประโยคเต็ม 2 ประโยคเข้าด้วยกัน! (ห้ามพูด 我喝咖啡跟他喝奶茶 ต้องคั่นด้วยจุลภาคจีน ，) (2) ในงานเขียนทางการหรือเอกสารสอบระดับสูง นิยมใช้ 和 มากกว่า 跟","As a conjunction (跟2), 跟 works just like 和2 — joining parallel nouns or noun phrases (爸爸跟妈妈, 猫跟狗, 咖啡跟奶茶), with a warmer, more conversational tone. · Two strict cautions: (1) Just like 和, NEVER use 跟 to join two full clauses (never 我喝咖啡跟他喝奶茶 — use a comma!). (2) Formal writing prefers 和 over 跟.","连词“跟2”相当于口语的“和”，连接并列的名词、代词或短语（爸爸跟妈妈、咖啡跟奶茶）。 · 两条注意：（1）同“和”一样，绝不能连接两个完整分句；（2）正式书面语通常更倾向用“和”。","Liên từ 跟2 giống 和2 trong khẩu ngữ — nối các danh từ/cụm danh từ bình đẳng (爸爸跟妈妈, 咖啡跟奶茶). · Lưu ý: KHÔNG dùng 跟2 nối hai mệnh đề hoàn chỉnh; văn viết trang trọng ưu tiên 和.","接続詞「跟2」は口語的な「和」で、名詞・名詞句を並列する（爸爸跟妈妈・咖啡跟奶茶）。 · 注意：「和」と同じく2つの文をつなぐことはできない。フォーマルな書き言葉では「和」が好まれる。"],"use":[{"ok":true,"zh":"爷爷跟奶奶都很喜欢喝茶。","fix":"","py":"Yéye gēn nǎinai dōu hěn xǐhuan hē chá.","tr":["คุณปู่กับคุณย่าต่างก็ชอบดื่มชามาก","Both Grandpa and Grandma love drinking tea.","Ông nội và bà nội đều rất thích uống trà.","おじいちゃんもおばあちゃんもお茶が大好きです。"],"h":["เชื่อมคำนาม 2 ตัวในภาษาพูดด้วย 跟2 (+ 都)","Link two parallel nouns in speech with 跟2 (+ 都)","口语并列两个名词用“A跟B（＋都）”","Khẩu ngữ nối 2 danh từ bằng 跟2 (+ 都)","口語で2つの名詞を並べる「A跟B（＋都）」"],"w":["ทำได้และฟังเป็นกันเองมาก เพราะ 爷爷 กับ 奶奶 เป็นคำนามคู่ขนานที่มีบทบาทเป็นประธานร่วมกัน","Works warmly in everyday speech because 爷爷 and 奶奶 are parallel nouns sharing the predicate.","“爷爷跟奶奶”并列作主语，口语亲切自然。","Đúng và thân mật vì 爷爷 và 奶奶 là hai danh từ song song làm chủ ngữ.","「爷爷」と「奶奶」を親しみやすく並列している。"],"ref":"กลุ่มเทียบคำ g37 · HSK 3.0 g3-2-028"},{"ok":true,"zh":"我买了苹果、面包跟牛奶。","fix":"","py":"Wǒ mǎile píngguǒ, miànbāo gēn niúnǎi.","tr":["ฉันซื้อแอปเปิล ขนมปัง แล้วก็นม","I bought apples, bread, and milk.","Tôi mua táo, bánh mì và sữa.","りんご、パン、それと牛乳を買いました。"],"h":["เรียง 3 รายการขึ้นไป วาง 跟2 หน้าตัวสุดท้ายเพียงครั้งเดียว","For 3+ nouns, place 跟2 only before the final item","三项并列只放一次“跟”在最后一项前","3 mục trở lên chỉ đặt 跟 trước mục cuối","3つ以上の並列は最後の項目の前だけ「跟」を1回置く"],"w":["ทำได้เช่นเดียวกับ 和 คือคั่นรายการก่อนหน้าด้วย 、 แล้วใส่ 跟 เพียงครั้งเดียวหน้าคำสุดท้าย","Works just like 和: separate earlier items with 、 and place ONE 跟 before the last noun.","与“和”规则相同，前用顿号，最后用一次“跟”。","Đúng như quy tắc của 和: dùng dấu 、 giữa các mục đầu và một chữ 跟 trước mục cuối.","「和」と同じく「、」で区切り、最後の前だけ1回「跟」を置く。"],"ref":"HSK 3.0 g3-2-028"},{"ok":false,"zh":"我打篮球跟他踢足球。","fix":"我打篮球，他踢足球。","py":"Wǒ dǎ lánqiú, tā tī zúqiú.","tr":["ฉันเล่นบาสเกตบอล ส่วนเขาเตะฟุตบอล","I play basketball, and he plays soccer.","Tôi chơi bóng rổ, anh ấy đá bóng.","私はバスケをし、彼はサッカーをします。"],"h":["ห้ามใช้ 跟2 เชื่อมประโยคเต็มสองประโยค","NEVER use 跟2 to connect two full clauses","“跟2”不能连接两个完整分句","Không dùng 跟2 nối hai mệnh đề hoàn chỉnh","2つの文を「跟2」でつないではいけない"],"w":["ไม่ได้ เพราะ 跟2 เชื่อมได้เฉพาะคำนามหรือกลุ่มคำนามเท่านั้น ถ้าเชื่อมสองประโยคต้องคั่นด้วยจุลภาคจีน ，","Wrong because 跟2 joins only nouns/noun phrases, never full clauses — use a comma instead.","不行，“跟”只能连接词语短语，两个完整分句间须用逗号。","Không được vì 跟 chỉ nối danh từ/cụm từ; nối 2 câu dùng dấu phẩy.","「跟」は名詞・句の並列専用。文と文は読点「，」でつなぐ。"],"ref":"HSK 3.0 g3-2-028 · g3-1-023"}],"ex":[["爷爷跟奶奶都很喜欢喝茶。","Yéye gēn nǎinai dōu hěn xǐhuan hē chá.","คุณปู่กับคุณย่าต่างชอบดื่มชามาก","Both Grandpa and Grandma like drinking tea.","Ông nội và bà nội đều thích uống trà.","祖父も祖母もお茶を飲むのが好きです。","跟"],["红茶跟绿茶我都喜欢。","Hóngchá gēn lǜchá wǒ dōu xǐhuan.","ทั้งชาแดงและชาเขียวฉันชอบหมดเลย","I like both black tea and green tea.","Hồng trà và trà xanh tôi đều thích.","紅茶も緑茶も両方好きです。","跟"],["书包里有本子跟笔。","Shūbāo lǐ yǒu běnzi gēn bǐ.","ในกระเป๋านักเรียนมีสมุดกับปากกา","There are notebooks and pens in the schoolbag.","Trong cặp có vở và bút.","かばんの中にノートとペンがあります。","跟"],["我喜欢猫跟狗。","Wǒ xǐhuan māo gēn gǒu.","ฉันชอบแมวกับหมา","I like cats and dogs.","Tôi thích mèo và chó.","私は猫と犬が好きです。","跟"],["爸爸跟妈妈都在饭馆吃饭。","Bàba gēn māma dōu zài fànguǎn chīfàn.","พ่อกับแม่กินข้าวอยู่ที่ร้านอาหารทั้งคู่","Both Dad and Mom are eating at the restaurant.","Bố và mẹ đều đang ăn ở quán ăn.","父も母もレストランで食事をしています。","跟"]],"err":[["我打篮球跟他踢足球。","我打篮球，他踢足球。","ห้ามใช้ 跟2 เชื่อมประโยคเต็มสองประโยค ให้ใช้จุลภาคคั่น","Never link two full clauses with 跟2; use a comma.","不能用“跟”连接两个完整分句。","Không dùng 跟 nối hai mệnh đề, dùng dấu phẩy.","2つの文を「跟」でつながず読点にする。"]],"rel":["g3-2-026","g3-1-023","g3-1-028"]},"g3-2-029":{"t":["คำสันธานเชื่อมประโยค: 虽然…但是 / 因为…所以 / 还是2 / 那","Clause conjunctions: 虽然…但是 / 因为…所以 / 还是2 / 那","连词：但、但是、那、虽然、还是2、因为2、所以","Liên từ nối mệnh đề: 虽然…但是 / 因为…所以 / 还是2 / 那","節をつなぐ接続詞：虽然…但是・因为…所以・还是2・那"],"f":["虽然……，但是/但……（转折）· 因为……，所以……（因果）","A + 还是2 + B？（选择疑问）· 那……（承接推论）"],"why":["ชุดคำสันธานเชื่อมประโยคย่อย 7 ตัวหัวใจของ HSK 2 ที่ช่วยต่อประโยคสั้นให้เป็นประโยคซับซ้อนได้คล่องแคล่ว: (1) 虽然…，但是/但… = 'ถึงแม้ว่า…แต่…' (ขัดแย้ง) — ภาษาจีนใช้ทั้งคู่พร้อมกันได้ (ต่างจากภาษาอังกฤษห้ามใช้ Although + but!) (2) 因为…，所以… = 'เพราะว่า…ดังนั้น…' (เหตุ-ผล) — ใช้คู่กันได้เช่นกัน (ต่างจากอังกฤษห้าม Because + so!) (3) 还是2 = 'หรือ' (ใช้เฉพาะในประโยคคำถามให้เลือก: 喝茶还是喝咖啡？) (4) 那 = 'งั้น… / ถ้าอย่างนั้น…' ใช้สรุปหรือตอบรับต่อจากประโยคก่อนหน้า (外面下雨了，那我们打车吧) · ข้อควรระวัง: ห้ามใช้ 还是2 ในประโยคบอกเล่า ('หรือ' ในบอกเล่าคือ 或者 ใน HSK 3) และคำเชื่อม 虽然/因为 วางหน้าหรือหลังประธานได้ แต่ แต่ละคู่ห้ามใช้ข้ามสายกัน!","Seven core HSK 2 clause conjunctions: (1) 虽然…，但是/但… ('although…but…' — UNLIKE English, Chinese happily pairs BOTH together!); (2) 因为…，所以… ('because…so…' — Chinese also pairs both!); (3) 还是2 ('or' in CHOICE QUESTIONS only: 喝茶还是喝咖啡？); (4) 那 ('then / in that case': 外面下雨了，那我们打车吧). · Caution: NEVER use 还是2 in plain statements (statements take 或者 in HSK 3), and never add 吗 to a 还是2 question!","HSK 2 七个核心分句连词：（1）虽然……，但／但是……（转折，汉语常成对使用）；（2）因为……，所以……（因果，也常成对使用）；（3）还是2（用于选择疑问句：喝茶还是喝咖啡？）；（4）那（承接上文“那么”：下雨了，那我们打车吧）。 · 注意：陈述句表选择不能用“还是”，选择问句末尾绝不加“吗”。","7 liên từ mệnh đề cốt lõi HSK 2: (1) 虽然…，但是/但… (tuy…nhưng… — tiếng Trung dùng cả cặp được!); (2) 因为…，所以… (vì…nên… — dùng cả cặp được!); (3) 还是2 ('hay là' CHỈ dùng trong câu hỏi lựa chọn); (4) 那 ('vậy thì…'). · Lưu ý: không thêm 吗 cuối câu hỏi 还是2.","HSK2の7つの重要接続詞：（1）「虽然…，但是／但…」（〜だが、しかし… — 英語と違い両方ペアで使える）、（2）「因为…，所以…」（〜なので、だから… — ペアで使える）、（3）「还是2」（選択疑問文の「それとも」）、（4）「那」（それなら）。 · 注意：「还是2」の疑問文に「吗」は付けない。"],"use":[{"ok":true,"zh":"虽然今天很冷，但是我还是去跑步了。","fix":"","py":"Suīrán jīntiān hěn lěng, dànshì wǒ háishi qù pǎobù le.","tr":["ถึงแม้วันนี้จะหนาวมาก แต่ฉันก็ยังไปวิ่งอยู่ดี","Although it's very cold today, I still went jogging.","Tuy hôm nay rất lạnh nhưng tôi vẫn đi chạy bộ.","今日はとても寒いですが、それでもジョギングに行きました。"],"h":["ภาษาจีนใช้ 虽然…，但是… คู่กันในประโยคเดียวได้ (ต่างจากอังกฤษ!)","Chinese pairs 虽然…但是… together in one sentence (unlike English Although+but!)","汉语允许“虽然……，但是……”成对呼应","Tiếng Trung dùng cả cặp 虽然…，但是… rất chuẩn","中国語では「虽然…，但是…」をセットで呼応させるのが自然"],"w":["ทำได้และเป็นรูปมาตรฐานที่ชัดเจนที่สุดของภาษาจีน (จะละ 虽然 หรือละ 但是 ไว้แค่ตัวเดียวก็ได้เช่นกัน)","Works as the clearest standard Chinese pattern (you may also omit one of the two if desired).","“虽然……，但是……”前后呼应，转折关系一目了然。","Đúng chuẩn tiếng Trung (cũng có thể lược 1 trong 2 từ khi cần gọn).","「虽然…，但是…」の呼応で逆接関係が非常に明確になる。"],"ref":"HSK 3.0 g3-2-029 · g3-2-069"},{"ok":true,"zh":"外面下雨了，那我们在家看电视吧。","fix":"","py":"Wàimiàn xià yǔ le, nà wǒmen zài jiā kàn diànshì ba.","tr":["ข้างนอกฝนตกแล้ว งั้นพวกเราดูทีวีอยู่บ้านกันเถอะ","It's raining outside; then let's watch TV at home.","Bên ngoài mưa rồi, vậy chúng ta ở nhà xem TV đi.","外は雨が降ってきたね、それなら家でテレビを見よう。"],"h":["ใช้ 那 ต้นประโยคหลังเพื่อแปลว่า 'งั้น… / ถ้าอย่างนั้น…'","Start the response clause with 那 for 'then / in that case'","“那……”承接前文引出决定或推论","Dùng 那 đầu vế sau nghĩa là 'vậy thì…'","前の状況を受けて「それなら…」と導く「那」"],"w":["ทำได้และเป็นธรรมชาติมากในบทสนทนาจริง (เหมือนคำว่า 'งั้น…' ในภาษาไทยเป๊ะ)","Works super naturally in conversation to draw a quick conclusion from the previous fact.","口语中用“那……”顺势提出决定或看法，自然流畅。","Đúng và cực kỳ tự nhiên trong hội thoại hằng ngày ('vậy thì…').","会話で前の発言を受けて「それなら…」と決断や提案を導く定番表現。"],"ref":"HSK 3.0 g3-2-029"},{"ok":false,"zh":"你喝红茶还是绿茶吗？","fix":"你喝红茶还是绿茶？","py":"Nǐ hē hóngchá háishi lǜchá?","tr":["คุณดื่มชาแดงหรือชาเขียว","Do you drink black tea or green tea?","Bạn uống hồng trà hay trà xanh?","紅茶と緑茶のどちらを飲みますか。"],"h":["ห้ามเติม 吗 ท้ายประโยคคำถามให้เลือกที่มี 还是2!","NEVER add 吗 at the end of a 还是2 choice question!","用“还是2”的选择问句末尾绝不能加“吗”","Tuyệt đối không thêm 吗 cuối câu hỏi lựa chọn 还是2!","選択疑問文「还是2」の末尾に「吗」は付けない"],"w":["ไม่ได้ เพราะ 还是2 บังคับให้ผู้ฟังเลือกตอบระหว่าง A กับ B อยู่แล้ว ไม่ใช่คำถามใช่/ไม่ใช่ จึงห้ามใส่ 吗 ท้ายประโยคเด็ดขาด","Wrong because 还是2 asks the listener to pick A or B (not yes/no), so adding 吗 is always ungrammatical.","不行，“还是”已构成选择疑问，句末绝不能再加是非问词“吗”。","Không được vì 还是 đã là câu hỏi lựa chọn rồi, không thể kèm 吗.","「还是」は選択疑問文なので諾否の「吗」を重ねてはいけない。"],"ref":"HSK 3.0 g3-2-029 · g3-2-056"}],"ex":[["虽然很贵，但是很好看。","Suīrán hěn guì, dànshì hěn hǎokàn.","ถึงแม้จะแพงมาก แต่สวยมากเลย","Although it's very expensive, it looks great.","Tuy rất đắt nhưng rất đẹp.","とても高いですが、とてもきれいです。","但是"],["因为下雨了，所以我没出门。","Yīnwèi xià yǔ le, suǒyǐ wǒ méi chūmén.","เพราะฝนตก ฉันเลยไม่ได้ออกจากบ้าน","Because it rained, I didn't go out.","Vì trời mưa nên tôi không ra ngoài.","雨が降ったので外出しませんでした。","所以"],["你想喝咖啡还是奶茶？","Nǐ xiǎng hē kāfēi háishi nǎichá?","คุณอยากดื่มกาแฟหรือชานม","Would you like coffee or milk tea?","Bạn muốn uống cà phê hay trà sữa?","コーヒーとミルクティーのどちらが飲みたいですか。","还是"],["你累了，那休息一会儿吧。","Nǐ lèi le, nà xiūxi yīhuìr ba.","คุณเหนื่อยแล้ว งั้นพักสักหน่อยเถอะ","You're tired — then rest a little while.","Bạn mệt rồi, vậy nghỉ một lát đi.","疲れたでしょう、それなら少し休んでね。","那"],["他很忙，但每天都运动。","Tā hěn máng, dàn měi tiān dōu yùndòng.","เขายุ่งมาก แต่ก็ออกกำลังกายทุกวัน","He is very busy, yet exercises every day.","Anh ấy rất bận nhưng ngày nào cũng tập thể dục.","彼はとても忙しいですが毎日運動します。","但"]],"err":[["你喝红茶还是绿茶吗？","你喝红茶还是绿茶？","คำถามให้เลือก (还是) ห้ามเติม 吗 ท้ายประโยค","Never add 吗 to a 还是 choice question.","选择问句“还是”句末绝不加“吗”。","Câu hỏi lựa chọn 还是 không thêm 吗.","選択疑問文「还是」の文末に「吗」は付けない。"]],"rel":["g3-2-068","g3-2-069","g3-2-070"]},"g3-2-030":{"t":["3 เตอะ (的 / 地 / 得): เจาะลึก 地 (หน้ากริยา) และ 得 (หลังกริยา)","The 3 'de's: 结构助词 地 (before verb) & 得 (after verb)","结构助词：得、地（对比“的”）","3 chữ 'de': Trợ từ kết cấu 地 (trước động từ) & 得 (sau động từ)","3つの「de」：構造助詞「得・地」（「的」との使い分け）"],"f":["定语 + 的 + 名词（漂亮的衣服 / 我的书）","状语（方式/神态）+ 地 + 动词（高兴地笑 / 慢慢地走）","动词 + 得 + 形容词性补语（跑得很快 / 说得不错）"],"why":["นี่คือ '3 เตอะ' ในตำนานที่ออกเสียง de (เสียงเบา) เหมือนกันเป๊ะ แต่แบ่งหน้าที่ชัดเจนตาม 'ตัวที่อยู่ติดกัน': · ① 的 (HSK 1) อยู่ 'หน้าคำนาม' (บอกลักษณะหรือเจ้าของ: 漂亮的衣服, 我的书) · ② 地 (HSK 2) อยู่ 'หน้าคำกริยา' (บอกว่าทำด้วยอาการ/ความรู้สึกอย่างไร: 高兴地笑了 = ยิ้มอย่างดีใจ, 慢慢地走 = เดินอย่างช้า ๆ) · ③ 得 (HSK 2) อยู่ 'หลังคำกริยา' (เชื่อมส่วนเสริมบอกผลลัพธ์หรือระดับความเก่งว่าทำได้แค่ไหน: 跑得很快 = วิ่งได้เร็วมาก, 说得很好 = พูดได้ดีมาก) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) จำสั้น ๆ ว่า 'นามใช้ 的 · หน้ากริยาใช้ 地 · หลังกริยาใช้ 得' — ห้ามเขียนสลับกันเด็ดขาด (他跑的很快 ผิด 100%! ต้องเป็น 他跑得很快!) (2) หลังกริยาที่มีกรรมติดมาด้วย (เช่น 说汉语) เมื่อใช้ 得 ต้องซ้ำกริยาหรือย้ายกรรมขึ้นหน้า (他说汉语说得很好 — ห้ามพูด 他说汉语得很好!)","Meet the famous '3 de's' — all pronounced neutral 'de', strictly split by what sits next to them: · ① 的 (HSK 1) comes BEFORE a NOUN (漂亮的衣服, 我的书). · ② 地 (HSK 2) comes BEFORE a VERB to describe the manner/feeling (高兴地笑了 'smiled happily', 慢慢地走 'walk slowly'). · ③ 得 (HSK 2) comes AFTER a VERB to introduce how well or to what degree it is done (跑得很快 'run very fast', 说得很好 'speak very well'). · Two iron rules: (1) NEVER swap them (他跑的很快 is wrong — use 得!). (2) 得 MUST touch the verb directly — if there is an object, repeat the verb or front the object (他说汉语说得很好, NEVER 他说汉语得很好!).","著名的“的、地、得”读音均为轻声 de，分工严格清晰： · ① 的（定语标志）：放在名词前（漂亮的衣服、我的书）。 · ② 地（状语标志）：放在动词前，描写动作方式或神态（高兴地笑了、慢慢地走）。 · ③ 得（补语标志）：放在动词或形容词后，引出程度或状态评价（跑得很快、说得很好）。 · 两条铁律：（1）三者绝不能混写（不说“他跑的很快”）；（2）“得”必须紧贴动词，带宾语时须重复动词或提前宾语（说“他说汉语说得很好”，绝不说“他说汉语得很好”）。","Bộ ba 'de' kinh điển (cùng đọc nhẹ de) chia việc cực rõ: · ① 的 đứng TRƯỚC DANH TỪ (漂亮的衣服, 我的书). · ② 地 đứng TRƯỚC ĐỘNG TỪ chỉ cách thức/trạng thái (高兴地笑了, 慢慢地走). · ③ 得 đứng SAU ĐỘNG TỪ nối bổ ngữ đánh giá mức độ/kết quả (跑得很快, 说得很好). · 2 quy tắc thép: (1) Không viết lẫn 3 chữ (không nói 他跑的很快!); (2) 得 phải bám sát động từ — có tân ngữ thì lặp động từ (他说汉语说得很好, không nói 他说汉语得很好!).","有名な3つの「de」（いずれも軽声 de）の厳密な使い分け： · ①「的」は名詞の前（漂亮的衣服・我的书）。 · ②「地」は動詞の前で様子・やり方（高兴地笑了・慢慢地走）。 · ③「得」は動詞の後ろで程度・評価（跑得很快・说得很好）。 · 鉄則2つ：（1）混同厳禁（他跑的很快×→他跑得很快○）。（2）「得」は動詞に直結させ、目的語があるときは動詞を重ねる（他说汉语说得很好、他说汉语得很好×）。"],"use":[{"ok":true,"zh":"他高兴地笑了。","fix":"","py":"Tā gāoxìng de xiào le.","tr":["เขายิ้มออกมาอย่างดีใจ","He smiled happily.","Anh ấy vui vẻ mỉm cười.","彼は嬉しそうに笑いました。"],"h":["บอกท่าทาง/อารมณ์ 'หน้ากริยา' ใช้ คำขยาย + 地 + กริยา","Describe manner/feeling BEFORE a verb with Modifier + 地 + Verb","状语描写动作神态放动词前，用“地”（高兴地笑）","Chỉ trạng thái/cách thức TRƯỚC động từ dùng 地 (高兴地笑)","動詞の前で様子・感情を修飾するときは「地」（高兴地笑）"],"w":["ทำได้เพราะ 高兴 (ดีใจ) เป็นคุณศัพท์ 2 พยางค์ที่ขยายกริยา 笑 (ยิ้ม) ด้านหลัง จึงเชื่อมด้วย 地 (เทียบภาษาอังกฤษ -ly: happily)","Works cleanly because 2-syllable 高兴 modifies the following verb 笑 via 地 (just like English '-ly').","“高兴”作状语修饰后面的动词“笑”，中间用结构助词“地”。","Đúng vì 高兴 bổ nghĩa cho động từ 笑 đứng sau nên nối bằng 地.","2音節の「高兴」が後ろの動詞「笑」を修飾するため「地」で結ぶ。"],"ref":"HSK 3.0 g3-2-030"},{"ok":true,"zh":"他跑得很快。","fix":"","py":"Tā pǎo de hěn kuài.","tr":["เขาวิ่งเร็วมาก","He runs very fast.","Anh ấy chạy rất nhanh.","彼は走るのがとても速いです。"],"h":["ประเมินผลลัพธ์/ความเก่ง 'หลังกริยา' ใช้ กริยา + 得 + 很/非常 + คุณศัพท์","Evaluate performance AFTER a verb with Verb + 得 + Degree + Adj","动词后评价动作程度或结果，用“得”（跑得很快）","Đánh giá mức độ SAU động từ dùng 得 (跑得很快)","動詞の後ろで程度・結果を評価するときは「得」（跑得很快）"],"w":["ทำได้ตามกลุ่มเทียบคำ g36 เพราะ 很快 (เร็วมาก) ขยายผลลัพธ์หลังกริยา 跑 จึงต้องเชื่อมด้วย 得 เท่านั้น","Works per comparison group g36: 很快 evaluates the verb 跑 from behind, so it MUST link with 得.","“很快”在动词“跑”后作状态补语评价速度，必须用“得”。","Đúng theo nhóm g36 vì 很快 đánh giá kết quả sau động từ 跑 nên bắt buộc dùng 得.","動詞「跑」の後ろで速さを評価する補語なので必ず「得」を使う。"],"ref":"กลุ่มเทียบคำ g36 · HSK 3.0 g3-2-052"},{"ok":false,"zh":"他跑的很快。","fix":"他跑得很快。","py":"Tā pǎo de hěn kuài.","tr":["เขาวิ่งเร็วมาก","He runs very fast.","Anh ấy chạy rất nhanh.","彼は走るのがとても速いです。"],"h":["ห้ามใช้ 的 (หรือ 地) หลังกริยาเพื่อเชื่อมส่วนเสริมความเก่ง/ระดับ!","NEVER use 的 (or 地) after a verb for a state complement — use 得!","动词后引补语绝不能写成“的”或“地”，必须用“得”","Tuyệt đối không dùng 的 hay 地 sau động từ nối bổ ngữ (phải dùng 得)","動詞の後ろの補語に「的・地」は不可、必ず「得」"],"w":["ไม่ได้ตามกลุ่มเทียบคำ g36 เพราะ 的 ใช้ขยายคำนามเท่านั้น (เช่น 跑得很快的人) ส่วนเชื่อมหลังกริยา 跑 เพื่อบอกระดับความเร็วบังคับใช้ 得","Wrong per group g36: 的 only modifies nouns; linking a performance complement after verb 跑 strictly requires 得.","不行，“的”只用于名词定语，动词后带补语必须用“得”：他跑得很快。","Không được theo nhóm g36: 的 chỉ đứng trước danh từ, sau động từ phải dùng 得.","「的」は名詞修飾専用。動詞の後ろで程度を述べるのは必ず「得」。"],"ref":"กลุ่มเทียบคำ g36"},{"ok":false,"zh":"他说汉语得很好。","fix":"他说汉语说得很好。","py":"Tā shuō Hànyǔ shuō de hěn hǎo.","tr":["เขาพูดภาษาจีนได้ดีมาก","He speaks Chinese very well.","Anh ấy nói tiếng Trung rất giỏi.","彼は中国語を話すのがとても上手です。"],"h":["ห้ามเอากรรม (汉语) มาคั่นระหว่างกริยา (说) กับ 得!","NEVER let an object (汉语) come between the verb (说) and 得!","“得”必须紧跟动词，有宾语时须重复动词（说汉语说得很好）","Không để tân ngữ chen giữa động từ và 得 (phải lặp động từ)","動詞と「得」の間に目的語（汉语）を挟めない（動詞を重ねる）"],"w":["ไม่ได้ เพราะ 得 ต้องเกาะติดหลังกริยา 说 โดยตรงเท่านั้น ถ้ามีกรรม 汉语 ต้องซ้ำกริยาเป็น 他说汉语说得很好 หรือย้ายกรรมขึ้นหน้าเป็น 他汉语说得很好","Wrong because 得 must touch the verb directly — repeat the verb (他说汉语说得很好) or front the object (他汉语说得很好).","不行，“得”不能隔着宾语“汉语”，须重动说“他说汉语说得很好”或把宾语提前“他汉语说得很好”。","Không được vì 得 phải bám sát động từ; phải lặp động từ (说汉语说得很好) hoặc đảo tân ngữ lên trước.","「得」は必ず動詞の直後に置く。目的語があるときは「他说汉语说得很好」または「他汉语说得很好」にする。"],"ref":"HSK 3.0 g3-2-030 · g3-2-052"}],"ex":[["他跑得很快。","Tā pǎo de hěn kuài.","เขาวิ่งเร็วมาก","He runs very fast.","Anh ấy chạy rất nhanh.","彼は走るのがとても速いです。","得"],["她说汉语说得很好。","Tā shuō Hànyǔ shuō de hěn hǎo.","เธอพูดภาษาจีนได้ดีมาก","She speaks Chinese very well.","Cô ấy nói tiếng Trung rất giỏi.","彼女は中国語を話すのがとても上手です。","得"],["他高兴地笑了。","Tā gāoxìng de xiào le.","เขายิ้มอย่างดีใจ","He smiled happily.","Anh ấy vui vẻ cười.","彼は嬉しそうに笑いました。","地"],["你慢慢地走，别跑。","Nǐ mànmàn de zǒu, bié pǎo.","คุณค่อย ๆ เดินช้า ๆ อย่าวิ่งนะ","Walk slowly; don't run.","Bạn đi từ từ thôi, đừng chạy.","ゆっくり歩いて、走らないでね。","地"],["昨天我睡得很好。","Zuótiān wǒ shuì de hěn hǎo.","เมื่อวานฉันนอนหลับสบายมาก","Yesterday I slept very well.","Hôm qua tôi ngủ rất ngon.","昨日はよく眠れました。","得"]],"err":[["他跑的很快。","他跑得很快。","หลังกริยาบอกระดับ/ความเก่งต้องใช้ 得 ไม่ใช่ 的","After a verb evaluating how well it's done, use 得 — not 的.","动词后引出补语用“得”，不用“的”。","Sau động từ nối bổ ngữ mức độ dùng 得, không dùng 的.","動詞の後ろの評価補語は「的」でなく「得」。"],["他说汉语得很好。","他说汉语说得很好。","得 ต้องติดกริยาโดยตรง มีกรรมให้ซ้ำกริยา: 说汉语说得很好","得 must touch the verb directly; repeat the verb when an object is present.","“得”须紧跟动词，带宾语时重复动词：说汉语说得很好。","得 phải sát động từ; có tân ngữ thì lặp động từ: 说汉语说得很好.","「得」は動詞に直結させ、目的語があれば動詞を重ねる。"]],"rel":["g3-1-024","g3-2-052","g3-2-009"]},"g3-2-031":{"t":["คำช่วยประสบการณ์ 过: เคย… (ผ่านมาแล้วในอดีต)","Experiential particle 过: 'have ever done'","动态助词：过","Trợ từ động thái 过: đã từng…","経験の助詞「过」：〜したことがある"],"f":["肯定：主语 + 动词 + 过 +（宾语）：我去过北京 / 我吃过中国菜","否定：主语 + 没（有）+ 动词 + 过 +（宾语）（保留“过”！）","疑问：主语 + 动词 + 过 + 宾语 + 吗 / 没有？"],"why":["过 (เสียงเบา guo) วาง 'ติดหลังกริยา' เพื่อบอกว่าเคยมีประสบการณ์นั้นมาแล้วในอดีต และเหตุการณ์นั้นจบสิ้นไปแล้วไม่ค้างถึงปัจจุบัน (เช่น 我去过北京 = ฉันเคยไปปักกิ่ง ตอนนี้ไม่ได้อยู่ที่นั่นแล้ว) · ข้อแตกต่างสำคัญที่สุดระหว่าง 过 กับ 了1: (1) เวลาปฏิเสธ 没 + 了1 ต้องตัด 了1 ออก (我没买书) แต่เวลาปฏิเสธ 没 + 过 'ต้องเก็บ 过 ไว้เสมอ!' (我没去过北京 = ฉันไม่เคยไปปักกิ่ง!) (2) ห้ามใช้ 过 กับเรื่องที่ทำซ้ำไม่ได้ (เช่น เกิด/ตาย) หรือกริยาที่มีความหมายถาวร (เช่น 我是过学生 ก็ได้เฉพาะกรณีเคยเป็นแล้วตอนนี้เลิกเป็นแล้ว)","Neutral-tone 过 attaches right after a verb to mark past LIFE EXPERIENCE that is no longer ongoing (我去过北京 'I have been to Beijing [and am back now]'). · #1 contrast with 了1: negating 了1 drops 了 (我没买书), whereas negating 过 ALWAYS KEEPS 过 (我没去过北京 'I have never been to Beijing')! · Question forms: 你去过北京吗？ or 你去过北京没有？","动态助词“过”读轻声，紧跟动词后，表示过去曾有某种经历且该状态已结束（我去过北京）。 · 与“了1”最核心区别：否定“了1”必须去掉“了”（没去），但否定“过”必须保留“过”（没去过北京）！ · 疑问用“……过……吗？”或“……过……没有？”。","Trợ từ 过 (đọc nhẹ guo) đứng sát sau động từ chỉ KINH NGHIỆM từng trải qua và đã kết thúc (我去过北京). · Điểm khác biệt lớn nhất với 了1: phủ định 了1 phải bỏ 了, nhưng phủ định 过 LUÔN GIỮ 过 (我没去过北京 = tôi chưa từng đi Bắc Kinh!).","動的助詞「过」（軽声）は動詞の直後に付き、過去の経験「〜したことがある」を表す（我去过北京）。 · 「了1」との最大の違い：「没」で否定するとき「了1」は落とすが、「过」は必ず残す（我没去过北京＝行ったことがない）。"],"use":[{"ok":true,"zh":"我没去过外国。","fix":"","py":"Wǒ méi qùguo wàiguó.","tr":["ฉันไม่เคยไปต่างประเทศเลย","I have never been abroad.","Tôi chưa từng đi nước ngoài.","外国へ行ったことがありません。"],"h":["ปฏิเสธ 'ไม่เคย…' ใช้ 没(有) + กริยา + 过 (ต้องเก็บ 过 ไว้เสมอ!)","Negate 'have never…' with 没(有) + Verb + 过 (ALWAYS keep 过!)","否定经历态必须保留“过”：没（有）＋动词＋过","Phủ định 'chưa từng' dùng 没(有) + động từ + 过 (LUÔN giữ 过!)","「〜したことがない」は「没（有）＋動詞＋过」（「过」を残す！）"],"w":["ทำได้และจำเป็นต้องคง 过 ไว้ เพราะถ้าตัด 过 ออกเป็น 我没去外国 จะแปลแค่ว่า 'ฉันไม่ได้ไปต่างประเทศ (ในครั้งนั้น)' ไม่ได้แปลว่า 'ไม่เคยไปในชีวิต'","Works and requires keeping 过: dropping 过 changes the meaning to 'I didn't go' instead of 'I have NEVER been'.","保留“过”才表达“从未有过该经历”；若省去“过”则只表某次没去。","Đúng và bắt buộc giữ 过 mới mang nghĩa 'chưa từng có trải nghiệm đó'.","「过」を残すことで「一度も経験がない」という意味になる。"],"ref":"HSK 3.0 g3-2-031 · g3-2-074"},{"ok":true,"zh":"你吃过包子吗？","fix":"","py":"Nǐ chīguo bāozi ma?","tr":["คุณเคยกินซาลาเปาไหม","Have you ever eaten steamed buns?","Bạn đã từng ăn bánh bao chưa?","肉まんを食べたことがありますか。"],"h":["ถามประสบการณ์ใช้ กริยา + 过 + กรรม + 吗 / 没有？","Ask about experience with Verb + 过 + Object + 吗 / 没有？","询问经历用“动词＋过＋宾语＋吗／没有？”","Hỏi kinh nghiệm dùng Động từ + 过 + tân ngữ + 吗 / 没有？","経験を尋ねるときは「動詞＋过＋目的語＋吗／没有？」"],"w":["ทำได้และตอบสั้น ๆ ได้ทันทีว่า 吃过 (เคยกิน) หรือ 没吃过 (ไม่เคยกิน)","Works cleanly and takes short answers 吃过 ('yes, I have') or 没吃过 ('no, never').","回答简洁直观：肯定答“吃过”，否定答“没吃过”。","Đúng và trả lời rất gọn: 吃过 (đã từng) hoặc 没吃过 (chưa từng).","返答も「吃过／没吃过」と簡潔に答えられる。"],"ref":"HSK 3.0 g3-2-031"},{"ok":false,"zh":"我不去过北京。","fix":"我没去过北京。","py":"Wǒ méi qùguo Běijīng.","tr":["ฉันไม่เคยไปปักกิ่ง","I have never been to Beijing.","Tôi chưa từng đi Bắc Kinh.","北京へ行ったことがありません。"],"h":["ห้ามใช้ 不 ปฏิเสธ 过 (ต้องใช้ 没 / 没有 เท่านั้น!)","NEVER negate 过 with 不 — ALWAYS use 没 / 没有!","否定“过”只能用“没（有）”，绝不能用“不”","Tuyệt đối không dùng 不 phủ định 过 (chỉ dùng 没/没有)","「过」を「不」で否定できない（必ず「没（有）」）"],"w":["ไม่ได้ เพราะ 过 เป็นเรื่องประสบการณ์ในอดีต จึงปฏิเสธได้เฉพาะ 没(有) เท่านั้น ห้ามใช้ 不 (ไม่พูด 不去过 / 不吃过)","Wrong because 过 is strictly past experience and can ONLY be negated with 没(有), never 不.","不行，“过”表过去经历，唯一否定词是“没（有）”，绝不说“不去过”。","Không được vì 过 là kinh nghiệm quá khứ nên chỉ dùng 没(有), không dùng 不.","「过」は過去の経験なので否定は必ず「没（有）」で、「不」は不可。"],"ref":"HSK 3.0 g3-2-031 · g3-1-020"}],"ex":[["我去过北京。","Wǒ qùguo Běijīng.","ฉันเคยไปปักกิ่ง","I have been to Beijing.","Tôi đã từng đi Bắc Kinh.","北京へ行ったことがあります。","过"],["我没去过外国。","Wǒ méi qùguo wàiguó.","ฉันไม่เคยไปต่างประเทศ","I have never been abroad.","Tôi chưa từng đi nước ngoài.","外国へ行ったことがありません。","没去过"],["你吃过中国菜吗？","Nǐ chīguo Zhōngguó cài ma?","คุณเคยกินอาหารจีนไหม","Have you ever eaten Chinese food?","Bạn đã từng ăn món Trung Quốc chưa?","中華料理を食べたことがありますか。","过"],["这个电影我看过两次。","Zhège diànyǐng wǒ kànguo liǎng cì.","หนังเรื่องนี้ฉันเคยดูมาสองครั้งแล้ว","I have seen this movie twice.","Bộ phim này tôi từng xem hai lần rồi.","この映画は2回見たことがあります。","过"],["我去年住过这家酒店。","Wǒ qùnián zhùguo zhè jiā jiǔdiàn.","ปีที่แล้วฉันเคยพักโรงแรมแห่งนี้","I stayed at this hotel last year.","Năm ngoái tôi từng ở khách sạn này.","昨年このホテルに泊まったことがあります。","过"]],"err":[["我不去过北京。","我没去过北京。","ปฏิเสธ 过 ใช้ 没(有) เท่านั้น ห้ามใช้ 不","Negate 过 only with 没(有), never 不.","“过”的否定只能用“没（有）”，不用“不”。","Phủ định 过 chỉ dùng 没(有), không dùng 不.","「过」の否定は「不」でなく必ず「没（有）」。"],["你去过北京了吗？","你去过北京吗？","ถามประสบการณ์ใช้ 过 + 吗 ไม่ต้องซ้อน 了 เข้ามา","Ask experience with 过 + 吗 without adding 了.","问经历用“去过……吗？”，不必再加“了”。","Hỏi kinh nghiệm dùng 过 + 吗, không thêm 了.","経験の質問は「过…吗？」で余計な「了」を足さない。"]],"rel":["g3-2-074","g3-2-013","g3-1-062"]},"g3-2-032":{"t":["คำช่วยสภาพต่อเนื่อง 着: …อยู่ / …ค้างไว้ (สถานะกำลังคงอยู่)","Continuous-state particle 着: ongoing state or accompanying action","动态助词：着","Trợ từ động thái 着: đang duy trì trạng thái","持続の助詞「着」：〜している・〜したまま"],"f":["主语 + 动词 + 着（门开着 / 电视开着 / 他拿着一本书）","否定：主语 + 没（有）+ 动词 + 着（门没开着）","伴随动作：动词1 + 着 + 动词2（他笑着说 / 站着看书）"],"why":["着 (เสียงเบา zhe) วาง 'ติดหลังกริยา' เพื่อบอกว่า 'สภาพผลลัพธ์ของการกระทำนั้นยังคงค้างต่อเนื่องอยู่' (ไม่ได้เน้นขยับตัวทำเหมือน 正在 แต่เน้นภาพนิ่งที่ค้างอยู่ตรงหน้า) เช่น 门开着 (ประตูเปิดค้างอยู่), 他拿着一本书 (เขาถือหนังสืออยู่ในมือ), 床上放着→桌子上有 (ใน HSK 2 ใช้ 开着, 拿着, 笑着, 站着, 坐着, 等着) · นอกจากนี้ 'กริยา1 + 着 + กริยา2' ยังแปลว่า 'ทำกริยา 2 ในสภาพของกริยา 1' เช่น 他笑着说 (เขาพูดไปยิ้มไป) · ข้อควรระวัง: (1) ปฏิเสธ 着 ใช้ 没 + กริยา + 着 (门没开着) ห้ามใช้ 不 (2) ห้ามใช้ 着 กับกริยาที่คงสภาพค้างไว้ไม่ได้ (เช่น 来着?, ไป/ถึง/ลืม/จบ: 忘着, 完着, 到着 ผิด!)","Neutral-tone 着 attaches right after a verb to describe a CONTINUING STATE (unlike dynamic 正在): 门开着 ('the door is standing open'), 他拿着一本书 ('he is holding a book'), 笑着说 ('say while smiling'). · Cautions: (1) Negate with 没 + Verb + 着 (门没开着 — NEVER 不开着 for state). (2) NEVER attach 着 to instantaneous/non-continuable verbs like 忘, 完, 到, 去 (never 忘着 or 到着!).","动态助词“着”读轻声，紧跟动词后，表示动作造成的状态正在持续（门开着、他拿着书），或伴随方式（他笑着说、坐着看书）。 · 注意：（1）否定用“没（有）＋动词＋着”（门没开着）；（2）不能用于无法持续的瞬间动词（忘、到、完等）。","Trợ từ 着 (đọc nhẹ zhe) đứng sát sau động từ diễn tả TRẠNG THÁI đang duy trì (门开着 = cửa đang mở, 他拿着书 = anh ấy đang cầm sách) hoặc hành động đi kèm (笑着说 = vừa cười vừa nói). · Lưu ý: phủ định dùng 没 + động từ + 着 (门没开着); không dùng với động từ tức thời như 忘, 到, 完.","動的助詞「着」（軽声）は動詞の直後に付き、状態がそのまま持続していること（门开着・他拿着书）や付帯状況（笑着说＝笑いながら言う）を表す。 · 注意：（1）否定は「没（有）＋動詞＋着」。（2）「忘・到・完」など持続できない瞬間動詞には付かない。"],"use":[{"ok":true,"zh":"教室的门开着。","fix":"","py":"Jiàoshì de mén kāizhe.","tr":["ประตูห้องเรียนเปิดค้างอยู่","The classroom door is open.","Cửa phòng học đang mở.","教室のドアが開いています。"],"h":["บรรยายสภาพที่คงค้างอยู่ (เปิดอยู่ / นั่งอยู่ / ถืออยู่) ใช้ กริยา + 着","Describe a static ongoing state with Verb + 着 (开着 / 坐着 / 拿着)","描写状态持续用“动词＋着”（门开着、电视开着）","Miêu tả trạng thái đang giữ nguyên dùng Động từ + 着","状態の持続には「動詞＋着」（门开着・电视开着）"],"w":["ทำได้เพราะ 门开着 ไม่ได้แปลว่ามีคนกำลังเอามือผลักเปิดประตู (正在开门) แต่แปลว่าประตูอยู่ในสภาพเปิดอ้าค้างไว้แล้ว","Works cleanly: 门开着 describes the resulting open state (unlike 正在开门 'is in the act of opening the door').","“门开着”描写门处于敞开的静态状态（区别于正在动作的“正在开门”）。","Đúng vì 门开着 miêu tả trạng thái cửa đang mở sẵn (khác 正在开门 = đang dùng tay mở cửa).","ドアを開けている最中（正在开门）ではなく、開いた状態が続いている描写。"],"ref":"HSK 3.0 g3-2-032 · g3-2-072"},{"ok":true,"zh":"他笑着对我说你好。","fix":"","py":"Tā xiàozhe duì wǒ shuō nǐ hǎo.","tr":["เขายิ้มพลางพูดสวัสดีกับฉัน","He smiled and said hello to me.","Anh ấy vừa cười vừa chào tôi.","彼は笑いながら私にこんにちはと言いました。"],"h":["ทำกริยา 2 ในสภาพกริยา 1: กริยา1 + 着 + กริยา2","Accompanying manner: Verb 1 + 着 + Verb 2","伴随方式：“动词1＋着＋动词2”（笑着说、坐着看书）","Trạng thái đi kèm: Động từ 1 + 着 + Động từ 2 (笑着说)","付帯状況「〜しながら」：「動詞1＋着＋動詞2」（笑着说）"],"w":["ทำได้และสละสลวยมาก โดยกริยาหลักคือ 说 (พูด) ส่วน 笑着 (ยิ้มอยู่) เป็นท่าทางที่เกิดควบคู่ไปด้วยขณะพูด","Works naturally: 说 is the main action, while 笑着 portrays the accompanying smile.","“笑着”作伴随状语修饰主要动作“说”，形象生动。","Đúng và tự nhiên: 说 là hành động chính, 笑着 là trạng thái đi kèm.","主動作「说」に付帯する様子を「笑着」で生き生きと添えている。"],"ref":"HSK 3.0 g3-2-032 · g3-2-073"},{"ok":false,"zh":"教室的门不开着。","fix":"教室的门没开着。","py":"Jiàoshì de mén méi kāizhe.","tr":["ประตูห้องเรียนไม่ได้เปิดอยู่","The classroom door is not open.","Cửa phòng học không mở.","教室のドアは開いていません。"],"h":["ปฏิเสธสภาพ 着 ใช้ 没 + กริยา + 着 ห้ามใช้ 不!","Negate a 着 state with 没 + Verb + 着 — NEVER 不!","否定“着”的状态持续用“没（有）＋动词＋着”，不用“不”","Phủ định trạng thái 着 dùng 没 + động từ + 着, không dùng 不!","「着」の状態の否定は「不」ではなく「没（有）＋動詞＋着」"],"w":["ไม่ได้ เพราะการปฏิเสธว่าสภาพนั้นไม่ได้คงอยู่ต้องใช้ 没 เท่านั้น (门没开着, 电视没开着)","Wrong because negating a continuous state takes 没 (门没开着, 电视没开着), never 不.","不行，否定持续状态须用“没”，说“门没开着”。","Không được vì phủ định trạng thái duy trì bắt buộc dùng 没 (门没开着).","状態の持続を否定するときは「不」ではなく必ず「没（门没开着）」にする。"],"ref":"HSK 3.0 g3-2-032"}],"ex":[["教室的门开着。","Jiàoshì de mén kāizhe.","ประตูห้องเรียนเปิดอยู่","The classroom door is open.","Cửa phòng học đang mở.","教室のドアが開いています。","着"],["他手里拿着一本书。","Tā shǒu lǐ názhe yī běn shū.","ในมือเขาถือหนังสืออยู่หนึ่งเล่ม","He is holding a book in his hand.","Trong tay anh ấy đang cầm một cuốn sách.","彼は手に本を1冊持っています。","着"],["他笑着对我说谢谢。","Tā xiàozhe duì wǒ shuō xièxie.","เขายิ้มพลางพูดขอบคุณฉัน","He smiled and said thank you to me.","Anh ấy vừa cười vừa nói cảm ơn tôi.","彼は笑いながら私にお礼を言いました。","着"],["大家都在门口等着你呢。","Dàjiā dōu zài ménkǒu děngzhe nǐ ne.","ทุกคนกำลังรอคุณอยู่ที่หน้าประตูเลย","Everyone is waiting for you at the doorway.","Mọi người đều đang đứng đợi bạn ở cửa đấy.","みんな入口であなたを待っていますよ。","着"],["门没开着。","Mén méi kāizhe.","ประตูไม่ได้เปิดอยู่","The door isn't open.","Cửa không mở.","ドアは開いていません。","没开着"]],"err":[["教室的门不开着。","教室的门没开着。","ปฏิเสธสภาพ 着 ใช้ 没 + กริยา + 着 ไม่ใช้ 不","Negate 着 with 没 + Verb + 着, never 不.","否定“着”用“没＋动词＋着”，不用“不”。","Phủ định 着 dùng 没 + động từ + 着, không dùng 不.","「着」の否定は「不」ではなく「没＋動詞＋着」。"]],"rel":["g3-2-072","g3-2-073","g3-2-060"]},"g3-2-033":{"t":["คำช่วยน้ำเสียง HSK 2: 呢4 / 吧2 / 的2 / 啊1","Sentence-final particles: 呢4 / 吧2 / 的2 / 啊1","语气助词：呢4、吧2、的2、啊1","Trợ từ ngữ khí: 呢4 / 吧2 / 的2 / 啊1","語気助詞：呢4・吧2・的2・啊1"],"f":["呢4（提醒确认：离这儿还远呢！）· 吧2（同意/推测：好吧 / 你是学生吧？）","的2（肯定语气：没问题的 / 我会的）· 啊1（感叹/热情：太好了啊！/ 快来啊！）"],"why":["คำช่วยน้ำเสียงท้ายประโยค 4 ตัวใน HSK 2 ที่เปลี่ยนประโยคทื่อ ๆ ให้มีชีวิตชีวาเหมือนเจ้าของภาษา: (1) 呢4 = ย้ำความจริงหรือเตือนให้อีกฝ่ายรู้ ('…อยู่นะ / …เชียวแหละ': 机场离这儿很远呢！) (2) 吧2 = คาดเดาแล้วถามย้ำ ('…ใช่ไหม') หรือตกลงยอมรับเบา ๆ ('เอาสิ / ก็ได้': 好吧, 你是王老师吧？) (3) 的2 = ยืนยันหนักแน่นให้ความมั่นใจ ('…แน่นอน / …อยู่แล้ว': 我会去的, 没问题的) (4) 啊1 = อุทานด้วยความรู้สึกหรือทักทายอย่างเป็นกันเอง (多漂亮啊！, 你来啊！) · ข้อควรระวัง: (1) อย่าวางคำช่วยน้ำเสียง 2 ตัวติดกันท้ายประโยค (เช่น 你是学生吧吗？ ผิด!) (2) คำช่วยทั้ง 4 ตัวออกเสียงเบา (neutral tone) เสมอ","Four HSK 2 final particles that make your Chinese sound genuinely native: (1) 呢4 emphasizes or reminds the listener of a fact (机场离这儿很远呢! 'It's quite far, you know!'); (2) 吧2 confirms a guess ('…right?': 你是王老师吧？) or agrees (好吧 'all right'); (3) 的2 adds firm reassurance (我会去的 'I'll definitely go'); (4) 啊1 adds warmth, enthusiasm, or exclamation (多漂亮啊!). · Caution: NEVER stack two final particles together (never 你是学生吧吗？!).","四个高频语气助词（均读轻声）：（1）呢4：强调或提醒某种事实（离这儿很远呢！）；（2）吧2：表推测确认（你是王老师吧？）或同意妥协（好吧）；（3）的2：表坚定肯定、让人放心（我会去的）；（4）啊1：表感叹或热情缓和语气（多漂亮啊！快进吧／快来啊！）。 · 注意：句末不要随意连用两个语气词（不说“你是学生吧吗？”）。","4 trợ từ ngữ khí HSK 2 (đều đọc thanh nhẹ): (1) 呢4 nhấn mạnh/nhắc sự thật (离这儿很远呢!); (2) 吧2 phỏng đoán xác nhận ('phải không?') hoặc đồng ý (好吧); (3) 的2 khẳng định chắc chắn cho yên tâm (我会去的); (4) 啊1 cảm thán/nhiệt tình (多漂亮啊!). · Lưu ý: KHÔNG ghép 2 trợ từ cuối câu (không nói 吧吗).","HSK2の4つの語気助詞（すべて軽声）：（1）「呢4」事実の強調・念押し（离这儿很远呢！）、（2）「吧2」推測確認「〜でしょう？」や同意「わかった」（好吧）、（3）「的2」確信・安心感（我会去的）、（4）「啊1」感嘆・親しみ（多漂亮啊！）。 · 注意：文末に2つの語気助詞を重ねない。"],"use":[{"ok":true,"zh":"明天我会去的，别忘了！","fix":"","py":"Míngtiān wǒ huì qù de, bié wàngle!","tr":["พรุ่งนี้ฉันไปแน่นอน อย่าลืมนะ!","I will definitely go tomorrow — don't forget!","Ngày mai tôi chắc chắn sẽ đi, đừng quên nhé!","明日は必ず行きますからね、忘れないで！"],"h":["ยืนยันหนักแน่นให้ความมั่นใจใช้ 会…的2","Add reassurance/certainty with sentence-final 的2 (我会去的)","句末“的2”表示肯定语气，让人放心","Khẳng định chắc chắn dùng 的2 ở cuối câu (我会去的)","確信・安心感を伝える文末の「的2」（我会去的）"],"w":["ทำได้และน้ำเสียงอบอุ่นมั่นใจกว่าพูดแค่ 明天我会去 เฉย ๆ เพราะ 的2 ช่วยย้ำความรับรองจากผู้พูด","Works warmly and reassuringly: final 的2 adds confidence and commitment beyond plain 我会去.","“我会去的”比光说“我会去”更坚定、更有承诺感。","Đúng và tạo cảm giác chắc chắn, yên tâm hơn hẳn nói trống 我会去.","「我会去」だけより「我会去的」の方が確かな約束の響きになる。"],"ref":"HSK 3.0 g3-2-033"},{"ok":true,"zh":"你是王老师吧？","fix":"","py":"Nǐ shì Wáng lǎoshī ba?","tr":["คุณคืออาจารย์หวังใช่ไหมครับ/คะ (เดาไว้แล้ว)","You're Teacher Wang, right?","Bạn là thầy Vương phải không?","王先生でいらっしゃいますよね？"],"h":["เดาไว้ในใจแล้วถามย้ำเพื่อยืนยัน ใช้ 吧2 (ต่างจาก 吗 ที่ไม่รู้เลย)","Use 吧2 when guessing and seeking confirmation (vs neutral 吗)","有把握的推测确认用“吧2”，完全不知道才用“吗”","Đoán sẵn rồi hỏi xác nhận dùng 吧2 (khác 吗 là chưa biết gì)","推測して確認するときは「吧2」（全く知らない質問は「吗」）"],"w":["ทำได้ตามกลุ่มเทียบคำ g13 เพราะผู้พูดค่อนข้างมั่นใจอยู่แล้วว่าคนตรงหน้าคืออาจารย์หวัง จึงใช้ 吧2 แทน 吗","Works per comparison group g13: 吧2 shows you already have a good guess, whereas 吗 is completely open.","心里已有七八分把握时用“吧”发问，比“吗”更礼貌自然。","Đúng theo nhóm g13: 吧2 dùng khi đã đoán gần chắc, tự nhiên hơn 吗.","ある程度見当がついている確認には「吗」より「吧2」が自然。"],"ref":"กลุ่มเทียบคำ g13 · HSK 3.0 g3-2-033"},{"ok":false,"zh":"你是王老师吧吗？","fix":"你是王老师吧？","py":"Nǐ shì Wáng lǎoshī ba?","tr":["คุณคืออาจารย์หวังใช่ไหมครับ/คะ","You are Teacher Wang, right?","Bạn là thầy Vương phải không?","王先生ですよね？"],"h":["ห้ามเอา 吧 กับ 吗 มาวางซ้อนกันท้ายประโยค","NEVER stack 吧 and 吗 together at sentence end","“吧”和“吗”绝不能在句末连用","Không bao giờ ghép 吧 và 吗 cuối câu","文末に「吧」と「吗」を重ねてはいけない"],"w":["ไม่ได้ เพราะ 吧 กับ 吗 ต่างทำหน้าที่ปิดประโยคคำถามคนละแบบ ต้องเลือกอย่างใดอย่างหนึ่ง (ไม่แน่ใจเลยใช้ 吗 / เดาไว้แล้วใช้ 吧)","Wrong because 吧 and 吗 are competing question particles — pick ONLY ONE: 吗 (open) or 吧 (guess).","不行，“吧”和“吗”不能叠用，只能二选一。","Không được vì 吧 và 吗 không đi chung; chỉ chọn 吗 hoặc 吧.","「吧」と「吗」はどちらか一方のみを使い、重ねてはいけない。"],"ref":"กลุ่มเทียบคำ g13"}],"ex":[["机场离这儿很远呢！","Jīchǎng lí zhèr hěn yuǎn ne!","สนามบินอยู่ห่างจากที่นี่ไกลเชียวแหละ!","The airport is quite far from here, you know!","Sân bay cách đây xa lắm đấy!","空港はここからすごく遠いんですよ！","呢"],["好吧，我们坐地铁去。","Hǎo ba, wǒmen zuò dìtiě qù.","ก็ได้ งั้นพวกเรานั่งรถไฟใต้ดินไปกัน","All right, let's take the subway.","Được thôi, chúng ta đi tàu điện ngầm vậy.","わかった、地下鉄で行きましょう。","吧"],["你是王老师吧？","Nǐ shì Wáng lǎoshī ba?","คุณคืออาจารย์หวังใช่ไหมครับ/คะ","You are Teacher Wang, right?","Bạn là thầy Vương phải không?","王先生ですよね？","吧"],["明天我会去的。","Míngtiān wǒ huì qù de.","พรุ่งนี้ฉันไปแน่นอน","I will definitely go tomorrow.","Ngày mai tôi chắc chắn sẽ đi.","明日は必ず行きますよ。","的"],["这里的花多漂亮啊！","Zhèlǐ de huā duō piàoliang a!","ดอกไม้ที่นี่ช่างสวยเหลือเกิน!","How beautiful the flowers here are!","Hoa ở đây đẹp biết bao!","ここの花はなんてきれいなんだろう！","啊"]],"err":[["你是王老师吧吗？","你是王老师吧？","ห้ามวาง 吧 กับ 吗 ซ้อนกันท้ายประโยค (เลือกตัวเดียว)","Never stack 吧 and 吗; pick just one.","句末不能连用“吧吗”，只能选一个。","Không ghép 吧吗 ở cuối câu.","文末に「吧吗」と重ねずどちらか一方を選ぶ。"]],"rel":["g3-1-026","g3-2-014","g3-2-065"]},"g3-2-034":{"t":["วลีกริยา-ส่วนเสริม (动补短语1): กริยา + ผลลัพธ์ / ทิศทาง / ระดับ","Verb-complement phrases (动补短语1)","短语结构：动补短语1","Cụm động bổ (动补短语1)","動補構造（动补短语1）：動詞＋補語"],"f":["动词 + 结果补语（看完 / 听懂 / 写错 / 准备好）","动词 + 趋向补语（进来 / 出去 / 回来）· 动词 + 得 + 形容词（跑得快）"],"why":["动补短语 เป็นโครงสร้างสำคัญมากของภาษาจีนที่ยกระดับจาก HSK 1 สู่ HSK 2 ประกอบด้วย 'กริยาหลัก (อยู่หน้า) + ส่วนเสริมบอกผล/ทิศทาง/ระดับ (อยู่หลัง)' เช่น 看完 (อ่านจบ), 听懂 (ฟังเข้าใจ), 写错 (เขียนผิด), 进来 (เดินเข้ามา), 跑得很快 (วิ่งได้เร็วมาก) · กฎทอง 2 ข้อของ 动补短语: (1) เวลาปฏิเสธกริยา+ผลลัพธ์ (看完, 听懂, 写错) ต้องใช้ 没 (我没听懂 = ฉันฟังไม่เข้าใจ) ห้ามใช้ 不听懂! (2) ห้ามแยกส่วนเสริมผลลัพธ์ (完/懂/错/好) ออกจากกริยาด้วยการเอากรรมไปคั่นตรงกลาง (看书完 ผิด! ต้องเป็น 看完书!)","A verb-complement phrase (动补短语) pairs a main verb with a trailing complement showing result (看完 'finish reading', 听懂 'understand'), direction (进来 'come in'), or degree (跑得很快 'run fast'). · Two golden rules: (1) Negate result complements with 没 (我没听懂 'I didn't catch that', NOT 我不听懂!). (2) NEVER split a verb and its result complement with an object (say 看完书, NEVER 看书完!).","动补短语由“动词＋补语”构成，补充说明动作的结果（看完、听懂、写错）、趋向（进来、出去）或状态（跑得很快）。 · 两条铁律：（1）否定结果补语用“没”（没听懂、没看完），不用“不”；（2）宾语放在动补短语后面（看完书，绝不说“看书完”）。","Cụm động bổ (动补短语) gồm 'Động từ + Bổ ngữ' chỉ kết quả (看完, 听懂, 写错), xu hướng (进来, 出去) hoặc trạng thái (跑得很快). · 2 quy tắc vàng: (1) Phủ định bổ ngữ kết quả dùng 没 (没听懂, không nói 不听懂); (2) Đặt tân ngữ SAU cụm động bổ (看完书, không nói 看书完!).","動補構造（动补短语）は「動詞＋補語」で結果（看完・听懂・写错）、方向（进来・出去）、程度（跑得很快）を表す。 · 2大鉄則：（1）結果補語の否定は「没」（没听懂、「不听懂」は不可）。（2）目的語は動補構造の後ろに置く（看完书、「看书完」は不可）。"],"use":[{"ok":true,"zh":"这本书我还没看完。","fix":"","py":"Zhè běn shū wǒ hái méi kànwán.","tr":["หนังสือเล่มนี้ฉันยังอ่านไม่จบเลย","I haven't finished reading this book yet.","Cuốn sách này tôi vẫn chưa đọc xong.","この本はまだ読み終わっていません。"],"h":["ปฏิเสธกริยา+ส่วนเสริมผลลัพธ์ ใช้ 没(有) + กริยา + ผลลัพธ์","Negate Verb + Result with 没(有) + Verb + Result","否定动结短语用“（还）没＋动词＋结果补语”","Phủ định động từ + bổ ngữ kết quả dùng 没 (没看完)","結果補語の否定は「（还）没＋動詞＋結果補語」"],"w":["ทำได้เพราะ 没看完 แปลว่าผลลัพธ์ 'จบ' ยังไม่เกิดขึ้น (และไม่ใส่ 了 ท้าย 没看完)","Works cleanly because 没看完 states that the completion result has not occurred yet (with no 了).","“没看完”否定结果实现，结构简洁地道。","Đúng vì 没看完 phủ định kết quả 'xong' chưa đạt được.","「読み終える」という結果が未実現であることを「没看完」で表す。"],"ref":"HSK 3.0 g3-2-034 · g3-2-048"},{"ok":true,"zh":"我做好早饭了。","fix":"","py":"Wǒ zuòhǎo zǎofàn le.","tr":["ฉันทำอาหารเช้าเสร็จเรียบร้อยแล้ว","I have finished making breakfast.","Tôi đã làm xong bữa sáng rồi.","朝ご飯を作り終えました。"],"h":["กรรม (早饭) วาง 'หลัง' กริยา+ผลลัพธ์ (做好) เสมอ","Put the object (早饭) AFTER the verb+result pair (做好)","宾语放在动结短语后面：做好早饭／看完书","Đặt tân ngữ SAU cụm động–bổ: 做好早饭 / 看完书","目的語は「動詞＋結果補語」の後ろ（做好早饭・看完书）"],"w":["ทำได้เพราะ 做好 ติดกันเป็นก้อนเดียวแล้วค่อยตามด้วยกรรม 早饭 (เช่นเดียวกับ 看完这本书, 听懂这个问题)","Works because 做好 forms a tight verb-result unit before the object 早饭 (just like 看完这本书).","“做好”紧密结合再带宾语“早饭”，完全符合汉语动补语序。","Đúng vì 做好 gắn liền thành một khối rồi mới tới tân ngữ 早饭.","「做好」がひとまとまりになり、後ろに目的語「早饭」を取る。"],"ref":"HSK 3.0 g3-2-034"},{"ok":false,"zh":"我看书完了。","fix":"我看完书了。","py":"Wǒ kànwán shū le.","tr":["ฉันอ่านหนังสือจบแล้ว","I finished reading the book.","Tôi đọc xong sách rồi.","本を読み終わりました。"],"h":["ห้ามเอาคำนามกรรม (书) มาแทรกระหว่างกริยา (看) กับผลลัพธ์ (完)!","NEVER insert the object (书) between the verb (看) and result (完)!","不能把宾语插在动词和结果补语中间（看书完×）","Không chèn tân ngữ vào giữa động từ và bổ ngữ kết quả (看书完×)","動詞と結果補語の間に目的語を挟めない（看书完×→看完书○）"],"w":["ไม่ได้ เพราะในภาษาไทยเรียง 'อ่าน + หนังสือ + จบแล้ว' แต่ในภาษาจีนส่วนเสริมผลลัพธ์ 完 ต้องเกาะติดกริยา 看 ก่อนเสมอแล้วค่อยวางกรรม: 看完书了","Wrong because Thai puts 'read + book + finish', whereas Chinese binds verb + result tightly BEFORE the object: 看完书了.","不行，汉语动结短语不能被宾语隔开，须说“看完书了”。","Không được vì tiếng Trung gắn chặt động từ + kết quả trước tân ngữ: 看完书了.","動詞と結果補語は切り離せず、必ず「看完书了」の順にする。"],"ref":"HSK 3.0 g3-2-034 · g3-2-048"}],"ex":[["我看完这本书了。","Wǒ kànwán zhè běn shū le.","ฉันอ่านหนังสือเล่มนี้จบแล้ว","I finished reading this book.","Tôi đã đọc xong cuốn sách này rồi.","この本を読み終わりました。","看完"],["我听懂这个问题了。","Wǒ tīngdǒng zhège wèntí le.","ฉันฟังคำถามนี้เข้าใจแล้ว","I understood this question.","Tôi nghe hiểu câu hỏi này rồi.","この質問の意味が分かりました。","听懂"],["不好意思，我写错了。","Bù hǎoyìsi, wǒ xiěcuò le.","ขอโทษที ฉันเขียนผิดไป","Sorry, I wrote it wrong.","Xin lỗi, tôi viết sai rồi.","すみません、書き間違えました。","写错"],["妈妈做好早饭了。","Māma zuòhǎo zǎofàn le.","แม่ทำอาหารเช้าเสร็จเรียบร้อยแล้ว","Mom finished making breakfast.","Mẹ đã làm xong bữa sáng rồi.","母が朝ご飯を作り終えました。","做好"],["你跑得真快！","Nǐ pǎo de zhēn kuài!","คุณวิ่งเร็วจริง ๆ เลย!","You run really fast!","Bạn chạy nhanh thật đấy!","本当に走るのが速いですね！","跑得"]],"err":[["我看书完了。","我看完书了。","ส่วนเสริมผลลัพธ์ (完/懂/错/好) ต้องติดกริยาก่อนแล้วค่อยตามด้วยกรรม","Keep verb + result together BEFORE the object (看完书了).","动词与结果补语紧连，宾语放后（看完书了）。","Gắn chặt động từ + kết quả trước tân ngữ (看完书了).","動詞と結果補語をくっつけ、目的語を後ろに置く（看完书了）。"],["我不听懂。","我没听懂。","ปฏิเสธผลลัพธ์ (听懂 / 看完) ใช้ 没 ไม่ใช่ 不","Negate result complements with 没 (没听懂), not 不.","否定结果补语用“没”（没听懂），不用“不”。","Phủ định bổ ngữ kết quả dùng 没 (没听懂), không dùng 不.","結果補語の否定は「不」ではなく「没」（没听懂）。"]],"rel":["g3-2-048","g3-2-049","g3-2-052"]},"g3-2-035":{"t":["วลี “的” (的字短语): อันสีแดง / ของฉัน / ของกิน (ละคำนามหลัง 的)","The 的-phrase (“的”字短语): 'the red one / mine / things to eat'","短语结构：“的”字短语","Cụm chữ 的 (“的”字短语): cái màu đỏ / của tôi / đồ ăn","「的」名詞句（“的”字短语）：赤いもの・私のもの"],"f":["名词 / 代词 / 形容词 / 动词 + 的 → 代替省略的名词","例如：这件是我的 / 我要红色的 / 我买了很多吃的"],"why":["“的”字短语 คือการเติม 的 ท้ายคำนาม สรรพนาม คุณศัพท์ หรือกริยา เพื่อทำหน้าที่แทน 'คำนามที่ละไว้ในฐานที่เข้าใจ' (เหมือนคำว่า 'one / ของ… / อันที่…' ในภาษาไทยและอังกฤษ) · ตัวอย่างสุดฮิต: (1) สรรพนาม + 的: 这本书是我的 (หนังสือเล่มนี้เป็น 'ของฉัน') (2) คุณศัพท์ + 的: 我喜欢红色的 (ฉันชอบ 'อันสีแดง'), 我要大的 (เอา 'อันใหญ่') (3) กริยา + 的: 我买了很多吃的和喝的 (ฉันซื้อ 'ของกิน' และ 'ของดื่ม' มาเยอะเลย), 卖菜的→开车的 (คนขับรถ) · ข้อควรระวัง: (1) จะละคำนามหลัง 的 ได้ต่อเมื่อคู่สนทนารู้จากบริบทแล้วว่าหมายถึงอะไร (2) ห้ามละ 的 ออกในประโยคบอกความเป็นเจ้าของเช่น 这本书是我 (ผิด! ต้องเป็น 这本书是我的!)","A 的-phrase (“的”字短语) adds 的 to a pronoun, adjective, or verb so it stands in for an understood noun (like English 'mine / the red one / things to eat'): 这本书是我的 ('is mine'), 我要红色的 ('I want the red one'), 吃的和喝的 ('food and drinks'). · Cautions: (1) Only omit the noun when context makes it clear. (2) NEVER drop 的 in possessive predicates (这本书是我 literally claims 'This book is me!' — always say 这本书是我的!).","“的”字短语把“的”附在代词、名词、形容词或动词后，整体起名词作用，替代语境中已知的名词：这是我的、我要红色的、买了很多吃的。 · 注意：（1）须有明确语境；（2）表领属作宾语时绝不能漏“的”（不说“这本书是我”，须说“这本书是我的”）。","Cụm chữ 的 (“的”字短语) gắn 的 sau đại từ, tính từ hoặc động từ để thay cho danh từ đã hiểu ngầm: 这是我的 (cái này của tôi), 我要红色的 (tôi lấy cái màu đỏ), 吃的 (đồ ăn). · Lưu ý: KHÔNG bỏ 的 trong câu sở hữu (phải nói 这本书是我的, không nói 这本书是我!).","「的」名詞句は代名詞・形容詞・動詞に「的」を付けて省略された名詞の代わりにする用法：这是我的（私のです）、我要红色的（赤いのが欲しい）、吃的（食べ物）。 · 注意：所有の述語では絶対に「的」を省けない（「这本书是我」は「この本は私だ」になる）。"],"use":[{"ok":true,"zh":"我要红色的，不要黑色的。","fix":"","py":"Wǒ yào hóngsè de, bùyào hēisè de.","tr":["ฉันเอาอันสีแดง ไม่เอาอันสีดำ","I want the red one, not the black one.","Tôi lấy cái màu đỏ, không lấy cái màu đen.","赤いのが欲しいです、黒いのは要りません。"],"h":["ละคำนามที่รู้กันอยู่แล้วด้วย คุณศัพท์/สี + 的","Stand in for a known noun with Adjective/Color + 的","语境明确时用“形容词＋的”代替名词（红色的、大的）","Thay danh từ đã rõ bằng Tính từ/Màu + 的 (红色的)","既知の名詞を省いて「形容詞・色＋的」で受ける"],"w":["ทำได้และกระชับเป็นธรรมชาติมาก เวลาซื้อเสื้อผ้า รองเท้า หรือผลไม้ที่ไม่ต้องพูดชื่อสิ่งของซ้ำสองรอบ","Works super concisely when shopping — no need to repeat the item name twice.","购物挑选时用“红色的、黑色的”替代物品，简洁地道。","Đúng và gọn khi mua sắm, không phải lặp tên đồ vật hai lần.","買い物などで物の名前を繰り返さずに色や大きさだけで選べる自然な表現。"],"ref":"HSK 3.0 g3-2-035"},{"ok":true,"zh":"我们在超市买了很多吃的和喝的。","fix":"","py":"Wǒmen zài chāoshì mǎile hěn duō chī de hé hē de.","tr":["พวกเราซื้อของกินและของดื่มจากซูเปอร์มาร์เก็ตมาเยอะมาก","We bought lots of things to eat and drink at the supermarket.","Chúng tôi đã mua rất nhiều đồ ăn và đồ uống ở siêu thị.","スーパーで食べ物と飲み物をたくさん買いました。"],"h":["กริยา + 的 ใช้แทน 'ของสำหรับทำ…' (吃的 = ของกิน, 喝的 = ของดื่ม)","Verb + 的 stands for 'things to…' (吃的 'food', 喝的 'drinks')","“动词＋的”可指代人或物（吃的、喝的、开车的）","Động từ + 的 thay cho 'đồ để…' (吃的 = đồ ăn, 喝的 = đồ uống)","「動詞＋的」で「〜するもの・人」（吃的＝食べ物・喝的＝飲み物）"],"w":["ทำได้และใช้บ่อยมากในชีวิตประจำวัน: 吃的 (ของกิน), 喝的 (ของดื่ม), 穿的→玩的 (ใน HSK 2 ใช้ 吃的, 喝的, 开车的)","Works idiomatically in everyday Chinese: 吃的 (edibles), 喝的 (beverages), 开车的 (driver).","“吃的、喝的”是口语最常用的动词性“的”字短语。","Đúng và cực thông dụng: 吃的 (đồ ăn), 喝的 (đồ uống).","「吃的」「喝的」は日常会話で最もよく使われる「的」名詞句。"],"ref":"HSK 3.0 g3-2-035"},{"ok":false,"zh":"这本书是我。","fix":"这本书是我的。","py":"Zhè běn shū shì wǒ de.","tr":["หนังสือเล่มนี้เป็นของฉัน","This book is mine.","Cuốn sách này là của tôi.","この本は私のものです。"],"h":["บอกความเป็นเจ้าของท้ายประโยค ห้ามลืม 的! (是我的 ไม่ใช่ 是我!)","NEVER drop 的 when saying 'is mine / is his'!","表领属“是我的”绝不能漏掉“的”","Chỉ sở hữu 'là của tôi' tuyệt đối không bỏ 的!","所有「私のもの」で「的」を絶対に落とさない"],"w":["ไม่ได้ เพราะ 这本书是我 แปลว่า 'หนังสือเล่มนี้คือตัวฉัน' (ผิดความหมาย!) ต้องเติม 的 เป็น 这本书是我的 จึงจะแปลว่า 'ของฉัน'","Wrong because 这本书是我 literally means 'This book IS me'! Add 的 → 这本书是我的 ('is mine').","不行，“这本书是我”意思完全错了，必须加“的”变成“我的”（属于我的书）。","Không được vì 这本书是我 nghĩa là 'cuốn sách này là tôi'! Phải thêm 的 → 是我的.","「这本书是我」は「この本は私だ」という意味になる。「是我的」と「的」が必須。"],"ref":"HSK 3.0 g3-2-035 · g3-1-024"}],"ex":[["这本书是我的。","Zhè běn shū shì wǒ de.","หนังสือเล่มนี้เป็นของฉัน","This book is mine.","Cuốn sách này là của tôi.","この本は私のものです。","我的"],["我要红色的，不要黑色的。","Wǒ yào hóngsè de, bùyào hēisè de.","ฉันเอาอันสีแดง ไม่เอาอันสีดำ","I want the red one, not the black one.","Tôi lấy cái màu đỏ, không lấy cái màu đen.","赤いのが欲しい、黒いのは要りません。","红色的"],["我买了很多吃的和喝的。","Wǒ mǎile hěn duō chī de hé hē de.","ฉันซื้อของกินและของดื่มมาเยอะมาก","I bought lots of food and drinks.","Tôi đã mua rất nhiều đồ ăn và đồ uống.","食べ物と飲み物をたくさん買いました。","吃的"],["这件衣服太大了，有小的吗？","Zhè jiàn yīfu tài dà le, yǒu xiǎo de ma?","เสื้อตัวนี้ใหญ่เกินไป มีตัวเล็กไหม","This shirt is too big; do you have a smaller one?","Chiếc áo này to quá, có cái nhỏ không?","この服は大きすぎます、小さいのはありますか。","小的"],["那个手机是王老师的。","Nàge shǒujī shì Wáng lǎoshī de.","โทรศัพท์เครื่องนั้นเป็นของอาจารย์หวัง","That mobile phone belongs to Teacher Wang.","Chiếc điện thoại đó là của thầy Vương.","あのスマホは王先生のものです。","王老师的"]],"err":[["这本书是我。","这本书是我的。","บอกความเป็นเจ้าของ 'เป็นของฉัน' ต้องใส่ 的 ปิดท้ายเสมอ","Never drop 的 when saying 'is mine' (是我的).","表示“是我的”不能省略“的”。","Chỉ sở hữu 'là của tôi' phải có 的 (是我的).","「私のもの」は必ず「是我的」と「的」を付ける。"]],"rel":["g3-1-024","g3-2-038","g3-2-047"]},"g3-2-036":{"t":["วลีกริยาเรียงต่อกัน (连谓短语): ทำกริยา 1 แล้วต่อกริยา 2","Serial-verb phrases (连谓短语): chaining two verb actions","短语结构：连谓短语","Cụm liên vị (连谓短语): chuỗi hai động từ","連述句（连谓短语）：複数の動詞句を並べる"],"f":["动词短语1 + 动词短语2（同一主语，按时间/方式先后排列）","例如：坐地铁去上班 / 去商场买衣服 / 打开书看 / 买票看电影"],"why":["连谓短语 คือการนำกลุ่มกริยา 2 กลุ่มขึ้นไปของประธานคนเดียวกันมาเรียงต่อกันโดยไม่มีคำสันธานคั่น เพื่อแสดงความสัมพันธ์ 3 แบบหลัก: (1) ลำดับก่อน–หลังตามเวลาจริง: 打开书看 (เปิดหนังสืออ่าน), 买票看电影 (ซื้อตั๋วดูหนัง) (2) วิธีการ → การกระทำหลัก: 坐地铁去上班 (นั่งรถไฟใต้ดินไปทำงาน), 打车去机场 (นั่งแท็กซี่ไปสนามบิน) (3) การเคลื่อนที่ → จุดประสงค์: 去药店买药 (ไปร้านขายยาซื้อยา), 上网查→上网看新闻→上网买东西 (เข้าเน็ตซื้อของ) · ข้อควรระวัง: ลำดับกริยาใน 连谓短语 สลับกันไม่ได้เด็ดขาด! ต้องเรียงตามเข็มนาฬิกาที่เกิดจริงเสมอ (เช่น ซื้อตั๋วก่อนแล้วค่อยดูหนัง: 买票看电影 ไม่ใช่ 看电影买票)","A serial-verb phrase (连谓短语) chains two or more verb phrases for the SAME subject without conjunctions, expressing: (1) Chronological sequence: 打开书看 ('open the book and read'), 买票看电影 ('buy tickets to see a movie'); (2) Method → Action: 坐地铁去上班 ('take the subway to work'); (3) Motion → Purpose: 去药店买药 ('go to the pharmacy to buy medicine'). · Caution: NEVER reverse the real-world chronological order!","连谓短语由同一主语连续发出的两个以上动词短语组成，不加连词，按逻辑先后排列：（1）顺承先后（打开书看、买票看电影）；（2）方式＋目的（坐地铁去上班）；（3）位移＋目的（去药店买药）。 · 注意：前后动词语序严格依时间逻辑，绝不能颠倒。","Cụm liên vị (连谓短语) ghép liền 2 cụm động từ trở lên của cùng một chủ ngữ không cần từ nối: (1) thứ tự thời gian (打开书看, 买票看电影); (2) phương tiện → đích đến (坐地铁去上班); (3) di chuyển → mục đích (去药店买药). · Lưu ý: KHÔNG đảo ngược trình tự xảy ra thực tế.","連述句（连谓短语）は同一主語の2つ以上の動詞句を接続詞なしで並べる構造：（1）時間順（打开书看・买票看电影）、（2）手段→移動（坐地铁去上班）、（3）移動→目的（去药店买药）。 · 注意：現実の時間・論理の順序を逆にしてはいけない。"],"use":[{"ok":true,"zh":"他买票去看电影了。","fix":"","py":"Tā mǎi piào qù kàn diànyǐng le.","tr":["เขาซื้อตั๋วไปดูหนังแล้ว","He bought a ticket to go see a movie.","Anh ấy mua vé đi xem phim rồi.","彼はチケットを買って映画を見に行きました。"],"h":["เรียง 2–3 กริยาต่อเนื่องตามลำดับเวลาจริงโดยไม่ต้องใส่คำเชื่อม","Chain 2–3 verb actions in real chronological order with no conjunction","按先后顺序自然连用多个动词短语（不加连词）","Xếp nối tiếp các hành động đúng trình tự thời gian (không cần từ nối)","現実の時間順に複数の動詞句を接続詞なしで並べる"],"w":["ทำได้และลื่นไหลมาก: ซื้อตั๋ว (买票) → ไป (去) → ดูหนัง (看电影) เรียงตามขั้นตอนที่เกิดขึ้นจริงทุกประการ","Works smoothly in exact real-world order: buy ticket (买票) → go (去) → watch movie (看电影).","先“买票”再“去看电影”，完全按动作发生的时间顺序排列。","Đúng vì xếp chuẩn theo thứ tự: mua vé (买票) → đi xem phim (去看电影).","「チケットを買う」→「映画を見に行く」という実際の順序通りに並んでいる。"],"ref":"HSK 3.0 g3-2-036"},{"ok":true,"zh":"请大家打开书看第一题。","fix":"","py":"Qǐng dàjiā dǎkāi shū kàn dì-yī tí.","tr":["ขอให้ทุกคนเปิดหนังสือดูข้อที่หนึ่งครับ/ค่ะ","Everyone, please open your books and look at Question 1.","Mời mọi người mở sách xem câu hỏi số 1.","皆さん本を開いて第1問を見てください。"],"h":["ทำกริยา 1 (打开书) เพื่อให้ทำกริยา 2 (看第一题) ต่อได้","Action 1 (打开书) enables Action 2 (看第一题)","前一动作是后一动作的前提（打开书看第一题）","Hành động 1 (打开书) làm tiền đề cho hành động 2 (看第一题)","動作1（打开书）が動作2（看第一题）の前提になる"],"w":["ทำได้เพราะต้องเปิดหนังสือก่อนจึงจะมองดูโจทย์ข้อแรกได้ ไม่ต้องใส่คำเชื่อม 'และ / เพื่อ' คั่นระหว่าง 打开书 กับ 看","Works directly because opening the book naturally precedes looking at Question 1 — no 'and' needed.","先“打开书”才能“看第一题”，两动宾短语直接相连。","Đúng vì mở sách rồi mới xem đề, nối thẳng không cần từ nối.","本を開いてから問題を見るという自然な流れを接続詞なしでつないでいる。"],"ref":"HSK 3.0 g3-2-036"},{"ok":false,"zh":"我看书打开书。","fix":"我打开书看。","py":"Wǒ dǎkāi shū kàn.","tr":["ฉันเปิดหนังสืออ่าน","I open the book and read.","Tôi mở sách ra đọc.","私は本を開いて読みます。"],"h":["ห้ามสลับลำดับกริยาที่เกิดทีหลังขึ้นก่อน (ต้อง เปิดก่อน → ค่อยอ่าน!)","NEVER reverse chronological order (open FIRST → read SECOND!)","连谓短语语序绝不能颠倒（须先“打开书”再“看”）","Không đảo ngược trình tự thực tế (phải mở sách trước rồi mới đọc)","時間順を逆にしてはいけない（開いてから読む！）"],"w":["ไม่ได้ เพราะในความเป็นจริงต้องเปิดหนังสือ (打开书) ก่อนถึงจะอ่าน (看) ได้ การสลับลำดับจะขัดตรรกะภาษาจีนทันที","Wrong because you must open the book before reading it — Chinese serial verbs never invert time order.","不行，连谓短语必须遵循实际发生顺序：先“打开书”，后“看”。","Không được vì phải mở sách trước mới đọc được: 我打开书看.","本を開いてから読むのが現実の順序。必ず「我打开书看」にする。"],"ref":"HSK 3.0 g3-2-036"}],"ex":[["请大家打开书看第一题。","Qǐng dàjiā dǎkāi shū kàn dì-yī tí.","ขอให้ทุกคนเปิดหนังสือดูข้อที่หนึ่ง","Please open your books and look at Question 1.","Mời mọi người mở sách xem câu 1.","皆さん本を開いて第1問を見てください。","打开书"],["我坐地铁去上班。","Wǒ zuò dìtiě qù shàngbān.","ฉันนั่งรถไฟใต้ดินไปทำงาน","I take the subway to work.","Tôi đi tàu điện ngầm đi làm.","地下鉄で出勤します。","坐地铁"],["妈妈去药店买药了。","Māma qù yàodiàn mǎi yào le.","แม่ไปซื้อยาที่ร้านขายยาแล้ว","Mom went to the pharmacy to buy medicine.","Mẹ đi hiệu thuốc mua thuốc rồi.","母は薬局へ薬を買いに行きました。","去药店"],["我喜欢上网买东西。","Wǒ xǐhuan shàngwǎng mǎi dōngxi.","ฉันชอบเข้าเน็ตซื้อของ","I like going online to buy things.","Tôi thích lên mạng mua đồ.","ネットで買い物するのが好きです。","上网"],["他买票去看电影了。","Tā mǎi piào qù kàn diànyǐng le.","เขาซื้อตั๋วไปดูหนังแล้ว","He bought a ticket to watch a movie.","Anh ấy mua vé đi xem phim rồi.","彼はチケットを買って映画を見に行きました。","买票"]],"err":[["我看书打开书。","我打开书看。","วลีกริยาเรียงต่อกันต้องเรียงตามลำดับเวลาที่เกิดจริง","Serial-verb phrases must follow chronological order.","连谓短语严格按先后顺序排列。","Cụm liên vị luôn theo đúng thứ tự thời gian.","連述句は実際の時間順どおりに並べる。"]],"rel":["g3-1-056","g3-1-057","g3-2-037"]},"g3-2-037":{"t":["วลีคำควบสองหน้าที่ (兼语短语): ชวน/สั่ง/ให้ + คน + ทำ…","Pivotal phrases (兼语短语): 请 / 叫 / 让 + Person + Verb","短语结构：兼语短语","Cụm kiêm ngữ (兼语短语): 请 / 叫 / 让 + Người + Động từ","兼語句（兼语短语）：请・叫・让＋人＋動詞"],"f":["请 / 叫 / 让 + 兼语（人）+ 动词（请他吃饭 / 叫你过来 / 让我看看）"],"why":["兼语短语 คือกลุ่มคำที่มี 'คนตรงกลาง (兼语)' ทำหน้าที่ควบสองตำแหน่งในเวลาเดียวกัน: เป็น 'กรรม' ของกริยาตัวแรก (请/叫/让) และเป็น 'ประธาน' ผู้ลงมือทำกริยาตัวที่สอง! · เช่น 请他吃饭 (เชิญเขา + เขากินข้าว = เลี้ยงข้าวเขา), 让我看看 (ให้ฉัน + ฉันดูหน่อย), 叫小王过来 (เรียกเสี่ยวหวัง + เสี่ยวหวังเดินมา) · ข้อควรระวังสำคัญ: (1) ตรงกลางห้ามขาด 'คน (兼语)' ในความหมายชวน/สั่งใครทำ (2) เวลาปฏิเสธต้องวาง 不/没 หน้ากริยาตัวแรก (如 妈妈不让我上网 = แม่ไม่ให้ฉันเล่นเน็ต) หรือหน้ากริยาตัวที่สองถ้าสั่งว่า 'ให้ไม่ทำ' (เช่น 老师叫我们别说话)","A pivotal phrase (兼语短语) has a middle person ('pivot') who plays TWO roles at once: Object of Verb 1 (请/叫/让) AND Subject of Verb 2! · Examples: 请他吃饭 ('invite him to eat'), 让我看看 ('let me take a look'), 叫小王过来 ('tell Xiao Wang to come over'). · Cautions: (1) Always include the pivot person between V1 and V2. (2) Put 不/没 before V1 to forbid/refuse permission (妈妈不让我去 'Mom won't let me go').","兼语短语中间的宾语同时充当后面动词的主语（一身兼两职）：请他吃饭（“他”既是“请”的宾语，又是“吃饭”的主语）、让我看看、叫你过来。 · 注意：否定允许时将“不／没”放第一动词前（妈妈不让我去）。","Cụm kiêm ngữ (兼语短语) có nhân vật ở giữa kiêm 2 vai: vừa là tân ngữ của động từ 1 (请/叫/让), vừa là chủ ngữ của động từ 2! · Ví dụ: 请他吃饭, 让我看看, 叫小王过来. · Lưu ý: phủ định sự cho phép đặt 不/没 TRƯỚC động từ 1 (妈妈不让我去).","兼語句（兼语短语）は真ん中の人が「動詞1の目的語」と「動詞2の主語」の2役を兼ねる構造：请他吃饭・让我看看・叫你过来。 · 注意：「〜させてくれない」の否定は動詞1の前に「不／没」を置く（妈妈不让我去）。"],"use":[{"ok":true,"zh":"妈妈让我每天都喝牛奶。","fix":"","py":"Māma ràng wǒ měi tiān dōu hē niúnǎi.","tr":["แม่ให้ฉันดื่มนมทุกวันเลย","Mom makes/has me drink milk every day.","Mẹ bảo tôi ngày nào cũng phải uống sữa.","母は私に毎日牛乳を飲ませます。"],"h":["请 (เชิญสุภาพ) / 叫 (เรียก/บอก) / 让 (ให้/อนุญาต) + คน + กริยา 2","Use 请 (invite) / 叫 (tell) / 让 (let/make) + Person + Verb 2","使令动词“请／叫／让”＋兼语（人）＋动词2","Động từ sai khiến 请 / 叫 / 让 + Người + Động từ 2","使役動詞「请・叫・让＋人＋動詞2」"],"w":["ทำได้เพราะ 我 เป็นทั้งกรรมของ 让 (แม่ให้ฉัน) และเป็นประธานของ 喝牛奶 (ฉันดื่มนม) ครบโครงสร้าง 兼语短语","Works cleanly: 我 serves both as object of 让 and subject of 喝牛奶.","“我”兼作“让”的宾语和“喝牛奶”的主语，构成标准兼语短语。","Đúng vì 我 vừa là tân ngữ của 让 vừa là chủ ngữ của 喝牛奶.","「我」が「让」の目的語と「喝牛奶」の主語を兼ねている。"],"ref":"HSK 3.0 g3-2-037 · g3-2-066"},{"ok":true,"zh":"爸爸不让我晚上出门。","fix":"","py":"Bàba bù ràng wǒ wǎnshang chūmén.","tr":["พ่อไม่ยอมให้ฉันออกจากบ้านตอนกลางคืน","Dad doesn't let me go out at night.","Bố không cho tôi ra ngoài vào buổi tối.","父は私に夜外出させてくれません。"],"h":["'ไม่ยอมให้ใครทำ…' วาง 不 / 没 ไว้หน้า 让 / 叫 / 请","Put 不 / 没 BEFORE 让 / 叫 / 请 for 'doesn't let someone do…'","表示“不准许”时否定词放在“让／叫／请”前（不让我……）","'Không cho phép ai làm' đặt 不 / 没 TRƯỚC 让 / 叫 / 请","「〜させてくれない」は「不／没」を「让・叫・请」の前に置く"],"w":["ทำได้เพราะเป็นคำสั่งห้ามจากพ่อ (不让) ต่างจาก 爸爸让我不出门 ที่จะฟังแปลกในบริบททั่วไป","Works idiomatically because the negation applies to permission (不让 'does not allow').","“不让我……”清楚表达“不允许”，是兼语短语最常用的否定位置。","Đúng vì 不让 phủ định sự cho phép ('không cho tôi…').","許可しないという意味なので「不」を「让」の前に置くのが自然。"],"ref":"HSK 3.0 g3-2-037"},{"ok":false,"zh":"妈妈让每天喝牛奶我。","fix":"妈妈让我每天喝牛奶。","py":"Māma ràng wǒ měi tiān hē niúnǎi.","tr":["แม่ให้ฉันดื่มนมทุกวัน","Mom has me drink milk every day.","Mẹ bảo tôi uống sữa mỗi ngày.","母は私に毎日牛乳を飲ませます。"],"h":["ห้ามแยกคน (我) ออกจากหลัง 让 / 请 / 叫!","NEVER move the pivot person (我) away from right after 让/请/叫!","兼语（人）必须紧跟在“让／请／叫”后面","Không tách nhân vật (我) khỏi ngay sau 让 / 请 / 叫!","兼語（我）を「让・请・叫」の直後から離してはいけない"],"w":["ไม่ได้ เพราะ 我 ต้องวางติดหลัง 让 ทันทีเพื่อทำหน้าที่เป็นสะพานเชื่อมต่อไปหากริยา 喝牛奶: 妈妈让我每天喝牛奶","Wrong because pivot 我 must stand directly after 让 to bridge cleanly into 喝牛奶.","不行，兼语“我”必须紧跟在“让”后：妈妈让我每天喝牛奶。","Không được vì kiêm ngữ 我 phải đứng ngay sau 让 để làm cầu nối sang 喝牛奶.","兼語の「我」は必ず「让」の直後に置いて「喝牛奶」へつなぐ。"],"ref":"HSK 3.0 g3-2-037"}],"ex":[["今天我请你吃饭。","Jīntiān wǒ qǐng nǐ chīfàn.","วันนี้ฉันเลี้ยงข้าวคุณเอง","Today I'll treat you to a meal.","Hôm nay tôi mời bạn ăn cơm.","今日は私がご飯をご馳走します。","请你吃饭"],["请让我看看。","Qǐng ràng wǒ kànkan.","ขอให้ฉันดูหน่อยนะ","Please let me take a look.","Xin cho tôi xem một chút.","私にちょっと見せてください。","让我看看"],["王老师叫你去教室。","Wáng lǎoshī jiào nǐ qù jiàoshì.","อาจารย์หวังเรียกให้คุณไปที่ห้องเรียน","Teacher Wang told you to go to the classroom.","Thầy Vương gọi bạn lên phòng học.","王先生があなたに教室へ行くように言っています。","叫你去"],["妈妈让我每天喝牛奶。","Māma ràng wǒ měi tiān hē niúnǎi.","แม่ให้ฉันดื่มนมทุกวัน","Mom has me drink milk every day.","Mẹ bảo tôi uống sữa mỗi ngày.","母は私に毎日牛乳を飲ませます。","让我"],["爸爸不让我晚上出门。","Bàba bù ràng wǒ wǎnshang chūmén.","พ่อไม่ให้ฉันออกจากบ้านตอนกลางคืน","Dad doesn't let me go out at night.","Bố không cho tôi ra ngoài buổi tối.","父は夜私を外出させてくれません。","不让我"]],"err":[["妈妈让每天喝牛奶我。","妈妈让我每天喝牛奶。","ผู้ถูกสั่ง/เชิญ (我) ต้องอยู่ติดหลัง 让 / 请 / 叫 เสมอ","The pivot person MUST sit directly after 让 / 请 / 叫.","兼语必须紧跟“让／请／叫”后（让我……）。","Kiêm ngữ luôn đứng sát sau 让 / 请 / 叫.","兼語は必ず「让・请・叫」の直後に置く。"]],"rel":["g3-2-066","g3-2-036"]},"g3-2-038":{"t":["กลุ่มคำทำหน้าที่คำนาม (名词性短语)","Noun phrases (名词性短语): phrases functioning as nouns","短语功能类型：名词性短语","Cụm danh từ (名词性短语)","名詞句（名词性短语）：名詞の働きをする句"],"f":["定语 +（的）+ 名词 · 联合名词 · “的”字短语 · 方位短语","在句中作主语、宾语（我的好朋友 / 一条黑色的裤子 / 桌子上）"],"why":["名词性短语 คือกลุ่มคำที่ 'ทั้งก้อนทำหน้าที่เหมือนคำนาม 1 ตัว' สามารถนำไปวางเป็นประธาน (主语), กรรม (宾语) หรือหลังบุพบท (在/从/往) ได้ทั้งหมด · ตัวอย่างที่พบทุกวันใน HSK 2: (1) วลีขยายนาม: 一条黑色的裤子 (กางเกงสีดำหนึ่งตัว), 我最好的朋友 (เพื่อนสนิทที่สุดของฉัน) (2) วลีเชื่อมคำนาม: 爷爷和奶奶, 红茶跟绿茶 (3) วลี 的: 买东西的, 红色的 (4) วลีตำแหน่ง: 学校的右边 · ข้อควรระวัง: แม้จะมีหลายคำขยายซ้อนกันยาวแค่ไหน คำนามหลัก (中心语) ต้องอยู่ 'ท้ายสุดของก้อน' เสมอ! เช่น 我买的那本汉语书 (ไม่ใช่วาง 汉语书 ไว้ข้างหน้าแบบไทย)","A noun phrase (名词性短语) functions as a single noun unit — filling subject, object, or prepositional slots. · Everyday HSK 2 examples: 一条黑色的裤子, 我最好的朋友, 爷爷和奶奶, 红色的, 学校的右边. · Golden rule: no matter how many modifiers stack up, the HEAD NOUN always sits at the VERY END of the phrase (我买的那本汉语书 — opposite to Thai 'หนังสือภาษาจีนเล่มนั้นที่ฉันซื้อ').","名词性短语整体具有名词的语法功能，可作主语、宾语、定语等，包括定中短语（一条黑色的裤子）、联合名词短语（爷爷和奶奶）、“的”字短语（红色的）、方位短语（学校右边）。 · 核心原则：定语无论多长，中心名词永远位于整个短语的最末尾！","Cụm danh từ (名词性短语) đóng vai trò như 1 danh từ (làm chủ ngữ, tân ngữ…): 一条黑色的裤子, 我最好的朋友, 红色的, 学校右边. · Quy tắc vàng: dù phần bổ nghĩa dài đến đâu, DANH TỪ TRUNG TÂM luôn đứng CUỐI CÙNG (我买的那本汉语书).","名詞句（名词性短语）は全体で1つの名詞のように主語・目的語になる（一条黑色的裤子・我最好的朋友・红色的・学校右边）。 · 鉄則：修飾語がどれだけ長くなっても中心名詞は常に句の最後尾に置く（我买的那本汉语书）。"],"use":[{"ok":true,"zh":"我买的那条裤子很舒服。","fix":"","py":"Wǒ mǎi de nà tiáo kùzi hěn shūfu.","tr":["กางเกงตัวนั้นที่ฉันซื้อใส่สบายมาก","Those pants that I bought are very comfortable.","Chiếc quần đó tôi mua mặc rất thoải mái.","私が買ったあのズボンはとても履き心地がいいです。"],"h":["ซ้อนส่วนขยายยาวไว้ข้างหน้า แล้ววางคำนามหลัก (裤子) ไว้ท้ายสุดของกลุ่ม","Stack modifiers in front and put the head noun (裤子) at the very end","多项修饰语前置，中心名词“裤子”放短语末尾","Xếp các định ngữ phía trước, danh từ chính 裤子 đứng cuối cụm","修飾語をすべて前に積み中心名詞「裤子」を句末に置く"],"w":["ทำได้เพราะ 我买的 (ที่ฉันซื้อ) + 那条 (ตัวนั้น) ต่างขยายคำนามหลัก 裤子 ที่อยู่ท้ายสุด และทั้งก้อนยืนเป็นประธานหน้า 很舒服 ได้สมบูรณ์","Works cleanly: 我买的 + 那条 both modify head noun 裤子 at the end, forming one crisp subject before 很舒服.","“我买的那条裤子”作为一个完整名词性短语作主语，中心语“裤子”压尾。","Đúng vì cả cụm 我买的那条裤子 lấy 裤子 làm trung tâm ở cuối, làm chủ ngữ hoàn chỉnh.","「我买的那条裤子」全体が1つの名詞句として主語になっている。"],"ref":"HSK 3.0 g3-2-038 · g3-2-047"},{"ok":true,"zh":"我认识那个高个子的男孩儿。","fix":"","py":"Wǒ rènshi nàge gāo gèzi de nánháir.","tr":["ฉันรู้จักเด็กผู้ชายตัวสูงคนนั้น","I know that tall boy.","Tôi quen cậu bé cao lớn kia.","私はあの背の高い男の子を知っています。"],"h":["ใช้วลีนามยาวเป็นกรรมหลังกริยา 认识 / 喜欢 / 买 ได้ทั้งก้อน","A full noun phrase fits cleanly as the object of 认识 / 喜欢 / 买","名词性短语整体作动词宾语（认识那个高个子的男孩儿）","Cả cụm danh từ làm tân ngữ sau 认识 / 喜欢 / 买","名詞句全体を動詞の目的語として置ける"],"w":["ทำได้เพราะทั้งก้อน 那个高个子的男孩儿 ทำหน้าที่เหมือนคำนาม 1 ตัวรับหลังกริยา 认识 ได้ทันที","Works naturally because 那个高个子的男孩儿 fills the single object slot after 认识.","整个名词性短语充当“认识”的宾语，层次清晰。","Đúng vì cả cụm 那个高个子的男孩儿 đóng vai trò 1 tân ngữ sau 认识.","長い名詞句全体が「认识」の目的語1枠にすっきり収まっている。"],"ref":"HSK 3.0 g3-2-038"},{"ok":false,"zh":"裤子那条我买的很舒服。","fix":"我买的那条裤子很舒服。","py":"Wǒ mǎi de nà tiáo kùzi hěn shūfu.","tr":["กางเกงตัวนั้นที่ฉันซื้อใส่สบายมาก","Those pants I bought are very comfortable.","Chiếc quần tôi mua đó rất thoải mái.","私が買ったあのズボンはとても快適です。"],"h":["ห้ามวางคำนามหลัก (裤子) ไว้ต้นกลุ่มแบบภาษาไทย!","NEVER put the head noun (裤子) at the front like Thai!","中心名词必须放短语末尾，不能放最前面","Không đặt danh từ chính 裤子 lên đầu cụm như tiếng Việt/Thái!","中心名詞「裤子」を句の先頭に置けない"],"w":["ไม่ได้ เพราะในภาษาไทยพูด 'กางเกง + ตัวนั้น + ที่ฉันซื้อ' แต่ภาษาจีนกลับด้านทั้งหมดเป็น 'ที่ฉันซื้อ + ตัวนั้น + กางเกง': 我买的那条裤子","Wrong because Thai puts 'pants + that + I bought', while Chinese reverses it completely to 我买的那条裤子.","不行，汉语中心语永远在最后：我买的那条裤子。","Không được vì tiếng Trung đảo ngược hoàn toàn: 我买的那条裤子.","中国語では必ず修飾語を先に置き中心名詞「裤子」を最後に置く。"],"ref":"HSK 3.0 g3-2-038 · g3-1-029"}],"ex":[["我买的那条裤子很舒服。","Wǒ mǎi de nà tiáo kùzi hěn shūfu.","กางเกงตัวนั้นที่ฉันซื้อใส่สบายมาก","Those pants I bought are very comfortable.","Chiếc quần đó tôi mua rất thoải mái.","私が買ったあのズボンはとても快適です。","那条裤子"],["我最好的朋友在北京工作。","Wǒ zuì hǎo de péngyou zài Běijīng gōngzuò.","เพื่อนที่ดีที่สุดของฉันทำงานที่ปักกิ่ง","My best friend works in Beijing.","Bạn thân nhất của tôi làm việc ở Bắc Kinh.","私の一番の親友は北京で働いています。","最好的朋友"],["桌子上有一杯热咖啡。","Zhuōzi shàng yǒu yī bēi rè kāfēi.","บนโต๊ะมีกาแฟร้อนอยู่หนึ่งแก้ว","There is a cup of hot coffee on the table.","Trên bàn có một cốc cà phê nóng.","机の上に熱いコーヒーが1杯あります。","热咖啡"],["学校右边是一家药店。","Xuéxiào yòubian shì yī jiā yàodiàn.","ทางขวาของโรงเรียนคือร้านขายยาหนึ่งร้าน","To the right of the school is a pharmacy.","Bên phải trường là một hiệu thuốc.","学校の右側は薬局です。","学校右边"],["我认识那个高个子的男孩儿。","Wǒ rènshi nàge gāo gèzi de nánháir.","ฉันรู้จักเด็กผู้ชายตัวสูงคนนั้น","I know that tall boy.","Tôi quen cậu bé cao lớn kia.","あの背の高い男の子を知っています。","高个子的男孩儿"]],"err":[["裤子那条我买的很舒服。","我买的那条裤子很舒服。","คำนามหลัก (裤子) ต้องอยู่ท้ายสุดของกลุ่มคำนามเสมอ","Always put the head noun (裤子) at the very end of the noun phrase.","名词性短语的中心名词永远在末尾（我买的那条裤子）。","Danh từ trung tâm luôn đứng cuối cụm danh từ (我买的那条裤子).","名詞句の中心名詞は常に最後尾（我买的那条裤子）。"]],"rel":["g3-2-035","g3-2-047","g3-1-029"]},"g3-2-039":{"t":["กลุ่มคำทำหน้าที่คำกริยา (动词性短语)","Verb phrases (动词性短语): phrases functioning as verbs","短语功能类型：动词性短语","Cụm động từ (动词性短语)","動詞句（动词性短语）：動詞の働きをする句"],"f":["动宾 / 状中 / 动补 / 连谓 / 兼语短语 → 作谓语、主语或宾语","例如：每天跑步对身体很好 / 我喜欢打篮球"],"why":["动词性短语 คือกลุ่มคำที่มีคำกริยาเป็นแกนกลาง (เช่น 打篮球, 每天跑步, 看完这本书, 去外国旅游) · จุดเด่นของภาษาจีนที่ง่ายกว่าภาษาอังกฤษมาก: เมื่อนำวลีกริยาทั้งก้อนไปเป็น 'ประธาน' (每天跑步很好 = การวิ่งทุกวันดีมาก) หรือ 'กรรม' (我喜欢打篮球 = ฉันชอบเล่นบาส) ไม่ต้องผันรูปเป็น -ing หรือเติม to เหมือนภาษาอังกฤษเลย! ยกทั้งก้อนไปวางได้ทันที · ข้อควรระวัง: อย่าเผลอใส่ 的 หรือ 是 แทรกมั่วเมื่อเอาวลีกริยาเป็นประธาน (เช่น 每天跑步很好 ไม่ต้องใส่ 是 หน้า 很好!)","A verb phrase (动词性短语) centers on a verb (打篮球, 每天跑步, 看完这本书, 去外国旅游). · Much simpler than English: when a verb phrase acts as a SUBJECT (每天跑步很好 'Jogging every day is great') or OBJECT (我喜欢打篮球 'I like playing basketball'), Chinese NEVER adds '-ing' or 'to' — just drop the bare verb phrase straight in! · Caution: don't insert 是 before an adjective predicate after a verb-phrase subject.","动词性短语以动词为核心（打篮球、每天跑步、去外国旅游），不仅能作谓语，还可不经任何形态变化直接作主语（每天跑步很好）或宾语（我喜欢打篮球）。 · 注意：动词性短语作主语接形容词谓语时，同样不能加“是”。","Cụm động từ (动词性短语) lấy động từ làm hạt nhân (打篮球, 每天跑步, 去外国旅游). Rất tiện lợi: khi làm chủ ngữ (每天跑步很好) hay tân ngữ (我喜欢打篮球) KHÔNG cần chia đuôi '-ing' hay 'to' như tiếng Anh! · Lưu ý: không thêm 是 trước tính từ vị ngữ.","動詞句（动词性短语）は動詞を中心とする句（打篮球・每天跑步・去外国旅游）。英語の動名詞 (-ing) や不定詞 (to) のような語形変化なしで、そのまま主語（每天跑步很好）や目的語（我喜欢打篮球）になれる。"],"use":[{"ok":true,"zh":"每天运动对身体很好。","fix":"","py":"Měi tiān yùndòng duì shēntǐ hěn hǎo.","tr":["การออกกำลังกายทุกวันดีต่อร่างกายมาก","Exercising every day is very good for your health.","Tập thể dục mỗi ngày rất tốt cho sức khỏe.","毎日運動することは体にとても良いです。"],"h":["ยกวลีกริยา (每天运动) เป็นประธานได้เลย ไม่ต้องมีคำนำหน้า 'การ…'","Use a bare verb phrase (每天运动) directly as subject — no '-ing' needed","动词性短语直接作主语（每天运动对身体很好）","Đặt thẳng cụm động từ làm chủ ngữ (每天运动对身体很好)","動詞句をそのまま主語に置ける（語形変化不要）"],"w":["ทำได้และเป็นธรรมชาติมาก ภาษาจีนไม่ต้องเติมคำว่า 'การ' หรือ -ing หน้า 每天运动 ก็ทำหน้าที่เป็นประธานได้ทันที","Works naturally without any '-ing' or nominalizer — 每天运动 directly serves as the sentence subject.","汉语动词性短语无需词形变化即可直接充当主语。","Đúng vì tiếng Trung không cần 'việc' hay '-ing', cụm 每天运动 tự làm chủ ngữ.","「〜すること」に当たる特別な形に変えずそのまま主語にできる。"],"ref":"HSK 3.0 g3-2-039"},{"ok":true,"zh":"我希望明年去中国旅游。","fix":"","py":"Wǒ xīwàng míngnián qù Zhōngguó lǚyóu.","tr":["ฉันหวังว่าปีหน้าจะได้ไปเที่ยวประเทศจีน","I hope to travel to China next year.","Tôi hy vọng năm sau được đi du lịch Trung Quốc.","来年、中国へ旅行に行きたいと思っています。"],"h":["วางวลีกริยายาวทั้งก้อนเป็นกรรมหลัง 希望 / 准备 / 开始 / 喜欢","Place a full verb phrase as the object of 希望 / 准备 / 开始 / 喜欢","动词性短语作“希望／准备／开始／喜欢”的宾语","Cả cụm động từ làm tân ngữ sau 希望 / 准备 / 开始 / 喜欢","「希望・准备・开始・喜欢」の目的語に動詞句全体を置ける"],"w":["ทำได้เพราะ 明年去中国旅游 ทั้งก้อนเป็นกรรมของกริยา 希望 (หวัง) โดยไม่ต้องมีคำเชื่อมใด ๆ คั่นกลาง","Works smoothly: 明年去中国旅游 acts as the complete verb-phrase object of 希望 with no 'to' needed.","“明年去中国旅游”整个动词性短语充当“希望”的宾语。","Đúng vì cả cụm 明年去中国旅游 làm tân ngữ trực tiếp của 希望.","「明年去中国旅游」全体が「希望」の目的語になる。"],"ref":"HSK 3.0 g3-2-039"},{"ok":false,"zh":"每天运动是对身体很好。","fix":"每天运动对身体很好。","py":"Měi tiān yùndòng duì shēntǐ hěn hǎo.","tr":["การออกกำลังกายทุกวันดีต่อร่างกายมาก","Exercising every day is very good for your health.","Tập thể dục mỗi ngày rất tốt cho sức khỏe.","毎日運動することは体にとても良いです。"],"h":["ห้ามใส่ 是 คั่นระหว่างประธานวลีกริยากับภาคแสดงคุณศัพท์ (很好)","NEVER insert 是 between a verb-phrase subject and an adjective predicate (很好)","动词短语作主语接形容词谓语时不能加“是”","Không thêm 是 giữa chủ ngữ cụm động từ và tính từ 很好","動詞句主語と形容詞述語（很好）の間に「是」を入れない"],"w":["ไม่ได้ เพราะภาคแสดงคือ 对身体很好 (มีคุณศัพท์ 很好 เป็นแกน) จึงไม่ใช้ 是 เชื่อมเหมือนภาษาอังกฤษ 'is good for'","Wrong because the predicate centers on adjective 很好 — never insert 是 for English 'is'.","不行，谓语中心是形容词“好”，绝不能加“是”。","Không được vì vị ngữ là tính từ 很好, không thêm 是 như tiếng Anh 'is'.","述語の中心が形容詞「很好」なので英語の is のように「是」を入れない。"],"ref":"HSK 3.0 g3-2-039 · g3-1-043"}],"ex":[["每天运动对身体很好。","Měi tiān yùndòng duì shēntǐ hěn hǎo.","การออกกำลังกายทุกวันดีต่อร่างกายมาก","Exercising every day is very good for your health.","Tập thể dục mỗi ngày rất tốt cho sức khỏe.","毎日運動するのは体にとても良いです。","每天运动"],["我喜欢打篮球和游泳。","Wǒ xǐhuan dǎ lánqiú hé yóuyǒng.","ฉันชอบเล่นบาสเกตบอลและว่ายน้ำ","I like playing basketball and swimming.","Tôi thích chơi bóng rổ và bơi lội.","バスケと水泳が好きです。","打篮球"],["我准备下个月出国旅游。","Wǒ zhǔnbèi xià ge yuè chūguó lǚyóu.","ฉันเตรียมตัวไปเที่ยวต่างประเทศเดือนหน้า","I plan to travel abroad next month.","Tôi chuẩn bị tháng sau đi du lịch nước ngoài.","来月海外旅行に行く準備をしています。","出国旅游"],["我希望明年去中国学习。","Wǒ xīwàng míngnián qù Zhōngguó xuéxí.","ฉันหวังว่าปีหน้าจะไปเรียนที่ประเทศจีน","I hope to go study in China next year.","Tôi hy vọng năm sau sang Trung Quốc học.","来年、中国へ留学したいです。","去中国学习"],["坐地铁去机场很快。","Zuò dìtiě qù jīchǎng hěn kuài.","การนั่งรถไฟใต้ดินไปสนามบินเร็วมาก","Taking the subway to the airport is very fast.","Đi tàu điện ngầm ra sân bay rất nhanh.","地下鉄で空港へ行くのはとても速いです。","坐地铁去机场"]],"err":[["每天运动是对身体很好。","每天运动对身体很好。","ภาคแสดงเป็นคุณศัพท์ (很好) ห้ามใส่ 是 คั่น","Never insert 是 before an adjective predicate (很好).","形容词谓语前不能加“是”。","Không thêm 是 trước vị ngữ tính từ (很好).","形容詞述語の前に「是」は入れない。"]],"rel":["g3-2-036","g3-2-038","g3-1-037"]},"g3-2-040":{"t":["กลุ่มคำทำหน้าที่คุณศัพท์ (形容词性短语)","Adjective phrases (形容词性短语): phrases functioning as adjectives","短语功能类型：形容词性短语","Cụm tính từ (形容词性短语)","形容詞句（形容词性短语）：形容詞の働きをする句"],"f":["副词 + 形容词（非常漂亮 / 很舒服）/ 比字短语（比昨天冷）/ 形容词重叠（高高兴兴）"],"why":["形容词性短语 คือกลุ่มคำที่มีคุณศัพท์เป็นแกนกลาง เช่น 非常漂亮 (สวยมาก ๆ), 很有意思 (น่าสนใจมาก), 比昨天冷 (หนาวกว่าเมื่อวาน), 舒服一点儿 (สบายขึ้นหน่อย), 高高兴兴 (ดีอกดีใจ) · ทำหน้าที่สำคัญ 3 อย่างในประโยค: (1) เป็นภาคแสดง (这本书很有意思) (2) เป็นส่วนขยายคำนาม — ต้องใส่ 的 คั่นเสมอ! (一本很有意思的书) (3) เป็นส่วนเสริมหลัง 得 (跑得非常快) · ข้อควรระวังเด็ดขาด: เมื่อเอาวลีคุณศัพท์ (ที่มี 很/非常/最 นำหน้า) ไปวางขยายหน้าคำนาม 'ห้ามลืมใส่ 的 เด็ดขาด!' (ห้ามพูด 一本很有意思书 ต้องเป็น 一本很有意思的书!)","An adjective phrase (形容词性短语) centers on an adjective: 非常漂亮, 很有意思, 比昨天冷, 舒服一点儿, 高高兴兴. · Three core roles: (1) Predicate (这本书很有意思); (2) Noun modifier — MUST take 的 (一本很有意思的书); (3) State complement after 得 (跑得非常快). · Iron rule: NEVER omit 的 when an adjective phrase with 很/非常/最 modifies a noun (never 一本很有意思书!).","形容词性短语以形容词为核心（非常漂亮、很有意思、比昨天冷、高高兴兴），主要作谓语（这本书很有意思）、定语（一本很有意思的书）和补语（跑得非常快）。 · 铁律：带程度副词的形容词性短语作定语修饰名词时，中间必须加“的”（不说“很有意思书”）。","Cụm tính từ (形容词性短语) lấy tính từ làm trung tâm (非常漂亮, 很有意思, 比昨天冷, 高高兴兴), làm vị ngữ, định ngữ hoặc bổ ngữ sau 得. · Quy tắc thép: khi cụm '很/非常/最 + tính từ' làm định ngữ trước danh từ BẮT BUỘC có 的 (一本很有意思的书).","形容詞句（形容词性短语）は形容詞を中心とする句（非常漂亮・很有意思・比昨天冷・高高兴兴）。述語・連体修飾語・補語として働く。 · 鉄則：程度副詞が付いた形容詞句で名詞を修飾するときは必ず「的」を入れる（一本很有意思的书）。"],"use":[{"ok":true,"zh":"这是一本很有意思的书。","fix":"","py":"Zhè shì yī běn hěn yǒuyìsi de shū.","tr":["นี่คือหนังสือที่น่าสนใจมากเล่มหนึ่ง","This is a very interesting book.","Đây là một cuốn sách rất thú vị.","これはとても面白い本です。"],"h":["วลีคุณศัพท์ (很有意思 / 非常漂亮) ขยายคำนาม ต้องใส่ 的 คั่นเสมอ","When an adjective phrase (很有意思 / 非常漂亮) modifies a noun, ALWAYS add 的","形容词性短语作定语必须加“的”（很有意思的书）","Cụm tính từ làm định ngữ luôn phải có 的 (很有意思的书)","形容詞句で名詞を修飾するときは必ず「的」を入れる"],"w":["ทำได้เพราะ 很有意思 เป็นวลีคุณศัพท์หลายพยางค์ จึงเชื่อมกับคำนาม 书 ด้วย 的 ได้ถูกต้องตามหลักไวยากรณ์","Works cleanly because multi-word adjective phrase 很有意思 links to noun 书 with mandatory 的.","“很有意思”为形容词性短语，加“的”修饰“书”完全规范。","Đúng vì cụm tính từ 很有意思 nối với 书 bằng 的 chuẩn xác.","形容詞句「很有意思」に必ず「的」を添えて名詞「书」を修飾している。"],"ref":"HSK 3.0 g3-2-040 · g3-1-039"},{"ok":true,"zh":"他今天舒服一点儿了。","fix":"","py":"Tā jīntiān shūfu yīdiǎnr le.","tr":["วันนี้เขาสบายตัวขึ้นนิดหน่อยแล้ว","He feels a bit more comfortable/better today.","Hôm nay anh ấy thấy dễ chịu hơn một chút rồi.","今日は彼は少し楽になりました。"],"h":["คุณศัพท์ + 一点儿 = …ขึ้นหน่อย (บอกระดับเปลี่ยนแปลงเล็กน้อย)","Adjective + 一点儿 = 'a bit more…'","“形容词＋一点儿”构成形容词性短语表略有变化","Tính từ + 一点儿 = 'hơn một chút'","「形容詞＋一点儿」＝少し〜になる"],"w":["ทำได้ตามกลุ่มเทียบคำ g15 โดยวาง 一点儿 หลังคุณศัพท์ 舒服 เพื่อบอกว่าอาการดีขึ้นกว่าเดิมเล็กน้อย (ต่างจาก 有点儿 ที่วางหน้าคุณศัพท์)","Works per group g15: placing 一点儿 AFTER 舒服 expresses slight improvement (unlike 有点儿 before an adjective).","“舒服一点儿”表示程度略有好转，配“了”自然地道。","Đúng theo nhóm g15: 一点儿 đặt sau tính từ 舒服 chỉ mức độ khá hơn một chút.","「舒服」の後ろに「一点儿」を置き、前より少し良くなったことを表す。"],"ref":"กลุ่มเทียบคำ g15 · HSK 3.0 g3-2-040"},{"ok":false,"zh":"这是一本非常漂亮书。","fix":"这是一本非常漂亮的书。","py":"Zhè shì yī běn fēicháng piàoliang de shū.","tr":["นี่คือหนังสือที่สวยมาก ๆ เล่มหนึ่ง","This is an extremely pretty book.","Đây là một cuốn sách cực kỳ đẹp.","これはとてもきれいな本です。"],"h":["ห้ามละ 的 เมื่อใช้วลีคุณศัพท์ (非常漂亮 / 很有意思) ขยายคำนาม!","NEVER omit 的 when an adjective phrase (非常漂亮 / 很有意思) modifies a noun!","带程度副词的形容词性短语作定语绝不能省“的”","Không bao giờ bỏ 的 khi cụm 非常漂亮 bổ nghĩa danh từ!","程度副詞付きの形容詞句が名詞を修飾するとき「的」は省けない"],"w":["ไม่ได้ เพราะคุณศัพท์ที่ละ 的 ได้มีเฉพาะคุณศัพท์พยางค์เดียวบางคำ (เช่น 新书, 好朋友) แต่พอมี 非常 / 很 นำหน้ากลายเป็นวลี ต้องมี 的 เสมอ: 非常漂亮的书","Wrong because only bare 1-syllable adjectives drop 的 (新书); phrases with 非常/很 ALWAYS require 的: 非常漂亮的书.","不行，只有个别单音节形容词可直接修饰名词（新书）；“非常漂亮”须加“的”。","Không được vì chỉ một số tính từ 1 âm tiết mới bỏ 的 (新书); cụm 非常漂亮 bắt buộc có 的.","「的」を省けるのは「新书」など一部の1音節形容詞のみ。「非常漂亮」には必ず「的」が要る。"],"ref":"HSK 3.0 g3-2-040 · g3-1-024"}],"ex":[["这是一本很有意思的书。","Zhè shì yī běn hěn yǒuyìsi de shū.","นี่คือหนังสือที่น่าสนใจมากเล่มหนึ่ง","This is a very interesting book.","Đây là một cuốn sách rất thú vị.","これはとても面白い本です。","很有意思的"],["这家酒店的房间非常舒服。","Zhè jiā jiǔdiàn de fángjiān fēicháng shūfu.","ห้องพักของโรงแรมนี้สบายมาก ๆ","The rooms at this hotel are extremely comfortable.","Phòng của khách sạn này cực kỳ thoải mái.","このホテルの部屋はとても快適です。","非常舒服"],["今天的天气比昨天冷。","Jīntiān de tiānqì bǐ zuótiān lěng.","อากาศวันนี้หนาวกว่าเมื่อวาน","Today's weather is colder than yesterday's.","Thời tiết hôm nay lạnh hơn hôm qua.","今日の天気は昨日より寒いです。","比昨天冷"],["喝了药，我舒服一点儿了。","Hēle yào, wǒ shūfu yīdiǎnr le.","พอกินยาแล้ว ฉันก็สบายขึ้นหน่อยแล้ว","After taking the medicine, I feel a little better.","Uống thuốc xong, tôi thấy đỡ hơn một chút rồi.","薬を飲んで少し楽になりました。","舒服一点儿"],["那个电影很没意思。","Nàge diànyǐng hěn méiyìsi.","หนังเรื่องนั้นน่าเบื่อมาก","That movie is really boring.","Bộ phim đó rất chán.","あの映画はとてもつまらなかったです。","很没意思"]],"err":[["这是一本非常漂亮书。","这是一本非常漂亮的书。","วลีคุณศัพท์ที่มี 非常/很 ขยายคำนาม ต้องมี 的 คั่นเสมอ","Adjective phrases with 非常/很 MUST take 的 before a noun.","“非常漂亮”等形容词性短语作定语必须加“的”。","Cụm 非常漂亮 làm định ngữ bắt buộc có 的.","「非常漂亮」など形容詞句で名詞を修飾するときは必ず「的」を入れる。"]],"rel":["g3-1-039","g3-1-043","g3-2-054"]},"g3-2-041":{"t":["วลีปิดท้าย 什么的: อะไรพวกนี้ / อะไรทำนองนั้น (ฯลฯ ภาษาพูด)","Fixed phrase 什么的: 'and so on / stuff like that'","固定短语：什么的","Cụm từ cố định 什么的: …gì đó / v.v. (khẩu ngữ)","慣用表現「什么的」：〜など・〜とか"],"f":["例子1（、例子2）+ 什么的（苹果、面包什么的 / 游泳、跑步什么的）"],"why":["什么的 ใช้ปิดท้ายรายการตัวอย่าง 1–2 อย่างในภาษาพูด แปลว่า '…อะไรพวกนี้ / …เป็นต้น' เพื่อบอกว่ายังมีสิ่งอื่นประเภทเดียวกันอีกโดยไม่ต้องไล่ครบทุกตัว เช่น 我喜欢喝红茶、绿茶什么的 (ฉันชอบดื่มชาแดง ชาเขียว อะไรพวกนี้), 我经常打篮球、跑步什么的 · ข้อควรระวังสำคัญ 2 ข้อ: (1) 什么的 วาง 'ท้ายสุด' ของรายการตัวอย่างเสมอ และใช้ในภาษาพูดที่เป็นกันเอง (ไม่ใช้ในรายการที่ระบุจำนวนครบเป๊ะแล้ว เช่น ห้ามพูด 我有两个朋友：小王、小李什么的!) (2) ห้ามใช้ 什么的 กับการยกตัวอย่างคนแบบไม่ให้เกียรติในสถานการณ์ทางการ","什么的 ('and so on / stuff like that') trails 1–2 spoken examples to mean 'things of that sort': 红茶、绿茶什么的, 打篮球、跑步什么的. · Two key cautions: (1) ONLY use 什么的 for open-ended lists — NEVER after an exhaustive list with an exact count (never 我有两个朋友：小王、小李什么的!). (2) Keep it for casual everyday speech, not formal writing.","“什么的”放在一两项列举之后表示省略同类事物，口语色彩浓厚（equivalent to 'etc. / stuff like that'）：红茶、绿茶什么的；打篮球、跑步什么的。 · 注意：（1）只用于未列举完的同类事物，前面已有确定总数时绝不能用；（2）多用于轻松口语，少用于正式书面语。","什么的 ('…gì đó / vân vân') đặt sau 1–2 ví dụ trong khẩu ngữ để chỉ các thứ cùng loại (红茶、绿茶什么的, 打篮球、跑步什么的). · Lưu ý: chỉ dùng khi liệt kê chưa hết, KHÔNG dùng sau danh sách đã chốt đủ số lượng.","「什么的」（〜とか／〜など）は口語で1〜2例挙げた後ろに付けて同類のものをまとめる：红茶、绿茶什么的、打篮球、跑步什么的。 · 注意：すべて挙げ切った確定リストの後ろには使えない。"],"use":[{"ok":true,"zh":"我买了苹果、面包什么的。","fix":"","py":"Wǒ mǎile píngguǒ, miànbāo shénme de.","tr":["ฉันซื้อแอปเปิล ขนมปัง อะไรพวกนี้มา","I bought apples, bread, and stuff like that.","Tôi mua táo, bánh mì mấy thứ đó.","りんごやパンなどを買いました。"],"h":["ยกตัวอย่างของประเภทเดียวกัน 1–2 อย่างแล้วปิดด้วย 什么的","List 1–2 sample items of a kind and close with 什么的","列举一两项同类事物后用“什么的”收尾","Liệt kê 1–2 món cùng loại rồi kết bằng 什么的","同類のものを1〜2例挙げて「什么的」で結ぶ"],"w":["ทำได้และเป็นธรรมชาติมากในภาษาพูด เวลาไม่อยากไล่รายการของที่ซื้อทั้งหมดทีละชิ้น","Works super naturally in conversation when you don't want to list every single grocery item.","口语中不必逐一细说所买物品，用“什么的”概括最自然。","Đúng và rất tự nhiên trong khẩu ngữ khi không cần kể hết từng món.","買ったものを全部挙げずに「〜など」とまとめる自然な口語表現。"],"ref":"HSK 3.0 g3-2-041"},{"ok":true,"zh":"他经常打篮球、游泳什么的。","fix":"","py":"Tā jīngcháng dǎ lánqiú, yóuyǒng shénme de.","tr":["เขาเล่นบาสเกตบอล ว่ายน้ำ อะไรพวกนี้เป็นประจำ","He often plays basketball, goes swimming, and stuff like that.","Anh ấy hay chơi bóng rổ, bơi lội mấy môn đó.","彼はよくバスケや水泳などをします。"],"h":["ใช้ 什么的 ปิดท้ายกลุ่มกริยา/กิจกรรมที่ชอบทำได้ด้วย","什么的 also works neatly after verb-phrase activities","“什么的”也可接在动词短语后列举活动爱好","什么的 cũng đặt được sau cụm động từ chỉ hoạt động","動作・趣味の例（動詞句）の後ろにも「什么的」が使える"],"w":["ทำได้เพราะ 什么的 ไม่จำกัดเฉพาะคำนามสิ่งของ แต่ใช้กับวลีกริยาอย่าง 打篮球, 游泳, 跑步, 看电影 ได้ดีมาก","Works great because 什么的 isn't restricted to nouns — it sums up hobbies and verb phrases cleanly too.","不仅能接名词，接“打篮球、游泳”等动词短语也同样自然。","Đúng vì 什么的 dùng được cho cả danh từ lẫn cụm động từ hoạt động.","名詞だけでなく「打篮球・游泳」のような動詞句の列挙にも自然に使える。"],"ref":"HSK 3.0 g3-2-041"},{"ok":false,"zh":"我家有两口人：爸爸、妈妈什么的。","fix":"我家有两口人：爸爸和妈妈。","py":"Wǒ jiā yǒu liǎng kǒu rén: bàba hé māma.","tr":["บ้านฉันมีสองคน คือพ่อกับแม่","There are two people in my family: Dad and Mom.","Nhà tôi có hai người: bố và mẹ.","私の家族は父と母の2人です。"],"h":["ห้ามใช้ 什么的 เมื่อระบุจำนวนครบถ้วนแล้วไม่มีรายการอื่นต่อ!","NEVER use 什么的 when the list is already complete!","前面已有确定总数、列举完毕时绝不能加“什么的”","Không dùng 什么的 khi đã liệt kê đủ số lượng rồi!","すべて挙げ切った確定のリストに「什么的」は付けられない"],"w":["ไม่ได้ เพราะระบุชัดเจนว่ามี 2 คนและเอ่ยครบทั้งพ่อและแม่แล้ว ไม่มีคนอื่นที่ละไว้อีก จึงใช้ 什么的 ไม่ได้ ต้องเชื่อมด้วย 和 เฉย ๆ","Wrong because 'two people' is already completely listed (Dad and Mom) — nothing is left out, so 什么的 is illogical.","不行，“两口人”已经全部列完没有省略，加“什么的”前后矛盾。","Không được vì '2 người' đã kể đủ cả bố và mẹ rồi, không còn gì để lược.","「2人」をすべて挙げ切っているため「など」に当たる「什么的」は矛盾する。"],"ref":"HSK 3.0 g3-2-041"}],"ex":[["我买了苹果、面包什么的。","Wǒ mǎile píngguǒ, miànbāo shénme de.","ฉันซื้อแอปเปิล ขนมปัง อะไรพวกนี้มา","I bought apples, bread, and stuff like that.","Tôi mua táo, bánh mì mấy thứ đó.","りんごやパンなどを買いました。","什么的"],["他经常打篮球、游泳什么的。","Tā jīngcháng dǎ lánqiú, yóuyǒng shénme de.","เขาเล่นบาส ว่ายน้ำ อะไรพวกนี้บ่อย ๆ","He often plays basketball, swims, and so on.","Anh ấy hay chơi bóng rổ, bơi lội gì đó.","彼はよくバスケや水泳などをします。","什么的"],["书包里有本子、笔什么的。","Shūbāo lǐ yǒu běnzi, bǐ shénme de.","ในกระเป๋ามีสมุด ปากกา อะไรพวกนี้","There are notebooks, pens, and things in the schoolbag.","Trong cặp có vở, bút mấy thứ linh tinh.","かばんの中にノートやペンなどがあります。","什么的"],["我喜欢喝红茶、绿茶什么的。","Wǒ xǐhuan hē hóngchá, lǜchá shénme de.","ฉันชอบดื่มชาแดง ชาเขียว อะไรพวกนี้","I like drinking black tea, green tea, and such.","Tôi thích uống hồng trà, trà xanh gì đó.","紅茶や緑茶などを飲むのが好きです。","什么的"],["晚上我喜欢看书、上网什么的。","Wǎnshang wǒ xǐhuan kàn shū, shàngwǎng shénme de.","ตอนเย็นฉันชอบอ่านหนังสือ เล่นเน็ต อะไรพวกนี้","In the evening I like reading, surfing the web, and stuff.","Buổi tối tôi thích đọc sách, lướt mạng gì đó.","夜は読書やネットなどをするのが好きです。","什么的"]],"err":[["我家有两口人：爸爸、妈妈什么的。","我家有两口人：爸爸和妈妈。","ระบุจำนวนครบถ้วนแล้วไม่มีรายการอื่นต่อ ห้ามใช้ 什么的","Never use 什么的 after a complete, exhaustive list.","列举已完整无省略时不能用“什么的”。","Liệt kê đã đủ hết rồi thì không dùng 什么的.","すべて挙げ切ったリストの後ろに「什么的」は使えない。"]],"rel":["g3-1-028","g3-2-035"]},"g3-2-042":{"t":["รูปแบบคงที่ 还是……吧: เอาเป็นว่า…ดีกว่าเถอะ","Fixed pattern 还是……吧: 'we'd better… / let's just…'","固定格式：还是……吧","Cấu trúc cố định 还是……吧: vẫn nên…thì hơn","固定表現「还是……吧」：やはり〜しよう／〜した方がいい"],"f":["（原因 / 情况），主语 + 还是 + 动词 + 吧（外面冷，你还是在家休息吧）"],"why":["รูปแบบคงที่ 还是……吧 ใช้เมื่อชั่งน้ำหนักสถานการณ์หรือทางเลือกหลายอย่างแล้วสรุปข้อเสนอแนะหรือการตัดสินใจว่า 'ยังไงก็ทำอย่างนี้ดีกว่าเถอะ!' · เช่น 机场很远，我们还是打车吧 (สนามบินไกลมาก พวกเรานั่งแท็กซี่กันดีกว่านะ), 天阴了，你还是别出门了吧 (ฟ้าครึ้มแล้ว คุณอย่าออกไปข้างนอกเลยดีกว่านะ) · ข้อควรระวังสำคัญ: (1) ประธานวางไว้ 'หน้า' 还是 เสมอ (我们还是去吧 ไม่ใช่ 还是我们去吧 — เว้นแต่ละประธาน) (2) รูปแบบนี้เป็นการเสนอแนะ/ตกลง ไม่ใช่คำถาม จึงลงท้ายด้วย 吧 ห้ามลงท้ายด้วย 吗","The fixed pattern 还是……吧 expresses a decision or friendly recommendation after weighing options ('we'd better… / let's just…'): 机场很远，我们还是打车吧. · Cautions: (1) Put the subject BEFORE 还是 (我们还是去吧). (2) Because it is a suggestion/decision rather than a yes-no question, close with 吧 — NEVER 吗.","固定格式“还是……吧”表示经过比较权衡后，认为某种做法更稳妥并提出建议或决定（外面冷，你还是在家休息吧）。 · 注意：（1）主语一般放“还是”前（我们还是打车吧）；（2）句末配“吧”，绝不能用“吗”。","Cấu trúc cố định 还是……吧 dùng để đề xuất hoặc quyết định phương án tốt hơn sau khi cân nhắc (外面冷，你还是在家休息吧). · Lưu ý: chủ ngữ đặt TRƯỚC 还是; cuối câu dùng 吧, tuyệt đối không dùng 吗.","固定表現「还是……吧」は比較検討の末に「やはり〜した方がいい／〜しよう」と提案・決定する文型（外面冷，你还是在家休息吧）。 · 注意：主語は「还是」の前、文末は必ず「吧」（「吗」は不可）。"],"use":[{"ok":true,"zh":"你身体不舒服，还是去医院看看吧。","fix":"","py":"Nǐ shēntǐ bù shūfu, háishi qù yīyuàn kànkan ba.","tr":["คุณไม่สบาย ยังไงก็ไปหาหมอที่โรงพยาบาลดูหน่อยดีกว่านะ","You aren't feeling well; you'd better go see a doctor at the hospital.","Bạn thấy trong người không khỏe, vẫn nên đi bệnh viện khám xem sao.","体調が悪いんだから、やはり病院で診てもらった方がいいよ。"],"h":["ให้คำแนะนำด้วยความห่วงใย: (เหตุผล) + 还是 + คำแนะนำ + 吧","Give caring advice: (reason) + 还是 + suggestion + 吧","关切建议：（原因）＋还是＋做法＋吧","Khuyên nhủ quan tâm: (lý do) + 还是 + lời khuyên + 吧","気遣いのアドバイス：「（理由）＋还是＋提案＋吧」"],"w":["ทำได้และสุภาพนุ่มนวลมาก เพราะ 还是…吧 แสดงความใส่ใจโดยไม่ฟังเหมือนออกคำสั่งแข็ง ๆ","Works warmly and politely because 还是…吧 sounds caring rather than bossy.","用“还是……吧”提建议既贴心又委婉，不显生硬。","Đúng và rất nhẹ nhàng, thể hiện sự quan tâm chứ không ra lệnh.","命令口調にならず親身なアドバイスとしてとても自然に響く。"],"ref":"HSK 3.0 g3-2-042"},{"ok":true,"zh":"这个太贵了，我还是不买了吧。","fix":"","py":"Zhège tài guì le, wǒ háishi bù mǎi le ba.","tr":["อันนี้แพงเกินไปแล้ว ฉันไม่ซื้อดีกว่า","This is too expensive; I'd better not buy it.","Cái này đắt quá, tôi vẫn không mua nữa vậy.","これは高すぎるから、やはり買うのをやめておこう。"],"h":["เปลี่ยนใจไม่ทำบางอย่าง ใช้ 还是 + 不 / 别 + กริยา + 吧","Decide against doing something with 还是 + 不 / 别 + Verb + 吧","否定决定用“还是＋不／别＋动词＋吧”","Quyết định không làm nữa dùng 还是 + 不/别 + động từ + 吧","「やはり〜しないでおこう」は「还是＋不／别＋動詞＋吧」"],"w":["ทำได้เพราะ 还是 วางหน้าคำปฏิเสธ 不 / 别 เสมอ (还是不买 / 还是别去) เพื่อบอกว่าชั่งใจแล้วเลือกไม่ทำ","Works cleanly with 还是 placed BEFORE 不 or 别 (还是不买 / 还是别去) to choose the negative option.","“还是”放在否定词“不／别”前，表示权衡后决定放弃。","Đúng vì 还是 đứng trước 不 / 别 để biểu thị quyết định từ bỏ.","否定詞「不・别」の前に「还是」を置いてやめる決断を表す。"],"ref":"HSK 3.0 g3-2-042"},{"ok":false,"zh":"我不还是买了。","fix":"我还是不买了。","py":"Wǒ háishi bù mǎi le.","tr":["ฉันไม่ซื้อดีกว่า","I'd better not buy it.","Tôi vẫn không mua nữa vậy.","やはり買いません。"],"h":["ห้ามเอา 不 มาวางหน้า 还是! (ต้องเป็น 还是不… เสมอ)","NEVER put 不 before 还是 — ALWAYS 还是不…!","只能说“还是不……”，绝不能说“不还是……”","Luôn nói 还是不…, không bao giờ đảo thành 不还是…","「不还是…」は不可、必ず「还是不…」にする"],"w":["ไม่ได้ เพราะ 还是 เป็นคำวิเศษณ์บอกน้ำเสียงที่ต้องอยู่ 'หน้า' คำปฏิเสธ 不 / 别 เสมอ เช่นเดียวกับ 也 (也不) และ 还 (还没)","Wrong because modal adverb 还是 ALWAYS precedes 不 / 别 (just like 也不 and 还没).","不行，语气副词“还是”必须位于否定词“不／别”之前。","Không được vì phó từ 还是 luôn đứng TRƯỚC 不 / 别.","語気副詞「还是」は必ず否定詞「不・别」の前に置く。"],"ref":"HSK 3.0 g3-2-042"}],"ex":[["外面下雨了，我们还是打车吧。","Wàimiàn xià yǔ le, wǒmen háishi dǎchē ba.","ข้างนอกฝนตกแล้ว พวกเรานั่งแท็กซี่กันดีกว่านะ","It's raining outside; let's take a taxi instead.","Ngoài trời mưa rồi, chúng ta bắt taxi đi nhé.","外は雨だからやはりタクシーで行きましょう。","还是"],["你身体不舒服，还是去医院看看吧。","Nǐ shēntǐ bù shūfu, háishi qù yīyuàn kànkan ba.","คุณไม่สบาย ไปตรวจที่โรงพยาบาลหน่อยดีกว่านะ","You're unwell; you'd better go to the hospital.","Bạn không khỏe, vẫn nên đi bệnh viện khám xem sao.","体調が悪いからやはり病院で診てもらった方がいいよ。","还是"],["你累了，还是早点儿睡觉吧。","Nǐ lèi le, háishi zǎodiǎnr shuìjiào ba.","คุณเหนื่อยแล้ว รีบนอนเร็วหน่อยดีกว่านะ","You're tired; you'd better go to sleep early.","Bạn mệt rồi, vẫn nên đi ngủ sớm chút đi.","疲れたでしょう、やはり早めに寝た方がいいよ。","还是"],["这个太贵了，我还是不买了吧。","Zhège tài guì le, wǒ háishi bù mǎi le ba.","อันนี้แพงเกินไป ฉันไม่ซื้อดีกว่า","This is too expensive; I'd better not buy it.","Cái này đắt quá, tôi thôi không mua nữa vậy.","高すぎるからやはり買うのはやめておこう。","还是"],["明天要考试，我还是在家学习吧。","Míngtiān yào kǎoshì, wǒ háishi zài jiā xuéxí ba.","พรุ่งนี้จะสอบแล้ว ฉันอ่านหนังสืออยู่บ้านดีกว่า","There's an exam tomorrow; I'd better study at home.","Ngày mai thi rồi, tôi vẫn nên ở nhà học bài thôi.","明日試験だからやはり家で勉強しよう。","还是"]],"err":[["我不还是买了。","我还是不买了。","还是 ต้องวางหน้า 不 / 别 เสมอ (还是不 / 还是别)","Always put 还是 BEFORE 不 or 别.","“还是”必须放在“不／别”前面。","Luôn đặt 还是 TRƯỚC 不 / 别.","「还是」は必ず「不・别」の前に置く。"]],"rel":["g3-2-020","g3-2-056","g3-2-068"]},"g3-2-043":{"t":["รูปแบบคงที่ 要 / 快要 / 就要……了: กำลังจะ / ใกล้จะ…แล้ว","Fixed pattern 要 / 快要 / 就要……了: 'about to happen'","固定格式：要/快要/就要……了","Cấu trúc cố định 要 / 快要 / 就要……了: sắp…rồi","固定表現「要／快要／就要……了」：もうすぐ〜する"],"f":["无具体时间：要 / 快要 / 快 + 动词 + 了（快要下雨了 / 要开学了）","有具体时间：具体时间 + 就要 + 动词 + 了（下星期就要考试了）"],"why":["โครงสร้าง 要…了 / 快要…了 / 就要…了 / 快…了 แปลว่า 'กำลังจะ / ใกล้จะ…แล้ว' ใช้บอกเหตุการณ์ที่จวนจะเกิดขึ้นในอีกไม่ช้า · จุดแยกสำคัญที่ออกสอบ HSK 2 ตลอดกาล: (1) ถ้าในประโยค 'มีเวลาเจาะจง' (เช่น 明天, 下星期, 八点, 还有十分钟) บังคับใช้ **就要……了** (หรือ 要…了) เท่านั้น! ห้ามใช้ 快要…了 หรือ 快…了 เด็ดขาด! (เช่น 明天就要开学了 ✓ แต่ 明天快要开学了 ✗) (2) ถ้า 'ไม่มีเวลาเจาะจง' ใช้ได้ทั้ง 要…了, 快要…了, 快…了, 就要…了 (3) โครงสร้างนี้ต้องมี **了** ปิดท้ายประโยคเสมอ!","The patterns 要…了, 快要…了, 快…了, and 就要…了 all mean 'about to / soon going to'. · Classic HSK 2 exam rule: (1) Whenever a SPECIFIC future time is stated (明天, 下星期, 八点), you MUST use **就要……了** (or 要…了) — NEVER 快要…了 or 快…了! (明天就要开学了 ✓, 明天快要开学了 ✗). (2) Without a specific time, any of the four work. (3) NEVER drop sentence-final 了!","“要／快要／快／就要……了”均表示动作或情况即将发生。 · 必考核心区别：（1）句中有具体时间词（明天、八点、下个月）时，只能用“就要……了”（或“要……了”），绝不能用“快要／快……了”；（2）无具体时间词时四者皆可用；（3）句末必须保留“了”。","Cấu trúc 要 / 快要 / 快 / 就要……了 đều nghĩa là 'sắp…rồi'. · Quy tắc thi cử cực quan trọng: (1) Khi có mốc thời gian cụ thể (明天, 八点, 下星期) CHỈ dùng **就要……了** (hoặc 要…了), KHÔNG dùng 快要 / 快…了! (2) Không có mốc giờ cụ thể thì dùng cả 4 đều được; (3) Luôn giữ 了 ở cuối câu.","「要／快要／快／就要……了」はいずれも「もうすぐ〜だ」。 · HSK2頻出ルール：（1）具体的な時間（明天・八点など）があるときは必ず「就要……了」（または「要……了」）を使い、「快要／快……了」は不可！（2）具体的な時間がなければ4つとも使える。（3）文末の「了」を省かない。"],"use":[{"ok":true,"zh":"下星期一就要考试了。","fix":"","py":"Xià xīngqīyī jiùyào kǎoshì le.","tr":["วันจันทร์หน้าก็จะสอบแล้ว","The exam is going to be next Monday.","Thứ Hai tuần sau là sắp thi rồi.","来週の月曜日にはもう試験です。"],"h":["มีเวลาเจาะจง (下星期一 / 明天 / 八点) ใช้ 就要……了 เท่านั้น!","With a specific future time (下星期一 / 明天 / 八点), use 就要……了!","句中有具体时间点时，必须用“就要……了”","Có mốc thời gian cụ thể bắt buộc dùng 就要……了","具体的な時刻・日程があるときは「就要……了」"],"w":["ทำได้และถูกต้องตามกฎ HSK 100% เพราะ 下星期一 เป็นวันเจาะจง จึงเลือก 就要…了 ไม่ใช้ 快要…了","Works 100% per HSK grammar rules because 下星期一 is a specific date requiring 就要…了 rather than 快要…了.","“下星期一”是具体时间点，配“就要……了”完全规范。","Đúng 100% vì 下星期一 là mốc cụ thể nên dùng 就要…了.","具体的な日時「下星期一」があるため「就要…了」を使うのが正解。"],"ref":"HSK 3.0 g3-2-043"},{"ok":true,"zh":"快要下雨了，别出门了。","fix":"","py":"Kuàiyào xià yǔ le, bié chūmén le.","tr":["ใกล้จะฝนตกแล้ว อย่าออกไปข้างนอกเลย","It's about to rain — don't go out.","Sắp mưa rồi, đừng ra ngoài nữa.","もうすぐ雨が降るから出かけないで。"],"h":["ไม่มีเวลาเจาะจง ใช้ 快要 / 快 / 要…了 ได้อย่างเป็นธรรมชาติ","With no specific timestamp, 快要 / 快 / 要…了 all sound natural","没有具体时间词时用“快要／快／要……了”","Không có mốc giờ cụ thể dùng 快要 / 快 / 要…了 đều tự nhiên","具体的な時刻がないときは「快要／快／要…了」が自然"],"w":["ทำได้เพราะเป็นการคาดการณ์จากสถานการณ์ว่าฝนกำลังจะตกในอีกไม่กี่นาทีโดยไม่ระบุเวลาเป๊ะ","Works naturally when predicting imminent rain without naming a clock time.","没有具体时刻，用“快要下雨了”生动表现即将发生。","Đúng vì không nêu giờ cụ thể mà chỉ nói sắp mưa ngay.","具体的な時刻を言わず切迫感を表すので「快要…了」がぴったり。"],"ref":"HSK 3.0 g3-2-043"},{"ok":false,"zh":"下星期一快要考试了。","fix":"下星期一就要考试了。","py":"Xià xīngqīyī jiùyào kǎoshì le.","tr":["วันจันทร์หน้าก็จะสอบแล้ว","The exam is coming up next Monday.","Thứ Hai tuần sau là thi rồi.","来週の月曜日にはもう試験です。"],"h":["ห้ามใช้ 快要…了 คู่กับวัน/เวลาเจาะจง (下星期一 / 明天八点)!","NEVER pair 快要…了 with a specific date or clock time!","有具体时间词时绝不能用“快要……了”，须改“就要……了”","Có mốc thời gian cụ thể TUYỆT ĐỐI không dùng 快要…了 (đổi sang 就要…了)","具体的な日時があるのに「快要…了」は不可（「就要…了」に直す）"],"w":["ไม่ได้ เพราะ 快 และ 快要 มีความหมายในตัวว่า 'อีกแป๊บเดียว' ซึ่งขัดกับการระบุวันเวลาตายตัวแบบ 下星期一 จึงต้องเปลี่ยนเป็น 就要…了","Wrong because 快/快要 inherently means 'very soon' and clashes with explicit timestamps — switch to 就要…了.","不行，“快／快要”不能跟具体时间状语同现，必须改成“就要……了”。","Không được vì 快要 xung đột với mốc thời gian cụ thể 下星期一; phải sửa thành 就要…了.","「快要」は具体的な日時と共存できない。必ず「就要…了」にする。"],"ref":"HSK 3.0 g3-2-043 · g3-2-016"},{"ok":false,"zh":"飞机快要到。","fix":"飞机快要到了。","py":"Fēijī kuàiyào dào le.","tr":["เครื่องบินใกล้จะถึงแล้ว","The plane is about to arrive.","Máy bay sắp đến rồi.","飛行機がもうすぐ着きます。"],"h":["ห้ามลืม 了 ปิดท้ายโครงสร้าง 要 / 快要 / 就要……了","NEVER omit closing 了 from 要 / 快要 / 就要……了","“要／快要／就要……了”句末绝不能省“了”","Không được quên 了 ở cuối cấu trúc 要 / 快要 / 就要…了","「要／快要／就要……了」の文末の「了」を落とさない"],"w":["ไม่ได้ เพราะ 了 ท้ายประโยคเป็นส่วนบังคับที่คู่กับ 要/快要/就要 เพื่อบ่งบอกความเปลี่ยนแปลงที่กำลังจะมาถึง","Wrong because closing 了 is an obligatory partner in the 'about to' frame — always include 了.","不行，“了”是该固定格式的必选成分，少了句子不成立。","Không được vì 了 cuối câu là thành phần bắt buộc của cấu trúc sắp xảy ra.","文末の「了」はこの構文の必須要素であり、省くと文が成り立たない。"],"ref":"HSK 3.0 g3-2-043"}],"ex":[["要下雨了，我们快回家吧。","Yào xià yǔ le, wǒmen kuài huí jiā ba.","ฝนกำลังจะตกแล้ว พวกเรารีบกลับบ้านกันเถอะ","It's going to rain; let's hurry home.","Sắp mưa rồi, chúng ta mau về nhà đi.","雨が降りそうだから急いで帰ろう。","要"],["飞机快要到了。","Fēijī kuàiyào dào le.","เครื่องบินใกล้จะถึงแล้ว","The plane is about to arrive.","Máy bay sắp hạ cánh rồi.","飛行機がもうすぐ到着します。","快要"],["下星期一就要考试了。","Xià xīngqīyī jiùyào kǎoshì le.","วันจันทร์หน้าก็จะสอบแล้ว","The exam is next Monday.","Thứ Hai tuần sau là thi rồi.","来週の月曜にはもう試験です。","就要"],["九月一号就要开学了。","Jiǔ yuè yī hào jiùyào kāixué le.","วันที่ 1 กันยายนก็จะเปิดเทอมแล้ว","School starts on September 1st.","Ngày 1 tháng 9 là sắp khai giảng rồi.","9月1日にはもう新学期が始まります。","就要"],["快过年了，大家都很高兴。","Kuài guònián le, dàjiā dōu hěn gāoxìng.","ใกล้จะถึงปีใหม่แล้ว ทุกคนต่างดีใจมาก","New Year is almost here; everyone is very happy.","Sắp đón Tết rồi, mọi người đều rất vui.","もうすぐお正月で、みんなとても嬉しそうです。","快"]],"err":[["下星期一快要考试了。","下星期一就要考试了。","มีเวลาเจาะจง (下星期一) ต้องใช้ 就要…了 ไม่ใช้ 快要…了","With a specific time, use 就要…了 instead of 快要…了.","有具体时间点用“就要……了”，不用“快要……了”。","Có mốc thời gian cụ thể dùng 就要…了, không dùng 快要…了.","具体的な日時があるときは「快要…了」でなく「就要…了」。"],["飞机快要到。","飞机快要到了。","อย่าลืม 了 ปิดท้ายประโยคเสมอ","Never drop final 了 from 快要…了.","固定格式句末须加“了”。","Không bỏ quên 了 ở cuối câu.","文末の「了」を忘れない。"]],"rel":["g3-2-016","g3-2-044","g3-1-063"]},"g3-2-044":{"t":["รูปแบบคงที่ 都……了: ตั้ง…แล้ว / …กันหมดแล้ว","Fixed pattern 都……了: 'already! (emphatic)'","固定格式：都……了","Cấu trúc cố định 都……了: đã…rồi đấy!","固定表現「都……了」：もう〜も経った／すっかり〜だ"],"f":["都 + 时间 / 数量 / 形容词 / 动词 + 了（都十点了 / 菜都冷了 / 我都等了一个小时了）"],"why":["รูปแบบคงที่ 都……了 เป็นสำนวนย้ำอารมณ์ที่คนจีนใช้พูดทุกวัน แปลว่า 'ตั้ง…แล้วนะ! / …ไปหมดแล้ว!' (คล้าย 已经……了 แต่เน้นความรู้สึกว่า ดึกแล้ว นานแล้ว มากแล้ว หรือสายไปแล้ว) · ใช้ได้ 3 แนวหลัก: (1) เวลาล่วงเลยไปแล้ว: 都十点了，快睡觉吧！(ตั้งสี่ทุ่มแล้ว รีบนอนเถอะ!) (2) รอนาน/ผ่านไปนาน: 我都等了二十分钟了！(ฉันรอมาตั้งยี่สิบนาทีแล้วนะ!) (3) สภาพเปลี่ยนไปหมดแล้ว: 菜都冷了！(กับข้าวเย็นชืดหมดแล้ว!) · ข้อควรระวัง: (1) ต้องมี 了 ปิดท้ายเสมอ (ห้ามตัด 了 ออก) (2) แยกให้ชัดระหว่าง 都1 ('ทั้งหมด': 大家都来了) กับ 都2…了 ('ตั้ง…แล้ว': 都十点了)","The fixed frame 都……了 is an emphatic everyday way to say 'already!' — stronger and more emotional than neutral 已经…了, signaling it's late, long, or overdue. · Three main uses: (1) Late time: 都十点了! ('It's already 10!'); (2) Long wait/duration: 我都等了二十分钟了!; (3) Completed change: 菜都冷了! ('The food has already gone cold!'). · Caution: final 了 is obligatory!","固定格式“都……了”相当于语气更强烈的“已经……了”，突出时间晚、持续久或程度深：都十点了！我都等了二十分钟了！菜都冷了！ · 注意：句末必须带“了”，否则不构成“已经”义。","Cấu trúc cố định 都……了 mang nghĩa 'đã…rồi đấy!' (nhấn mạnh muộn/lâu/nhiều hơn 已经…了): 都十点了! (đã 10 giờ rồi!), 菜都冷了! (đồ ăn nguội hết rồi!). · Lưu ý: bắt buộc phải có 了 cuối câu.","固定表現「都……了」は「已经…了」より強い感情を込めて「もう〜も！」を表す：都十点了！（もう10時だ！）、我都等了二十分钟了！（もう20分も待ったよ！）、菜都冷了！（料理がすっかり冷めた！）。 · 文末の「了」が必須。"],"use":[{"ok":true,"zh":"快吃饭吧，菜都冷了。","fix":"","py":"Kuài chīfàn ba, cài dōu lěng le.","tr":["รีบกินข้าวเถอะ กับข้าวเย็นหมดแล้ว","Hurry and eat — the food has already gone cold.","Mau ăn cơm đi, đồ ăn nguội hết rồi.","早く食べて、料理がすっかり冷めちゃったよ。"],"h":["ย้ำว่าสภาพเปลี่ยนไปเรียบร้อยแล้ว ใช้ ประธาน + 都 + คุณศัพท์ + 了","Emphasize that a state has already changed: Subject + 都 + Adj + 了","“都＋形容词＋了”强调状态早已变化（菜都冷了）","Nhấn mạnh trạng thái đã thay đổi: 都 + tính từ + 了","状態がすっかり変わった強調：「都＋形容詞＋了」"],"w":["ทำได้และอบอุ่นเป็นธรรมชาติมาก เพราะ 都…了 แฝงความเร่งเร้าเบา ๆ ให้รีบมากินก่อนจะไม่อร่อย","Works naturally and warmly: 都…了 carries gentle urgency to hurry and eat before it gets colder.","“菜都冷了”既表变化已完成，又隐含催促语气，十分地道。","Đúng và tự nhiên vì 都…了 vừa báo đã nguội vừa giục nhẹ ăn ngay.","「すっかり冷めてしまった」という変化と「早く食べて」の催促が自然に伝わる。"],"ref":"HSK 3.0 g3-2-044"},{"ok":true,"zh":"我都等了二十分钟了！","fix":"","py":"Wǒ dōu děngle èrshí fēnzhōng le!","tr":["ฉันรอมาตั้งยี่สิบนาทีแล้วนะ!","I've already been waiting for twenty minutes!","Tôi đã đợi những 20 phút rồi đấy!","もう20分も待ったんですよ！"],"h":["บ่นหรือเน้นว่าทำมานานมากแล้ว ใช้ 都 + กริยา + 了 + ระยะเวลา + 了","Emphasize how long you've been doing something: 都 + V + 了 + Duration + 了","“都＋动词＋了＋时长＋了”强调时间之久","Nhấn mạnh đã làm rất lâu rồi: 都 + động từ + 了 + thời lượng + 了","「もう〜も続いている」は「都＋動詞＋了＋期間＋了」"],"w":["ทำได้เพราะ 了 ตัวแรกหลัง 等 บอกการกระทำเกิดขึ้นไปแล้ว และ 了 ตัวท้ายคู่กับ 都 บอกว่าถึงตอนนี้ก็ยังรออยู่และนานมากแล้ว!","Works vividly: 了1 after 等 + final 了2 paired with 都 highlights that the 20-minute wait is still ongoing and feels long!","双“了”配“都”，生动表现“已经等了很久且仍在等”的焦急语气。","Đúng và rất sinh động: cặp 都…了 nhấn mạnh thời gian chờ đã quá lâu.","「都」と2つの「了」の組み合わせで「もう20分も待ち続けている」焦りが伝わる。"],"ref":"HSK 3.0 g3-2-044 · g3-2-053"},{"ok":false,"zh":"都十二点，还不睡觉！","fix":"都十二点了，还不睡觉！","py":"Dōu shí'èr diǎn le, hái bù shuìjiào!","tr":["ตั้งเที่ยงคืนแล้วนะ ยังไม่ยอมนอนอีก!","It's already twelve o'clock, and you're still not sleeping!","Đã 12 giờ rồi mà vẫn chưa ngủ!","もう12時なのにまだ寝ないの！"],"h":["ห้ามลืม 了 ในโครงสร้าง 都……了 เด็ดขาด!","NEVER drop final 了 in 都……了!","“都……了”句末绝不能省略“了”","Tuyệt đối không bỏ 了 trong cấu trúc 都……了!","「都……了」の「了」は絶対に省けない"],"w":["ไม่ได้ เพราะถ้าตัด 了 ทิ้ง ประโยคจะขาดคู่รับของ 都2 ทำให้ฟังผิดเพี้ยนทันที ต้องใส่ 了 เป็น 都十二点了","Wrong because without closing 了, 都2 loses its 'already' frame — always close with 了: 都十二点了.","不行，没有“了”就无法表达“已经十二点”的感叹，必须加“了”。","Không được vì thiếu 了 thì 都2 mất nghĩa 'đã…rồi'; phải viết 都十二点了.","「了」がないと「もう〜だ」の意味が成立しない。必ず「都十二点了」にする。"],"ref":"HSK 3.0 g3-2-044"}],"ex":[["都十点了，快起床吧！","Dōu shí diǎn le, kuài qǐchuáng ba!","ตั้งสิบโมงแล้วนะ รีบตื่นเถอะ!","It's already 10 o'clock — get up!","Đã 10 giờ rồi, mau dậy đi!","もう10時だよ、早く起きて！","都"],["快吃饭吧，菜都冷了。","Kuài chīfàn ba, cài dōu lěng le.","รีบกินข้าวเถอะ กับข้าวเย็นหมดแล้ว","Hurry and eat; the food is already cold.","Mau ăn đi, đồ ăn nguội hết rồi.","早く食べて、料理がすっかり冷めたよ。","都"],["我都等了二十分钟了！","Wǒ dōu děngle èrshí fēnzhōng le!","ฉันรอมาตั้งยี่สิบนาทีแล้วนะ!","I've already waited twenty minutes!","Tôi đã đợi 20 phút rồi đấy!","もう20分も待ったんだよ！","都"],["奶奶今年都八十岁了。","Nǎinai jīnnián dōu bāshí suì le.","ปีนี้คุณย่าอายุตั้งแปดสิบปีแล้ว","Grandma is already eighty years old this year.","Năm nay bà nội đã 80 tuổi rồi.","おばあちゃんは今年もう80歳になりました。","都"],["他都学了三年汉语了。","Tā dōu xuéle sān nián Hànyǔ le.","เขาเรียนภาษาจีนมาตั้งสามปีแล้วนะ","He has already studied Chinese for three years.","Anh ấy đã học tiếng Trung những ba năm rồi.","彼はもう3年も中国語を勉強しています。","都"]],"err":[["都十二点，还不睡觉！","都十二点了，还不睡觉！","โครงสร้าง 都……了 ต้องมี 了 ปิดท้ายเสมอ","Always close 都……了 with 了.","固定格式“都……了”不能省“了”。","Cấu trúc 都……了 luôn phải có 了.","「都……了」では必ず「了」を付ける。"]],"rel":["g3-2-020","g3-2-043","g3-1-063"]},"g3-2-045":{"t":["ประธานผู้ถูกกระทำ (受事主语): ข้าวทำเสร็จแล้ว / ตั๋วซื้อแล้ว","Patient-as-subject (受事主语): notional passive without 被","句子成分·主语：受事主语","Chủ ngữ chịu tác động (受事主语)","受動主語（受事主语）：「被」を使わない受身"],"f":["受事主语（已知事物）+（谁）+ 动词 + 补语 / 了（早饭做好了 / 机票买好了）"],"why":["受事主语 เป็นจุดเด่นสุดยอดของภาษาจีนที่คนไทยเข้าใจง่ายมาก: เมื่อ 'สิ่งของที่ถูกกระทำ' (เช่น ข้าว, หนังสือ, ตั๋วเครื่องบิน) เป็นหัวข้อที่รู้กันอยู่แล้ว เราสามารถยกมันขึ้นเป็นประธานต้นประโยคได้เลยโดย 'ไม่ต้องใส่คำว่า 被 (ถูก…)'! · เช่น 早饭做好了 (ข้าวเช้าทำเสร็จแล้ว), 机票买好了 (ตั๋วเครื่องบินซื้อเรียบร้อยแล้ว), 这本书我看完了 (หนังสือเล่มนี้ฉันอ่านจบแล้ว) · ข้อควรระวัง 2 ข้อ: (1) ประธานแบบนี้มักเป็นสิ่งของที่ 'เจาะจง/รู้จักแล้ว' (这本书, 早饭, 机票) และภาคแสดงต้องมีส่วนเสริมผลลัพธ์ (完/好/错) หรือ 了 ตามหลังเสมอ (ไม่พูดห้วน ๆ ว่า 早饭做!) (2) ไม่ต้องแปลประโยคอังกฤษ 'Breakfast is made' ด้วย 是 หรือ 被 เกินความจำเป็น","Patient-as-subject (受事主语) is a super-idiomatic Chinese structure: when the affected object (breakfast, tickets, a book) is the known topic, put it upfront as the subject WITHOUT needing passive 被! · Examples: 早饭做好了 ('Breakfast is ready'), 机票买好了 ('The flight ticket is booked'), 这本书我看完了 ('I finished this book'). · Two cautions: (1) Always include a result complement (好/完/错) or 了 after the verb — never bare 早饭做! (2) Don't add English-style 是 before the verb.","受事主语即动作的承受者充当主语，无需加“被”即可自然表被动意义（早饭做好了、机票买好了、这本书我看完了）。 · 两条注意：（1）受事主语通常是有定已知的，且谓语动词常带结果补语（好、完、错）或“了”，不能说光杆“早饭做”；（2）不要受英语被动影响误加“是”。","Chủ ngữ chịu tác động (受事主语) đưa vật bị tác động đã biết lên đầu câu mà KHÔNG cần chữ 被: 早饭做好了 (bữa sáng làm xong rồi), 机票买好了 (vé máy bay mua xong rồi), 这本书我看完了. · Lưu ý: động từ phía sau cần bổ ngữ kết quả (好/完/错) hoặc 了 (không nói trống 早饭做); không thêm 是 thừa.","受動主語（受事主语）は動作の対象（既知の物）をそのまま主語に置き、「被」を使わずに自然な受身の意味を表す文：早饭做好了、机票买好了、这本书我看完了。 · 注意：後ろの動詞には結果補語（好・完・错）や「了」が必要（裸の「早饭做」は不可）。英語のような「是」は入れない。"],"use":[{"ok":true,"zh":"早饭做好了，快来吃吧。","fix":"","py":"Zǎofàn zuòhǎo le, kuài lái chī ba.","tr":["อาหารเช้าทำเสร็จแล้ว รีบมากินเถอะ","Breakfast is ready — come eat!","Bữa sáng làm xong rồi, mau lại ăn đi.","朝ご飯ができたよ、早く食べにおいで。"],"h":["ยกสิ่งของที่เสร็จเรียบร้อยแล้วเป็นประธาน + กริยา + 好/完 + 了","Put the finished item upfront + Verb + 好/完 + 了 (no 被 needed)","受事主语＋动词＋结果补语（好／完）＋了","Đặt vật đã xong làm chủ ngữ + động từ + 好/完 + 了","出来上がった物を主語にし「動詞＋好／完＋了」"],"w":["ทำได้และเป็นธรรมชาติกว่าภาษาอังกฤษมาก เพราะเราสนใจสภาพว่า 'อาหารเช้าพร้อมกินแล้ว' ไม่ต้องระบุว่าใครทำและไม่ต้องใส่ 被","Works effortlessly because the focus is that breakfast is ready — no agent or passive 被 needed.","关注焦点在“早饭已经准备好”，不用提谁做的，也不用加“被”。","Đúng và tự nhiên hơn nhiều vì trọng tâm là bữa sáng đã xong, không cần 被.","「誰が作ったか」ではなく「朝ご飯ができた」結果に焦点を当てる自然な中国語。"],"ref":"HSK 3.0 g3-2-045"},{"ok":true,"zh":"这本书我已经看完了。","fix":"","py":"Zhè běn shū wǒ yǐjīng kànwán le.","tr":["หนังสือเล่มนี้ฉันอ่านจบเรียบร้อยแล้ว","This book — I've already finished reading it.","Cuốn sách này tôi đã đọc xong rồi.","この本はもう読み終わりました。"],"h":["ยกสิ่งของเจาะจงขึ้นเป็นหัวข้อก่อน แล้วค่อยตามด้วยผู้ทำ (我) + กริยา","Front a specific object as topic, followed by doer (我) + verb","有定受事提前作大主语：这本书＋我已经看完了","Đưa vật xác định lên đầu làm chủ đề: 这本书 + 我已经看完了","特定の物を主題として前に出し「这本书＋我已经看完了」"],"w":["ทำได้และคนจีนพูดแบบนี้บ่อยมากเมื่อต้องการเน้นว่า 'สำหรับหนังสือเล่มนี้ (ที่ถืออยู่/พูดถึงอยู่) ฉันอ่านจบแล้ว'","Works idiomatically whenever you highlight a specific item already in conversation ('As for this book…').","把话题对象“这本书”提前，重点说明已经看完。","Đúng và rất phổ biến khi muốn nhấn mạnh đối tượng đang nói tới (这本书).","目の前の本を話題に取り上げて「これはもう読み終えた」と述べる自然な語順。"],"ref":"HSK 3.0 g3-2-045 · g3-2-055"},{"ok":false,"zh":"早饭是做好了。","fix":"早饭做好了。","py":"Zǎofàn zuòhǎo le.","tr":["อาหารเช้าทำเสร็จแล้ว","Breakfast is ready.","Bữa sáng làm xong rồi.","朝ご飯ができました。"],"h":["ห้ามใส่ 是 หน้ากริยา 做好 เพื่อแปลประโยค 'is done' แบบภาษาอังกฤษ!","NEVER insert 是 before 做好 to copy English 'is made / is done'!","受事主语句动词前不要受英语影响乱加“是”","Không thêm 是 thừa trước 做好 kiểu tiếng Anh 'is done'!","英語の is done のように「是」を入れてはいけない"],"w":["ไม่ได้ในประโยคบอกเล่าปกติ เพราะ 做好了 เป็นภาคแสดงกริยาที่สมบูรณ์ในตัวอยู่แล้ว ไม่ต้องมี 是 นำหน้า","Wrong in normal statements because 做好了 is already a complete verb predicate — drop 是.","不行，“做好了”本身作谓语，普通陈述句不加“是”。","Không được vì 做好了 đã là vị ngữ hoàn chỉnh, câu thường bỏ 是.","「做好了」だけで述語が完結するため、普通の平叙文では「是」を入れない。"],"ref":"HSK 3.0 g3-2-045"}],"ex":[["早饭做好了，快来吃吧。","Zǎofàn zuòhǎo le, kuài lái chī ba.","อาหารเช้าทำเสร็จแล้ว รีบมากินเถอะ","Breakfast is ready; come eat!","Bữa sáng làm xong rồi, mau lại ăn đi.","朝ご飯ができたよ、早く食べにおいで。","早饭"],["机票已经买好了。","Jīpiào yǐjīng mǎihǎo le.","ตั๋วเครื่องบินซื้อเรียบร้อยแล้ว","The flight tickets have already been bought.","Vé máy bay đã mua xong rồi.","航空券はもう買ってあります。","机票"],["衣服洗好了。","Yīfu xǐhǎo le.","เสื้อผ้าซักเสร็จเรียบร้อยแล้ว","The clothes are washed.","Quần áo giặt xong rồi.","洗濯が終わりました。","衣服"],["这本书我已经看完了。","Zhè běn shū wǒ yǐjīng kànwán le.","หนังสือเล่มนี้ฉันอ่านจบแล้ว","I have already finished reading this book.","Cuốn sách này tôi đọc xong rồi.","この本はもう読み終わりました。","这本书"],["那个问题大家没听懂。","Nàge wèntí dàjiā méi tīngdǒng.","คำถามข้อนั้นทุกคนฟังไม่เข้าใจ","Everyone didn't understand that question.","Câu hỏi đó mọi người nghe không hiểu.","あの質問はみんな聞き取れませんでした。","那个问题"]],"err":[["早饭是做好了。","早饭做好了。","ประโยคประธานผู้ถูกกระทำบอกเล่าปกติไม่ใส่ 是 หน้ากริยา","Don't add 是 before the verb in a plain patient-subject sentence.","普通受事主语句不加“是”。","Câu chủ ngữ chịu tác động bình thường không thêm 是.","通常の受動主語文では動詞の前に「是」を入れない。"]],"rel":["g3-2-048","g3-2-055","g3-1-035"]},"g3-2-046":{"t":["วลีนามเป็นภาคแสดง (名词性短语作谓语): วันนี้ฟ้าโปร่ง / พรุ่งนี้วันเกิดฉัน","Noun phrases as predicates (名词性短语作谓语)","句子成分·谓语：名词性短语作谓语","Cụm danh từ làm vị ngữ (名词性短语作谓语)","述語（名詞句が述語になる文）"],"f":["主语 + 名词性短语（今天晴天 / 明天我生日 / 这本书三十块钱 / 他高个子）","否定：主语 + 不是 + 名词性短语（今天不是晴天）"],"why":["ต่อยอดจาก HSK 1 ที่ใช้คำนามเดี่ยวเป็นภาคแสดง ใน HSK 2 เราใช้วลีนามทั้งก้อนเป็นภาคแสดงได้โดยไม่ต้องใส่ 是 ใน 5 หมวดหลัก: (1) สภาพอากาศ: 今天晴天, 明天阴天 (2) วันสำคัญ/วันเกิด: 明天我生日 (3) ลักษณะรูปร่าง/คุณสมบัติ: 他高个子, 她大眼睛 (4) ราคา/ปริมาณต่อหน่วย: 苹果五块钱一斤→一杯咖啡二十块钱 (5) วันเวลาละเอียด: 今天五月八号星期五 · ข้อควรระวัง: (1) ประโยคปฏิเสธต้องนำ 不是 กลับมาเสมอ (今天不是晴天) (2) ลักษณะที่ไม่ได้อยู่ในหมวดเหล่านี้ยังต้องใช้ 是 ตามปกติ","Expanding on HSK 1 noun predicates, HSK 2 lets full NOUN PHRASES serve directly as predicates (without 是) for weather (今天晴天), birthdays/dates (明天我生日), body traits (他高个子), prices (一杯咖啡二十块钱), and full dates (今天五月八号星期五). · Caution: negation ALWAYS restores 不是 (今天不是晴天, never 今天不晴天!).","在 HSK 1 名词谓语基础上，HSK 2 可用更丰富的名词性短语直接作谓语（不加“是”），说明天气（今天晴天）、生日日期（明天我生日）、外貌特征（他高个子）、价格（一杯咖啡二十块钱）等。 · 注意：否定必须补出“不是”（今天不是晴天）。","Mở rộng từ HSK 1, cụm danh từ có thể trực tiếp làm vị ngữ KHÔNG cần 是 khi nói thời tiết (今天晴天), sinh nhật (明天我生日), ngoại hình (他高个子), giá cả (一杯咖啡二十块钱). · Lưu ý: phủ định bắt buộc có 不是 (今天不是晴天).","HSK1の名詞述語を発展させ、天気（今天晴天）、誕生日（明天我生日）、外見の特徴（他高个子）、価格（一杯咖啡二十块钱）などでは名詞句全体を「是」なしで述語にできる。 · 注意：否定文は必ず「不是」を補う。"],"use":[{"ok":true,"zh":"明天我生日，我请你吃饭！","fix":"","py":"Míngtiān wǒ shēngrì, wǒ qǐng nǐ chīfàn!","tr":["พรุ่งนี้วันเกิดฉัน ฉันเลี้ยงข้าวคุณเอง!","Tomorrow is my birthday — dinner's on me!","Ngày mai sinh nhật tôi, tôi mời bạn ăn cơm!","明日は私の誕生日だからご飯をご馳走するよ！"],"h":["บอกวันเกิด/สภาพอากาศ/รูปร่างแบบภาษาพูด วางวลีนามต่อประธานได้เลย","In natural speech, put birthday/weather/traits directly as a noun-phrase predicate","口语中日期生日、天气、外貌可直接用名词短语作谓语","Khẩu ngữ nói sinh nhật/thời tiết/ngoại hình đặt thẳng cụm danh từ","誕生日・天気・外見は口語で名詞句をそのまま述語にできる"],"w":["ทำได้และสั้นกระชับเป็นธรรมชาติมาก (หรือใส่ 是 เป็น 明天是我的生日 ก็ถูกทั้งคู่ในภาษาที่เป็นทางการกว่า)","Works super concisely in speech (明天是我的生日 is also valid and slightly more formal).","“明天我生日”简洁地道，正式一点也可说“明天是我的生日”。","Đúng và rất gọn trong khẩu ngữ (trang trọng hơn nói 明天是我的生日).","会話では「明天我生日」が軽快で自然（丁寧なら「明天是我的生日」）。"],"ref":"HSK 3.0 g3-2-046"},{"ok":true,"zh":"今天不是晴天，是阴天。","fix":"","py":"Jīntiān bù shì qíngtiān, shì yīntiān.","tr":["วันนี้ไม่ใช่ฟ้าโปร่ง เป็นวันฟ้าครึ้ม","Today isn't sunny; it's overcast.","Hôm nay không phải trời nắng, là trời âm u.","今日は晴れではなく曇りです。"],"h":["ปฏิเสธภาคแสดงวลีนามต้องใส่ 不是 กลับมาเสมอ","Negating a noun-phrase predicate ALWAYS restores 不是","否定名词性短语谓语必须补出“不是”","Phủ định vị ngữ cụm danh từ luôn phải thêm 不是","名詞句述語の否定では必ず「不是」を補う"],"w":["ทำได้เพราะ 不 ไม่สามารถปฏิเสธคำนาม 晴天 โดยตรงได้ จึงต้องใช้ 不是 晴天","Works because 不 cannot negate noun 晴天 directly — restoring 是 forms 不是晴天.","“不”不能直接修饰名词“晴天”，须用“不是晴天”。","Đúng vì 不 không đứng thẳng trước danh từ 晴天 được, phải dùng 不是.","「不」は名詞を直接否定できないため必ず「不是晴天」にする。"],"ref":"HSK 3.0 g3-2-046"},{"ok":false,"zh":"今天不晴天。","fix":"今天不是晴天。","py":"Jīntiān bù shì qíngtiān.","tr":["วันนี้ไม่ใช่วันฟ้าโปร่ง","Today isn't sunny.","Hôm nay không phải trời nắng.","今日は晴れではありません。"],"h":["ห้ามวาง 不 โดด ๆ หน้าคำนาม 晴天 / 阴天","NEVER put bare 不 before noun 晴天 / 阴天","不能说“不晴天／不阴天”，要说“不是晴天”","Không nói 不晴天 — phải nói 不是晴天","「不晴天」は不可、必ず「不是晴天」"],"w":["ไม่ได้ เพราะ 晴天 (วันฟ้าโปร่ง) เป็นคำนาม ไม่ใช่คุณศัพท์ (ส่วน 晴 เดี่ยว ๆ เป็นคุณศัพท์จึงพูดได้เฉพาะในบริบทจำกัด) วิธีปลอดภัยและถูก 100% คือใช้ 不是晴天","Wrong because 晴天 ('sunny day') is a noun, not an adjective — always negate with 不是晴天.","不行，“晴天”是名词，否定必须说“不是晴天”。","Không được vì 晴天 là danh từ, phủ định bắt buộc dùng 不是晴天.","「晴天」は名詞なので否定は必ず「不是晴天」にする。"],"ref":"HSK 3.0 g3-2-046 · g3-1-036"}],"ex":[["今天晴天，我们去旅游吧。","Jīntiān qíngtiān, wǒmen qù lǚyóu ba.","วันนี้ฟ้าโปร่ง พวกเราไปเที่ยวกันเถอะ","Today is sunny; let's go traveling.","Hôm nay trời nắng đẹp, chúng ta đi du lịch đi.","今日は晴れだから旅行に行きましょう。","晴天"],["明天我生日，我请你吃饭。","Míngtiān wǒ shēngrì, wǒ qǐng nǐ chīfàn.","พรุ่งนี้วันเกิดฉัน ฉันเลี้ยงข้าวคุณเอง","Tomorrow is my birthday; dinner's on me.","Ngày mai sinh nhật tôi, tôi mời bạn ăn cơm.","明日は私の誕生日だからご飯をご馳走するよ。","我生日"],["他高个子，大眼睛。","Tā gāo gèzi, dà yǎnjing.","เขาตัวสูง ตาโต","He has a tall build and big eyes.","Anh ấy dáng cao, mắt to.","彼は背が高くて目が大きいです。","高个子"],["一杯奶茶十五块钱。","Yī bēi nǎichá shíwǔ kuài qián.","ชานมหนึ่งแก้วราคาสิบห้าหยวน","A cup of milk tea is fifteen yuan.","Một cốc trà sữa 15 tệ.","ミルクティー1杯15元です。","十五块钱"],["今天五月八号星期五。","Jīntiān wǔ yuè bā hào xīngqīwǔ.","วันนี้วันศุกร์ที่ 8 พฤษภาคม","Today is Friday, May 8th.","Hôm nay là thứ Sáu ngày 8 tháng 5.","今日は5月8日金曜日です。","五月八号"]],"err":[["今天不晴天。","今天不是晴天。","ปฏิเสธวลีนาม (晴天 / 阴天) ต้องใช้ 不是 เสมอ","Always negate noun predicates (晴天/阴天) with 不是.","否定名词性短语谓语须用“不是”。","Phủ định vị ngữ danh từ luôn dùng 不是.","名詞句述語の否定は必ず「不是」。"]],"rel":["g3-1-036","g3-1-044","g3-2-038"]},"g3-2-047":{"t":["ส่วนขยายคำนามด้วยกริยา/ประโยค (动词/主谓短语作定语): …ที่…","Relative clauses as noun modifiers (动词/主谓短语作定语)","句子成分·定语：动词或动词性短语、主谓短语作定语","Định ngữ là cụm động từ / chủ vị (…mà…)","連体修飾語（動詞句・主述句が名詞を修飾する）"],"f":["动词短语 + 的 + 名词（喝咖啡的人 / 去北京的飞机）","主谓短语 + 的 + 名词（妈妈做的菜 / 我买的那本书）"],"why":["นี่คือวิธีสร้างคำแปลว่า '…ที่…' (Relative Clause) ในภาษาจีน ซึ่ง 'กลับด้าน' กับภาษาไทยและอังกฤษ 100%!! · ไทย: 'อาหาร + ที่แม่ทำ' / อังกฤษ: 'the food that Mom cooked' → จีน: 'แม่ทำ + 的 + อาหาร' (妈妈做的菜) · ไทย: 'คนที่กำลังดื่มกาแฟ' → จีน: 'กำลังดื่มกาแฟ + 的 + คน' (正在喝咖啡的人) · กฎเหล็ก 2 ข้อที่ห้ามลืมเด็ดขาด: (1) ส่วนขยายที่เป็นกริยาหรือประโยค (动词短语 / 主谓短语) ต้องมี **的** เชื่อมหน้าคำนามเสมอ ห้ามละ 的 เด็ดขาด! (2) ห้ามเอาคำนามหลักขึ้นก่อนส่วนขยายแบบภาษาไทย (菜妈妈做的 ผิด 100%!)","This is how Chinese forms relative clauses ('the X that…') — the EXACT mirror image of English and Thai! · English: 'the food that Mom cooked' → Chinese: 妈妈做的菜 ('Mom-cooked 的 food'). · English: 'the person drinking coffee' → Chinese: 喝咖啡的人 ('drink-coffee 的 person'). · Two iron rules: (1) Verb or clause modifiers MUST ALWAYS take **的** before the noun — NEVER drop 的! (2) NEVER put the head noun before the clause.","动词短语或主谓短语作定语（相当于泰语“……ที่……”或英语定语从句），顺序与泰语、英语完全相反：先放修饰成分，加“的”，中心名词永远在最后！（妈妈做的菜、喝咖啡的人、我买的书）。 · 两条铁律：（1）动词／主谓短语作定语绝不能省“的”；（2）中心名词绝不能提前。","Đây là cách tạo mệnh đề quan hệ ('…mà…') trong tiếng Trung — NGƯỢC 100% tiếng Việt/Thái/Anh! · Việt: 'món ăn mẹ nấu' → Trung: 妈妈做的菜; 'người uống cà phê' → 喝咖啡的人. · 2 quy tắc thép: (1) BẮT BUỘC có 的 trước danh từ; (2) Danh từ chính luôn đứng CUỐI.","動詞句や主述句で名詞を修飾する連体修飾節（日本語と同じ語順で「…的＋名詞」）：妈妈做的菜（母が作った料理）、喝咖啡的人（コーヒーを飲んでいる人）、我买的书（私が買った本）。 · 鉄則：（1）必ず「的」を入れる（省略不可）。（2）中心名詞は常に最後。"],"use":[{"ok":true,"zh":"妈妈做的菜最好吃。","fix":"","py":"Māma zuò de cài zuì hǎochī.","tr":["กับข้าวที่แม่ทำอร่อยที่สุดเลย","The food that Mom cooks is the most delicious.","Món ăn mẹ nấu là ngon nhất.","母が作る料理が一番おいしいです。"],"h":["ประโยคขยายนาม (主谓短语): ใครทำ + 的 + สิ่งของ","Clause modifier: Doer + Verb + 的 + Head Noun","主谓短语作定语：“谁＋动词＋的＋中心名词”","Cụm chủ vị làm định ngữ: Ai làm + 的 + Danh từ","主述句による修飾：「誰＋動詞＋的＋中心名詞」"],"w":["ทำได้และเป็นธรรมชาติ 100% โดย 妈妈做的 ('ที่แม่ทำ') วางหน้า 菜 ('กับข้าว') และเชื่อมด้วย 的 ที่ขาดไม่ได้","Works 100% naturally: 妈妈做的 ('that Mom cooks') precedes head noun 菜 with mandatory 的.","“妈妈做的”整体修饰中心名词“菜”，“的”不可或缺。","Đúng 100%: 妈妈做的 đứng trước 菜 và nối bắt buộc bằng 的.","「妈妈做的」が中心名詞「菜」を前から修飾し、必須の「的」で結んでいる。"],"ref":"HSK 3.0 g3-2-047"},{"ok":true,"zh":"正在喝咖啡的那个人是我的朋友。","fix":"","py":"Zhèngzài hē kāfēi de nàge rén shì wǒ de péngyou.","tr":["คนคนนั้นที่กำลังดื่มกาแฟอยู่คือเพื่อนของฉัน","That person who is drinking coffee is my friend.","Người đang uống cà phê kia là bạn của tôi.","今コーヒーを飲んでいるあの人は私の友達です。"],"h":["วลีกริยา (正在喝咖啡) + 的 + คำนามเจาะจง (那个人)","Verb phrase (正在喝咖啡) + 的 + specific noun (那个人)","动词性短语＋“的”＋特指名词（正在喝咖啡的那个人）","Cụm động từ + 的 + danh từ xác định (正在喝咖啡的那个人)","動詞句＋「的」＋特定名詞（正在喝咖啡的那个人）"],"w":["ทำได้เพราะวางการกระทำที่กำลังเห็น (正在喝咖啡) + 的 ไว้หน้า 那个人 ได้ชัดและกระชับ","Works smoothly by placing the visible action (正在喝咖啡) + 的 right before 那个人.","“正在喝咖啡的”清晰限定“那个人”，语序地道。","Đúng vì đặt hành động 正在喝咖啡 + 的 ngay trước 那个人.","「今コーヒーを飲んでいる」という動詞句を「的」で「那个人」に前からつないでいる。"],"ref":"HSK 3.0 g3-2-047"},{"ok":false,"zh":"菜妈妈做的很好吃。","fix":"妈妈做的菜很好吃。","py":"Māma zuò de cài hěn hǎochī.","tr":["กับข้าวที่แม่ทำอร่อยมาก","The food Mom cooked is very delicious.","Món ăn mẹ nấu rất ngon.","母が作った料理はとてもおいしいです。"],"h":["ห้ามเอาคำนาม (菜) ขึ้นหน้าส่วนขยายแบบภาษาไทย!","NEVER put the noun (菜) before the modifier clause like Thai/English!","绝不能把中心名词放定语前面（菜妈妈做的×）","Không đặt danh từ chính (菜) trước mệnh đề bổ nghĩa!","中心名詞（菜）を修飾節の前に置けない"],"w":["ไม่ได้ เพราะในภาษาไทยเรียง 'กับข้าว + ที่แม่ทำ' แต่ภาษาจีนต้องเอาทั้งก้อน 'ที่แม่ทำ' วางหน้าคำว่า 'กับข้าว' เสมอ: 妈妈做的菜","Wrong because Chinese strictly puts the entire relative clause BEFORE the noun: 妈妈做的菜.","不行，汉语定语永远在中心语前：妈妈做的菜。","Không được vì định ngữ tiếng Trung luôn đứng TRƯỚC danh từ: 妈妈做的菜.","中国語は日本語と同じく修飾節が名詞の前：「妈妈做的菜」。"],"ref":"HSK 3.0 g3-2-047"},{"ok":false,"zh":"这是我买书。","fix":"这是我买的书。","py":"Zhè shì wǒ mǎi de shū.","tr":["นี่คือหนังสือที่ฉันซื้อ","This is the book I bought.","Đây là cuốn sách tôi mua.","これは私が買った本です。"],"h":["ห้ามละ 的 เมื่อใช้กริยาหรือประโยค (我买) ขยายคำนาม (书)!","NEVER drop 的 when a verb or clause (我买) modifies a noun (书)!","动词或主谓短语作定语绝不能省“的”","Tuyệt đối không bỏ 的 khi cụm động từ/chủ vị bổ nghĩa danh từ!","動詞句・主述句が名詞を修飾するとき「的」は絶対に省けない"],"w":["ไม่ได้ เพราะถ้าตัด 的 ออกเป็น 我买书 จะกลายเป็นประโยค 'ฉันซื้อหนังสือ' แทนที่จะเป็นวลีนาม 'หนังสือที่ฉันซื้อ' ต้องมี 的 เสมอ: 我买的书","Wrong because dropping 的 turns it into a clause 'I buy books' instead of 'the book I bought' — keep 的: 我买的书.","不行，省掉“的”就变成了动宾结构，必须加“的”：我买的书。","Không được vì bỏ 的 sẽ thành câu 'tôi mua sách'; bắt buộc giữ 的: 我买的书.","「的」を省くと動目構造になってしまう。必ず「我买的书」とする。"],"ref":"HSK 3.0 g3-2-047 · g3-1-024"}],"ex":[["妈妈做的菜最好吃。","Māma zuò de cài zuì hǎochī.","กับข้าวที่แม่ทำอร่อยที่สุด","The dishes Mom cooks are the most delicious.","Món mẹ nấu ngon nhất.","母が作った料理が一番おいしいです。","妈妈做的"],["这是我昨天买的书。","Zhè shì wǒ zuótiān mǎi de shū.","นี่คือหนังสือที่ฉันซื้อเมื่อวาน","This is the book I bought yesterday.","Đây là cuốn sách hôm qua tôi mua.","これは昨日私が買った本です。","买的"],["去北京的火车八点到。","Qù Běijīng de huǒchē bā diǎn dào.","รถไฟที่ไปปักกิ่งถึงตอนแปดโมง","The train going to Beijing arrives at 8:00.","Chuyến tàu đi Bắc Kinh đến lúc 8 giờ.","北京行きの電車は8時に着きます。","去北京的"],["正在喝咖啡的那个人是我哥哥。","Zhèngzài hē kāfēi de nàge rén shì wǒ gēge.","คนคนนั้นที่กำลังดื่มกาแฟคือพี่ชายฉัน","That person drinking coffee is my older brother.","Người đang uống cà phê kia là anh trai tôi.","コーヒーを飲んでいるあの人は私の兄です。","喝咖啡的"],["你介绍的饭馆真不错。","Nǐ jièshào de fànguǎn zhēn bùcuò.","ร้านอาหารที่คุณแนะนำดีจริง ๆ เลย","The restaurant you recommended is really great.","Quán ăn bạn giới thiệu thật sự rất ổn.","あなたが紹介してくれたレストランは本当にいいですね。","介绍的"]],"err":[["菜妈妈做的很好吃。","妈妈做的菜很好吃。","ส่วนขยาย 'ที่แม่ทำ' ต้องวางหน้าคำนาม 'กับข้าว' เสมอ (妈妈做的菜)","Always place the relative clause BEFORE the noun (妈妈做的菜).","主谓定语放在中心名词前面（妈妈做的菜）。","Định ngữ luôn đặt TRƯỚC danh từ (妈妈做的菜).","修飾節は常に名詞の前に置く（妈妈做的菜）。"],["这是我买书。","这是我买的书。","ประโยคขยายนามต้องมี 的 คั่นหน้าคำนามเสมอ (我买的书)","Clause modifiers MUST take 的 before the noun (我买的书).","主谓短语作定语必须加“的”（我买的书）。","Định ngữ chủ vị bắt buộc có 的 (我买的书).","主述句による修飾には必ず「的」を入れる（我买的书）。"]],"rel":["g3-1-024","g3-2-038","g3-2-035"]},"g3-2-048":{"t":["ส่วนเสริมผลลัพธ์ 1 (结果补语1): กริยา + 错 / 懂 / 好 / 会 / 完","Result complements 1 (结果补语1): Verb + 错 / 懂 / 好 / 会 / 完","补语·结果补语1：动词+错/懂/好/会/完","Bổ ngữ kết quả 1 (结果补语1): Động từ + 错 / 懂 / 好 / 会 / 完","結果補語1（结果补语1）：動詞＋错・懂・好・会・完"],"f":["肯定：动词 + 错 / 懂 / 好 / 会 / 完（+ 宾语）+ 了（看完书了 / 听懂了）","否定：没（有）+ 动词 + 结果补语（没听懂 / 没看完，不用“不”和“了”）"],"why":["结果补语 เป็นเอกลักษณ์สำคัญมากของภาษาจีน: กริยาเดี่ยว ๆ อย่าง 看 (ดู), 听 (ฟัง), 写 (เขียน) บอกแค่ 'ลงมือทำ' แต่ไม่ได้บอกว่า 'ผลเป็นยังไง' จึงต้องเอาคำบอกผล 5 ตัวใน HSK 2 มาเกาะติดหลังกริยา: (1) 完 = จบ/หมด (看完, 吃完) (2) 好 = เสร็จเรียบร้อยพร้อมใช้ (做好, 准备好, 买好) (3) 懂 = เข้าใจ (听懂, 看懂) (4) 错 = ผิดพลาด (写错, 听错, 买错) (5) 会 = ทำเป็นจนชำนาญ (学会) · กฎเหล็กเด็ดขาด 3 ข้อ: (1) ปฏิเสธผลลัพธ์ใช้ **没(有)** เท่านั้น (没听懂, 没看完) ห้ามใช้ 不! และต้องตัด 了 ออก! (2) ห้ามเอากรรมมาแทรกกลาง (ห้ามพูด 听老师懂 หรือ 吃饭完!) (3) ถามว่าเสร็จ/เข้าใจหรือยังใช้ …了吗？ หรือ …没有？ (你看懂了吗？)","Result complements are a superpower of Chinese: bare verbs (看, 听, 写) only express attempting an action, while attaching a result shows the OUTCOME: 完 ('finished': 看完), 好 ('ready/well done': 做好, 准备好), 懂 ('understood': 听懂, 看懂), 错 ('wrong': 写错, 买错), 会 ('mastered': 学会). · Three iron rules: (1) Negate ONLY with 没(有) and DROP 了 (没听懂, 没看完 — NEVER 不听懂!). (2) NEVER split Verb + Result with an object (never 吃饭完!). (3) Ask with …了吗？ or …没有？","结果补语紧跟在动词后，说明动作达到的结果：完（看完、吃完）、好（做好、准备好）、懂（听懂、看懂）、错（写错、买错）、会（学会）。 · 三条铁律：（1）否定只能用“没（有）”，且必须去掉“了”（没听懂、没看完，绝不说“不听懂”）；（2）动词与结果补语中间绝不能插入宾语或“了”（不说“吃饭完”）；（3）疑问用“……了吗？”或“……没有？”。","Bổ ngữ kết quả gắn sát sau động từ để nêu KẾT QUẢ đạt được: 完 (xong: 看完), 好 (xong xuôi sẵn sàng: 做好, 准备好), 懂 (hiểu: 听懂, 看懂), 错 (sai: 写错, 买错), 会 (học được/biết làm: 学会). · 3 quy tắc thép: (1) Phủ định chỉ dùng 没(有) và bỏ 了 (没听懂, không nói 不听懂); (2) KHÔNG chèn tân ngữ vào giữa (không nói 吃饭完); (3) Hỏi dùng …了吗？ / …没有？.","結果補語は動詞の直後に付き、動作の結果を表す：完（終える：看完）、好（完了・整う：做好・准备好）、懂（理解する：听懂・看懂）、错（間違える：写错・买错）、会（習得する：学会）。 · 3大鉄則：（1）否定は必ず「没（有）」で「了」を落とす（没听懂、「不听懂」は不可）。（2）動詞と結果補語の間に目的語を挟まない（吃饭完×）。"],"use":[{"ok":true,"zh":"我学会游泳了！","fix":"","py":"Wǒ xuéhuì yóuyǒng le!","tr":["ฉันเรียนว่ายน้ำเป็นแล้ว!","I've learned how to swim!","Tôi đã học biết bơi rồi!","泳げるようになりました！"],"h":["เรียนจนทำเป็นใช้ 学会 (学 + ผลลัพธ์ 会)","Use 学会 (学 + result 会) for 'have learned / mastered'","学到掌握某项技能用“学会”（学会游泳／学会开车）","Học đến khi biết làm dùng 学会 (学会游泳)","習得したときは「学会」（学会游泳・学会开车）"],"w":["ทำได้เพราะ 学 เฉย ๆ แปลว่า 'เรียน' (อาจยังไม่เป็น) แต่พอเติมผลลัพธ์ 会 เข้าไปเป็น 学会 แปลชัดเจนว่า 'เรียนจนทำเป็นแล้ว!'","Works cleanly: bare 学 only means 'study', while 学会 confirms you actually mastered the skill!","光说“学”不知是否掌握，加上结果补语“会”明确表示“已经掌握了”。","Đúng vì 学 chỉ là 'học', thêm kết quả 会 thành 学会 nghĩa là 'học được rồi'.","「学」だけでは習得したか不明だが、「学会」で確実にできるようになったことを表す。"],"ref":"HSK 3.0 g3-2-048"},{"ok":true,"zh":"对不起，我听错了。","fix":"","py":"Duìbuqǐ, wǒ tīngcuò le.","tr":["ขอโทษครับ/ค่ะ ฉันฟังผิดไป","Sorry, I misheard.","Xin lỗi, tôi nghe nhầm rồi.","すみません、聞き間違えました。"],"h":["ทำผิดพลาด (ฟังผิด / เขียนผิด / ซื้อผิด) ใช้ กริยา + 错 + 了","Express mistakes (mishear / miswrite / buy wrong) with Verb + 错 + 了","表示动作失误用“动词＋错＋了”（听错、写错、买错）","Làm nhầm/sai dùng Động từ + 错 + 了 (听错, 写错)","間違い（聞き間違い・書き間違い）は「動詞＋错＋了」"],"w":["ทำได้และสั้นกระชับมากในภาษาจีน: 听错 (ฟังผิด), 看错 (ดูผิด), 写错 (เขียนผิด), 买错 (ซื้อผิด) ใช้แทนประโยคยาว ๆ ได้ในสองพยางค์","Works super concisely: 听错, 看错, 写错, 买错 express 'mis-V' cleanly in just two characters.","“听错、看错、写错、买错”两字即可精准表达动作失误。","Đúng và cực gọn: 听错 (nghe nhầm), 写错 (viết sai), 买错 (mua nhầm).","「听错・看错・写错・买错」と2文字で的確にミスを表せる。"],"ref":"HSK 3.0 g3-2-048"},{"ok":false,"zh":"我不看懂这个字。","fix":"我没看懂这个字。","py":"Wǒ méi kàndǒng zhège zì.","tr":["ฉันอ่านอักษรตัวนี้ไม่เข้าใจ","I didn't understand this character.","Tôi đọc không hiểu chữ này.","この字の意味が分かりませんでした。"],"h":["ปฏิเสธส่วนเสริมผลลัพธ์ (看懂 / 听懂 / 看完) ใช้ 没 ห้ามใช้ 不!","Negate result complements (看懂/听懂/看完) with 没 — NEVER 不!","否定结果补语必须用“没”，绝不能用“不”（没看懂）","Phủ định bổ ngữ kết quả bắt buộc dùng 没, KHÔNG dùng 不!","結果補語の否定は「不」ではなく必ず「没」（没看懂）"],"w":["ไม่ได้ เพราะผลลัพธ์ 'เข้าใจแล้ว/เสร็จแล้ว' เป็นสิ่งที่เกิดขึ้นหรือไม่เกิดขึ้นจริง จึงปฏิเสธด้วย 没 เท่านั้น (没看懂, 没听懂, 没做完)","Wrong because whether a result was achieved is negated strictly with 没 (没看懂, 没听懂, 没做完), never 不.","不行，结果是否达成只能用“没”否定：没看懂、没听懂、没做完。","Không được vì phủ định kết quả đạt được bắt buộc dùng 没 (没看懂).","結果が達成されたかどうかは「没」でのみ否定する（没看懂・没听懂）。"],"ref":"HSK 3.0 g3-2-048"},{"ok":false,"zh":"我吃饭完了。","fix":"我吃完饭了。","py":"Wǒ chīwán fàn le.","tr":["ฉันกินข้าวเสร็จแล้ว","I've finished eating.","Tôi ăn cơm xong rồi.","ご飯を食べ終わりました。"],"h":["ห้ามเอาคำนามกรรม (饭 / 书) แทรกกลางระหว่างกริยากับ 完/好/懂/错!","NEVER wedge the object (饭/书) between the verb and 完/好/懂/错!","宾语绝不能插在动词和结果补语中间（吃完饭了）","Không chèn tân ngữ vào giữa động từ và 完/好/懂/错!","動詞と結果補語の間に目的語を挟まない（吃完饭了にする）"],"w":["ไม่ได้ เพราะ 吃 กับ 完 ต้องเกาะติดเป็นคำเดียวก่อนแล้วค่อยตามด้วยกรรม 饭: 吃完饭了 (และกริยาแยกได้อย่าง 吃饭 พอเติม 完 ต้องแยก 饭 ออกไปข้างหลัง!)","Wrong because 吃 + 完 must fuse tightly BEFORE the object 饭: 吃完饭了 (never 吃饭完!).","不行，动结组合“吃完”不能拆开，宾语“饭”必须放在后面：吃完饭了。","Không được vì 吃完 gắn chặt không tách được; tân ngữ 饭 đặt sau: 吃完饭了.","「吃完」は切り離せないため目的語「饭」は必ず後ろに置く（吃完饭了）。"],"ref":"HSK 3.0 g3-2-048 · g3-2-034"}],"ex":[["我吃完饭了。","Wǒ chīwán fàn le.","ฉันกินข้าวเสร็จแล้ว","I have finished eating.","Tôi đã ăn cơm xong rồi.","ご飯を食べ終わりました。","吃完"],["对不起，我没听懂。","Duìbuqǐ, wǒ méi tīngdǒng.","ขอโทษครับ/ค่ะ ฉันฟังไม่เข้าใจ","Sorry, I didn't understand.","Xin lỗi, tôi nghe không hiểu.","すみません、聞き取れませんでした。","听懂"],["这个词我写错了。","Zhège cí wǒ xiěcuò le.","คำนี้ฉันเขียนผิดไป","I wrote this word wrong.","Từ này tôi viết sai rồi.","この単語を書き間違えました。","写错"],["我已经准备好了。","Wǒ yǐjīng zhǔnbèihǎo le.","ฉันเตรียมตัวเสร็จเรียบร้อยแล้ว","I am already ready.","Tôi đã chuẩn bị xong rồi.","もう準備ができました。","准备好"],["我学会游泳了！","Wǒ xuéhuì yóuyǒng le!","ฉันเรียนว่ายน้ำเป็นแล้ว!","I've learned how to swim!","Tôi đã học biết bơi rồi!","泳げるようになりました！","学会"]],"err":[["我吃饭完了。","我吃完饭了。","ส่วนเสริมผลลัพธ์ 完 ต้องติดหลังกริยา 吃 ก่อนกรรม 饭 (吃完饭了)","Result 完 must attach directly to verb 吃 before 饭 (吃完饭了).","“吃完”紧连，宾语放后：我吃完饭了。","完 gắn sát 吃 trước 饭: 我吃完饭了.","「吃完」を先に並べ、目的語「饭」は後ろ（我吃完饭了）。"],["我不听懂。","我没听懂。","ปฏิเสธส่วนเสริมผลลัพธ์ใช้ 没 ไม่ใช่ 不","Negate result complements with 没, not 不.","否定结果补语用“没”，不用“不”。","Phủ định bổ ngữ kết quả dùng 没, không dùng 不.","結果補語の否定は「不」でなく「没」。"]],"rel":["g3-2-034","g3-2-045","g3-2-049"]},"g3-2-049":{"t":["ส่วนเสริมทิศทางอย่างง่าย 1 (简单趋向补语1): กริยา + 来 / 去","Simple directional complements 1: Verb + 来 / 去","补语·趋向补语1（1）：动词+来/去","Bổ ngữ xu hướng đơn 1: Động từ + 来 / 去","単純方向補語1：動詞＋来／去"],"f":["动词 + 来（朝向说话人：进来 / 回来 / 上来 / 拿来）","动词 + 去（远离说话人：出去 / 回去 / 下去 / 拿去）","带处所宾语：动词 + 处所 + 来 / 去（进教室来 / 回北京去）"],"why":["来 และ 去 ต่อท้ายกริยาเพื่อบอกทิศทางเทียบกับ 'ตำแหน่งของผู้พูด': · 来 = เคลื่อนที่ 'เข้ามาหา' ผู้พูด (เช่น เราอยู่ในห้องแล้วเรียกเพื่อนว่า 请进来! = เชิญเข้ามา!) · 去 = เคลื่อนที่ 'ออกไปห่างจาก' ผู้พูด (เช่น เราอยู่ในห้องแล้วบอกเพื่อนให้ออกไปว่า 你出去吧! = คุณออกไปเถอะ!) · จุดตายเรื่องตำแหน่งกรรมที่ออกสอบบ่อยสุด ๆ: (1) ถ้ากรรมเป็น 'สถานที่' (如 教室, 家, 北京) บังคับวาง 'ระหว่าง' กริยากับ 来/去 เสมอ!! (进教室来, 回家去 — ห้ามพูด 进来教室 หรือ 回去家!) (2) ถ้ากรรมเป็น 'สิ่งของ' (如 书, 咖啡) วางได้ทั้งตรงกลางและข้างหลัง (拿来一本书 หรือ 拿一本书来 ได้ทั้งคู่!)","来 and 去 attach after a verb to indicate movement relative to the SPEAKER: · 来 = toward the speaker (请进来! 'Come in!' when you're inside). · 去 = away from the speaker (出去 'go out', 回去 'go back'). · Exam-critical object rule: (1) PLACE objects (教室, 家, 北京) MUST go BETWEEN the verb and 来/去 (进教室来, 回家去 — NEVER 进来教室 or 回去家!). (2) Concrete THING objects can go either between or after (拿来一本书 / 拿一本书来).","“来、去”作简单趋向补语，以说话人位置为参照：“来”表朝向说话人（进来、回来、上来），“去”表远离说话人（出去、回去、下去）。 · 宾语位置铁律：（1）处所宾语必须插在“动词”和“来／去”中间（进教室来、回家去，绝不说“进来教室”）；（2）事物宾语放中间或后面均可（拿一本书来／拿来一本书）。","来 và 去 sau động từ chỉ hướng so với VỊ TRÍ NGƯỜI NÓI: 来 = hướng về phía người nói (进来, 回来); 去 = đi xa người nói (出去, 回去). · Quy tắc vị trí tân ngữ cực quan trọng: (1) Tân ngữ NƠI CHỐN bắt buộc chen GIỮA động từ và 来/去 (进教室来, 回家去 — KHÔNG nói 进来教室!); (2) Đồ vật đặt giữa hay sau đều được.","「来・去」は話し手の位置を基準に方向を表す：「来」は話し手へ近づく（进来・回来）、「去」は遠ざかる（出去・回去）。 · 目的語位置の鉄則：（1）場所目的語は必ず動詞と「来／去」の間に挟む（进教室来・回家去、「进来教室」は不可！）。（2）物の目的語は間でも後ろでも可。"],"use":[{"ok":true,"zh":"他回北京去了。","fix":"","py":"Tā huí Běijīng qù le.","tr":["เขากลับปักกิ่งไปแล้ว (ตัวผู้พูดไม่ได้อยู่ที่ปักกิ่ง)","He went back to Beijing.","Anh ấy về Bắc Kinh rồi.","彼は北京へ帰っていきました。"],"h":["กรรมเป็นสถานที่ (北京 / 家 / 教室) แทรกระหว่างกริยากับ 来/去 เสมอ","Place objects (北京 / 家 / 教室) ALWAYS sit between Verb and 来/去","处所宾语必须放在“动词”与“来／去”中间（回北京去）","Tân ngữ nơi chốn luôn chen giữa động từ và 来/去 (回北京去)","場所目的語は必ず動詞と「来／去」の間に挟む（回北京去）"],"w":["ทำได้เพราะวางสถานที่ 北京 ไว้ตรงกลางระหว่าง 回 กับ 去 และใช้ 去 เพราะผู้พูดไม่ได้อยู่ที่ปักกิ่ง (ถ้าผู้พูดอยู่ปักกิ่งจะพูด 他回北京来了)","Works cleanly: place 北京 sits between 回 and 去, and 去 shows the speaker is NOT in Beijing.","处所词“北京”插在“回”和“去”中间，且说话人不在北京故用“去”。","Đúng vì địa điểm 北京 nằm giữa 回 và 去, và người nói không ở Bắc Kinh nên dùng 去.","場所「北京」を「回」と「去」の間に挟み、話し手が北京にいないため「去」を使う。"],"ref":"HSK 3.0 g3-2-049"},{"ok":true,"zh":"请你拿一杯水来。","fix":"","py":"Qǐng nǐ ná yī bēi shuǐ lái.","tr":["ช่วยเอาน้ำมาให้ฉันสักแก้วหน่อย","Please bring a glass of water here.","Xin bạn lấy một cốc nước lại đây.","お水を1杯持って来てください。"],"h":["กรรมเป็นสิ่งของ (一杯水) วางก่อน 来/去 หรือหลัง 来/去 ก็ได้","Thing objects (一杯水) can go before OR after 来/去","事物宾语可放“来／去”前，也可放后（拿一杯水来／拿来一杯水）","Đồ vật đặt trước hay sau 来/去 đều được (拿一杯水来)","物の目的語は「来／去」の前でも後ろでも置ける（拿一杯水来）"],"w":["ทำได้เพราะ 一杯水 เป็นสิ่งของ (ไม่ใช่สถานที่) จึงวางตรงกลางว่า 拿一杯水来 (ถ้ามี 了 วางหลัง来 ได้เป็น 拿来了一杯水)","Works flexibly because 一杯水 is an object (not a place), so 拿一杯水来 (or completed 拿来了一杯水) is natural.","“一杯水”是事物宾语，未发生动作常说“拿一杯水来”，已完成可说“拿来了一杯水”。","Đúng vì 一杯水 là đồ vật nên đặt trước 来 (拿一杯水来) rất tự nhiên.","「一杯水」は物なので「拿一杯水来」が自然（完了なら「拿来了一杯水」も可）。"],"ref":"HSK 3.0 g3-2-049"},{"ok":false,"zh":"老师进来教室了。","fix":"老师进教室来了。","py":"Lǎoshī jìn jiàoshì lái le.","tr":["คุณครูเดินเข้ามาในห้องเรียนแล้ว","The teacher came into the classroom.","Thầy giáo đi vào lớp học rồi.","先生が教室に入って来ました。"],"h":["ห้ามวางชื่อสถานที่ (教室 / 家 / 北京) ไว้หลัง 进来 / 回去!","NEVER put a place (教室 / 家 / 北京) AFTER 进来 / 回去!","处所宾语绝不能放“来／去”后面（进来教室×→进教室来○）","Tuyệt đối không đặt nơi chốn SAU 进来 / 回去 (phải là 进教室来)","場所を「进来／回去」の後ろに置けない（进教室来にする）"],"w":["ไม่ได้ เพราะเป็นกฎเหล็กที่ออกสอบตลอด: กรรมสถานที่อย่าง 教室, 房间, 家, 楼 ต้องแทรกระหว่างกริยากับ 来/去 เสมอ: 进教室来, 上楼去, 回家去","Wrong per an absolute Chinese rule: place objects (教室, 家, 楼) MUST go between the verb and 来/去 (进教室来, 上楼去).","不行，处所宾语必须插在中间：进教室来、上楼去、回家去，绝不说“进来教室”。","Không được vì quy tắc cứng: tân ngữ nơi chốn bắt buộc chen giữa (进教室来, 上楼去).","場所目的語は必ず動詞と「来／去」の間に挟む鉄則（进教室来・上楼去）。"],"ref":"HSK 3.0 g3-2-049"}],"ex":[["请进来吧！","Qǐng jìnlai ba!","เชิญเข้ามาข้างในสิครับ/ค่ะ!","Please come in!","Mời vào đi!","どうぞお入りください！","进来"],["老师进教室来了。","Lǎoshī jìn jiàoshì lái le.","คุณครูเข้ามาในห้องเรียนแล้ว","The teacher came into the classroom.","Thầy giáo vào phòng học rồi.","先生が教室に入って来ました。","来"],["他回北京去了。","Tā huí Běijīng qù le.","เขากลับปักกิ่งไปแล้ว","He went back to Beijing.","Anh ấy về Bắc Kinh rồi.","彼は北京へ帰っていきました。","去"],["请你拿一杯水来。","Qǐng nǐ ná yī bēi shuǐ lái.","กรุณาเอาน้ำมาหนึ่งแก้วหน่อย","Please bring a glass of water here.","Xin bạn mang một cốc nước lại đây.","お水を1杯持って来てください。","来"],["上面太冷了，我们下去吧。","Shàngmiàn tài lěng le, wǒmen xiàqu ba.","ข้างบนหนาวเกินไปแล้ว พวกเราลงไปกันเถอะ","It's too cold up here; let's go down.","Trên này lạnh quá, chúng ta xuống đi.","上は寒すぎるから下りましょう。","下去"]],"err":[["老师进来教室了。","老师进教室来了。","กรรมสถานที่ (教室/家/北京) ต้องแทรกกลางระหว่างกริยากับ 来/去 เสมอ","Place objects MUST sit between the verb and 来/去 (进教室来).","处所宾语必须插在动词和“来／去”中间（进教室来）。","Tân ngữ nơi chốn luôn chen giữa động từ và 来/去 (进教室来).","場所目的語は必ず動詞と「来／去」の間に挟む（进教室来）。"],["他回去北京了。","他回北京去了。","แทรกสถานที่ 北京 ไว้ตรงกลางระหว่าง 回 กับ 去","Put place 北京 between 回 and 去 (回北京去).","处所词“北京”放中间：回北京去了。","Đặt 北京 vào giữa 回 và 去: 回北京去了.","「北京」を「回」と「去」の間に挟む（回北京去了）。"]],"rel":["g3-2-050","g3-2-051","g3-2-034"]},"g3-2-050":{"t":["ส่วนเสริมทิศทางอย่างง่าย 2 (简单趋向补语2): กริยา + 上 / 下 / 进 / 出 / 过 / 回","Simple directional complements 2: Verb + 上 / 下 / 进 / 出 / 过 / 回","补语·趋向补语1（2）：动词+上/下/进/出/过/回","Bổ ngữ xu hướng đơn 2: Động từ + 上 / 下 / 进 / 出 / 过 / 回","単純方向補語2：動詞＋上・下・进・出・过・回"],"f":["动词 + 上 / 下 / 进 / 出 / 过 / 回 +（处所/宾语）","例如：走上楼 / 走进教室 / 走出门 / 跑回家 / 走过这条路"],"why":["นอกจาก 来/去 แล้ว กริยาบอกการเคลื่อนไหว (เช่น 走 เดิน, 跑 วิ่ง, 飞 บิน, 拿 หยิบ, 游 ว่าย) ยังต่อท้ายด้วยคำบอกทิศทางเจาะจง 6 ตัวได้โดยตรง: · 上 (ขึ้น: 走上楼) · 下 (ลง: 跑下楼) · 进 (เข้า: 走进教室) · 出 (ออก: 走出房间) · 过 (ข้าม/ผ่าน: 走过这条路) · 回 (กลับ: 跑回家) · ข้อควรระวัง: (1) ต่างจาก 来/去! เมื่อใช้กลุ่ม 6 ตัวนี้ (上/下/进/出/过/回) ชื่อสถานที่จะวาง 'ข้างหลัง' ตัวทิศทางได้เลย! (走进教室 ✓ ไม่ใช่ 走教室进 ✗) (2) เวลาเล่าเหตุการณ์ที่ทำสำเร็จแล้ว ให้ใส่ 了 ไว้หลังคำทิศทางหรือท้ายประโยค (走进了教室 / 走进教室了)","Action verbs (走, 跑, 飞, 拿) pair directly with 6 specific directional complements: 上 (up: 走上楼), 下 (down: 跑下楼), 进 (into: 走进教室), 出 (out of: 走出房间), 过 (across/past: 走过这条路), 回 (back: 跑回家). · Key contrast with 来/去: place objects go AFTER these 6 directionals (走进教室 ✓, NEVER 走教室进 ✗)! · Put 了 after the directional or at sentence end (走进教室了).","动作动词后可直接加“上、下、进、出、过、回”标明具体位移方向：走上楼、跑下楼、走进教室、走出房间、走过这条路、跑回家。 · 与“来／去”对比：接这六个趋向补语时，处所宾语放在趋向补语后面（走进教室，不说“走教室进”）。","Động từ di chuyển (走, 跑, 飞, 拿) gắn trực tiếp 6 bổ ngữ hướng: 上 (lên: 走上楼), 下 (xuống: 跑下楼), 进 (vào: 走进教室), 出 (ra: 走出房间), 过 (qua: 走过这条路), 回 (về: 跑回家). · Khác 来/去: tân ngữ nơi chốn đặt SAU 6 từ này (走进教室).","動作動詞の直後に「上・下・进・出・过・回」を付けて具体的な移動方向を表す：走上楼・跑下楼・走进教室・走出房间・走过这条路・跑回家。 · 「来／去」と違い、場所目的語はこれら6つの後ろに置く（走进教室）。"],"use":[{"ok":true,"zh":"王老师走进教室了。","fix":"","py":"Wáng lǎoshī zǒujìn jiàoshì le.","tr":["อาจารย์หวังเดินเข้าไปในห้องเรียนแล้ว","Teacher Wang walked into the classroom.","Thầy Vương đã đi vào phòng học rồi.","王先生は教室へ歩いて入りました。"],"h":["กริยาเคลื่อนไหว + 进/出/上/下/回 + สถานที่","Motion verb + 进/出/上/下/回 + Place","“动作动词＋进／出／上／下／回＋处所”","Động từ di chuyển + 进/出/上/下/回 + Nơi chốn","「移動動詞＋进／出／上／下／回＋場所」"],"w":["ทำได้และเห็นภาพชัดเจนกว่า 进教室 เฉย ๆ เพราะ 走 บอกวิธี ('เดิน') และ 进 บอกทิศทาง ('เข้าไป') แล้ววางสถานที่ 教室 ไว้ข้างหลังได้เลย","Works vividly: 走 tells the manner ('walk'), 进 gives the direction ('into'), and place 教室 follows right behind.","“走”表方式，“进”表方向，处所“教室”直接跟在“走进”后面。","Đúng và rõ hình ảnh: 走 (đi bộ) + 进 (vào) + 教室 (lớp học).","「走」（歩く）＋「进」（入る）で動きが鮮明になり、場所「教室」は後ろに置ける。"],"ref":"HSK 3.0 g3-2-050"},{"ok":true,"zh":"下雨了，孩子跑回家了。","fix":"","py":"Xià yǔ le, háizi pǎohuí jiā le.","tr":["ฝนตกแล้ว ลูกวิ่งกลับบ้านไปแล้ว","It started raining, so the child ran back home.","Trời mưa rồi, đứa bé chạy về nhà rồi.","雨が降ってきたので子どもは家へ走って帰りました。"],"h":["วิ่งกลับ / เดินกลับ ใช้ 跑回 / 走回 + สถานที่","Use 跑回 / 走回 + Place for 'run/walk back to…'","“跑回／走回＋处所”表示以某种方式返回","Chạy về / đi bộ về dùng 跑回 / 走回 + Nơi chốn","走って帰る・歩いて帰るは「跑回／走回＋場所」"],"w":["ทำได้เพราะ 跑 (วิ่ง) + 回 (กลับ) รวมเป็นกริยา+ทิศทางที่กระชับในสองพยางค์ แล้วต่อสถานที่ 家 ทันที","Works cleanly in two characters (跑回 'run back') directly followed by destination 家.","“跑回”两字兼表方式和方向，直接带宾语“家”。","Đúng vì 跑回 kết hợp gọn cả cách thức (chạy) và hướng (về) trước 家.","「跑回」で「走って戻る」を2文字で表し、目的地「家」を後ろに続ける。"],"ref":"HSK 3.0 g3-2-050"},{"ok":false,"zh":"王老师走教室进了。","fix":"王老师走进教室了。","py":"Wáng lǎoshī zǒujìn jiàoshì le.","tr":["อาจารย์หวังเดินเข้าไปในห้องเรียนแล้ว","Teacher Wang walked into the classroom.","Thầy Vương đi vào lớp học rồi.","王先生は教室に歩いて入りました。"],"h":["ห้ามแยก 进 / 出 / 上 / 下 / 回 ออกจากกริยาด้วยชื่อสถานที่!","NEVER separate 进 / 出 / 上 / 下 / 回 from the verb with a place noun!","“走／跑”与“上、下、进、出、回”紧连，处所放后面","Không tách 进 / 出 / 上 / 下 / 回 khỏi động từ bằng địa điểm!","動詞と「上・下・进・出・回」の間に場所を挟めない"],"w":["ไม่ได้ เพราะในโครงสร้างนี้ 走进 เกาะติดกันเป็นก้อนเดียวแล้วค่อยวางสถานที่ 教室 ข้างหลัง (ต่างจาก 来/去 ที่ต้องแทรกสถานที่ไว้หน้า 来/去)","Wrong because 走进 stays fused as one unit BEFORE 教室 (only 来/去 go after a place object!).","不行，“走进”紧密相连，处所“教室”放后面（只有“来／去”才放处所后）。","Không được vì 走进 dính liền rồi mới tới 教室 (chỉ 来/去 mới đứng sau nơi chốn).","「走进」は切り離せず場所「教室」は後ろに置く（「来／去」だけ場所の後ろ）。"],"ref":"HSK 3.0 g3-2-050 · g3-2-049"}],"ex":[["王老师走进教室了。","Wáng lǎoshī zǒujìn jiàoshì le.","อาจารย์หวังเดินเข้าไปในห้องเรียนแล้ว","Teacher Wang walked into the classroom.","Thầy Vương đã đi vào lớp học rồi.","王先生は教室に入って行きました。","走进"],["小猫跑进房间了。","Xiǎo māo pǎojìn fángjiān le.","ลูกแมววิ่งเข้าไปในห้องแล้ว","The kitten ran into the room.","Mèo con chạy vào phòng rồi.","子猫が部屋へ走り込みました。","跑进"],["他跑上三楼了。","Tā pǎoshàng sān lóu le.","เขาวิ่งขึ้นไปชั้นสามแล้ว","He ran up to the third floor.","Anh ấy chạy lên tầng ba rồi.","彼は3階へ駆け上がりました。","跑上"],["下雨了，孩子跑回家了。","Xià yǔ le, háizi pǎohuí jiā le.","ฝนตกแล้ว ลูกวิ่งกลับบ้านไปแล้ว","It started raining, so the child ran back home.","Trời mưa rồi, đứa bé chạy về nhà rồi.","雨が降ってきて子どもは家へ走って帰りました。","跑回"],["走过这条路就是医院。","Zǒuguò zhè tiáo lù jiù shì yīyuàn.","เดินข้ามถนนเส้นนี้ไปก็เป็นโรงพยาบาลเลย","Walk across this road and there's the hospital.","Đi qua con đường này chính là bệnh viện.","この道を渡ればすぐ病院です。","走过"]],"err":[["王老师走教室进了。","王老师走进教室了。","进 / 出 / 上 / 下 / 回 ต้องเกาะติดหลังกริยาก่อนแล้วค่อยตามด้วยสถานที่","Keep Verb + 进/出/上/下/回 fused BEFORE the place (走进教室了).","“走进”紧连，处所放后面（走进教室了）。","Gắn chặt 走进 trước địa điểm (走进教室了).","「走进」を切り離さず場所を後ろに置く（走进教室了）。"]],"rel":["g3-2-049","g3-2-051","g3-2-034"]},"g3-2-051":{"t":["ส่วนเสริมทิศทางผสม (复合趋向补语1): 出来 / 出去 / 进来 / 进去 / 回来 / 起来…","Compound directional complements (复合趋向补语1)","补语·趋向补语1：复合趋向补语（出来/进去/回来/起来…）","Bổ ngữ xu hướng kép (复合趋向补语1)","複合方向補語1（复合趋向补语1）：出来・进去・回来・起来など"],"f":["动词 + 上/下/进/出/回/过/起 + 来/去（走进来 / 跑出去 / 拿出来 / 站起来）","带处所宾语：动词 + 进/出/上/下/回 + 处所 + 来/去（走进教室来）"],"why":["复合趋向补语 คือการรวม 'ทิศทางเฉพาะ (上/下/进/出/回/过/起)' เข้ากับ 'ทิศเทียบผู้พูด (来/去)' เพื่อบอกทิศทางครบ 2 มิติในทีเดียว! เช่น 走进来 (เดินเข้ามาหาเรา), 跑出去 (วิ่งออกไปจากเรา), 拿出来 (หยิบออกมา), 走过去 (เดินข้ามไปฝั่งนู้น), 站起来 (ลุกขึ้นยืน — ระวัง 起 จับคู่ได้เฉพาะ 起来 ไม่มี 起去!) · กฎเหล็กเรื่องตำแหน่งกรรม: (1) ถ้ามี 'กรรมสถานที่' (เช่น 教室, 房间, 楼) บังคับแทรกไว้ 'หน้า 来/去' เสมอ! (走进教室来, 跑回房间去 — ห้ามพูด 走进来教室!) (2) ถ้ามี 'กรรมสิ่งของ' (เช่น 手机, 书) วางหน้าหรือหลัง 来/去 ก็ได้ (拿出手机来 หรือ 拿出来一个手机)","Compound directional complements fuse a specific direction (上/下/进/出/回/过/起) with speaker perspective (来 toward / 去 away): 走进来 ('walk in toward me'), 跑出去 ('run out away'), 拿出来 ('take out'), 站起来 ('stand up' — note 起 ONLY pairs with 来, never 起去!). · Iron object rule: (1) PLACE objects MUST go BEFORE 来/去 (走进教室来, 跑回房间去 — NEVER 走进来教室!). (2) Thing objects can sit either before or after 来/去.","复合趋向补语把具体方向（上、下、进、出、回、过、起）与立足点（来、去）组合起来，构成“走进来、跑出去、拿出来、站起来”（注意：“起”只配“来”，没有“起去”）。 · 宾语铁律：（1）处所宾语必须插在“来／去”前面（走进教室来，绝不说“走进来教室”）；（2）事物宾语放“来／去”前或后均可。","Bổ ngữ xu hướng kép ghép hướng cụ thể (上/下/进/出/回/过/起) với góc nhìn người nói (来/去): 走进来, 跑出去, 拿出来, 站起来 (lưu ý: 起 chỉ đi với 来, không có 起去). · Quy tắc thép: tân ngữ NƠI CHỐN bắt buộc đặt TRƯỚC 来/去 (走进教室来, không nói 走进来教室!).","複合方向補語は具体的方向（上・下・进・出・回・过・起）＋話し手視点（来・去）の組み合わせ：走进来・跑出去・拿出来・站起来（「起」は「起来」のみで「起去」はない）。 · 鉄則：場所目的語は必ず「来／去」の前に挟む（走进教室来、「走进来教室」は不可）。"],"use":[{"ok":true,"zh":"他从外面拿进一本书来。","fix":"","py":"Tā cóng wàimiàn nájìn yī běn shū lái.","tr":["เขาถือหนังสือเล่มหนึ่งเข้ามาจากข้างนอก","He brought a book inside from outside.","Anh ấy cầm từ bên ngoài vào một cuốn sách.","彼は外から本を1冊持ち込みました。"],"h":["กริยา + 进 + สิ่งของ + 来 (หรือ 拿进来 + 一本书)","Verb + 进 + thing + 来 (or 拿进来 + thing)","事物宾语可放“来／去”前：拿进一本书来（或拿进来一本书）","Đồ vật đặt trước 来/去: 拿进一本书来 (hoặc 拿进来一本书)","物の目的語は「来／去」の前（拿进一本书来）または後ろ"],"w":["ทำได้และเป็นธรรมชาติมาก โดยเฉพาะเมื่อวางกรรม 一本书 ไว้หน้า 来 (หรือเมื่อเสร็จแล้วพูดว่า 拿进来了一本书 ก็ถูกเช่นกัน)","Works super naturally with object 一本书 placed right before 来 (completed 拿进来了一本书 also works).","“拿进一本书来”流畅自然，带“了”也可说“拿进来了一本书”。","Đúng và rất tự nhiên khi đặt 一本书 trước 来.","「拿进一本书来」と目的語を「来」の前に挟むのが最も自然。"],"ref":"HSK 3.0 g3-2-051"},{"ok":true,"zh":"老师走进教室来了。","fix":"","py":"Lǎoshī zǒujìn jiàoshì lái le.","tr":["คุณครูเดินเข้ามาในห้องเรียนแล้ว","The teacher walked into the classroom.","Thầy giáo bước vào lớp học rồi.","先生が教室に入って来ました。"],"h":["กรรมสถานที่ (教室 / 房间 / 楼) บังคับแทรกกลางก่อน 来/去 เสมอ!","Place objects (教室 / 房间 / 楼) MUST go inside right before 来/去!","处所宾语必须插在“来／去”之前：走进教室来","Tân ngữ nơi chốn BẮT BUỘC chen trước 来/去: 走进教室来","場所目的語は必ず「来／去」の前に挟む（走进教室来）"],"w":["ทำได้เพราะแทรกสถานที่ 教室 ไว้ระหว่าง 走进 กับ 来 ถูกต้องตามกฎลำดับกรรมของส่วนเสริมทิศทาง 100%","Works 100% per directional complement rules: place 教室 goes between 走进 and 来.","处所词“教室”位于“走进”后、“来”前，完全规范。","Đúng 100% vì địa điểm 教室 chen giữa 走进 và 来.","場所「教室」を「走进」の後・「来」の前に挟む完璧な語順。"],"ref":"HSK 3.0 g3-2-051"},{"ok":false,"zh":"老师走进来教室了。","fix":"老师走进教室来了。","py":"Lǎoshī zǒujìn jiàoshì lái le.","tr":["คุณครูเดินเข้ามาในห้องเรียนแล้ว","The teacher walked into the classroom.","Thầy giáo bước vào lớp học rồi.","先生が教室に入って来ました。"],"h":["ห้ามวางชื่อสถานที่ไว้หลัง 进来 / 出去 / 上去!","NEVER put a place noun AFTER 进来 / 出去 / 上去!","处所宾语绝不能放在复合趋向补语后面（走进来教室×）","Tuyệt đối không đặt nơi chốn SAU 走进来 / 跑出去!","場所名詞を「走进来／跑出去」の後ろに置けない"],"w":["ไม่ได้ เพราะกรรมสถานที่ต้องแทรกไว้ก่อน 来/去 เสมอ: 走进教室来, 跑回房间去, 走上三楼去","Wrong because place objects MUST go before 来/去: 走进教室来, 跑回房间去.","不行，处所宾语必须插在“来／去”前面：走进教室来。","Không được vì tân ngữ nơi chốn bắt buộc đặt TRƯỚC 来/去: 走进教室来.","場所目的語は必ず「来／去」の前に挟み「走进教室来」にする。"],"ref":"HSK 3.0 g3-2-051"}],"ex":[["王老师走进教室来了。","Wáng lǎoshī zǒujìn jiàoshì lái le.","อาจารย์หวังเดินเข้ามาในห้องเรียนแล้ว","Teacher Wang walked into the classroom.","Thầy Vương bước vào lớp học rồi.","王先生が教室に入って来ました。","走进"],["小狗跑出去了。","Xiǎo gǒu pǎo chūqu le.","ลูกหมาวิ่งออกไปแล้ว","The puppy ran out.","Chú chó con chạy ra ngoài rồi.","子犬が走り出て行きました。","出去"],["他从外面拿进一本书来。","Tā cóng wàimiàn nájìn yī běn shū lái.","เขาถือหนังสือเข้ามาจากข้างนอกหนึ่งเล่ม","He brought a book inside from outside.","Anh ấy cầm từ ngoài vào một cuốn sách.","彼は外から本を1冊持って入りました。","拿进"],["请大家站起来。","Qǐng dàjiā zhàn qǐlai.","ขอให้ทุกคนยืนขึ้นครับ/ค่ะ","Everyone, please stand up.","Mời mọi người đứng dậy.","皆さん起立してください。","起来"],["他往我这儿走过来了。","Tā wǎng wǒ zhèr zǒu guòlai le.","เขาเดินข้ามมาทางฉันแล้ว","He walked over toward me.","Anh ấy đi về phía tôi rồi.","彼がこちらへ歩いて来ました。","过来"]],"err":[["老师走进来教室了。","老师走进教室来了。","กรรมสถานที่ (教室) ต้องแทรกไว้หน้า 来/去 เสมอ","Place objects MUST go before 来/去 (走进教室来).","处所宾语须插在“来／去”前（走进教室来）。","Tân ngữ nơi chốn luôn chen trước 来/去 (走进教室来).","場所目的語は必ず「来／去」の前（走进教室来）。"]],"rel":["g3-2-049","g3-2-050","g3-2-023"]},"g3-2-052":{"t":["ส่วนเสริมบอกระดับ/สภาพ (状态补语1): กริยา + 得 + คุณศัพท์","State complements 1 (状态补语1): Verb + 得 + Adj phrase","补语·状态补语1：动词+得+形容词性短语","Bổ ngữ trạng thái 1 (状态补语1): Động từ + 得 + Cụm tính từ","様態補語1（状态补语1）：動詞＋得＋形容詞句"],"f":["肯定：主语 +（宾语）+ 动词 + 得 + 很 / 非常 + 形容词（他跑得很快）","带宾语：主语 + 动词 + 宾语 + 动词 + 得 + 形容词（她说汉语说得很好）","否定：主语 + 动词 + 得 + 不 + 形容词（他跑得不快，绝不是“不跑得快”！）"],"why":["状态补语1 ใช้โครงสร้าง 'กริยา + 得 + คุณศัพท์' เพื่อประเมินหรือบรรยายว่าการกระทำนั้น 'ทำได้ดีแค่ไหน / เร็วแค่ไหน / ช้าแค่ไหน' เช่น 他跑得很快 (เขาวิ่งเร็วมาก), 昨天我睡得很好 (เมื่อวานฉันนอนหลับดีมาก), 这次考试我考得不错 (สอบครั้งนี้ฉันทำได้ดีทีเดียว) · กฎเหล็ก 3 ข้อที่ออกสอบทุกครั้ง: (1) ประโยคปฏิเสธต้องวาง **不** ไว้ 'หลัง 得' เสมอ! (他跑得不快 ✓ ห้ามพูด 他不跑得快 ✗!) (2) ประโยคคำถาม A不A ก็ทำที่หลัง 得 เช่น 他跑得快不快？ (ห้ามพูด 他跑不跑得快 ✗!) (3) เมื่อกริยามีกรรมติดมาด้วย (如 说汉语, 写汉字) ห้ามคั่นกรรมไว้หน้า 得 — ต้องซ้ำกริยา (她说汉语说得很好) หรือย้ายกรรมขึ้นหน้า (她汉语说得很好)!","State complements (Verb + 得 + Adj phrase) evaluate HOW well, fast, or smoothly an action is performed: 他跑得很快, 昨天我睡得很好, 考得不错. · Three exam-critical rules: (1) ALWAYS put negation 不 AFTER 得 (他跑得不快 ✓ — NEVER 他不跑得快 ✗!). (2) A-not-A questions also go AFTER 得 (跑得快不快？). (3) When an object is present, 得 MUST still touch the verb — repeat the verb (她说汉语说得很好) or front the object (她汉语说得很好).","状态补语1“动词＋得＋形容词性短语”用于描写或评价动作达到的状态或程度（他跑得很快、睡得很好、考得不错）。 · 三条必考铁律：（1）否定词“不”必须放在“得”后面（跑得不快，绝不说“不跑得快”）；（2）正反问在补语上重叠（跑得快不快？）；（3）带宾语时必须重动或提前宾语（说汉语说得很好／汉语说得很好）。","Bổ ngữ trạng thái 1 ('Động từ + 得 + Cụm tính từ') đánh giá mức độ/trạng thái của hành động (他跑得很快, 睡得很好, 考得不错). · 3 quy tắc vàng: (1) Phủ định đặt 不 SAU 得 (他跑得不快, KHÔNG nói 不跑得快!); (2) Hỏi chính phản ở sau 得 (跑得快不快？); (3) Có tân ngữ phải lặp động từ (说汉语说得很好) hoặc đưa tân ngữ lên trước.","様態補語1「動詞＋得＋形容詞句」は動作の程度・上手さを評価する（他跑得很快・睡得很好・考得不错）。 · 3大鉄則：（1）否定の「不」は必ず「得」の後ろ（跑得不快、「不跑得快」は不可）。（2）反復疑問も「得」の後ろ（跑得快不快？）。（3）目的語があるときは動詞を重ねる（说汉语说得很好）か目的語を前に出す。"],"use":[{"ok":true,"zh":"他来得很早，走得很晚。","fix":"","py":"Tā lái de hěn zǎo, zǒu de hěn wǎn.","tr":["เขามาเช้ามาก และกลับดึกมาก","He arrives very early and leaves very late.","Anh ấy đến rất sớm và về rất muộn.","彼は来るのがとても早く、帰るのがとても遅いです。"],"h":["กริยา + 得 + 很 / 非常 / 太 + คุณศัพท์ (บอกเล่ามักใส่ 很)","Verb + 得 + 很 / 非常 / 太 + Adj (keep 很 in plain statements)","肯定状态补语常加程度副词“很／非常”（来得很早）","Khẳng định thường thêm 很 / 非常 sau 得 (来得很早)","肯定の様態補語は「很・非常」を添える（来得很早）"],"w":["ทำได้และเป็นธรรมชาติมาก เหมือนประโยคคุณศัพท์ทั่วไปที่ควรมี 很 นำหน้าคุณศัพท์ในรูปบอกเล่า (来得很早, 跑得很快)","Works naturally: just like adjective predicates, plain affirmative state complements normally take 很 (来得很早).","肯定式状态补语的形容词前通常带“很、非常”等程度副词。","Đúng vì giống câu tính từ, câu khẳng định thường có 很 trước tính từ.","形容詞述語と同じく肯定文では「很」などを添えるのが自然。"],"ref":"HSK 3.0 g3-2-052"},{"ok":true,"zh":"他游得不快。","fix":"","py":"Tā yóu de bù kuài.","tr":["เขาว่ายน้ำไม่เร็ว","He doesn't swim fast.","Anh ấy bơi không nhanh.","彼は泳ぐのが速くありません。"],"h":["ปฏิเสธระดับความเก่ง: วาง 不 ไว้ 'หลัง 得' เสมอ (游得不快)","Put negation 不 AFTER 得 (游得不快 — NEVER 不游得快!)","否定状态补语将“不”放在“得”后（游得不快、说得不好）","Phủ định đặt 不 SAU 得 (游得不快, 说得不好)","否定の「不」は必ず「得」の後ろ（游得不快・说得不好）"],"w":["ทำได้เพราะสิ่งที่เราปฏิเสธไม่ใช่ว่า 'เขาไม่ได้ว่ายน้ำ' แต่ปฏิเสธระดับว่า 'ว่ายได้ไม่เร็ว' จึงวาง 不 ไว้หน้า 快 หลัง 得","Works because you aren't denying the swimming itself — you're negating the speed (不快) right after 得.","否定的不是“游”这个动作，而是程度“快”，所以“不”在“得”后。","Đúng vì phủ định mức độ 'không nhanh' chứ không phủ định hành động bơi.","否定しているのは「泳ぐ」ことではなく「速い」程度なので「得」の後ろに「不」を置く。"],"ref":"HSK 3.0 g3-2-052"},{"ok":false,"zh":"他不跑得快。","fix":"他跑得不快。","py":"Tā pǎo de bù kuài.","tr":["เขาวิ่งไม่เร็ว","He doesn't run fast.","Anh ấy chạy không nhanh.","彼は走るのが速くないです。"],"h":["ห้ามวาง 不 ไว้หน้ากริยาในประโยค 得 (不跑得快 ผิด 100%!)","NEVER put 不 before the verb in a 得 sentence (不跑得快 is wrong!)","状态补语句否定绝不能说“不跑得快”，须说“跑得不快”","Tuyệt đối không nói 不跑得快 — phải nói 跑得不快","「不跑得快」は100%誤用、必ず「跑得不快」にする"],"w":["ไม่ได้ เพราะในประโยค状态补语 ตำแหน่งปฏิเสธบังคับอยู่หลัง 得 เสมอ (跑得不快, 写得不好, 考得不错)","Wrong because state complements ALWAYS place negation after 得: 跑得不快, 写得不好, 考得不错.","不行，“不”必须放在补语前、“得”后面：他跑得不快。","Không được vì phủ định của bổ ngữ trạng thái bắt buộc đứng SAU 得: 他跑得不快.","様態補語の否定は必ず「得」の後ろに「不」を置く（他跑得不快）。"],"ref":"HSK 3.0 g3-2-052"},{"ok":false,"zh":"她写汉字得很好看。","fix":"她写汉字写得很好看。","py":"Tā xiě Hànzì xiě de hěn hǎokàn.","tr":["เธอเขียนอักษรจีนได้สวยมาก","She writes Chinese characters very nicely.","Cô ấy viết chữ Hán rất đẹp.","彼女は漢字を書くのがとてもきれいです。"],"h":["มีกรรม (汉字) ต้องซ้ำกริยา (写汉字写得…) หรือย้ายกรรมขึ้นหน้า (汉字写得…)","With an object (汉字), repeat the verb (写汉字写得…) or front it (汉字写得…)","带宾语时必须重动或把宾语提前，不能说“写汉字得很好看”","Có tân ngữ (汉字) phải lặp động từ (写汉字写得…) hoặc đảo tân ngữ lên trước","目的語があるときは動詞を重ねる（写汉字写得…）か目的語を前に出す"],"w":["ไม่ได้ เพราะ 得 ต้องติดกริยา 写 โดยตรง ห้ามให้ 汉字 มาคั่นกลาง (และห้ามใส่ 了 หลังกริยาด้วย เช่น ห้ามพูด 跑了得很快!)","Wrong because 得 must sit directly after 写 with no object or 了 in between — repeat 写 or front 汉字.","不行，“得”前不能隔宾语或“了”，须说“她写汉字写得很好看”或“她汉字写得很好看”。","Không được vì 得 phải sát động từ 写, không bị tân ngữ 汉字 hay 了 chen giữa.","「得」は動詞「写」の直後にしか置けないため「写汉字写得很好看」にする。"],"ref":"HSK 3.0 g3-2-052 · g3-2-030"}],"ex":[["他跑得很快。","Tā pǎo de hěn kuài.","เขาวิ่งเร็วมาก","He runs very fast.","Anh ấy chạy rất nhanh.","彼は走るのがとても速いです。","得"],["她说汉语说得很好。","Tā shuō Hànyǔ shuō de hěn hǎo.","เธอพูดภาษาจีนได้ดีมาก","She speaks Chinese very well.","Cô ấy nói tiếng Trung rất giỏi.","彼女は中国語を話すのがとても上手です。","说得"],["昨天我睡得很好。","Zuótiān wǒ shuì de hěn hǎo.","เมื่อวานฉันนอนหลับสบายมาก","Yesterday I slept very well.","Hôm qua tôi ngủ rất ngon.","昨日はよく眠れました。","得"],["他跑得不快。","Tā pǎo de bù kuài.","เขาวิ่งไม่เร็ว","He doesn't run fast.","Anh ấy chạy không nhanh.","彼は走るのが速くありません。","得不"],["你这次考得怎么样？","Nǐ zhè cì kǎo de zěnmeyàng?","สอบครั้งนี้คุณทำได้เป็นยังไงบ้าง","How did you do on this exam?","Lần này bạn thi thế nào?","今回の試験はどうでしたか。","考得"]],"err":[["他不跑得快。","他跑得不快。","ประโยค 得 ต้องวาง 不 ไว้หลัง 得 เสมอ (跑得不快)","Always place 不 AFTER 得 in a state complement (跑得不快).","否定词“不”放在“得”后（他跑得不快）。","Phủ định đặt 不 SAU 得 (他跑得不快).","否定の「不」は必ず「得」の後ろ（他跑得不快）。"],["她写汉字得很好看。","她写汉字写得很好看。","มีกรรมให้ซ้ำกริยาหน้า 得 (写汉字写得很好看)","When an object is present, repeat the verb before 得.","带宾语须重动：写汉字写得很好看。","Có tân ngữ phải lặp động từ trước 得.","目的語があるときは「得」の前で動詞を重ねる。"]],"rel":["g3-2-030","g3-2-064","g3-2-034"]},"g3-2-053":{"t":["ส่วนเสริมระยะเวลา (数量补语2-1): ทำกริยานานแค่ไหน","Duration complements (数量补语2-1): how long an action lasts","补语·数量补语2（1）：表示动作持续的时间","Bổ ngữ thời lượng (数量补语2-1): hành động kéo dài bao lâu","時間量補語（数量补语2-1）：動作の継続時間"],"f":["无宾语：主语 + 动词 + 了 + 时长（我等了十分钟 / 睡了八个小时）","有普通宾语：动词 + 了 + 时长 +（的）+ 宾语（学了两年汉语）或重动（看书看了两个小时）"],"why":["时量补语 บอก 'ความยาวนานของระยะเวลา' ที่ทำกริยานั้น (เช่น นอน 8 ชั่วโมง, รอ 10 นาที, เรียน 2 ปี) — กฎเหล็กที่สำคัญมาก: ระยะเวลาต้องวาง **หลังกริยา** เสมอ! ต่างจาก 'จุดเวลา' (如 八点, 明天) ที่วางหน้ากริยา! · วิธีจัดการเมื่อมีกรรม: (1) ไม่มีกรรม: วางระยะเวลาหลัง กริยา+了 ทันที (我等了十分钟, 睡了八个小时) (2) มีกรรมคำนามทั่วไป: แทรกระยะเวลาไว้ระหว่าง กริยา+了 กับกรรม (我学了两年汉语 = ฉันเรียนภาษาจีนมา 2 ปี) หรือซ้ำกริยา (我看书看了两个小时) (3) มีกรรมสรรพนามคน (他/你/我): วางสรรพนามไว้ 'ก่อน' ระยะเวลาเสมอ (我等了他十分钟!) · ข้อควรระวัง: ห้ามวางระยะเวลาไว้หน้ากริยา (ห้ามพูด 我两个小时看书!)","Duration complements state HOW LONG an action lasts (8 hours, 10 minutes, 2 years) — and ALWAYS go AFTER the verb (unlike points in time like 八点/明天 which go before the verb!). · Handling objects: (1) No object: V + 了 + Duration (等了十分钟); (2) Noun object: put duration before the object (学了两年汉语) OR repeat the verb (看书看了两个小时); (3) Personal pronoun object (他/你/我): MUST sit BEFORE the duration (等了他十分钟!). · Caution: NEVER put duration before the verb (never 我两个小时看书!).","时量补语表示动作持续的时间长度，必须放在动词后面（区别于放动词前的时点状语“八点、明天”）。 · 带宾语规律：（1）无宾语：等了十分钟；（2）普通名词宾语：插在中间“学了两年汉语”或重动“看书看了两个小时”；（3）人称代词宾语必须放时长前（等了他十分钟）。 · 注意：绝不能把时长放动词前（不说“我两个小时看书”）。","Bổ ngữ thời lượng nêu KHOẢNG THỜI GIAN hành động kéo dài và LUÔN đứng SAU động từ (khác mốc giờ 八点 đứng trước động từ!). · Với tân ngữ: (1) Không tân ngữ: 等了十分钟; (2) Danh từ thường: 学了两年汉语 hoặc lặp động từ 看书看了两个小时; (3) Đại từ nhân xưng (他/你/我) đặt TRƯỚC thời lượng: 等了他十分钟.","時間量補語は動作の継続時間を表し、必ず動詞の後ろに置く（時点の「八点・明天」は動詞の前）。 · 目的語の扱い：（1）目的語なし：等了十分钟、（2）一般名詞：学了两年汉语、または動詞重ね「看书看了两个小时」、（3）人称代名詞は期間の前（等了他十分钟）。"],"use":[{"ok":true,"zh":"我学了两年汉语了。","fix":"","py":"Wǒ xuéle liǎng nián Hànyǔ le.","tr":["ฉันเรียนภาษาจีนมาสองปีแล้ว (และตอนนี้ยังเรียนอยู่)","I have been studying Chinese for two years (and still am).","Tôi đã học tiếng Trung được hai năm rồi (vẫn đang học).","中国語を勉強して2年になります（今も継続中）。"],"h":["了1 หลังกริยา + ระยะเวลา + กรรม (+ 了2 ท้ายประโยค = ยังทำอยู่จนตอนนี้!)","V + 了1 + Duration + Object (+ final 了2 = still continuing now!)","双“了”表动作持续至今仍在继续（学了两年汉语了）","Hai chữ 了 chỉ việc kéo dài đến nay vẫn đang tiếp tục","2つの「了」で今まで続いており今も継続中を表す"],"w":["ทำได้และละเอียดมาก: เทียบ 我学了两年汉语 (เคยเรียน 2 ปี ตอนนี้อาจเลิกแล้ว) กับ 我学了两年汉语了 (เรียนมา 2 ปีแล้วและตอนนี้ก็ยังเรียนอยู่!)","Works with precision: 我学了两年汉语 (studied for 2 years, maybe stopped) vs 我学了两年汉语了 (2 years and STILL studying!).","单“了”表过去一段经历；双“了”（学了两年汉语了）表一直持续到现在。","Đúng và cực tinh tế: thêm 了 cuối câu để báo đến nay vẫn đang học tiếp.","文末にも「了」を添えることで「今も継続して勉強している」ニュアンスが出る。"],"ref":"HSK 3.0 g3-2-053"},{"ok":true,"zh":"我在门口等了你十分钟。","fix":"","py":"Wǒ zài ménkǒu děngle nǐ shí fēnzhōng.","tr":["ฉันรอคุณอยู่ที่หน้าประตูสิบนาทีแล้ว","I waited for you at the doorway for ten minutes.","Tôi đã đợi bạn ở cửa mười phút rồi.","入口であなたを10分間待ちました。"],"h":["กรรมเป็นสรรพนามคน (你 / 他 / 我) วาง 'หน้า' ระยะเวลาเสมอ!","Personal pronoun objects (你 / 他 / 我) ALWAYS precede the duration!","人称代词宾语必须放在时量补语前面（等了你十分钟）","Đại từ nhân xưng (你 / 他 / 我) luôn đặt TRƯỚC thời lượng","人称代名詞（你・他・我）は必ず継続時間の前に置く"],"w":["ทำได้เพราะสรรพนามคน 你 เกาะติดหลัง 等了 ก่อน แล้วจึงต่อด้วยระยะเวลา 十分钟 (ห้ามพูด 等了十分钟你!)","Works strictly per Chinese word order: pronoun 你 sits right after 等了 before 十分钟 (never 等了十分钟你!).","人称代词“你”紧跟“等了”，再接时量“十分钟”。","Đúng vì đại từ 你 đứng sát sau 等了 rồi mới tới 十分钟.","人称代名詞「你」を「等了」の直後に置き、その後に「十分钟」を続ける。"],"ref":"HSK 3.0 g3-2-053"},{"ok":false,"zh":"我两个小时看书了。","fix":"我看了两个小时书。","py":"Wǒ kànle liǎng ge xiǎoshí shū.","tr":["ฉันอ่านหนังสือไปสองชั่วโมง","I read books for two hours.","Tôi đã đọc sách hai tiếng đồng hồ.","2時間本を読みました。"],"h":["ห้ามวางระยะเวลา (两个小时) ไว้หน้ากริยาเหมือนจุดเวลา (八点)!","NEVER put a duration (两个小时) before the verb like a clock time (八点)!","时量补语（两个小时）必须放动词后，不能放动词前","Không đặt thời lượng (两个小时) trước động từ như mốc giờ!","継続時間（两个小时）を時点（八点）のように動詞の前に置けない"],"w":["ไม่ได้ เพราะ 八点 (จุดเวลา 8 โมง) วางหน้ากริยา (我八点看书) แต่ 两个小时 (ระยะเวลานาน 2 ชั่วโมง) เป็นส่วนเสริม ต้องวางหลังกริยาเสมอ: 我看了两个小时书","Wrong because clock points (八点) precede the verb, while durations (两个小时) are complements and MUST follow the verb: 我看了两个小时书.","不行，时点“八点”放动词前，时长“两个小时”必须放动词后：我看了两个小时书。","Không được vì mốc giờ 八点 đứng trước động từ, còn thời lượng 两个小时 bắt buộc đứng sau động từ.","時点「八点」は動詞の前だが、継続時間「两个小时」は必ず動詞の後ろ（我看了两个小时书）。"],"ref":"HSK 3.0 g3-2-053 · g3-1-040"},{"ok":false,"zh":"我等了十分钟你。","fix":"我等了你十分钟。","py":"Wǒ děngle nǐ shí fēnzhōng.","tr":["ฉันรอคุณสิบนาที","I waited for you for ten minutes.","Tôi đã đợi bạn mười phút.","あなたを10分待ちました。"],"h":["ห้ามวางสรรพนามบุคคล (你 / 他 / 我) ไว้หลังระยะเวลา!","NEVER place a personal pronoun (你 / 他 / 我) after the duration!","人称代词宾语不能放时长后面（等了十分钟你×）","Không đặt đại từ nhân xưng SAU thời lượng (等了十分钟你×)","人称代名詞を継続時間の後ろに置けない（等了十分钟你×）"],"w":["ไม่ได้ เพราะกรรมที่เป็นสรรพนามคน (你, 他, 我) ต้องอยู่หน้าส่วนเสริมระยะเวลาเสมอ: 我等了你十分钟","Wrong because personal pronouns always sit right after the verb, BEFORE the duration: 我等了你十分钟.","不行，人称代词宾语须置于时量补语之前：我等了你十分钟。","Không được vì đại từ nhân xưng phải đứng TRƯỚC thời lượng: 我等了你十分钟.","人称代名詞は必ず時間量補語の前（我等了你十分钟）に置く。"],"ref":"HSK 3.0 g3-2-053"}],"ex":[["昨天晚上我睡了八个小时。","Zuótiān wǎnshang wǒ shuìle bā ge xiǎoshí.","เมื่อคืนฉันนอนไปแปดชั่วโมง","Last night I slept for eight hours.","Tối qua tôi đã ngủ tám tiếng.","昨夜8時間寝ました。","八个小时"],["我学了两年汉语了。","Wǒ xuéle liǎng nián Hànyǔ le.","ฉันเรียนภาษาจีนมาสองปีแล้ว","I have been studying Chinese for two years.","Tôi đã học tiếng Trung hai năm rồi.","中国語を2年勉強しています。","两年"],["我在门口等了你十分钟。","Wǒ zài ménkǒu děngle nǐ shí fēnzhōng.","ฉันรอคุณที่หน้าประตูสิบนาที","I waited for you at the doorway for ten minutes.","Tôi đã đợi bạn ở cửa mười phút.","入口であなたを10分待ちました。","十分钟"],["我昨天看书看了两个小时。","Wǒ zuótiān kàn shū kànle liǎng ge xiǎoshí.","เมื่อวานฉันอ่านหนังสือไปสองชั่วโมง","Yesterday I read books for two hours.","Hôm qua tôi đã đọc sách hai tiếng.","昨日2時間本を読みました。","两个小时"],["我游了一个小时泳。","Wǒ yóule yī ge xiǎoshí yǒng.","ฉันว่ายน้ำไปหนึ่งชั่วโมง","I swam for an hour.","Tôi đã bơi một tiếng.","1時間泳ぎました。","一个小时"]],"err":[["我两个小时看书了。","我看了两个小时书。","ระยะเวลา (两个小时) ต้องวางหลังกริยาเสมอ ไม่วางหน้ากริยา","Put duration (两个小时) AFTER the verb, never before it.","时量补语放动词后（看了两个小时书）。","Đặt thời lượng SAU động từ (看了两个小时书).","継続時間は動詞の後ろ（看了两个小时书）。"],["我等了十分钟你。","我等了你十分钟。","สรรพนามคน (你 / 他 / 我) วางหน้า 十分钟 เสมอ","Put personal pronoun 你 BEFORE 十分钟.","人称代词放时长前（等了你十分钟）。","Đặt đại từ 你 TRƯỚC 十分钟.","人称代名詞「你」を「十分钟」の前に置く。"]],"rel":["g3-2-005","g3-2-013","g3-1-040"]},"g3-2-054":{"t":["ส่วนเสริมจำนวนหลังคุณศัพท์ (数量补语2-2): คุณศัพท์ + จำนวน/ระดับต่าง","Adjective + quantity complement (数量补语2-2): 大三岁 / 贵十块 / 快一点儿","补语·数量补语2（2）：形容词+数量补语","Bổ ngữ số lượng sau tính từ (数量补语2-2): 大三岁 / 贵十块","形容詞＋数量補語（数量补语2-2）：大三岁・贵十块"],"f":["形容词 + 具体数量（大三岁 / 贵十块钱 / 早十分钟）","形容词 + 一点儿 / 一些（慢一点儿 / 便宜一点儿）"],"why":["หลังคำคุณศัพท์ในภาษาจีนสามารถเติม 'จำนวนส่วนต่าง' (数量补语) เพื่อระบุให้เป๊ะว่า 'ต่างกันเท่าไร / ขึ้นอีกนิดหน่อย' เช่น 大三岁 (โตกว่าสามปี), 贵十块钱 (แพงกว่าสิบหยวน), 早十分钟 (เร็วกว่าสิบนาที), 慢一点儿 (ช้าลงหน่อย) · มักใช้คู่กับประโยค 比 (哥哥比我大三岁) หรือใช้ในคำขอ/คำแนะนำ (请说慢一点儿) · กฎเหล็กเด็ดขาด 2 ข้อ: (1) ห้ามวางจำนวนส่วนต่างไว้ 'หน้า' คุณศัพท์ (ห้ามพูด 比我三岁大 หรือ 比这个十块贵!) (2) เมื่อใช้ 一点儿 วาง 'หลังคุณศัพท์' แปลว่า '…ขึ้นหน่อย' (慢一点儿) ต่างจาก 有点儿 ที่วาง 'หน้าคุณศัพท์' แปลว่า '…ไปหน่อย' (有点儿慢)!","Place a quantity complement AFTER an adjective to state the exact difference or slight degree: 大三岁 ('3 years older'), 贵十块钱 ('10 yuan pricier'), 早十分钟 ('10 minutes earlier'), 慢一点儿 ('a bit slower'). · Common in 比 comparisons (哥哥比我大三岁) and polite requests (请说慢一点儿). · Two iron rules: (1) NEVER put the amount BEFORE the adjective (never 比我三岁大!). (2) 一点儿 goes AFTER an adjective ('a bit more…'), while 有点儿 goes BEFORE it ('a bit too…').","形容词后面接数量短语或“一点儿”作数量补语，精确说明差别或轻微变化：大三岁、贵十块钱、早十分钟、慢一点儿。 · 两条铁律：（1）数量差必须放形容词后（大三岁，绝不说“三岁大”表差额）；（2）区分“形容词＋一点儿”（慢一点儿＝再慢些）与“有点儿＋形容词”（有点儿慢＝偏慢）。","Đặt cụm số lượng hoặc 一点儿 SAU tính từ để nêu mức chênh lệch cụ thể: 大三岁 (hơn 3 tuổi), 贵十块钱 (đắt hơn 10 tệ), 早十分钟 (sớm hơn 10 phút), 慢一点儿 (chậm hơn chút). · 2 quy tắc thép: (1) KHÔNG đặt mức chênh lệch trước tính từ; (2) Phân biệt 'tính từ + 一点儿' với '有点儿 + tính từ'.","形容詞の後ろに数量詞や「一点儿」を置いて具体的な差を表す：大三岁（3歳年上）、贵十块钱（10元高い）、早十分钟（10分早い）、慢一点儿（もう少しゆっくり）。 · 鉄則：（1）差の数量は必ず形容詞の後ろ（三岁大×）。（2）「形容詞＋一点儿」と「有点儿＋形容詞」を区別する。"],"use":[{"ok":true,"zh":"哥哥比我大三岁。","fix":"","py":"Gēge bǐ wǒ dà sān suì.","tr":["พี่ชายอายุมากกว่าฉันสามปี","My older brother is three years older than me.","Anh trai hơn tôi ba tuổi.","兄は私より3歳年上です。"],"h":["ระบุส่วนต่างตัวเลขเป๊ะ ๆ วาง 'หลังคุณศัพท์' (大 + 三岁)","Place the exact numeric difference AFTER the adjective (大 + 三岁)","具体差额放在形容词后面：比我大三岁／贵十块钱","Đặt mức chênh lệch cụ thể SAU tính từ (大三岁 / 贵十块钱)","具体的な差の数値は必ず形容詞の後ろ（大三岁・贵十块钱）"],"w":["ทำได้และแม่นยำมาก โดยใช้ 大 (อายุมากกว่า) / 小 (อายุน้อยกว่า) ตามด้วยจำนวนปี 三岁 ทันที","Works precisely: age comparisons use 大 ('older') or 小 ('younger') followed directly by the number of years.","比较年龄大小固定用“大／小＋几岁”，数量补语放形容词后。","Đúng và cực chuẩn khi so sánh tuổi tác (大/小 + số tuổi).","年齢差は「大／小＋〜岁」と形容詞の後ろに数詞を置く定番表現。"],"ref":"HSK 3.0 g3-2-054 · g3-2-062"},{"ok":true,"zh":"请说慢一点儿，我没听懂。","fix":"","py":"Qǐng shuō màn yīdiǎnr, wǒ méi tīngdǒng.","tr":["กรุณาพูดช้าลงหน่อยครับ/ค่ะ ฉันฟังไม่เข้าใจ","Please speak a bit more slowly; I didn't understand.","Xin nói chậm hơn một chút, tôi nghe không hiểu.","もう少しゆっくり話してください、聞き取れませんでした。"],"h":["ขอให้ทำช้าลง/เร็วขึ้น/ถูกหน่อย ใช้ คุณศัพท์ + 一点儿","Use Adjective + 一点儿 for 'a little more [adj]'","表示期望更怎样用“形容词＋一点儿”（慢一点儿、快一点儿）","Yêu cầu thay đổi chút dùng Tính từ + 一点儿 (慢一点儿)","「もう少し〜して」は「形容詞＋一点儿」（慢一点儿）"],"w":["ทำได้ตามกลุ่มเทียบคำ g15 เพราะ 一点儿 หลังคุณศัพท์ 慢 แปลว่า 'ช้ากว่านี้อีกหน่อย' (ต่างจาก 你说得有点儿快 = คุณพูดเร็วไปหน่อย)","Works per group g15: 慢一点儿 asks for 'a bit slower' (contrast 有点儿慢 'a bit too slow').","“慢一点儿”表希望更慢些，区别于表不满的“有点儿慢”。","Đúng theo nhóm g15: 慢一点儿 nghĩa là 'chậm hơn chút nữa'.","「慢一点儿」は「もう少しゆっくり」の依頼（不満を表す「有点儿慢」と対照的）。"],"ref":"กลุ่มเทียบคำ g15 · HSK 3.0 g3-2-054"},{"ok":false,"zh":"哥哥比我三岁大。","fix":"哥哥比我大三岁。","py":"Gēge bǐ wǒ dà sān suì.","tr":["พี่ชายอายุมากกว่าฉันสามปี","Older brother is three years older than me.","Anh trai hơn tôi ba tuổi.","兄は私より3歳年上です。"],"h":["ห้ามวางตัวเลขส่วนต่าง (三岁 / 十块钱) ไว้หน้าคุณศัพท์แบบภาษาอังกฤษ ('3 years older')!","NEVER put the difference (三岁 / 十块钱) BEFORE the adjective like English '3 years older'!","数量补语绝不能放形容词前（三岁大×→大三岁○）","Không đặt mức chênh lệch TRƯỚC tính từ (phải là 大三岁)","差の数値を形容詞の前に置けない（三岁大×→大三岁○）"],"w":["ไม่ได้ เพราะในภาษาอังกฤษเรียง '3 years + older' แต่ในภาษาจีนส่วนเสริมจำนวนต้องวาง 'หลังคุณศัพท์' เสมอ: 大三岁, 贵十块钱, 早十分钟","Wrong because English says '3 years older', whereas Chinese ALWAYS places the quantity AFTER the adjective: 大三岁.","不行，汉语数量补语须在形容词后：大三岁、贵十块钱、早十分钟。","Không được vì tiếng Trung luôn đặt số lượng chênh lệch SAU tính từ: 大三岁.","英語の 3 years older とは逆で、中国語は必ず「大三岁」「贵十块钱」と後ろに置く。"],"ref":"HSK 3.0 g3-2-054 · g3-2-062"}],"ex":[["哥哥比我大三岁。","Gēge bǐ wǒ dà sān suì.","พี่ชายแก่กว่าฉันสามปี","Older brother is three years older than me.","Anh trai hơn tôi ba tuổi.","兄は私より3歳年上です。","大三岁"],["这件衣服比那件贵二十块钱。","Zhè jiàn yīfu bǐ nà jiàn guì èrshí kuài qián.","เสื้อตัวนี้แพงกว่าตัวนั้นยี่สิบหยวน","This shirt is 20 yuan more expensive than that one.","Chiếc áo này đắt hơn chiếc kia 20 tệ.","この服はあれより20元高いです。","贵二十块钱"],["我今天比昨天早十分钟到教室。","Wǒ jīntiān bǐ zuótiān zǎo shí fēnzhōng dào jiàoshì.","วันนี้ฉันมาถึงห้องเรียนเร็วกว่าเมื่อวานสิบนาที","Today I arrived at the classroom 10 minutes earlier than yesterday.","Hôm nay tôi đến lớp sớm hơn hôm qua 10 phút.","今日は昨日より10分早く教室に着きました。","早十分钟"],["请说慢一点儿。","Qǐng shuō màn yīdiǎnr.","กรุณาพูดช้าลงหน่อยครับ/ค่ะ","Please speak a bit more slowly.","Xin nói chậm hơn một chút.","もう少しゆっくり話してください。","慢一点儿"],["这个苹果大一点儿。","Zhège píngguǒ dà yīdiǎnr.","แอปเปิลลูกนี้ใหญ่กว่านิดหน่อย","This apple is a little bigger.","Quả táo này to hơn một chút.","このりんごの方が少し大きいです。","大一点儿"]],"err":[["哥哥比我三岁大。","哥哥比我大三岁。","จำนวนส่วนต่างต้องวางหลังคุณศัพท์เสมอ (大三岁)","Always put the quantity difference AFTER the adjective (大三岁).","数量补语必须放形容词后（大三岁）。","Số lượng chênh lệch luôn đặt SAU tính từ (大三岁).","差の数量は必ず形容詞の後ろに置く（大三岁）。"],["请说有点儿慢。","请说慢一点儿。","ขอให้ช้าลงหน่อยใช้ คุณศัพท์ + 一点儿 (慢一点儿 ไม่ใช่ 有点儿慢)","Use Adj + 一点儿 (慢一点儿), not 有点儿 + Adj, for 'a bit more slowly'.","表“再慢些”用“慢一点儿”，不用“有点儿慢”。","Nói 'chậm hơn chút' dùng 慢一点儿, không dùng 有点儿慢.","「もう少しゆっくり」は「有点儿慢」でなく「慢一点儿」。"]],"rel":["g3-2-062","g3-2-053","g3-1-015"]},"g3-2-055":{"t":["ประโยคภาคแสดงเป็นประธาน-กริยา (主谓谓语句): 他个子很高 / 我头疼","Topic-comment sentences (主谓谓语句): 大主语 + 小主语 + 谓语","句型·主谓句4：主谓谓语句","Câu vị ngữ chủ vị (主谓谓语句): 他个子很高 / 我头疼","主述述語文（主谓谓语句）：大主語＋小主語＋述語"],"f":["大主语（整体/人/地方）+ 小主语（部分/属性）+ 谓语（他个子很高 / 我头疼 / 身体很好）"],"why":["主谓谓语句 เป็นโครงสร้างจีนแท้ที่กระชับและมีเสน่ห์มาก: วาง 'หัวข้อใหญ่ (大主语)' ขึ้นต้น แล้วบรรยายด้วยก้อน 'ประธานย่อย + ภาคแสดง (主谓短语)' ต่อทันทีโดยไม่ต้องใส่ 的 หรือ 有! · ตัวอย่างสุดคลาสสิก: (1) คน + ส่วนร่างกาย/ลักษณะ: 我头疼 (ฉันปวดหัว — ไม่ต้องพูด 我的头疼!), 他个子很高 (เขารูปร่างสูงมาก), 奶奶身体很好 (คุณย่าสุขภาพดีมาก) (2) สถานที่/เวลา + สภาพ: 北京天气很冷 (ปักกิ่งอากาศหนาวมาก), 这家饭馆菜很好吃 (ร้านนี้กับข้าวอร่อยมาก) · ข้อควรระวัง: อย่าเผลอใส่ 有 แบบภาษาไทย ('เขามีรูปร่างสูง' → ห้ามพูด 他有个子很高!) และไม่จำเป็นต้องยัด 的 เข้าไปทุกประโยค","A topic-comment sentence (主谓谓语句) puts a broad TOPIC (大主语) upfront and describes it with a mini subject+predicate — NO 的 or 有 required! · Classic examples: 我头疼 ('I have a headache'), 他个子很高 ('He is tall in build'), 奶奶身体很好 ('Grandma is in great health'), 这家饭馆菜很好吃 ('This restaurant has great food'). · Caution: NEVER translate Thai/English 'have' as 有 in 他有个子很高!","主谓谓语句由“大主语（整体／话题）＋主谓短语（小主语＋谓语）”构成，是汉语最具特色的句型之一：我头疼、他个子很高、奶奶身体很好、这家饭馆菜很好吃。 · 注意：不必硬加“的”，更不能受英语影响误加“有”（不说“他有个子很高”）。","Câu vị ngữ chủ vị (主谓谓语句) đặt CHỦ ĐỀ LỚN (toàn thể) lên đầu rồi miêu tả bằng 1 cụm chủ–vị (bộ phận) mà KHÔNG cần 的 hay 有: 我头疼 (tôi đau đầu), 他个子很高 (anh ấy dáng rất cao), 奶奶身体很好. · Lưu ý: không thêm 有 thừa (không nói 他有个子很高!).","主述述語文（主谓谓语句）は「大主語（全体・主題）＋小主語（部分・側面）＋述語」という中国語らしい文型（日本語の「象は鼻が長い」と同じ！）：我头疼、他个子很高、奶奶身体很好、这家饭馆菜很好吃。 · 注意：「有」を余計に入れない（他有个子很高×）。"],"use":[{"ok":true,"zh":"我今天头疼，想去药店买药。","fix":"","py":"Wǒ jīntiān tóu téng, xiǎng qù yàodiàn mǎi yào.","tr":["วันนี้ฉันปวดหัว อยากไปซื้อยาที่ร้านขายยา","I have a headache today and want to go to the pharmacy to buy medicine.","Hôm nay tôi đau đầu, muốn ra hiệu thuốc mua thuốc.","今日頭が痛いので薬局へ薬を買いに行きたいです。"],"h":["อาการเจ็บป่วยตามอวัยวะ: คน + อวัยวะ + 疼 (我头疼 / 我手疼)","Body aches: Person + Body part + 疼 (我头疼 / 我手疼 — no 有!)","身体不适直接说“人＋部位＋疼”（我头疼、我手疼）","Đau bộ phận cơ thể nói thẳng: Người + Bộ phận + 疼 (我头疼)","体の痛みは「人＋部位＋疼」（我头疼・我手疼）"],"w":["ทำได้และสั้นตรงใจเหมือนภาษาไทย ('ฉันหัวปวด' → ปวดหัว) และภาษาญี่ปุ่น ('私は頭が痛い') โดยไม่ต้องใส่ 有 หรือ 的","Works super cleanly without 有 or 的: 我 (topic) + 头疼 (head hurts).","“我头疼、我眼睛疼”是汉语最地道的主谓谓语句，不加“有”。","Đúng và cực tự nhiên giống tiếng Việt ('tôi đau đầu'), không cần 有 hay 的.","日本語の「私は頭が痛い」と同じ語順で「有」も「的」も要らない。"],"ref":"HSK 3.0 g3-2-055"},{"ok":true,"zh":"这家饭馆菜很好吃，人也很多。","fix":"","py":"Zhè jiā fànguǎn cài hěn hǎochī, rén yě hěn duō.","tr":["ร้านอาหารร้านนี้กับข้าวอร่อยมาก คนก็เยอะมากด้วย","At this restaurant the food is delicious, and there are lots of people too.","Quán ăn này đồ ăn rất ngon, người cũng rất đông.","このレストランは料理がおいしくて、人もとても多いです。"],"h":["ยกสถานที่/หัวข้อใหญ่ขึ้นก่อน แล้วบรรยายแง่มุมย่อย ๆ ต่อท้าย","State the place/topic upfront, then describe its aspects with mini S-P clauses","以处所／事物为大主语，用多个主谓短语分别评价","Đặt địa điểm/chủ đề lớn lên đầu rồi nhận xét các khía cạnh","場所や物を大主語にし、小主語＋述語で側面を次々描写する"],"w":["ทำได้และลื่นไหลมาก เพราะยก 这家饭馆 ไว้ต้นประโยคครั้งเดียว แล้วบรรยายต่อได้ทั้ง 菜很好吃 และ 人也很多 โดยไม่ต้องซ้ำคำว่า 这家饭馆","Works smoothly: introduce 这家饭馆 once upfront, then comment on both its food (菜很好吃) and crowd (人也很多).","大主语“这家饭馆”统领后面两个小主谓短语，行文流畅紧凑。","Đúng và rất mượt: nêu 这家饭馆 một lần rồi nhận xét cả 菜 và 人.","大主語「这家饭馆」を1回出せば「菜很好吃」「人也很多」とスムーズに続けられる。"],"ref":"HSK 3.0 g3-2-055"},{"ok":false,"zh":"他有个子很高。","fix":"他个子很高。","py":"Tā gèzi hěn gāo.","tr":["เขารูปร่างสูงมาก","He is very tall in build.","Anh ấy dáng rất cao.","彼は背がとても高いです。"],"h":["ห้ามใส่ 有 แทรกกลางในประโยค 主谓谓语句 (他有个子很高 ผิด!)","NEVER insert 有 inside a topic-comment sentence (never 他有个子很高!)","主谓谓语句中间绝不能乱加“有”（他个子很高）","Không chèn 有 thừa vào câu vị ngữ chủ vị (không nói 他有个子很高)","主述述語文の間に「有」を入れない（他个子很高にする）"],"w":["ไม่ได้ เพราะในประโยค 他个子很高 ตัว 个子很高 ทำหน้าที่เป็นภาคแสดงอธิบาย 他 โดยตรง การใส่ 有 เข้าไปจะทำให้ประโยคซ้อนโครงสร้างผิดไวยากรณ์","Wrong because 个子很高 directly serves as the predicate for 他 — adding 有 breaks the sentence structure.","不行，“个子很高”直接作“他”的谓语，加“有”属于句式杂糅。","Không được vì 个子很高 tự làm vị ngữ cho 他 rồi; thêm 有 là sai cấu trúc.","「个子很高」が直接述語になるため、「有」を入れると文構造が壊れる。"],"ref":"HSK 3.0 g3-2-055"}],"ex":[["他个子很高。","Tā gèzi hěn gāo.","เขารูปร่างสูงมาก","He is very tall.","Anh ấy dáng rất cao.","彼は背がとても高いです。","个子很高"],["我今天头疼。","Wǒ jīntiān tóu téng.","วันนี้ฉันปวดหัว","I have a headache today.","Hôm nay tôi đau đầu.","今日頭が痛いです。","头疼"],["爷爷奶奶身体都很好。","Yéye nǎinai shēntǐ dōu hěn hǎo.","คุณปู่คุณย่าสุขภาพแข็งแรงดีทั้งคู่","Both Grandpa and Grandma are in good health.","Ông bà nội sức khỏe đều rất tốt.","祖父も祖母も体調がとても良いです。","身体都很好"],["这家饭馆菜很好吃。","Zhè jiā fànguǎn cài hěn hǎochī.","ร้านอาหารร้านนี้กับข้าวอร่อยมาก","The food at this restaurant is very delicious.","Quán ăn này đồ ăn rất ngon.","このレストランは料理がとてもおいしいです。","菜很好吃"],["我学习很忙，但是很快乐。","Wǒ xuéxí hěn máng, dànshì hěn kuàilè.","ฉันเรียนยุ่งมาก แต่ก็มีความสุขมาก","My studies are very busy, yet I'm very happy.","Tôi học hành rất bận nhưng rất vui vẻ.","勉強はとても忙しいですが、とても楽しいです。","学习很忙"]],"err":[["他有个子很高。","他个子很高。","ประโยค 主谓谓语句 ห้ามใส่ 有 คั่นกลาง (他个子很高)","Never insert 有 inside 他个子很高.","主谓谓语句不加“有”（他个子很高）。","Câu vị ngữ chủ vị không thêm 有 (他个子很高).","主述述語文の間に「有」は入れない（他个子很高）。"],["我有头疼。","我头疼。","'ปวดหัว' พูดตรง ๆ ว่า 我头疼 ไม่ใส่ 有 แบบภาษาอังกฤษ","Say 我头疼 directly — never add 有 like English 'have a headache'.","说“我头疼”，不加“有”。","Nói thẳng 我头疼, không thêm 有 kiểu tiếng Anh.","英語の have に釣られず「我头疼」と直接言う。"]],"rel":["g3-1-031","g3-2-045","g3-1-043"]},"g3-2-056":{"t":["ประโยคคำถามให้เลือก (选择问句): …还是…？ (A หรือ B?)","Choice questions (选择问句): A 还是 B？","句类·疑问句：用“还是”连接的选择问句","Câu hỏi lựa chọn (选择问句): A 还是 B？","選択疑問文（选择问句）：A 还是 B？"],"f":["主语 + 动词 + A + 还是 + B？（你喝茶还是喝咖啡？）","主语 + A + 还是 + B？（今天冷还是热？/ 你去还是他去？）"],"why":["选择问句 ใช้ **还是** ('หรือ') เชื่อมทางเลือกตั้งแต่ 2 ทางขึ้นไปในประโยคคำถามเพื่อให้ผู้ฟังเลือกตอบ 1 อย่าง (เช่น 你喝红茶还是绿茶？, 我们坐地铁还是打车？, 你今天去还是明天去？) · กฎเหล็ก 3 ข้อที่ออกสอบตลอด: (1) ห้ามเติม **吗** ท้ายประโยคคำถาม 还是 เด็ดขาด! (你喝茶还是咖啡吗？ ผิด 100%!) (2) ห้ามตอบรับด้วย 是 หรือ 不是 เฉย ๆ — ต้องเลือกตอบทางเลือกใดทางเลือกหนึ่ง (เช่น 喝红茶 หรือ 坐地铁) (3) คำว่า 'หรือ' ในประโยคคำถามใช้ **还是** เท่านั้น (ส่วนบอกเล่าใช้ 或者 ใน HSK 3)","Choice questions use **还是** ('or') to present two or more options for the listener to choose between: 你喝红茶还是绿茶？, 我们坐地铁还是打车？ · Three iron rules: (1) NEVER add **吗** at the end (你喝茶还是咖啡吗？ is 100% wrong!). (2) Do NOT answer 'yes/no' — pick an option (喝红茶 / 坐地铁). (3) Use **还是** for 'or' in questions (statements use 或者 in HSK 3).","选择问句用“还是”连接两个或多个供选项目，让对方择一回答（你喝红茶还是绿茶？坐地铁还是打车？）。 · 三条铁律：（1）句末绝不能加“吗”（可加“呢”缓和语气）；（2）回答须选其中一项，不能用“是／不是”回答；（3）疑问句的“或”只能用“还是”。","Câu hỏi lựa chọn dùng **还是** ('hay là') nối 2 phương án để người nghe chọn 1 (你喝红茶还是绿茶？). · 3 quy tắc thép: (1) KHÔNG thêm 吗 ở cuối câu (có thể thêm 呢); (2) Trả lời bằng cách chọn 1 phương án, không đáp 是/不是; (3) 'Hay/hoặc' trong câu hỏi luôn dùng 还是.","選択疑問文は「还是」（それとも）で2つ以上の選択肢を並べ、どちらかを選んで答えてもらう文（你喝红茶还是绿茶？）。 · 3大鉄則：（1）文末に「吗」は絶対不可（「呢」は可）。（2）返答は選択肢の1つを答える。（3）疑問文の「または」は必ず「还是」。"],"use":[{"ok":true,"zh":"你喝咖啡还是喝奶茶？","fix":"","py":"Nǐ hē kāfēi háishi hē nǎichá?","tr":["คุณดื่มกาแฟหรือดื่มชานม","Would you like coffee or milk tea?","Bạn uống cà phê hay uống trà sữa?","コーヒーを飲みますか、それともミルクティーを飲みますか。"],"h":["เชื่อม 2 ทางเลือกในคำถามด้วย 还是 (ไม่ใส่ 吗)","Join two choices in a question with 还是 (NO 吗)","“A＋还是＋B？”构成选择问句，句末不加“吗”","Nối 2 lựa chọn bằng 还是 (KHÔNG thêm 吗)","2つの選択肢を「还是」でつなぐ（「吗」不要）"],"w":["ทำได้ทั้งแบบซ้ำกริยา (喝咖啡还是喝奶茶？) และละกริยาตัวหลัง (喝咖啡还是奶茶？) โดยลงท้ายด้วยเครื่องหมายคำถาม ？ เฉย ๆ","Works both with the verb repeated (喝咖啡还是喝奶茶？) or omitted in the second half (喝咖啡还是奶茶？), with no 吗.","后项动词“喝”可留可省，句末直接用问号不加“吗”。","Đúng cả khi lặp động từ 喝 lẫn khi lược gọn (喝咖啡还是奶茶？).","後ろの動詞「喝」は繰り返しても省いても自然。文末に「吗」は付けない。"],"ref":"HSK 3.0 g3-2-056"},{"ok":true,"zh":"我们今天去还是明天去？","fix":"","py":"Wǒmen jīntiān qù háishi míngtiān qù?","tr":["พวกเราไปวันนี้หรือไปพรุ่งนี้","Are we going today or tomorrow?","Chúng ta đi hôm nay hay ngày mai đi?","今日行きますか、それとも明日行きますか。"],"h":["เปรียบเทียบทางเลือกได้ทั้งเวลา สถานที่ วิธีการ หรือบุคคล","Offer choices of time, place, method, or person with 还是","可对时间、方式、人物等任何成分提问选择","Hỏi chọn được cả thời gian, phương tiện, địa điểm, người","時間・場所・手段・人など何でも「还是」で選択質問できる"],"w":["ทำได้เพราะวาง 还是 คั่นระหว่าง 2 ทางเลือกเวลา (今天去 vs 明天去) ชัดเจน","Works cleanly by placing 还是 right between the two time options (今天去 vs 明天去).","“今天去”与“明天去”对称并列，清楚询问时间选择。","Đúng vì 还是 nối rõ hai phương án thời gian 今天去 và 明天去.","「今天去」と「明天去」を対称に並べて分かりやすく尋ねている。"],"ref":"HSK 3.0 g3-2-056"},{"ok":false,"zh":"你坐地铁还是打车吗？","fix":"你坐地铁还是打车？","py":"Nǐ zuò dìtiě háishi dǎchē?","tr":["คุณนั่งรถไฟใต้ดินหรือเรียกแท็กซี่","Are you taking the subway or a taxi?","Bạn đi tàu điện ngầm hay bắt taxi?","地下鉄で行きますか、それともタクシーにしますか。"],"h":["ห้ามเติม 吗 ท้ายประโยคคำถาม 还是 เด็ดขาด!","NEVER put 吗 at the end of a 还是 choice question!","选择问句末尾绝不能加“吗”","Tuyệt đối không thêm 吗 cuối câu hỏi 还是!","「还是」の選択疑問文の文末に「吗」は絶対不可"],"w":["ไม่ได้ เพราะ 吗 ใช้ถามแค่ 'ใช่/ไม่ใช่' เท่านั้น ส่วน 还是 ให้เลือก A หรือ B จึงชนกันตรง ๆ (ถ้าอยากให้น้ำเสียงนุ่มลงใช้ 呢 แทนได้: 你坐地铁还是打车呢？)","Wrong because 吗 is strictly yes/no while 还是 asks to pick A or B (if you want a softer particle, use 呢 instead).","不行，“吗”只用于是非问，绝不能加在“还是”句末（可加“呢”）。","Không được vì 吗 là câu hỏi có/không, xung đột với 还是 (có thể dùng 呢 cho nhẹ nhàng).","「吗」は諾否専用なので選択の「还是」とは併用不可（和らげるなら「呢」）。"],"ref":"HSK 3.0 g3-2-056 · g3-1-047"}],"ex":[["你喝咖啡还是喝奶茶？","Nǐ hē kāfēi háishi hē nǎichá?","คุณดื่มกาแฟหรือดื่มชานม","Do you drink coffee or milk tea?","Bạn uống cà phê hay uống trà sữa?","コーヒーとミルクティーどちらを飲みますか。","还是"],["我们坐地铁还是打车？","Wǒmen zuò dìtiě háishi dǎchē?","พวกเรานั่งรถไฟใต้ดินหรือเรียกแท็กซี่","Should we take the subway or a taxi?","Chúng ta đi tàu điện ngầm hay bắt taxi?","地下鉄で行きますか、タクシーにしますか。","还是"],["你今天去还是明天去？","Nǐ jīntiān qù háishi míngtiān qù?","คุณไปวันนี้หรือไปพรุ่งนี้","Are you going today or tomorrow?","Bạn đi hôm nay hay ngày mai?","今日行きますか、明日行きますか。","还是"],["这件衣服是红色的还是黑色的？","Zhè jiàn yīfu shì hóngsè de háishi hēisè de?","เสื้อตัวนี้สีแดงหรือสีดำ","Is this shirt red or black?","Chiếc áo này màu đỏ hay màu đen?","この服は赤ですか、黒ですか。","还是"],["你喜欢打篮球还是踢足球？","Nǐ xǐhuan dǎ lánqiú háishi tī zúqiú?","คุณชอบเล่นบาสเกตบอลหรือเตะฟุตบอล","Do you like playing basketball or soccer?","Bạn thích chơi bóng rổ hay đá bóng?","バスケとサッカーどちらが好きですか。","还是"]],"err":[["你坐地铁还是打车吗？","你坐地铁还是打车？","ประโยคคำถามให้เลือก (还是) ห้ามเติม 吗 ท้ายประโยค","Never add 吗 to a 还是 choice question.","“还是”选择问句句末绝不能加“吗”。","Câu hỏi lựa chọn 还是 không thêm 吗.","選択疑問文「还是」の文末に「吗」は付けない。"]],"rel":["g3-2-068","g3-2-042","g3-1-047"]},"g3-2-057":{"t":["ประโยคคำสั่งห้ามด้วย 别 (用“别”的祈使句): อย่า…! / พอได้แล้ว!","Prohibitive imperatives with 别 (用“别”的祈使句)","句类·祈使句：用“别”的祈使句","Câu cầu khiến cấm đoán với 别 (用“别”的祈使句)","「别」の禁止命令文（用“别”的祈使句）"],"f":["（你 / 你们）+ 别 + 动词 / 形容词（+ 了）！（别跑！/ 别太累了！）"],"why":["ประโยคคำสั่งห้ามด้วย 别 เป็นรูปแบบประโยค祈使句ที่ใช้บ่อยที่สุดในชีวิตประจำวัน แบ่งเป็น 2 น้ำเสียงหลัก: (1) ห้ามไม่ให้เริ่มทำ: 别 + กริยา (别说话！= อย่าพูด!, 别跑！= อย่าวิ่ง!, 别忘了！= อย่าลืม!) (2) สั่งให้หยุดสิ่งที่กำลังทำอยู่ หรือปลอบโยนไม่ให้ทำเกินไป: 别 + กริยา/คุณศัพท์ + 了 (别看手机了！= เลิกดูมือถือได้แล้ว!, 别太累了！= อย่าหักโหมจนเหนื่อยเกินไปนะ!) · ข้อควรระวัง: (1) ห้ามใช้ 别 กับกริยาสภาวะที่สั่งห้ามไม่ได้ (เช่น 别是…, 别认识…) (2) หากต้องการลดความแข็งให้สุภาพขึ้น เติม 请 ข้างหน้า หรือ 吧 ข้างหลังได้ (请别说话 / 别跑了吧)","Prohibitive imperatives with 别 are everyday spoken commands in two moods: (1) Stop before starting: 别 + Verb (别说话!, 别跑!, 别忘了!); (2) Stop what's already happening / caring advice: 别 + Verb/Adj + 了 (别看手机了!, 别太累了!). · Cautions: (1) Add 请 before or 吧 after to soften the tone (请别说话 / 别去了吧). (2) Never use 别 with non-controllable stative verbs or with trailing 吗.","“别”字祈使句是口语最常用的禁止／劝阻句式：（1）阻止未发生动作：“别＋动词”（别说话！别忘了！）；（2）制止正在进行的动作或关切劝慰：“别＋动词／形容词＋了”（别看手机了！别太累了！）。 · 注意：前加“请”或后加“吧”可使语气更委婉；不可加“吗”。","Câu cầu khiến với 别 rất phổ biến trong khẩu ngữ: (1) Ngăn chưa làm: 别 + động từ (别说话!, 别忘了!); (2) Bảo dừng việc đang làm / khuyên nhẹ: 别 + động/tính từ + 了 (别看手机了!, 别太累了!). · Lưu ý: thêm 请 trước hoặc 吧 sau để dịu giọng; không thêm 吗.","「别」の禁止命令文は日常会話で最もよく使う：（1）未然の禁止「别＋動詞」（别说话！・别忘了！）、（2）進行中の制止や気遣い「别＋動詞／形容詞＋了」（别看手机了！・别太累了！）。 · 「请」や「吧」で口調を和らげられる。「吗」は不可。"],"use":[{"ok":true,"zh":"你工作一天了，别太累了！","fix":"","py":"Nǐ gōngzuò yī tiān le, bié tài lèi le!","tr":["คุณทำงานมาทั้งวันแล้ว อย่าหักโหมจนเหนื่อยเกินไปนะ!","You've worked all day — don't wear yourself out!","Bạn làm việc cả ngày rồi, đừng quá mệt nhé!","一日中働いたんだから、あまり無理しないでね！"],"h":["เตือน/ปลอบด้วยความห่วงใย: 别 + 太 + คุณศัพท์ + 了！","Caring advice: 别 + 太 + Adjective + 了!","关切劝慰常用“别太＋形容词＋了！”","Khuyên nhủ quan tâm dùng 别 + 太 + tính từ + 了!","気遣いの言葉：「别太＋形容詞＋了！」"],"w":["ทำได้และอบอุ่นมาก เพราะ 别 ไม่ใช่คำดุเสมอไป เมื่อจับคู่กับ 太…了 จะเป็นการเตือนด้วยความห่วงใย (别太累了, 别太晚了)","Works warmly because 别 + 太…了 expresses genuine care rather than harsh scolding.","“别太累了、别太晚了”是表达关心的地道口语句式。","Đúng và rất ấm áp vì 别 + 太…了 thể hiện sự quan tâm chân thành.","「别太累了」「别太晚了」は相手を気遣う温かい口語表現。"],"ref":"HSK 3.0 g3-2-057"},{"ok":true,"zh":"请别在这里说话。","fix":"","py":"Qǐng bié zài zhèlǐ shuōhuà.","tr":["กรุณาอย่าพูดคุยตรงนี้ครับ/ค่ะ","Please do not talk here.","Xin đừng nói chuyện ở đây.","ここではお話しにならないでください。"],"h":["เติม 请 หน้า 别 เพื่อทำให้คำสั่งห้ามสุภาพขึ้นมาก","Add 请 before 别 to make a prohibition polite","“请别……”使禁止祈使句礼貌得体","Thêm 请 trước 别 giúp câu cấm đoán lịch sự hơn","「别」の前に「请」を付けると丁寧な禁止になる"],"w":["ทำได้และสุภาพเหมาะสำหรับสถานที่สาธารณะหรือพูดกับผู้ใหญ่ (เช่น 请别在这里说话 / 请别忘了)","Works politely for public spaces or elders: 请 softens 别 immediately.","在公共场所或对长辈、陌生人说“请别……”礼貌得体。","Đúng và lịch sự khi nhắc nhở ở nơi công cộng hoặc với người lớn.","公共の場や目上の人への注意には「请别…」が丁寧で角が立たない。"],"ref":"HSK 3.0 g3-2-057"},{"ok":false,"zh":"别你去吧！","fix":"你别去吧！","py":"Nǐ bié qù ba!","tr":["คุณอย่าไปเลยนะ!","Better not go!","Bạn đừng đi nhé!","行かないでおきなよ！"],"h":["ถ้าใส่ประธาน (你 / 大家) ต้องวางประธานไว้ 'หน้า 别' เสมอ!","When including a subject (你 / 大家), ALWAYS put it BEFORE 别!","出现主语时，主语必须在“别”前面（你别去／大家别跑）","Nếu có chủ ngữ (你 / 大家) bắt buộc đặt TRƯỚC 别!","主語（你・大家）を入れるときは必ず「别」の前に置く"],"w":["ไม่ได้ เพราะ 别 เป็นคำวิเศษณ์ปฏิเสธ ต้องวางหลังประธานและหน้ากริยาเสมอ (你别去, 大家别说话 — ห้ามพูด 别你去!)","Wrong because 别 is an adverb that sits AFTER the subject and BEFORE the verb (你别去, never 别你去).","不行，“别”是副词，主语必须放在“别”前面：你别去！","Không được vì 别 là phó từ luôn đứng SAU chủ ngữ: 你别去!","「别」は副詞なので主語の後ろ・動詞の前に置く（你别去！）。"],"ref":"HSK 3.0 g3-2-057"}],"ex":[["你别跑，慢慢走！","Nǐ bié pǎo, mànmàn zǒu!","คุณอย่าวิ่ง ค่อย ๆ เดินนะ!","Don't run — walk slowly!","Bạn đừng chạy, đi từ từ thôi!","走らないで、ゆっくり歩いて！","别"],["请别在这里说话。","Qǐng bié zài zhèlǐ shuōhuà.","กรุณาอย่าพูดคุยตรงนี้","Please don't talk here.","Xin đừng nói chuyện ở đây.","ここで話さないでください。","请别"],["别忘了买门票。","Bié wàngle mǎi ménpiào.","อย่าลืมซื้อบัตรเข้าชมนะ","Don't forget to buy admission tickets.","Đừng quên mua vé vào cửa nhé.","入場券を買うのを忘れないで。","别"],["你工作一天了，别太累了！","Nǐ gōngzuò yī tiān le, bié tài lèi le!","คุณทำงานมาทั้งวันแล้ว อย่าเหนื่อยเกินไปนะ!","You've worked all day; don't get too tired!","Bạn làm việc cả ngày rồi, đừng quá mệt nhé!","一日働いたんだから無理しないでね！","别太"],["别上网了，快睡觉吧！","Bié shàngwǎng le, kuài shuìjiào ba!","เลิกเล่นเน็ตได้แล้ว รีบนอนเถอะ!","Stop surfing the internet and go to sleep!","Đừng lướt mạng nữa, mau ngủ đi!","もうネットはやめて早く寝なさい！","别"]],"err":[["别你去吧！","你别去吧！","ประธาน (你 / 大家) ต้องอยู่หน้า 别 เสมอ","Always place the subject BEFORE 别 (你别去吧).","主语必须在“别”前面（你别去）。","Chủ ngữ luôn đặt TRƯỚC 别 (你别去).","主語は必ず「别」の前に置く（你别去）。"]],"rel":["g3-2-018","g3-1-050","g3-2-042"]},"g3-2-058":{"t":["ประโยค “是” 2 (是字句2): อธิบายลักษณะ / คุณสมบัติ / สี / ประเภท","是 sentences 2 (是字句2): describing features & categories","特殊句式·“是”字句2：表示说明或特征","Câu chữ 是 2 (是字句2): giải thích đặc trưng / tính chất","「是」構文2（是字句2）：説明・特徴"],"f":["主语 + 是 + 形容词 / 名词 + 的（这件衣服是红色的 / 那个手机是新的）","主语 + 是 + 说明性短语（他是个高个子 / 这杯是绿茶）"],"why":["ใน HSK 1 เราเรียนกฎว่า 'ห้ามวาง 是 หน้าคุณศัพท์เดี่ยว ๆ' (ห้ามพูด 衣服是红!) แต่ใน HSK 2 มีข้อยกเว้นสุดสำคัญ: เมื่อเราเติม **的** ปิดท้ายหลังคุณศัพท์ (เช่น 红色的, 新的, 真的, 坏的) คำคุณศัพท์นั้นจะกลายเป็นวลีนามบอก 'ประเภทหรือคุณสมบัติจำแนก' จึงใช้คู่กับ **是** ได้อย่างถูกต้อง! · เช่น 这件衣服是红色的 (เสื้อตัวนี้เป็นสีแดง), 这个手机是新的 (มือถือเครื่องนี้เป็นของใหม่), 这杯是热的 (แก้วนี้เป็นแบบร้อน) · ข้อควรระวังเด็ดขาด: ถ้าใช้ 是 กับคุณศัพท์บอกคุณสมบัติ ต้องมี **的** ปิดท้ายเสมอ! (这件衣服是红色的 ✓ — ห้ามตัด 的 เหลือ 这件衣服是红色 หรือ 这件衣服是新 ✗!)","In HSK 1 you learned NEVER to put 是 before a bare adjective — now HSK 2 shows the exact exception: add **的** after the adjective to classify a feature/type! · Examples: 这件衣服是红色的 ('This shirt is red'), 这个手机是新的 ('This phone is new'), 这杯是热的 ('This cup is a hot one'). · Iron rule: when using 是 with a feature adjective, NEVER drop the final **的** (这个手机是新的 ✓, NEVER 这个手机是新 ✗!).","HSK 2 的“是”字句2用于说明事物的特征、颜色、质地或类别，常见结构为“主语＋是＋形容词／颜色＋的”：这件衣服是红色的、这个手机是新的、这杯是热的。 · 铁律：用“是”引出性质特征时，末尾必须带“的”（不说“这个手机是新”）。","Câu chữ 是 2 diễn tả đặc trưng, màu sắc, phân loại bằng mẫu 'Chủ ngữ + 是 + Tính từ/Màu + 的': 这件衣服是红色的 (áo này màu đỏ), 这个手机是新的 (điện thoại này là đồ mới). · Quy tắc thép: BẮT BUỘC có 的 ở cuối (không nói 这个手机是新!).","「是」構文2は物の特徴・色・分類を説明する用法で、「主語＋是＋形容詞／色＋的」の形を取る：这件衣服是红色的、这个手机是新的、这杯是热的。 · 鉄則：「是」で特徴を述べるときは文末の「的」を絶対に省けない（这个手机是新×）。"],"use":[{"ok":true,"zh":"这个手机是新的，不是坏的。","fix":"","py":"Zhège shǒujī shì xīn de, bù shì huài de.","tr":["โทรศัพท์เครื่องนี้เป็นของใหม่ ไม่ใช่ของเสีย","This phone is new, not broken.","Chiếc điện thoại này là đồ mới, không phải đồ hỏng.","このスマホは新品で、壊れたものではありません。"],"h":["จำแนกคุณสมบัติ/สภาพด้วย 是 + คุณศัพท์ + 的 (และปฏิเสธด้วย 不是…的)","Classify features/condition with 是 + Adj + 的 (negate with 不是…的)","说明性质特征用“是……的”，否定用“不是……的”","Phân loại đặc trưng dùng 是 + tính từ + 的 (phủ định 不是…的)","特徴・分類は「是＋形容詞＋的」（否定は「不是…的」）"],"w":["ทำได้เพราะ 新的 และ 坏的 มี 的 ปิดท้ายทำให้กลายเป็นกลุ่มประเภท ('ของใหม่ / ของเสีย') จึงใช้คู่กับ 是 / 不是 ได้ถูกต้อง 100%","Works 100% cleanly because 的 turns 新 and 坏 into categories ('a new one / a broken one') that pair with 是 / 不是.","“新的、坏的”带“的”转为名词性分类特征，与“是／不是”搭配完全规范。","Đúng 100% vì có 的 biến 新 và 坏 thành phân loại đặc trưng đi chuẩn với 是 / 不是.","「的」が付いて名詞的な分類になるため「是／不是」と自然に結びつく。"],"ref":"HSK 3.0 g3-2-058 · g3-2-035"},{"ok":true,"zh":"我的裤子是黑色的。","fix":"","py":"Wǒ de kùzi shì hēisè de.","tr":["กางเกงของฉันเป็นสีดำ","My pants are black.","Quần của tôi màu đen.","私のズボンは黒色です。"],"h":["บอกสีของสิ่งของใช้ 是 + 颜色 + 的 (白色的 / 红色的 / 绿色的)","State colors with 是 + Color + 的 (白色的 / 红色的 / 绿色的)","说明颜色常用“是＋颜色＋的”（白色的、黑色的）","Nói màu sắc dùng 是 + Màu + 的 (白色的, 黑色的)","色の説明は「是＋色＋的」（白色的・黑色的）"],"w":["ทำได้และเป็นวิธีบอกสีที่เป็นธรรมชาติที่สุดในภาษาจีน (เช่น 这朵花是白色的 → 这花是白色的 / 她的眼睛是黑色的)","Works as the most natural way to state colors in Chinese (黑色的, 白色的, 红色的, 绿色的).","说明事物颜色最地道的表达是“是＋红色／黑色／白色／绿色的”。","Đúng và là cách nói màu sắc tự nhiên nhất trong tiếng Trung.","色を述べるときは「是＋〜色的」が最も自然な定番表現。"],"ref":"HSK 3.0 g3-2-058"},{"ok":false,"zh":"这个手机是新。","fix":"这个手机是新的。","py":"Zhège shǒujī shì xīn de.","tr":["โทรศัพท์เครื่องนี้เป็นของใหม่","This phone is new.","Chiếc điện thoại này là đồ mới.","このスマホは新品です。"],"h":["ห้ามตัด 的 ทิ้งเมื่อใช้ 是 + คุณศัพท์บอกคุณสมบัติ!","NEVER drop 的 when using 是 + a feature adjective!","用“是”说明特征时绝不能漏掉“的”（是新×→是新的○）","Không bao giờ bỏ 的 khi dùng 是 + tính từ đặc trưng!","「是＋形容詞」で特徴を述べるとき「的」は絶対に落とせない"],"w":["ไม่ได้ เพราะถ้าไม่มี 的 จะกลายเป็นการวาง 是 หน้าคุณศัพท์ตรง ๆ ซึ่งผิดหลักภาษาจีน ต้องเลือกอย่างใดอย่างหนึ่ง: 这个手机是新的 (เน้นคุณสมบัติ/ประเภท) หรือ 这个手机很新 (บรรยายทั่วไป)","Wrong because without 的, 是 clashes directly with bare adjective 新 — choose either 这个手机是新的 OR 这个手机很新.","不行，不加“的”就犯了“是＋光杆形容词”的错误；须说“是新的”或“很新”。","Không được vì thiếu 的 thành lỗi 是 + tính từ trần; chọn 是新的 hoặc 很新.","「的」がないと「是＋裸の形容詞」の誤用になる。「是新的」か「很新」にする。"],"ref":"HSK 3.0 g3-2-058 · g3-1-043"}],"ex":[["这件衣服是红色的。","Zhè jiàn yīfu shì hóngsè de.","เสื้อตัวนี้เป็นสีแดง","This shirt is red.","Chiếc áo này màu đỏ.","この服は赤色です。","是红色的"],["我的裤子是黑色的。","Wǒ de kùzi shì hēisè de.","กางเกงของฉันเป็นสีดำ","My pants are black.","Quần của tôi màu đen.","私のズボンは黒いです。","是黑色的"],["这个手机是新的。","Zhège shǒujī shì xīn de.","โทรศัพท์เครื่องนี้เป็นของใหม่","This phone is new.","Chiếc điện thoại này là đồ mới.","このスマホは新品です。","是新的"],["这杯茶是热的，那杯是冷的。","Zhè bēi chá shì rè de, nà bēi shì lěng de.","ชาแก้วนี้ร้อน แก้วนั้นเย็น","This cup of tea is hot; that cup is cold.","Cốc trà này nóng, cốc kia lạnh.","このお茶は熱くて、あちらは冷たいです。","是热的"],["他不是坏人，他是好人。","Tā bù shì huàirén, tā shì hǎorén.","เขาไม่ใช่คนไม่ดี เขาเป็นคนดี","He is not a bad person; he is a good person.","Anh ấy không phải người xấu, anh ấy là người tốt.","彼は悪い人ではなく、いい人です。","是"]],"err":[["这个手机是新。","这个手机是新的。","ใช้ 是 บอกคุณสมบัติด้วยคุณศัพท์ ต้องมี 的 ปิดท้ายเสมอ (是新的)","Always close 是 + feature adjective with 的 (是新的).","“是”说明特征须加“的”（是新的）。","Dùng 是 nêu đặc trưng luôn phải có 的 (是新的).","「是」で特徴を述べるときは必ず「的」を付ける（是新的）。"]],"rel":["g3-1-052","g3-2-035","g3-1-043"]},"g3-2-059":{"t":["ประโยค “有” 2 (有字句2): ถึงระดับ / มากถึง / ยาวนานถึง","有 sentences 2 (有字句2): reaching an amount or extent","特殊句式·“有”字句2：表示达到","Câu chữ 有 2 (有字句2): đạt đến mức / khoảng","「有」構文2（有字句2）：到達・程度（〜はある）"],"f":["主语 + 有 + 数量 / 程度（我学汉语有两年了 / 这条路有这么长）","疑问：主语 + 有 + 多 + 形容词？（你有多高？/ 学校离这儿有多远？）"],"why":["นอกจากแปลว่า 'มี/เป็นเจ้าของ' (HSK 1) แล้ว ใน HSK 2 กริยา **有** ยังแปลว่า 'มากถึง / นานถึง / สูงถึง / ไกลถึง' (表示达到) เพื่อประมาณหรือยืนยันระดับจำนวนที่ไปถึง · ตัวอย่างที่ใช้บ่อยมาก: (1) เวลาถึงขั้นนั้นแล้ว: 我学汉语有两年了 (ฉันเรียนภาษาจีนมาถึงสองปีแล้ว), 我等你有十分钟了 (ฉันรอคุณมาตั้งสิบนาทีแล้ว) (2) จำนวน/อายุถึงระดับ: 我们班有三十多个人, 爷爷有八十岁了 (3) ถามระดับด้วย **有多 + คุณศัพท์**: 你有多高？ (คุณสูงเท่าไร?), 机场离这儿有多远？ (สนามบินอยู่ไกลแค่ไหน?) · ข้อควรระวัง: ปฏิเสธว่า 'ไม่ถึงระดับนั้น' ใช้ **没有** (我学汉语没有两年 = ยังไม่ถึงสองปี, 没有那么远 = ไม่ได้ไกลขนาดนั้น)","Beyond ownership (HSK 1), HSK 2 **有** means 'reach / measure up to / be as much as' for time, quantity, age, or extent! · Common uses: (1) Duration reached: 我学汉语有两年了 ('It's been two years since I started Chinese'); (2) Age/number reached: 爷爷有八十岁了 ('Grandpa is already 80'); (3) Asking extent with **有多 + Adj**: 你有多高？ ('How tall are you?'), 机场离这儿有多远？ ('How far is the airport?'). · Caution: negate with **没有** (没有两年 'not even two years').","“有”字句2表示数量、时间、年龄或程度达到某一标准或估计值：我学汉语有两年了、爷爷有八十岁了。 · 询问程度常用“有多＋形容词”（你有多高？机场离这儿有多远？）。 · 否定“未达到”用“没有”（没有两年、没有那么远）。","Câu chữ 有 2 diễn tả số lượng, thời gian, tuổi tác hoặc mức độ ĐẠT ĐẾN ngưỡng nào đó: 我学汉语有两年了 (học tiếng Trung được 2 năm rồi), 爷爷有八十岁了. · Hỏi mức độ dùng **有多 + tính từ** (你有多高？ / 有多远？). · Phủ định dùng 没有.","「有」構文2は数量・期間・年齢・程度が「ある水準に達している（〜はある）」ことを表す：我学汉语有两年了、爷爷有八十岁了。 · 程度の質問は「有多＋形容詞」（你有多高？・有多远？）。 · 未到達の否定は「没有」。"],"use":[{"ok":true,"zh":"机场离这儿有多远？","fix":"","py":"Jīchǎng lí zhèr yǒu duō yuǎn?","tr":["สนามบินอยู่ห่างจากที่นี่ไกลแค่ไหน","How far is the airport from here?","Sân bay cách đây bao xa?","空港はここからどのくらい遠いですか。"],"h":["ถามความสูง/ระยะทาง/ความยาว ใช้ 有多 + 高 / 远 / 长 / 大？","Ask height, distance, length, or size with 有多 + 高 / 远 / 长 / 大？","询问高度、距离、长度常用“有多＋高／远／长／大？”","Hỏi chiều cao/khoảng cách/độ dài dùng 有多 + 高 / 远 / 长 / 大？","高さ・距離・長さを尋ねるときは「有多＋高／远／长／大？」"],"w":["ทำได้และเป็นคำถามมาตรฐานมาก โดยเลือกคุณศัพท์ฝั่ง 'มาก/บวก' (高, 远, 长, 大) ไม่ใช้ฝั่งน้อย (ไม่ถาม 你有多小？ / 有多近？)","Works cleanly as the standard question form — always choose the positive-pole adjective (高, 远, 长, 大, never 有多近？).","提问程度须用积极维度的形容词（多高、多远、多长、多大），不用“多近、多短”。","Đúng chuẩn: luôn dùng tính từ chiều dương (高, 远, 长, 大), không hỏi 有多近.","程度を尋ねるときはプラス極の形容詞（高・远・长・大）を使う（「有多近」とは言わない）。"],"ref":"HSK 3.0 g3-2-059 · g3-2-014"},{"ok":true,"zh":"我学汉语有两年了。","fix":"","py":"Wǒ xué Hànyǔ yǒu liǎng nián le.","tr":["ฉันเรียนภาษาจีนมาได้สองปีแล้ว","I have been studying Chinese for two years now.","Tôi học tiếng Trung được hai năm rồi.","中国語を勉強してもう2年になります。"],"h":["บอกว่าระยะเวลา/อายุ/จำนวนถึงจุดนั้นแล้ว ใช้ ประธาน + 有 + จำนวน + 了","State a reached duration/age/amount with Subject + 有 + Amount + 了","表示时长或年龄达到某数用“……有＋数量＋了”","Chỉ thời gian/tuổi đạt mốc dùng …有 + số lượng + 了","期間・年齢が達したことを「…有＋数量＋了」で表す"],"w":["ทำได้และเน้นตัวเลข 两年 ชัดเจน (ปฏิเสธว่ายังไม่ถึงสองปีพูดว่า 我学汉语没有两年)","Works smoothly to highlight reaching 两年 (negate 'not yet two years' with 没有两年).","“有两年了”突出时长已达到两年，否定说“没有两年”。","Đúng vì nhấn mạnh thời gian đã đạt mốc 2 năm (phủ định: 没有两年).","「2年という期間に達した」ことを強調できる（否定は「没有两年」）。"],"ref":"HSK 3.0 g3-2-059"},{"ok":false,"zh":"机场离这儿有多近？","fix":"机场离这儿有多远？","py":"Jīchǎng lí zhèr yǒu duō yuǎn?","tr":["สนามบินอยู่ห่างจากที่นี่ไกลแค่ไหน","How far is the airport from here?","Sân bay cách đây bao xa?","空港はここからどのくらい遠いですか。"],"h":["ถามระยะทางใช้ 有多远？ ไม่ใช้ 有多近？","Ask distance with 有多远？ — NOT 有多近？","问距离用“多远”，不用“多近”；问身高用“多高”","Hỏi khoảng cách dùng 有多远, không dùng 有多近","距離を尋ねるときは「有多近」でなく「有多远」"],"w":["ไม่ได้ตามความเคยชินของภาษาจีน เพราะการถามขนาด/ระยะทาง/อายุที่เป็นกลางต้องใช้ฝั่งบวกเสมอ: 多远 (ไกลแค่ไหน), 多高 (สูงเท่าไร), 多长 (ยาวเท่าไร), 多大 (อายุเท่าไร)","Unnatural/wrong: neutral dimension questions ALWAYS pick the positive pole: 多远, 多高, 多长, 多大.","不行，中性询问维度必须用正向形容词：多远、多高、多长、多大。","Không tự nhiên: câu hỏi trung tính luôn dùng chiều dương 多远, 多高, 多长, 多大.","中立的に規模を尋ねるときは常にプラス側（多远・多高・多长・多大）を使う。"],"ref":"HSK 3.0 g3-2-059"}],"ex":[["我学汉语有两年了。","Wǒ xué Hànyǔ yǒu liǎng nián le.","ฉันเรียนภาษาจีนมาได้สองปีแล้ว","I have been studying Chinese for two years.","Tôi học tiếng Trung được hai năm rồi.","中国語を勉強して2年になります。","有"],["爷爷今年有八十岁了。","Yéye jīnnián yǒu bāshí suì le.","ปีนี้คุณปู่อายุถึงแปดสิบปีแล้ว","Grandpa is already eighty years old this year.","Năm nay ông nội đã 80 tuổi rồi.","おじいちゃんは今年もう80歳です。","有"],["机场离这儿有多远？","Jīchǎng lí zhèr yǒu duō yuǎn?","สนามบินอยู่ห่างจากที่นี่ไกลแค่ไหน","How far is the airport from here?","Sân bay cách đây bao xa?","空港はここからどのくらい遠いですか。","有多远"],["我等你有二十分钟了。","Wǒ děng nǐ yǒu èrshí fēnzhōng le.","ฉันรอคุณมาถึงยี่สิบนาทีแล้ว","I've been waiting for you for twenty minutes.","Tôi đã đợi bạn được 20 phút rồi.","あなたをもう20分も待っています。","有"],["从家到学校没有那么远。","Cóng jiā dào xuéxiào méiyǒu nàme yuǎn.","จากบ้านไปโรงเรียนไม่ได้ไกลขนาดนั้น","It's not that far from home to school.","Từ nhà đến trường không xa đến thế đâu.","家から学校まではそんなに遠くありません。","没有"]],"err":[["机场离这儿有多近？","机场离这儿有多远？","ถามระยะทางใช้ฝั่งบวก 有多远？ ไม่ใช้ 有多近？","Ask neutral distance with positive-pole 有多远？, not 有多近？.","问距离用“有多远”，不用“有多近”。","Hỏi khoảng cách dùng 有多远, không dùng 有多近.","距離を尋ねるときは「有多近」でなく「有多远」。"]],"rel":["g3-1-053","g3-2-063","g3-2-014"]},"g3-2-060":{"t":["ประโยคแสดงการมีอยู่ 2 (存现句2): สถานที่ + กริยา + 着 + จำนวน + คำนาม","Existence sentences 2 (存现句2): Place + Verb + 着 + Noun","特殊句式·存现句2：处所+动词+着(+数量短语)+名词","Câu tồn hiện 2 (存现句2): Nơi chốn + Động từ + 着 + Danh từ","存在文2（存现句2）：場所＋動詞＋着（＋数量詞）＋名詞"],"f":["处所 + 动词 + 着 +（数量短语）+ 名词（门口站着一个人 / 教室里坐着很多学生）"],"why":["存现句2 ยกระดับจาก 'สถานที่ + 有 + คำนาม' (HSK 1) ให้เห็นภาพชัดเจนขึ้นมากด้วยการเปลี่ยน 有 เป็น **กริยา + 着** เพื่อบอกว่าคนหรือสิ่งของนั้น 'อยู่ในท่าทาง/สภาพแบบไหน' ณ สถานที่นั้น! · เช่น 门口站着一个人 (หน้าประตูมีคนยืนอยู่หนึ่งคน), 教室里坐着很多学生 (ในห้องเรียนมีนักเรียนนั่งอยู่เยอะมาก), 房间里开着电视 (ในห้องเปิดทีวีค้างอยู่) · กฎเหล็กเด็ดขาด 2 ข้อเหมือน 存现句1 เป๊ะ: (1) ห้ามใส่ **在** นำหน้าสถานที่ต้นประโยคเด็ดขาด! (门口站着一个人 ✓ — ห้ามพูด 在门口站着一个人 ✗!) (2) คำนามข้างหลังมักเป็นสิ่ง/คนที่ไม่เจาะจง (มีจำนวนหรือ 很多 นำหน้า: 一个人, 很多学生 — ไม่พูด 门口站着王老师! ถ้าเจาะจงชื่อคนให้พูด 王老师在门口站着)","Existence sentences 2 upgrade HSK 1 'Place + 有' into vivid imagery using **Place + Verb + 着 + Qty + Noun**, describing HOW someone/something exists in that spot: 门口站着一个人 ('A person is standing at the doorway'), 教室里坐着很多学生 ('Many students are sitting in the classroom'). · Two iron rules: (1) NEVER put **在** before the place subject (never 在门口站着一个人!). (2) The noun at the end should be INDEFINITE (一个人, 很多学生) — for a definite person like 王老师, start with 王老师在门口站着.","存现句2“处所＋动词＋着（＋数量短语）＋名词”不仅说明某处存在人或物，还形象描写其存在方式：门口站着一个人、教室里坐着很多学生、房间里开着电视。 · 两条铁律：（1）处所主语前绝不能加“在”（不说“在门口站着一个人”）；（2）句尾宾语通常为无定名词短语，有定人名须用“王老师在门口站着”。","Câu tồn hiện 2 ('Nơi chốn + Động từ + 着 + Số lượng + Danh từ') miêu tả sinh động trạng thái tồn tại ở một nơi: 门口站着一个人 (ở cửa có một người đang đứng), 教室里坐着很多学生. · 2 quy tắc thép: (1) TUYỆT ĐỐI không thêm 在 ở đầu câu; (2) Danh từ cuối câu thường bất định (一个人, 很多学生).","存在文2「場所＋動詞＋着（＋数量詞）＋名詞」はある場所に人・物がどんな姿勢・状態で存在するか生き生きと描く：门口站着一个人、教室里坐着很多学生、房间里开着电视。 · 鉄則2つ：（1）場所主語の前に「在」を付けない。（2）後ろの名詞は不特定（一个人など）。特定の人は「王老师在门口站着」にする。"],"use":[{"ok":true,"zh":"教室里坐着很多学生。","fix":"","py":"Jiàoshì lǐ zuòzhe hěn duō xuésheng.","tr":["ในห้องเรียนมีนักเรียนนั่งอยู่เยอะมาก","Many students are sitting in the classroom.","Trong phòng học có rất nhiều học sinh đang ngồi.","教室にはたくさんの学生が座っています。"],"h":["สถานที่ + กริยาท่าทาง (坐/站/开/拿) + 着 + จำนวน/很多 + คำนาม","Place + Posture/State verb (坐/站/开) + 着 + Qty + Indefinite Noun","“处所＋坐／站／开＋着＋无定名词”描写静态画面","Nơi chốn + 坐/站/开 + 着 + số lượng + danh từ bất định","「場所＋坐／站／开＋着＋不特定名詞」で情景を描く"],"w":["ทำได้และเห็นภาพชัดเจนกว่า 教室里有很多学生 เพราะ 坐着 บอกท่าทางว่าทุกคนกำลังนั่งอยู่เรียบร้อยในห้อง","Works vividly (richer than plain 有): 坐着 paints the scene of many students seated inside.","“坐着”比光用“有”更有画面感，且处所前不加“在”。","Đúng và sinh động hơn 有 rất nhiều vì 坐着 cho thấy tư thế đang ngồi.","「有」だけより「坐着」の方が教室に学生が座っている情景が鮮やかに浮かぶ。"],"ref":"HSK 3.0 g3-2-060 · g3-2-032"},{"ok":true,"zh":"王老师在门口站着呢。","fix":"","py":"Wáng lǎoshī zài ménkǒu zhànzhe ne.","tr":["อาจารย์หวังกำลังยืนอยู่ที่หน้าประตูเลย","Teacher Wang is standing at the doorway.","Thầy Vương đang đứng ở cửa kìa.","王先生が入口に立っていますよ。"],"h":["ถ้าเป็นคน/ของที่เจาะจงชื่อ (王老师) ให้ขึ้นต้นด้วยชื่อคน + 在 + สถานที่ + กริยา着","For a DEFINITE person (王老师), put the person first + 在 + Place + V着","有定人物（王老师）须作主语：王老师在门口站着","Đối tượng xác định (王老师) đặt đầu câu: 王老师在门口站着","特定の人（王老师）は主語にして「王老师在门口站着」"],"w":["ทำได้เพราะ 王老师 เป็นบุคคลที่เจาะจงชัดเจน จึงไม่เอาไปวางท้ายประโยค 存现句 แต่ยกขึ้นเป็นประธานต้นประโยคแทน","Works cleanly because definite 王老师 belongs in subject position rather than at the end of a 存现句.","“王老师”是有定对象，放句首作主语完全符合汉语信息结构。","Đúng vì 王老师 là người xác định nên phải làm chủ ngữ đầu câu.","特定の人物「王老师」は存在文の末尾ではなく主語に置くのが中国語の原則。"],"ref":"HSK 3.0 g3-2-060"},{"ok":false,"zh":"在门口站着一个人。","fix":"门口站着一个人。","py":"Ménkǒu zhànzhe yī ge rén.","tr":["หน้าประตูมีคนยืนอยู่หนึ่งคน","A person is standing at the doorway.","Ở cửa có một người đang đứng.","入口に人が1人立っています。"],"h":["ห้ามใส่ 在 นำหน้าสถานที่ต้นประโยค 存现句 เด็ดขาด!","NEVER put 在 before the place subject in an existence sentence!","存现句处所主语前绝不能加“在”（门口站着一个人）","Tuyệt đối không thêm 在 trước nơi chốn đầu câu tồn hiện!","存在文の場所主語の前に「在」を絶対に付けない"],"w":["ไม่ได้ เพราะถ้าใส่ 在 ข้างหน้า 门口 จะกลายเป็นวลีบุพบท ทำให้ประโยคขาดประธาน ต้องตัด 在 ออกเหลือ 门口站着一个人","Wrong because leading 在 turns 门口 into a prepositional phrase, leaving the sentence subjectless — drop 在.","不行，加“在”会使全句缺主语，必须去掉“在”：门口站着一个人。","Không được vì thêm 在 làm câu mất chủ ngữ; phải bỏ 在 → 门口站着一个人.","「在」を付けると主語が欠けてしまう。必ず「门口站着一个人」にする。"],"ref":"HSK 3.0 g3-2-060 · g3-1-055"}],"ex":[["门口站着一个人。","Ménkǒu zhànzhe yī ge rén.","หน้าประตูมีคนยืนอยู่หนึ่งคน","There is a person standing at the doorway.","Ở cửa có một người đang đứng.","入口に1人立っています。","站着"],["教室里坐着很多学生。","Jiàoshì lǐ zuòzhe hěn duō xuésheng.","ในห้องเรียนมีนักเรียนนั่งอยู่เยอะมาก","Many students are sitting in the classroom.","Trong lớp có nhiều học sinh đang ngồi.","教室にたくさんの学生が座っています。","坐着"],["房间里开着电视。","Fángjiān lǐ kāizhe diànshì.","ในห้องเปิดทีวีค้างอยู่","The TV is on in the room.","Trong phòng đang bật TV.","部屋の中でテレビがついています。","开着"],["椅子上坐着一只小猫。","Yǐzi shàng zuòzhe yī zhī xiǎo māo.","บนเก้าอี้มีลูกแมวนั่งอยู่หนึ่งตัว","A kitten is sitting on the chair.","Trên ghế có một chú mèo con đang ngồi.","椅子の上に子猫が1匹座っています。","坐着"],["床上睡着一个小孩儿。","Chuáng shàng shuìzhe yī ge xiǎoháir.","บนเตียงมีเด็กน้อยนอนหลับอยู่หนึ่งคน","A small child is sleeping on the bed.","Trên giường có một em bé đang ngủ.","ベッドの上で小さな子どもが1人寝ています。","睡着"]],"err":[["在门口站着一个人。","门口站着一个人。","ประโยค 存现句 ห้ามใส่ 在 นำหน้าสถานที่ต้นประโยค","Never put 在 before the location subject.","存现句处所主语前绝不能加“在”。","Không thêm 在 trước nơi chốn đầu câu tồn hiện.","存在文の場所主語の前に「在」を付けない。"]],"rel":["g3-1-055","g3-2-032","g3-2-072"]},"g3-2-061":{"t":["ประโยคเปรียบเทียบ 1 (比较句1-1): A + 比 + B + คุณศัพท์","Comparison 1 (比较句1-1): A 比 B + Adjective","特殊句式·比较句1（1）：A比B+形容词","Câu so sánh 1 (比较句1-1): A 比 B + Tính từ","比較文1（比较句1-1）：A 比 B ＋ 形容詞"],"f":["肯定：A + 比 + B + 形容词（今天比昨天冷 / 坐地铁比打车快）","疑问：A + 比 + B + 形容词 + 吗？（今天比昨天冷吗？）"],"why":["โครงสร้างเปรียบเทียบพื้นฐานที่สุดในภาษาจีนคือ **A + 比 + B + คุณศัพท์** แปลว่า 'A … กว่า B' · กฎเหล็ก 3 ข้อของประโยค 比 พื้นฐาน: (1) ห้ามใส่ 很, 非常, 真, 太 หน้าคุณศัพท์เด็ดขาด! (今天比昨天冷 ✓ — ห้ามพูด 今天比昨天很冷 ✗!) (2) สิ่งที่นำมาเทียบกัน (A กับ B) ต้องเป็นสิ่งประเภทเดียวกันหรือเทียบกันได้จริง (เช่น 今天的天气比昨天的天气冷 หรือย่อเป็น 今天比昨天冷 — ไม่เทียบข้ามรุ่นเช่น 我的书包比他大 เมื่อหมายถึงกระเป๋าของเขา ต้องเป็น 我的书包比他的大!) (3) ถ้าต้องการถามเปรียบเทียบ เติม **吗** ท้ายประโยคได้เลย (坐地铁比打车快吗？) ส่วนรูปปฏิเสธ (เช่น A 不比 B) จะเรียนละเอียดขึ้นใน HSK 3 (`g3-3-076`)","The core Chinese comparison pattern is **A + 比 + B + Adjective** ('A is more [adj] than B'). · Three iron rules: (1) NEVER put 很, 非常, 真, or 太 before the adjective (今天比昨天冷 ✓, NEVER 今天比昨天很冷 ✗!). (2) Compare matching categories — say 我的书包比他的大 ('my bag is bigger than his'), NOT 我的书包比他大 ('my bag is bigger than HIM'!). (3) To ask a comparison question, just add **吗** at the end (坐地铁比打车快吗？); negative patterns like 不比 come in HSK 3 (`g3-3-076`).","基本比较句“A＋比＋B＋形容词”表示 A 在某性质上超过 B（今天比昨天冷、坐地铁比打车快）。 · 三条铁律：（1）形容词前绝不能加“很、非常、真、太”；（2）比较对象须同类对应（我的书包比他的大，不说“我的书包比他大”）；（3）疑问句直接在句尾加“吗”（否定式“不比”见 HSK 3 g3-3-076）。","Mẫu so sánh cơ bản nhất: **A + 比 + B + Tính từ** ('A…hơn B'). · 3 quy tắc thép: (1) KHÔNG thêm 很 / 非常 / 真 / 太 trước tính từ; (2) Hai đối tượng so sánh phải cùng loại (我的书包比他的大, không nói 我的书包比他大!); (3) Câu hỏi thêm **吗** cuối câu (dạng phủ định 不比 học ở HSK 3 g3-3-076).","基本の比較文は「A＋比＋B＋形容詞」（AはBより〜だ）。 · 3大鉄則：（1）形容詞の前に「很・非常・真・太」は絶対不可。（2）比較対象は同類に揃える（我的书包比他的大、「我的书包比他大」は不可）。（3）疑問文は文末に「吗」を付ける（否定形「不比」はHSK 3で学習）。"],"use":[{"ok":true,"zh":"我的书包比他的大。","fix":"","py":"Wǒ de shūbāo bǐ tā de dà.","tr":["กระเป๋านักเรียนของฉันใหญ่กว่าของเขา","My schoolbag is bigger than his.","Cặp sách của tôi to hơn cặp của anh ấy.","私のかばんは彼のかばんより大きいです。"],"h":["เทียบของกับของ ต้องเติม 的 ให้คู่เทียบตรงกัน (我的书包 vs 他的)","Keep compared items parallel: add 的 for 'his' (我的书包 vs 他的)","比较双方须同类对称（我的书包比他的大）","So sánh hai vật tương đương phải thêm 的 (我的书包 vs 他的)","比較する2つを同類に揃える（我的书包 vs 他的）"],"w":["ทำได้และแม่นยำมาก เพราะ 他的 ย่อมาจาก 他的书包 ทำให้เป็นการเทียบกระเป๋ากับกระเป๋าอย่างถูกต้อง","Works accurately because 他的 stands for 他的书包, comparing bag to bag.","“他的”指代“他的书包”，使比较双方同类对称，严谨规范。","Đúng và chính xác vì 他的 đại diện cho 他的书包 (so sánh cặp với cặp).","「他的」で「彼のかばん」を指し、かばん同士を正しく比較している。"],"ref":"HSK 3.0 g3-2-061 · g3-2-035"},{"ok":true,"zh":"今天比昨天冷吗？","fix":"","py":"Jīntiān bǐ zuótiān lěng ma?","tr":["วันนี้หนาวกว่าเมื่อวานไหม","Is today colder than yesterday?","Hôm nay có lạnh hơn hôm qua không?","今日は昨日より寒いですか。"],"h":["ถามเปรียบเทียบเติม 吗 ท้ายประโยค A + 比 + B + คุณศัพท์ ได้เลย","Ask a comparison question by adding 吗 to A + 比 + B + Adj","比较疑问句直接在“A比B＋形容词”后加“吗”","Đặt câu hỏi so sánh chỉ cần thêm 吗 cuối câu A + 比 + B + tính từ","比較の疑問文は「A比B＋形容詞」の文末に「吗」を付けるだけ"],"w":["ทำได้ง่ายและเป็นธรรมชาติมาก ไม่ต้องใส่ 很 หน้าคุณศัพท์เหมือนประโยคบอกเล่าเช่นกัน","Works naturally and easily — just like statements, keep 很 out before the adjective.","“A比B＋形容词＋吗？”是最常用的比较是非问，同样不加“很”。","Đúng và tự nhiên, cũng không thêm 很 trước tính từ như câu khẳng định.","最も自然な比較の疑問文で、平叙文と同じく形容詞の前に「很」は入れない。"],"ref":"HSK 3.0 g3-2-061"},{"ok":false,"zh":"我的书包比他大。","fix":"我的书包比他的大。","py":"Wǒ de shūbāo bǐ tā de dà.","tr":["กระเป๋านักเรียนของฉันใหญ่กว่าของเขา","My schoolbag is bigger than his.","Cặp sách của tôi to hơn của anh ấy.","私のかばんは彼のより大きいです。"],"h":["อย่าลืม 的 ท้าย 他的 มิฉะนั้นจะกลายเป็น 'กระเป๋าฉันใหญ่กว่าตัวเขา'!","Don't drop 的 from 他的 — otherwise you're comparing your bag to HIM!","比较对象不对称（书包不能直接和人比），须加“的”","Đừng quên 的 sau 他的 kẻo thành so cái cặp với con người!","「他的」の「的」を落とすとかばんと人間を比べることになってしまう"],"w":["ไม่ได้ เพราะ A คือ 书包 (สิ่งของ) แต่ B คือ 他 (คน) จึงเทียบข้ามประเภทกัน ต้องเติม 的 เป็น 他的 แทน 他的书包","Wrong because A is a bag (书包) and B is a person (他) — add 的 (他的) to mean 'his bag'.","不行，“我的书包”是物品，“他”是人，不能直接比较，须加“的”指代他的书包。","Không được vì 书包 là đồ vật còn 他 là người; phải thêm 的 → 他的.","「书包」（物）と「他」（人）は比較できない。「他的」にして揃える。"],"ref":"HSK 3.0 g3-2-061"},{"ok":false,"zh":"坐地铁比打车非常快。","fix":"坐地铁比打车快。","py":"Zuò dìtiě bǐ dǎchē kuài.","tr":["นั่งรถไฟใต้ดินเร็วกว่าเรียกแท็กซี่","Taking the subway is faster than a taxi.","Đi tàu điện ngầm nhanh hơn bắt taxi.","地下鉄の方がタクシーより速いです。"],"h":["ห้ามใส่ 非常 / 很 / 太 / 真 หน้าคุณศัพท์ในประโยค 比!","NEVER put 非常 / 很 / 太 / 真 before the adjective in a 比 sentence!","“比”字句形容词前绝不能加“非常、很、太、真”","Tuyệt đối không thêm 非常 / 很 / 太 / 真 trước tính từ trong câu 比!","「比」構文の形容詞の前に「非常・很・太・真」は絶対不可"],"w":["ไม่ได้ เพราะในประโยค 比 คำคุณศัพท์ไม่ต้องมี 很 / 非常 นำหน้า (ถ้าจะบอกว่าเร็วกว่ามาก ให้วาง 多了 ไว้ข้างหลังเป็น 坐地铁比打车快多了)","Wrong because 比 forbids 很/非常 before the adjective (put 多了 AFTER the adjective instead: 快多了).","不行，“比”字句形容词前禁加“非常、很”；要强调差距很大须放后面说“快多了”。","Không được vì câu 比 cấm thêm 非常/很 trước tính từ (muốn nhấn mạnh đặt 多了 phía sau).","「比」の文では形容詞の前に「非常・很」を置けない（強調は後ろに「多了」）。"],"ref":"HSK 3.0 g3-2-061 · g3-2-062"}],"ex":[["今天比昨天冷。","Jīntiān bǐ zuótiān lěng.","วันนี้หนาวกว่าเมื่อวาน","Today is colder than yesterday.","Hôm nay lạnh hơn hôm qua.","今日は昨日より寒いです。","比"],["我的书包比他的大。","Wǒ de shūbāo bǐ tā de dà.","กระเป๋านักเรียนของฉันใหญ่กว่าของเขา","My schoolbag is bigger than his.","Cặp sách của tôi to hơn của anh ấy.","私のかばんは彼のより大きいです。","比"],["坐地铁比打车快。","Zuò dìtiě bǐ dǎchē kuài.","นั่งรถไฟใต้ดินเร็วกว่านั่งแท็กซี่","Taking the subway is faster than a taxi.","Đi tàu điện ngầm nhanh hơn đi taxi.","地下鉄はタクシーより速いです。","比"],["红茶比绿茶贵。","Hóngchá bǐ lǜchá guì.","ชาแดงแพงกว่าชาเขียว","Black tea is more expensive than green tea.","Hồng trà đắt hơn trà xanh.","紅茶は緑茶より高いです。","比"],["哥哥比弟弟高。","Gēge bǐ dìdi gāo.","พี่ชายสูงกว่าน้องชาย","My older brother is taller than my younger brother.","Anh trai cao hơn em trai.","兄は弟より背が高いです。","比"]],"err":[["坐地铁比打车非常快。","坐地铁比打车快。","ประโยค 比 ห้ามใส่ 非常 / 很 หน้าคุณศัพท์","Never put 非常 / 很 before the adjective in a 比 sentence.","“比”字句形容词前绝不能加“非常／很”。","Không thêm 非常 / 很 trước tính từ trong câu 比.","「比」の文の形容詞の前に「非常・很」は入れない。"],["我的书包比他大。","我的书包比他的大。","เทียบของกับของต้องใส่ 的 ให้ตรงคู่ (我的书包 vs 他的)","Keep compared items parallel by adding 的 (他的).","比较对象须对称，应加“的”（比他的大）。","Thêm 的 để hai đối tượng so sánh cùng loại (比他的大).","比較対象を揃えるため「的」を補う（比他的大）。"]],"rel":["g3-2-062","g3-2-063","g3-2-025"]},"g3-2-062":{"t":["ประโยคเปรียบเทียบ 2 (比较句1-2): A + 比 + B + คุณศัพท์ + ส่วนต่าง","Comparison 2 (比较句1-2): A 比 B + Adj + difference / degree","特殊句式·比较句1（2）：A比B+形容词+数量补语/程度补语","Câu so sánh 2 (比较句1-2): A 比 B + Tính từ + mức chênh lệch","比較文2（比较句1-2）：A 比 B ＋ 形容詞 ＋ 数量・程度補語"],"f":["具体差额：A + 比 + B + 形容词 + 数量（哥哥比我大三岁 / 贵十块钱）","小差距：A + 比 + B + 形容词 + 一点儿（今天比昨天冷一点儿）","大差距：A + 比 + B + 形容词 + 多了 / 得多（飞机比火车快多了）"],"why":["เมื่ออยากระบุในประโยค 比 ว่า 'มากกว่านิดหน่อย / มากกว่าเยอะมาก / มากกว่าเท่าไรเป๊ะ ๆ' กฎเหล็กคือต้องวางคำบอกส่วนต่างไว้ **หลังคุณศัพท์** เสมอ (ห้ามวางหน้าคุณศัพท์เหมือน 很!): · (1) ต่างกันชัดเจนเป็นตัวเลข: 哥哥比我大三岁 (แก่กว่า 3 ปี), 这件比那件贵二十块钱 (แพงกว่า 20 หยวน) · (2) ต่างกันนิดหน่อย: 今天比昨天冷一点儿 (หนาวกว่านิดหน่อย) · (3) ต่างกันมากโข: 飞机比火车快多了 / 快得多 (เครื่องบินเร็วกว่ารถไฟเยอะมาก!) · ข้อควรระวังเด็ดขาด: ห้ามพูด 飞机比火车很快 (ผิด!) ต้องย้ายความ 'มาก' ไปข้างหลังเป็น 飞机比火车快多了 / 快得多!","To specify HOW MUCH more in a 比 sentence, ALWAYS place the margin AFTER the adjective (never before it like 很!): · (1) Exact amount: 哥哥比我大三岁 ('3 years older'), 贵二十块钱 ('20 yuan pricier'); · (2) Small margin: 今天比昨天冷一点儿 ('a bit colder'); · (3) Huge margin: 飞机比火车快多了 / 快得多 ('MUCH faster!'). · Iron rule: NEVER say 飞机比火车很快 — express 'much faster' AFTER the adjective as 快多了 / 快得多!","要在“比”字句中表达差距大小，数量或程度补语必须放在形容词后面：（1）具体差额：大三岁、贵二十块钱；（2）微小差距：冷一点儿；（3）极大差距：快多了／快得多。 · 铁律：表示“……得多”绝不能在形容词前加“很”，必须在形容词后加“多了／得多”。","Để nói hơn BAO NHIÊU trong câu 比, mức chênh lệch LUÔN đặt SAU tính từ: (1) Con số cụ thể: 大三岁, 贵二十块钱; (2) Hơn chút: 冷一点儿; (3) Hơn rất nhiều: 快多了 / 快得多. · Quy tắc thép: KHÔNG thêm 很 trước tính từ — muốn nói 'hơn nhiều' dùng 多了 / 得多 ở phía sau!","「比」の文で差の大きさを表すときは必ず形容詞の後ろに補語を置く：（1）具体的な差：大三岁・贵二十块钱、（2）わずかな差：冷一点儿、（3）大きな差：快多了／快得多。 · 鉄則：「ずっと〜だ」を「很」で表すことはできず、必ず後ろに「多了／得多」を置く。"],"use":[{"ok":true,"zh":"坐飞机比坐火车快多了。","fix":"","py":"Zuò fēijī bǐ zuò huǒchē kuài duō le.","tr":["นั่งเครื่องบินเร็วกว่ารถไฟเยอะเลย","Taking a plane is way faster than taking a train.","Đi máy bay nhanh hơn đi tàu hỏa nhiều lắm.","飛行機に乗る方が電車よりずっと速いです。"],"h":["ต่างกันมากโข ใช้ คุณศัพท์ + 多了 (หรือ 得多)","Express a big difference with Adjective + 多了 (or 得多)","差距很大用“A比B＋形容词＋多了／得多”","Chênh lệch lớn dùng Tính từ + 多了 / 得多","大きな差は「形容詞＋多了／得多」"],"w":["ทำได้และเป็นวิธีพูด '…กว่ามาก' ที่เจ้าของภาษาใช้บ่อยที่สุดแทนที่ความผิดพลาดอย่าง 很快","Works as the #1 native way to express 'much faster / way more…' instead of illegal 很快.","“快多了／快得多”是表示差距显著的最地道表达。","Đúng và là cách nói 'hơn nhiều' tự nhiên nhất (thay cho lỗi 很快).","「ずっと速い」を表す最も自然な言い方（快多了／快得多）。"],"ref":"HSK 3.0 g3-2-062"},{"ok":true,"zh":"那家饭馆的菜比这家便宜十块钱。","fix":"","py":"Nà jiā fànguǎn de cài bǐ zhè jiā piányi shí kuài qián.","tr":["อาหารของร้านนั้นถูกกว่าร้านนี้สิบหยวน","The food at that restaurant is 10 yuan cheaper than at this one.","Đồ ăn quán kia rẻ hơn quán này 10 tệ.","あのレストランの料理はここより10元安いです。"],"h":["ระบุส่วนต่างตัวเลขเป๊ะ ๆ วางหลังคุณศัพท์ (便宜 + 十块钱)","Put the exact difference right after the adjective (便宜 + 十块钱)","精确差额紧跟形容词后：便宜十块钱／大三岁","Mức chênh lệch cụ thể đứng ngay sau tính từ (便宜十块钱)","正確な差の数値は形容詞の直後（便宜十块钱）"],"w":["ทำได้เพราะวางจำนวนเงิน 十块钱 ไว้หลังคุณศัพท์ 便宜 ตรงตามลำดับ 形容词 + 数量补语 เป๊ะ","Works cleanly with the exact price difference 十块钱 placed straight after 便宜.","数量补语“十块钱”紧跟“便宜”后，清晰准确。","Đúng vì số tiền 十块钱 đứng ngay sau tính từ 便宜.","価格差「十块钱」を形容詞「便宜」の直後に置く正確な語順。"],"ref":"HSK 3.0 g3-2-062 · g3-2-054"},{"ok":false,"zh":"坐飞机比坐火车多快了。","fix":"坐飞机比坐火车快多了。","py":"Zuò fēijī bǐ zuò huǒchē kuài duō le.","tr":["นั่งเครื่องบินเร็วกว่ารถไฟเยอะเลย","Taking a plane is much faster than taking a train.","Đi máy bay nhanh hơn đi tàu hỏa nhiều lắm.","飛行機は電車よりずっと速いです。"],"h":["ห้ามวาง 多了 / 一点儿 ไว้หน้าคุณศัพท์! (ต้องเป็น 快多了 / 快一点儿)","NEVER place 多了 / 一点儿 BEFORE the adjective — ALWAYS AFTER!","“多了／得多／一点儿”必须放在形容词后面（快多了）","Không bao giờ đặt 多了 / 一点儿 TRƯỚC tính từ (phải là 快多了)","「多了・一点儿」は必ず形容詞の後ろ（快多了・快一点儿）"],"w":["ไม่ได้ เพราะ 多了, 得多, 一点儿 ทำหน้าที่เป็นส่วนเสริม (补语) ซึ่งในภาษาจีนส่วนเสริมทุกตัวต้องอยู่ 'หลังคุณศัพท์' เสมอ: 快多了 / 快一点儿","Wrong because 多了, 得多, and 一点儿 are complements and MUST follow the adjective: 快多了 / 快一点儿.","不行，“多了、得多、一点儿”是补语，必须放形容词后：快多了。","Không được vì 多了 / 得多 / 一点儿 là bổ ngữ, luôn đứng SAU tính từ: 快多了.","「多了・得多・一点儿」は補語なので必ず形容詞の後ろに置く（快多了）。"],"ref":"HSK 3.0 g3-2-062"}],"ex":[["坐飞机比坐火车快多了。","Zuò fēijī bǐ zuò huǒchē kuài duō le.","นั่งเครื่องบินเร็วกว่ารถไฟเยอะเลย","Flying is much faster than taking the train.","Đi máy bay nhanh hơn đi tàu hỏa nhiều.","飛行機は電車よりずっと速いです。","快多了"],["今天比昨天冷一点儿。","Jīntiān bǐ zuótiān lěng yīdiǎnr.","วันนี้หนาวกว่าเมื่อวานนิดหน่อย","Today is a little colder than yesterday.","Hôm nay lạnh hơn hôm qua một chút.","今日は昨日より少し寒いです。","冷一点儿"],["哥哥比我大三岁。","Gēge bǐ wǒ dà sān suì.","พี่ชายแก่กว่าฉันสามปี","Older brother is three years older than me.","Anh trai hơn tôi ba tuổi.","兄は私より3歳年上です。","大三岁"],["这个商场比那个大得多。","Zhège shāngchǎng bǐ nàge dà de duō.","ห้างนี้ใหญ่กว่าห้างนั้นมากโขเลย","This mall is much bigger than that one.","Trung tâm thương mại này to hơn cái kia nhiều.","このモールはあちらよりずっと大きいです。","大得多"],["红茶比绿茶贵五块钱。","Hóngchá bǐ lǜchá guì wǔ kuài qián.","ชาแดงแพงกว่าชาเขียวห้าหยวน","Black tea is five yuan pricier than green tea.","Hồng trà đắt hơn trà xanh năm tệ.","紅茶は緑茶より5元高いです。","贵五块钱"]],"err":[["坐飞机比坐火车多快了。","坐飞机比坐火车快多了。","多了 / 得多 / 一点儿 ต้องวางหลังคุณศัพท์เสมอ (快多了)","Place 多了 / 得多 / 一点儿 AFTER the adjective (快多了).","补语“多了／得多／一点儿”放形容词后（快多了）。","Đặt 多了 / 得多 / 一点儿 SAU tính từ (快多了).","「多了・得多・一点儿」は必ず形容詞の後ろ（快多了）。"]],"rel":["g3-2-061","g3-2-054","g3-2-064"]},"g3-2-063":{"t":["ประโยคเปรียบเทียบ 3 (比较句1-3): A + 有 / 没有 + B + (这么/那么) + คุณศัพท์","Comparison 3 (比较句1-3): A 有 / 没有 B (这么/那么) + Adj ('as…as')","特殊句式·比较句1（3）：A有/没有B（+这么/那么）+形容词","Câu so sánh 3 (比较句1-3): A 有 / 没有 B (+ 这么/那么) + Tính từ","比較文3（比较句1-3）：A 有／没有 B（＋这么／那么）＋ 形容詞"],"f":["否定（最常用）：A + 没有 + B +（这么/那么）+ 形容词（我没有他那么高）","疑问：A + 有 + B +（这么/那么）+ 形容词 + 吗？（你有哥哥那么高吗？）"],"why":["โครงสร้าง **A + 没有 + B + (这么/那么) + คุณศัพท์** แปลว่า 'A ไม่…เท่า B' (เท่ากับ A ไม่ถึงระดับของ B เช่น 我没有他高 = ฉันไม่สูงเท่าเขา, 坐火车没有坐飞机那么快 = นั่งรถไฟไม่เร็วเท่าเครื่องบิน) ซึ่งเป็นวิธีปฏิเสธประโยคเปรียบเทียบที่คนจีนใช้บ่อยที่สุด! · ส่วนรูปบอกเล่า **A + 有 + B + 这么/那么 + คุณศัพท์** มักใช้ในประโยคคำถาม (你有他那么高吗？= คุณสูงเท่าเขาไหม?) หรือใช้เมื่อชี้ให้เห็นระดับความสูง/ขนาดจริง ๆ (他有爸爸那么高了 = เขาสูงเท่าพ่อแล้วนะ!) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ห้ามเอา **没有** กับ **比** มาซ้อนกัน! (我没有比他高 ไม่ได้แปลว่าไม่เท่าเขา — วิธีมาตรฐานคือตัด 比 เหลือ 我没有他高!) (2) ในประโยค 没有… ห้ามใส่ 很 หน้าคุณศัพท์ (ห้ามพูด 我没有他很高 — ให้ใช้ 这么 / 那么 แทน!)","**A + 没有 + B + (这么/那么) + Adj** means 'A is NOT as [adj] as B' (我没有他高 'I am not as tall as him') — the #1 standard negation of comparisons! · Affirmative **A + 有 + B + 这么/那么 + Adj** is used in questions (你有他那么高吗？ 'Are you as tall as him?') or when pointing out that A has reached B's level (他有爸爸那么高了!). · Two iron rules: (1) NEVER use 很 before the adjective here (never 我没有他很高 — use 这么/那么 instead!). (2) Do not mix 没有 + 比 for basic 'not as…as' — simply say A 没有 B + Adj.","“A＋没有＋B（＋这么／那么）＋形容词”表示“A 不如 B 那么……”（我没有他那么高），是“比”字句最常用的否定形式。 · 肯定式“A＋有＋B＋这么／那么＋形容词”多用于疑问句（你有哥哥那么高吗？）或强调达到对方程度（弟弟有爸爸那么高了）。 · 注意：形容词前可加“这么／那么”，但绝不能加“很”（不说“我没有他很高”）。","**A + 没有 + B (+ 这么/那么) + Tính từ** nghĩa là 'A không…bằng B' (我没有他高 = tôi không cao bằng anh ấy) — dạng phủ định phổ biến nhất của câu so sánh! · Dạng khẳng định 有 hay dùng trong câu hỏi (你有他那么高吗？). · Lưu ý: trước tính từ dùng 这么/那么 chứ TUYỆT ĐỐI không dùng 很 (không nói 我没有他很高!).","「A＋没有＋B（＋这么／那么）＋形容詞」は「AはBほど〜ではない」（我没有他高）で比較文の最も一般的な否定形。 · 肯定の「有」は疑問文（你有他那么高吗？）や到達（弟弟有爸爸那么高了）に使う。 · 注意：形容詞の前に「很」は絶対不可（「这么／那么」を使う）。"],"use":[{"ok":true,"zh":"今天没有昨天那么冷。","fix":"","py":"Jīntiān méiyǒu zuótiān nàme lěng.","tr":["วันนี้ไม่หนาวเท่าเมื่อวาน","Today is not as cold as yesterday.","Hôm nay không lạnh bằng hôm qua.","今日は昨日ほど寒くありません。"],"h":["'A ไม่…เท่า B': A + 没有 + B + (那么/这么) + คุณศัพท์","'A is not as…as B': A + 没有 + B + (那么/这么) + Adj","否定比较用“A没有B（那么／这么）＋形容词”","'A không…bằng B': A + 没有 + B + (那么/这么) + tính từ","「AはBほど〜ではない」：「A没有B（那么／这么）＋形容詞」"],"w":["ทำได้และเป็นธรรมชาติมาก โดย 昨天 ไม่มี 很 หน้า 冷 แต่ใช้ 那么 ช่วยรับความหมาย 'ขนาดเมื่อวาน' ได้สละสลวย","Works super naturally: 那么 echoes yesterday's coldness cleanly without illegal 很.","“没有……那么冷”比光说“没有……冷”更柔和自然。","Đúng và cực tự nhiên khi thêm 那么 (và tuyệt đối không thêm 很).","「那么」を添えることで「昨日ほどには寒くない」が柔らかく自然に表現できる。"],"ref":"HSK 3.0 g3-2-063"},{"ok":true,"zh":"弟弟有哥哥那么高了吗？","fix":"","py":"Dìdi yǒu gēge nàme gāo le ma?","tr":["น้องชายสูงเท่าพี่ชายแล้วหรือยัง","Is the younger brother as tall as the older brother now?","Em trai đã cao bằng anh trai chưa?","弟はもうお兄さんと同じくらい背が高くなりましたか。"],"h":["ถามว่า 'A …เท่า B ไหม?' ใช้ A + 有 + B + 那么/这么 + คุณศัพท์ + 吗？","Ask 'Is A as…as B?' with A + 有 + B + 那么/这么 + Adj + 吗？","询问是否达到同等程度：A＋有＋B＋那么＋形容词＋吗？","Hỏi 'A có…bằng B không?' dùng A + 有 + B + 那么 + tính từ + 吗？","「AはBと同じくらい〜か？」は「A有B那么＋形容詞＋吗？」"],"w":["ทำได้เพราะคำว่า 有 ในที่นี้แปลว่า 'สูงถึงระดับของพี่ชายแล้วหรือยัง' (เชื่อมตรงจาก 有字句2 表示达到)","Works cleanly because 有 here means 'reached the level of older brother's height'.","“有……那么高吗”询问是否已经达到哥哥的身高。","Đúng vì 有 mang nghĩa 'đạt đến mức cao bằng anh trai chưa'.","「お兄さんの背丈に達したか」を「有…那么高吗？」で尋ねている。"],"ref":"HSK 3.0 g3-2-063 · g3-2-059"},{"ok":false,"zh":"今天没有昨天很冷。","fix":"今天没有昨天那么冷。","py":"Jīntiān méiyǒu zuótiān nàme lěng.","tr":["วันนี้ไม่หนาวเท่าเมื่อวาน","Today is not as cold as yesterday.","Hôm nay không lạnh bằng hôm qua.","今日は昨日ほど寒くありません。"],"h":["ห้ามใส่ 很 หน้าคุณศัพท์ในประโยค 没有! (ให้ใช้ 那么 หรือ 这么 แทน)","NEVER put 很 before the adjective in a 没有 comparison — use 那么 / 这么!","“A没有B……”形容词前绝不能加“很”，可加“那么／这么”","KHÔNG thêm 很 trước tính từ trong câu 没有 (dùng 那么 / 这么)","「没有」の比較文で形容詞の前に「很」は不可（「那么／这么」を使う）"],"w":["ไม่ได้ เพราะในประโยคเปรียบเทียบทุกแบบ (ทั้ง 比 และ 没有) ห้ามใช้คำวิเศษณ์ระดับ 很 หน้าคุณศัพท์ ให้เปลี่ยนเป็น 那么 หรือตัดออกเลย (今天没有昨天冷)","Wrong because comparison sentences (both 比 and 没有) forbid 很 before the adjective — use 那么 or omit it (今天没有昨天冷).","不行，比较句形容词前不能加“很”，须改为“那么”或直接省去（今天没有昨天冷）。","Không được vì câu so sánh cấm 很 trước tính từ; đổi thành 那么 hoặc bỏ luôn.","比較文では「很」が使えない。「那么」に換えるか省いて「今天没有昨天冷」にする。"],"ref":"HSK 3.0 g3-2-063"}],"ex":[["我没有他高。","Wǒ méiyǒu tā gāo.","ฉันไม่สูงเท่าเขา","I am not as tall as him.","Tôi không cao bằng anh ấy.","私は彼ほど背が高くありません。","没有"],["今天没有昨天那么冷。","Jīntiān méiyǒu zuótiān nàme lěng.","วันนี้ไม่หนาวเท่าเมื่อวาน","Today isn't as cold as yesterday.","Hôm nay không lạnh bằng hôm qua.","今日は昨日ほど寒くありません。","没有"],["坐火车没有坐飞机那么快。","Zuò huǒchē méiyǒu zuò fēijī nàme kuài.","นั่งรถไฟไม่เร็วเท่าเครื่องบิน","Taking a train is not as fast as flying.","Đi tàu hỏa không nhanh bằng đi máy bay.","電車は飛行機ほど速くありません。","没有"],["你有哥哥那么高吗？","Nǐ yǒu gēge nàme gāo ma?","คุณสูงเท่าพี่ชายไหม","Are you as tall as your older brother?","Bạn có cao bằng anh trai không?","お兄さんと同じくらい背が高いですか。","有"],["这家酒店没有那家贵。","Zhè jiā jiǔdiàn méiyǒu nà jiā guì.","โรงแรมนี้ไม่แพงเท่าโรงแรมนั้น","This hotel isn't as expensive as that one.","Khách sạn này không đắt bằng khách sạn kia.","このホテルはあちらほど高くありません。","没有"]],"err":[["今天没有昨天很冷。","今天没有昨天那么冷。","ประโยคเปรียบเทียบ 没有 ห้ามใส่ 很 หน้าคุณศัพท์ (ใช้ 那么 / 这么 หรือตัดออก)","Never put 很 before the adjective in 没有 comparisons (use 那么 or drop it).","“没有”比较句形容词前不能加“很”，用“那么”或省去。","Câu so sánh 没有 không dùng 很 trước tính từ (dùng 那么 hoặc bỏ).","「没有」の比較文に「很」は入れず「那么」にするか省く。"]],"rel":["g3-2-061","g3-2-059","g3-2-008"]},"g3-2-064":{"t":["ประโยคเปรียบเทียบ 4 (比较句1-4): เทียบความเก่ง/เร็วของกริยาด้วย 比 + 得","Comparison 4 (比较句1-4): comparing verbs with 比 + 得","特殊句式·比较句1（4）：A比B+动词+得+形容词 / A+动词+得+比+B+形容词","Câu so sánh 4 (比较句1-4): so sánh động từ với 比 + 得","比較文4（比较句1-4）：動詞の程度比較（比＋得）"],"f":["形式1：A + 比 + B + 动词 + 得 + 形容词（他比我跑得快）","形式2：A + 动词 + 得 + 比 + B + 形容词（他跑得比我快）","带宾语：A +（动词）+ 宾语 + 动词 + 得 + 比 + B + 形容词（他汉语说得比我好）"],"why":["เมื่อต้องการเปรียบเทียบ 'การกระทำ' ว่าใครทำได้เก่งกว่า เร็วกว่า หรือดีกว่า (เช่น เขาวิ่งเร็วกว่าฉัน, เธอพูดภาษาจีนเก่งกว่าฉัน) ภาษาจีนผสาน **比** เข้ากับ **得** ได้ 2 แบบที่ถูกทั้งคู่: · แบบที่ 1: **A + 比 + B + กริยา + 得 + คุณศัพท์** (他比我跑得快) · แบบที่ 2: **A + กริยา + 得 + 比 + B + คุณศัพท์** (他跑得比我快 — นิยมสุดในภาษาพูด!) · กรณีมีกรรม (เช่น 说汉语): ซ้ำกริยาหรือย้ายกรรมขึ้นหน้าก่อน เช่น 他说汉语说得比我好 หรือ 他汉语说得比我好 · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ห้ามใส่ 很 หน้าคุณศัพท์เด็ดขาด (他跑得比我很快 ผิด!) (2) ห้ามลืม **得** เชื่อมหลังกริยา (他比我跑快 ผิด!)","To compare HOW WELL or FAST two people do an action, combine **比** + **得** in either of two equally valid ways: · Pattern 1: **A + 比 + B + Verb + 得 + Adj** (他比我跑得快); · Pattern 2: **A + Verb + 得 + 比 + B + Adj** (他跑得比我快 — most natural in speech!). · With an object (说汉语): front the object or repeat the verb (他汉语说得比我好 / 他说汉语说得比我好). · Two iron rules: (1) NEVER add 很 before the adjective! (2) NEVER drop **得** (never 他比我跑快!).","比较动作的程度或结果时，把“比”和状态补语“得”结合，有两种等价语序：（1）A比B＋动词＋得＋形容词（他比我跑得快）；（2）A＋动词＋得＋比B＋形容词（他跑得比我快，口语最常用）。 · 带宾语时须重动或提前宾语（他汉语说得比我好）。 · 两条铁律：（1）形容词前绝不加“很”；（2）绝不能漏掉“得”。","Khi so sánh mức độ của ĐỘNG TỪ (ai chạy nhanh hơn, nói giỏi hơn), kết hợp **比** + **得** theo 2 cách đều đúng: (1) A 比 B + Động từ + 得 + Tính từ (他比我跑得快); (2) A + Động từ + 得 + 比 B + Tính từ (他跑得比我快 — tự nhiên nhất!). · Lưu ý: KHÔNG thêm 很 trước tính từ và KHÔNG bỏ 得!","動作の速さや上手さを比較するときは「比」と様態補語「得」を組み合わせ、2つの語順がどちらも使える：（1）「A比B＋動詞＋得＋形容詞」（他比我跑得快）、（2）「A＋動詞＋得＋比B＋形容詞」（他跑得比我快・口語で最頻出）。 · 鉄則：「很」不可、「得」の省略不可。"],"use":[{"ok":true,"zh":"他跑得比我快多了。","fix":"","py":"Tā pǎo de bǐ wǒ kuài duō le.","tr":["เขาวิ่งเร็วกว่าฉันเยอะเลย","He runs much faster than me.","Anh ấy chạy nhanh hơn tôi nhiều lắm.","彼は私より走るのがずっと速いです。"],"h":["แบบที่นิยมสุดในภาษาพูด: A + กริยา + 得 + 比 + B + คุณศัพท์ (+ 多了/一点儿)","Most popular spoken order: A + Verb + 得 + 比 + B + Adj (+ 多了/一点儿)","口语最常用：A＋动词＋得＋比＋B＋形容词（＋多了／一点儿）","Dạng phổ biến nhất: A + động từ + 得 + 比 + B + tính từ (+ 多了)","口語で最頻出：「A＋動詞＋得＋比＋B＋形容詞（＋多了）」"],"w":["ทำได้และลื่นไหลที่สุดเพราะวาง 跑得 ชิดกัน แล้วค่อยเปรียบเทียบ 比我快多了 ด้านหลังอย่างชัดเจน","Works super smoothly by keeping 跑得 together and placing the full comparison 比我快多了 right after.","“跑得”紧连，后接“比我快多了”，层次清晰、非常地道。","Đúng và mượt nhất vì 跑得 bám sát nhau rồi mới so sánh 比我快多了.","「跑得」を密着させて後ろに「比我快多了」を続ける最も自然な語順。"],"ref":"HSK 3.0 g3-2-064 · g3-2-052"},{"ok":true,"zh":"他汉语说得比我好。","fix":"","py":"Tā Hànyǔ shuō de bǐ wǒ hǎo.","tr":["เขาพูดภาษาจีนเก่งกว่าฉัน","He speaks Chinese better than I do.","Anh ấy nói tiếng Trung giỏi hơn tôi.","彼は私より中国語を話すのが上手です。"],"h":["กริยามีกรรม (说汉语): ย้ายกรรมขึ้นหน้า (他汉语说得比我好) หรือซ้ำกริยา","With an object (说汉语), front the object (他汉语说得比我好) or repeat the verb","带宾语时提前宾语（他汉语说得比我好）或重动（他说汉语说得比我好）","Có tân ngữ (说汉语) thì đảo tân ngữ lên trước hoặc lặp động từ","目的語（说汉语）があるときは目的語を前に出すか動詞を重ねる"],"w":["ทำได้และกระชับกว่าซ้ำกริยาสองรอบ โดยย้ายหัวข้อ 汉语 มาไว้หลัง 他 แล้วให้ 说得 เกาะติดกันถูกต้อง 100%","Works even more concisely than verb-copying: fronting 汉语 keeps 说得 fused cleanly.","把宾语“汉语”提前到主语后，避免重复动词，简练地道。","Đúng và gọn hơn cả lặp động từ vì 汉语 lên trước để 说得 sát nhau.","目的語「汉语」を前に出すことで動詞を繰り返さず簡潔に「说得」を直結できる。"],"ref":"HSK 3.0 g3-2-064"},{"ok":false,"zh":"他比我跑快。","fix":"他比我跑得快。","py":"Tā bǐ wǒ pǎo de kuài.","tr":["เขาวิ่งเร็วกว่าฉัน","He runs faster than me.","Anh ấy chạy nhanh hơn tôi.","彼は私より速く走ります。"],"h":["ห้ามลืม 得 หลังกริยาเมื่อเทียบระดับความเร็ว/ความเก่ง!","NEVER drop 得 after the verb when comparing how well/fast!","比较动作程度绝不能漏掉结构助词“得”（跑得快）","Tuyệt đối không bỏ 得 sau động từ khi so sánh tốc độ/trình độ!","動作の程度比較で動詞の後ろの「得」を落とせない"],"w":["ไม่ได้ เพราะ 快 บอกระดับความเร็วของกริยา 跑 จึงต้องมี 得 เชื่อมเสมอ (他比我跑得快 หรือ 他跑得比我快)","Wrong because 快 evaluates verb 跑, which strictly requires 得 (他比我跑得快 or 他跑得比我快).","不行，动词后接状态补语必须用“得”连接：他比我跑得快。","Không được vì 快 bổ ngữ mức độ cho động từ 跑, bắt buộc có 得.","動詞の後ろの様態補語には必ず「得」が要る（他比我跑得快）。"],"ref":"HSK 3.0 g3-2-064 · g3-2-030"},{"ok":false,"zh":"他跑得比我很快。","fix":"他跑得比我快。","py":"Tā pǎo de bǐ wǒ kuài.","tr":["เขาวิ่งเร็วกว่าฉัน","He runs faster than me.","Anh ấy chạy nhanh hơn tôi.","彼は私より速く走ります。"],"h":["ห้ามใส่ 很 หน้าคุณศัพท์ในประโยค 比 + 得!","NEVER put 很 before the adjective in a 比 + 得 comparison!","带“比”的状态补语句形容词前不能加“很”","Không thêm 很 trước tính từ trong câu so sánh 比 + 得!","「比＋得」の形容詞の前に「很」は絶対不可"],"w":["ไม่ได้ เพราะถึงแม้ประโยค 得 ทั่วไปจะมี 很 (他跑得很快) แต่พอมี **比** เข้ามา กฎเหล็กของ 比 จะห้ามใส่ 很 หน้าคุณศัพท์ทันที! (ถ้าจะเน้นมากให้ใช้ 快多了)","Wrong because even though plain 得 takes 很 (他跑得很快), adding 比 immediately forbids 很 before the adjective (use 快多了 for 'much faster').","不行，虽然“他跑得很快”要加“很”，但一有“比”就绝不能加“很”（要说“快多了”）。","Không được vì dù 他跑得很快 có 很, nhưng cứ xuất hiện 比 là cấm thêm 很 trước tính từ!","普通の「他跑得很快」には「很」が付くが、「比」が入ると「很」は禁止になる（「快多了」にする）。"],"ref":"HSK 3.0 g3-2-064"}],"ex":[["他比我跑得快。","Tā bǐ wǒ pǎo de kuài.","เขาวิ่งเร็วกว่าฉัน","He runs faster than I do.","Anh ấy chạy nhanh hơn tôi.","彼は私より走るのが速いです。","比我跑得"],["他跑得比我快多了。","Tā pǎo de bǐ wǒ kuài duō le.","เขาวิ่งเร็วกว่าฉันเยอะเลย","He runs much faster than me.","Anh ấy chạy nhanh hơn tôi nhiều lắm.","彼は私よりずっと速く走ります。","跑得比我"],["她汉语说得比我好。","Tā Hànyǔ shuō de bǐ wǒ hǎo.","เธอพูดภาษาจีนเก่งกว่าฉัน","She speaks Chinese better than I do.","Cô ấy nói tiếng Trung giỏi hơn tôi.","彼女は私より中国語が上手です。","说得比我"],["哥哥比我游得快一点儿。","Gēge bǐ wǒ yóu de kuài yīdiǎnr.","พี่ชายว่ายน้ำเร็วกว่าฉันนิดหน่อย","Older brother swims a little faster than me.","Anh trai bơi nhanh hơn tôi một chút.","兄は私より少し速く泳ぎます。","游得"],["他今天来得比我早。","Tā jīntiān lái de bǐ wǒ zǎo.","วันนี้เขามาเช้ากว่าฉัน","Today he arrived earlier than me.","Hôm nay anh ấy đến sớm hơn tôi.","今日彼は私より早く来ました。","来得比我"]],"err":[["他比我跑快。","他比我跑得快。","เทียบความเก่ง/เร็วของกริยา ห้ามลืม 得 หลังกริยา","Never drop 得 after the verb in a verb comparison.","比较动作状态不能省“得”（他比我跑得快）。","So sánh động từ không được bỏ 得.","動作の比較で「得」を省いてはいけない。"],["他跑得比我很快。","他跑得比我快。","พอมี 比 เข้ามา ห้ามใส่ 很 หน้าคุณศัพท์เด็ดขาด","Once 比 is present, NEVER put 很 before the adjective.","有“比”字时形容词前绝不加“很”。","Đã có 比 thì tuyệt đối không thêm 很 trước tính từ.","「比」があるときは形容詞の前に「很」を絶対に入れない。"]],"rel":["g3-2-052","g3-2-061","g3-2-030"]},"g3-2-065":{"t":["ประโยคเน้นย้ำ “是……的” 1: เน้นเวลา / สถานที่ / วิธี / ผู้ทำ (ในอดีต)","Emphatic “是……的” 1: highlighting time, place, means, or doer (past)","特殊句式·“是……的”句1：强调时间、地点、方式、动作者","Câu nhấn mạnh “是……的” 1: nhấn mạnh thời gian, địa điểm, cách thức, chủ thể","「是……的」構文1：過去の時・場所・手段・動作主の強調"],"f":["主语 +（是）+ 时间 / 地点 / 方式 / 动作者 + 动词 + 的","否定：主语 + 不是 + 强调部分 + 动词 + 的（“是”绝不能省略！）"],"why":["โครงสร้าง **是……的** เป็นไวยากรณ์พระเอกของ HSK 2! ใช้กับเหตุการณ์ที่ **เกิดขึ้นจบไปแล้วในอดีต** (ทั้งสองฝ่ายรู้แล้วว่าเกิดเรื่องนั้นขึ้น) แต่ต้องการ 'โฟกัสเน้นย้ำรายละเอียด' 4 อย่าง: · ① เวลา: 我是昨天来的 (ฉันมา 'เมื่อวาน' นะ) · ② สถานที่: 这个手机是在网上买的 (ซื้อ 'ทางออนไลน์' นะ) · ③ วิธีเดินทาง: 我是坐飞机去北京的 (ไป 'โดยเครื่องบิน' นะ) · ④ ผู้กระทำ: 这些菜是妈妈做的 (เป็น 'แม่' ที่ทำนะ) · กฎเหล็ก 3 ข้อที่ออกสอบทุกครั้ง: (1) วาง **是** ไว้ 'หน้าสิ่งที่ต้องการเน้น' เสมอ! (2) ประโยคบอกเล่าละ 是 ได้ (我昨天来的) แต่ประโยคปฏิเสธ **ห้ามละ 是** ต้องใช้ **不是……的** เสมอ! (3) ใช้เฉพาะเรื่องที่เกิดไปแล้วในอดีต ห้ามใช้กับเรื่องอนาคตที่ยังไม่เกิด (ห้ามพูด 我是明天去北京的!)","The **是……的** frame is a crown jewel of HSK 2! Use it for an action that **ALREADY HAPPENED** to spotlight one detail: · ① Time: 我是昨天来的 ('It was YESTERDAY that I came'); · ② Place: 是在网上买的 ('bought it ONLINE'); · ③ Means: 我是坐飞机去的 ('went BY PLANE'); · ④ Doer: 这些菜是妈妈做的 ('MOM cooked them'). · Three exam rules: (1) Place 是 right BEFORE the focused detail. (2) Positive sentences may drop 是, but negatives MUST keep **不是……的**. (3) Strictly for past/completed events — NEVER future plans (never 我是明天去的!).","“是……的”句1用于动作已经发生，重点强调动作的时间（我是昨天来的）、地点（在网上买的）、方式（坐飞机去的）或动作者（妈妈做的）。 · 三条必考铁律：（1）“是”紧放在要强调的成分前面；（2）肯定句可省“是”，否定句必须保留“不是……的”；（3）只用于已发生事件，不能用于未发生的将来动作。","Cấu trúc **是……的** dùng cho việc ĐÃ XẢY RA để nhấn mạnh 1 chi tiết: ① Thời gian (我是昨天来的), ② Địa điểm (是在网上买的), ③ Cách thức (我是坐飞机去的), ④ Người làm (是妈妈做的). · 3 quy tắc vàng: (1) Đặt 是 ngay TRƯỚC phần cần nhấn mạnh; (2) Câu phủ định bắt buộc giữ **不是……的**; (3) Chỉ dùng cho việc quá khứ, KHÔNG dùng cho tương lai!","「是……的」構文1はすでに起きた過去の出来事について、①時（我是昨天来的）、②場所（在网上买的）、③手段（坐飞机去的）、④動作主（妈妈做的）を強調する最重要文型。 · 3大鉄則：（1）「是」は強調したい部分の直前に置く。（2）否定は必ず「不是……的」（「是」は省略不可）。（3）未来の予定には使えない。"],"use":[{"ok":true,"zh":"我是坐飞机来北京的。","fix":"","py":"Wǒ shì zuò fēijī lái Běijīng de.","tr":["ฉันนั่งเครื่องบินมาปักกิ่ง (เน้นว่ามาด้วยเครื่องบิน)","I came to Beijing by plane.","Tôi đến Bắc Kinh bằng máy bay.","私は飛行機で北京へ来たのです。"],"h":["เน้นวิธีเดินทาง/เวลา/สถานที่ในอดีต: ประธาน + 是 + สิ่งที่เน้น + กริยา + 的","Spotlight past means/time/place: Subject + 是 + Focus + Verb + 的","强调已发生动作的方式／时间／地点：是＋焦点＋动词＋的","Nhấn mạnh cách thức/thời gian/nơi chốn đã xảy ra: 是 + trọng tâm + động từ + 的","過去の手段・時・場所の強調：「是＋焦点＋動詞＋的」"],"w":["ทำได้เพราะตอนนี้ผู้พูดอยู่ที่ปักกิ่งแล้ว (มาถึงแล้วในอดีต) และต้องการเน้นคำตอบของคำถาม 'คุณมาปักกิ่งยังไง?' (你怎么来的？)","Works cleanly because arriving in Beijing already happened, and 是 spotlights 坐飞机 ('by plane').","来北京已是事实，“是”紧跟在“坐飞机”前突出交通方式。","Đúng vì việc đến Bắc Kinh đã xảy ra rồi, 是 nhấn mạnh phương tiện 坐飞机.","北京に来たことは既知の事実で、手段の「坐飞机」を「是…的」で強調している。"],"ref":"HSK 3.0 g3-2-065"},{"ok":true,"zh":"这个手机不是在商店买的，是在网上买的。","fix":"","py":"Zhège shǒujī bù shì zài shāngdiàn mǎi de, shì zài wǎngshàng mǎi de.","tr":["โทรศัพท์เครื่องนี้ไม่ได้ซื้อที่ร้านค้า ซื้อทางออนไลน์นะ","This phone wasn't bought at a shop; it was bought online.","Chiếc điện thoại này không phải mua ở cửa hàng, mà mua trên mạng.","このスマホはお店で買ったのではなく、ネットで買ったのです。"],"h":["ปฏิเสธรายละเอียดที่ผิดแล้วแก้ด้วย 不是……的，是……的","Correct a detail with 不是……的，是……的 (never drop 是 in negation!)","否定并纠正细节必须保留“不是……的”","Phủ định và đính chính chi tiết dùng 不是……的，是……的","詳細を否定・訂正するときは必ず「不是……的，是……的」"],"w":["ทำได้และชัดเจนมาก เพราะไม่ได้ปฏิเสธว่าไม่ได้ซื้อ แต่ปฏิเสธเฉพาะสถานที่ซื้อ (ไม่ใช่ที่ร้าน แต่เป็นที่ออนไลน์)","Works crisply: it doesn't deny buying the phone — it negates ONLY the place (not at a shop, online!).","“不是……的”只否定被强调的地点，不否定“买”这件事本身。","Đúng vì 不是…的 chỉ phủ định địa điểm mua chứ không phủ định việc mua.","「買った」事実ではなく「買った場所」だけを「不是…的」で鮮やかに訂正している。"],"ref":"HSK 3.0 g3-2-065"},{"ok":false,"zh":"我是明天坐飞机去北京的。","fix":"我明天坐飞机去北京。","py":"Wǒ míngtiān zuò fēijī qù Běijīng.","tr":["พรุ่งนี้ฉันจะนั่งเครื่องบินไปปักกิ่ง","Tomorrow I'm flying to Beijing.","Ngày mai tôi đi Bắc Kinh bằng máy bay.","明日飛行機で北京へ行きます。"],"h":["ห้ามใช้ 是……的 กับเหตุการณ์ในอนาคต (明天) ที่ยังไม่เกิด!","NEVER use past-focus 是……的 for a future event (明天)!","“是……的”句1只用于已发生的事，不能用于将来（明天）","KHÔNG dùng 是……的 cho việc tương lai chưa xảy ra (明天)!","未来の予定（明天）に過去の「是……的」は使えない"],"w":["ไม่ได้ เพราะ 明天 ยังมาไม่ถึง โครงสร้าง 是……的 สำหรับเน้นเวลา/สถานที่/วิธีใช้ได้เฉพาะเรื่องที่เกิดขึ้นแล้วในอดีตเท่านั้น ถ้าเป็นอนาคตให้พูดประโยคปกติ: 我明天坐飞机去北京","Wrong because 明天 hasn't happened yet! Detail-focus 是……的 only applies to completed past events — use a normal sentence for future plans.","不行，“明天”尚未发生，不能套用表过去强调的“是……的”，应说“我明天坐飞机去北京”。","Không được vì ngày mai chưa xảy ra; tương lai nói câu bình thường 我明天坐飞机去北京.","「明天」はまだ起きていない未来なので「是…的」構文1は使えず、普通の平叙文にする。"],"ref":"HSK 3.0 g3-2-065"}],"ex":[["我是昨天来的。","Wǒ shì zuótiān lái de.","ฉันมาเมื่อวานนี้เอง","I arrived yesterday.","Tôi đến từ hôm qua.","私は昨日来たのです。","是"],["我是坐飞机来北京的。","Wǒ shì zuò fēijī lái Běijīng de.","ฉันนั่งเครื่องบินมาปักกิ่ง","I came to Beijing by plane.","Tôi đến Bắc Kinh bằng máy bay.","飛行機で北京へ来たのです。","是"],["这个手机是在网上买的。","Zhège shǒujī shì zài wǎngshàng mǎi de.","โทรศัพท์เครื่องนี้ซื้อทางออนไลน์นะ","This phone was bought online.","Chiếc điện thoại này mua trên mạng đấy.","このスマホはネットで買ったのです。","的"],["这些菜都是妈妈做的。","Zhèxiē cài dōu shì māma zuò de.","กับข้าวพวกนี้แม่เป็นคนทำทั้งหมดเลย","All these dishes were cooked by Mom.","Những món này đều do mẹ nấu đấy.","これらの料理は全部母が作ったものです。","是"],["我不是打车来的，我是坐地铁来的。","Wǒ bù shì dǎchē lái de, wǒ shì zuò dìtiě lái de.","ฉันไม่ได้นั่งแท็กซี่มา ฉันนั่งรถไฟใต้ดินมา","I didn't come by taxi; I came by subway.","Tôi không phải đi taxi tới, tôi đi tàu điện ngầm tới.","タクシーではなく地下鉄で来たのです。","不是"]],"err":[["我是明天坐飞机去北京的。","我明天坐飞机去北京。","是……的 (เน้นเวลา/วิธี/สถานที่) ใช้กับอดีตที่เกิดแล้วเท่านั้น ไม่ใช้กับอนาคต","Use detail-focus 是……的 only for completed past events, not the future.","强调时间方式的“是……的”只用于已发生事件，不用于将来。","是……的 chỉ dùng cho việc đã xảy ra, không dùng cho tương lai.","時・手段強調の「是……的」は過去専用で未来には使えない。"],["我没是昨天来的。","我不是昨天来的。","ปฏิเสธประโยค 是……的 ใช้ 不是……的 เสมอ ห้ามใช้ 没是","Negate 是……的 with 不是……的, never 没是.","否定“是……的”必须用“不是……的”。","Phủ định 是……的 luôn dùng 不是……的.","「是……的」の否定は必ず「不是……的」。"]],"rel":["g3-2-058","g3-2-033","g3-1-052"]},"g3-2-066":{"t":["ประโยคคำควบ (兼语句1): ให้ / เชิญ / สั่งใครทำอะไร (请 / 叫 / 让)","Pivotal sentences 1 (兼语句1): 请 / 叫 / 让 + Person + Verb","特殊句式·兼语句1：表使令（请/叫/让）","Câu kiêm ngữ 1 (兼语句1): 请 / 叫 / 让 + Người + Động từ","兼語文1（兼语句1）：使役・依頼（请・叫・让）"],"f":["主语 + 请 / 叫 / 让 + 宾语1（人）+ 动词（+ 宾语2）"],"why":["兼语句1 ใช้กริยาบังคับ/ขอร้อง 3 ตัวหลักที่ต่างกันที่ระดับความสุภาพ: · **请** = เชิญอย่างสุภาพ/เลี้ยง (我请你喝咖啡, 请大家坐下) · **让** = ให้/อนุญาต/ขอให้ (กลาง ๆ ใช้ได้กว้างสุด: 老师让我们看书, 妈妈让我喝牛奶) · **叫** = เรียกให้/สั่งให้ (ภาษาพูด ใช้กับคนที่สนิทหรืออายุน้อยกว่า: 爸爸叫我回家) · ข้อควรระวังสำคัญ 2 ข้อ: (1) เวลาปฏิเสธว่า 'ไม่ยอมให้ทำ' วาง 不/没 ไว้ 'หน้า 让/叫/请' (妈妈不让我上网) แต่ถ้าสั่งว่า 'ให้ไม่ทำ/อย่าทำ' วาง 别 หน้ากริยาตัวที่สอง (老师叫我们别说话) (2) ห้ามสลับเอาคนไปวางท้ายประโยค!","Pivotal sentences 1 use three causative verbs ranked by politeness: · **请** = politely invite / treat (我请你喝咖啡); · **让** = let / have / ask (neutral & versatile: 老师让我们看书); · **叫** = tell / call upon (casual, for peers/juniors: 爸爸叫我回家). · Two cautions: (1) Put 不/没 BEFORE 让/请 to refuse permission (妈妈不让我上网), or put 别 before Verb 2 to convey 'told us not to…' (老师叫我们别说话). (2) Keep the pivot person right after 请/叫/让.","兼语句1用使令动词“请、叫、让”引出兼语（既是前动词的宾语，又是后动词的主语）。 · 语气区分：“请”最客气礼貌，“让”中性通用，“叫”较口语随意（多用于平辈或晚辈）。 · 注意：“不让＋人＋V”表不允许；“让／叫＋人＋别V”表吩咐不要做。","Câu kiêm ngữ 1 dùng 3 động từ sai khiến theo sắc thái lịch sự: **请** (mời lịch sự), **让** (cho phép/bảo — trung tính, dùng rộng nhất), **叫** (gọi/bảo — thân mật). · Lưu ý: 不让… = không cho phép; 叫/让…别… = bảo ai đừng làm gì.","兼語文1は使役動詞「请・叫・让」を使う。丁寧さの違い：「请」は最も丁寧な招待・依頼、「让」は中立で万能、「叫」は親しい相手・目下への口語的な指示。 · 注意：「不让…」は不許可、「叫／让…别…」は「〜するなと言う」。"],"use":[{"ok":true,"zh":"老师让我们每天多读汉语。","fix":"","py":"Lǎoshī ràng wǒmen měi tiān duō dú Hànyǔ.","tr":["คุณครูให้พวกเราอ่านภาษาจีนเยอะ ๆ ทุกวัน","The teacher asks us to read Chinese a lot every day.","Thầy giáo bảo chúng tôi mỗi ngày đọc tiếng Trung nhiều lên.","先生は私たちに毎日中国語をたくさん読むように言います。"],"h":["ใช้ 让 (กลาง ๆ สุภาพ) + คน (我们) + กริยาที่ให้ทำ","Use versatile 让 + Person (我们) + Action","中性委婉的使令最常用“让＋人＋动词”","Dùng 让 (trung tính lịch sự) + Người + Hành động","中立で使いやすい使役は「让＋人＋動詞」"],"w":["ทำได้และเป็นธรรมชาติที่สุดในห้องเรียนหรือที่ทำงาน เพราะ 让 ไม่ฟังออกคำสั่งห้วนเหมือน 叫 และไม่ทางการเกินไปเหมือน 请","Works most naturally in classrooms or workplaces: 让 is polite and neutral without sounding bossy.","“让”语气平缓自然，学校和日常场合使用频率最高。","Đúng và tự nhiên nhất vì 让 không cộc lốc như 叫 và không quá trịnh trọng như 请.","「让」は命令っぽくならず、学校や職場で最も自然に使える。"],"ref":"HSK 3.0 g3-2-066"},{"ok":true,"zh":"老师叫大家别说话。","fix":"","py":"Lǎoshī jiào dàjiā bié shuōhuà.","tr":["คุณครูบอกให้ทุกคนอย่าพูดคุย","The teacher told everyone not to talk.","Thầy giáo bảo mọi người đừng nói chuyện.","先生はみんなに話さないように言いました。"],"h":["สั่งให้ใคร 'อย่าทำอะไร' วาง 别 หน้ากริยาตัวที่สอง (叫大家别说话)","For 'tell someone NOT to do something', put 别 before Verb 2","要求某人不要做某事：叫／让＋人＋别＋动词","Bảo ai ĐỪNG làm gì đặt 别 trước động từ 2 (叫大家别说话)","「〜しないように言う」は動詞2の前に「别」を置く"],"w":["ทำได้และแยกความหมายชัดจาก ไม่ยอมให้ทำ: 老师不让大家说话 (ไม่อนุญาต) vs 老师叫大家别说话 (บอกทุกคนว่าอย่าคุยนะ)","Works cleanly to report a prohibition directly ('told everyone: don't talk!').","“别”放在第二动词前，准确转达“不要说话”的要求。","Đúng và rõ nghĩa: 别 đặt trước động từ 2 để truyền đạt lời nhắc 'đừng nói'.","動詞2の前に「别」を置くことで「話さないように」という指示を正確に伝えられる。"],"ref":"HSK 3.0 g3-2-066"},{"ok":false,"zh":"我请喝咖啡你。","fix":"我请你喝咖啡。","py":"Wǒ qǐng nǐ hē kāfēi.","tr":["ฉันเลี้ยงกาแฟคุณ","Let me treat you to coffee.","Tôi mời bạn uống cà phê.","あなたにコーヒーをご馳走します。"],"h":["ห้ามเอาผู้ถูกเชิญ (你) ไปวางท้ายประโยค! ต้องวางติดหลัง 请 ทันที","NEVER move the invited person (你) to the end — keep 你 right after 请!","兼语“你”必须紧跟在“请”后面（我请你喝咖啡）","Không đẩy người được mời (你) ra cuối câu; phải đứng sát sau 请!","兼語「你」を文末に置けない、必ず「请」の直後に置く"],"w":["ไม่ได้ เพราะ 你 เป็นทั้งกรรมของ 请 และประธานของ 喝咖啡 จึงต้องยืนอยู่ตรงกลางเป็นสะพานเชื่อมเสมอ: 我请你喝咖啡","Wrong because 你 is the pivot bridging 请 and 喝咖啡 — it MUST sit between them: 我请你喝咖啡.","不行，“你”既是“请”的宾语又是“喝咖啡”的主语，必须在中间：我请你喝咖啡。","Không được vì 你 là cầu nối giữa 请 và 喝咖啡, bắt buộc ở giữa: 我请你喝咖啡.","「你」は「请」と「喝咖啡」をつなぐ兼語なので必ず間に置く（我请你喝咖啡）。"],"ref":"HSK 3.0 g3-2-066 · g3-2-037"}],"ex":[["我请你喝咖啡吧。","Wǒ qǐng nǐ hē kāfēi ba.","ฉันเลี้ยงกาแฟคุณนะ","Let me treat you to coffee.","Để tôi mời bạn uống cà phê nhé.","コーヒーをご馳走しますね。","请"],["老师让我们每天多读汉语。","Lǎoshī ràng wǒmen měi tiān duō dú Hànyǔ.","คุณครูให้พวกเราอ่านภาษาจีนเยอะ ๆ ทุกวัน","The teacher has us read Chinese a lot every day.","Thầy giáo bảo chúng tôi mỗi ngày đọc nhiều tiếng Trung.","先生は私たちに毎日中国語をたくさん読むように言います。","让"],["妈妈叫我去超市买牛奶。","Māma jiào wǒ qù chāoshì mǎi niúnǎi.","แม่บอกให้ฉันไปซื้อนมที่ซูเปอร์มาร์เก็ต","Mom told me to go buy milk at the supermarket.","Mẹ bảo tôi ra siêu thị mua sữa.","母が私にスーパーへ牛乳を買いに行くように言いました。","叫"],["请让我帮你一下吧。","Qǐng ràng wǒ bāng nǐ yīxià ba.","ให้ฉันช่วยคุณหน่อยนะ","Please let me help you a bit.","Hãy để tôi giúp bạn một chút nhé.","ちょっと手伝わせてください。","让"],["医生叫我多喝水，多休息。","Yīshēng jiào wǒ duō hē shuǐ, duō xiūxi.","คุณหมอสั่งให้ฉันดื่มน้ำเยอะ ๆ พักผ่อนเยอะ ๆ","The doctor told me to drink lots of water and rest more.","Bác sĩ dặn tôi uống nhiều nước và nghỉ ngơi nhiều.","お医者さんに水をたくさん飲んでよく休むように言われました。","叫"]],"err":[["我请喝咖啡你。","我请你喝咖啡。","ผู้ถูกเชิญ (你) ต้องอยู่ติดหลัง 请 เสมอ (我请你喝咖啡)","Always place the pivot person right after 请 (我请你喝咖啡).","兼语必须紧跟“请”后（我请你喝咖啡）。","Kiêm ngữ luôn đứng sát sau 请 (我请你喝咖啡).","兼語「你」は必ず「请」の直後に置く（我请你喝咖啡）。"]],"rel":["g3-2-037","g3-2-057"]},"g3-2-067":{"t":["ประโยคกรรมสองตัว 2 (双宾语句2): กริยา + 给 + คน + สิ่งของ","Double-object sentences 2 (双宾语句2): Verb + 给 + Person + Thing","特殊句式·双宾语句2：主语+动词+给+宾语1+宾语2","Câu hai tân ngữ 2 (双宾语句2): Động từ + 给 + Người + Vật","二重目的語文2（双宾语句2）：動詞＋给＋人＋物"],"f":["主语 + 送 / 拿 / 介绍 + 给 + 宾语1（人）+ 宾语2（事物）","例如：我送给他一本书 / 妈妈拿给我一杯水 / 朋友介绍给我一家饭馆"],"why":["ต่อยอดจาก双宾语句1 (HSK 1: 他给我一本书) ใน HSK 2 เราสามารถนำกริยาบอกการส่งต่อ/ยื่นให้/แนะนำ (เช่น 送 มอบให้, 拿 หยิบส่งให้, 介绍 แนะนำ) มาติดท้ายด้วย **给** เป็น **送给 / 拿给 / 介绍给** แล้วตามด้วย 'คน (กรรม 1) + สิ่งของ (กรรม 2)' ได้เลย! · ตัวอย่างสุดฮิต: 我送给妈妈一束花→我送给妈妈一些花→我送给妈妈一件新衣服 (ฉันมอบเสื้อใหม่ให้แม่หนึ่งตัว), 朋友介绍给我一家好饭馆 (เพื่อนแนะนำร้านอาหารดี ๆ ให้ฉันหนึ่งร้าน) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ลำดับกรรมต้องเป็น **คน (กรรม 1) → สิ่งของ (กรรม 2)** เสมอ! (送给他一本书 ✓ ห้ามพูด 送给一本书他 ✗!) (2) เมื่อมี 了1 ให้วางหลัง 给 (送给了他一本书 หรือ 送给他了一本书)","Building on HSK 1 double objects, HSK 2 fuses **给** directly onto transfer verbs like 送 ('gift'), 拿 ('hand over'), and 介绍 ('recommend') to form **Verb + 给 + Person + Thing**: 我送给妈妈一件新衣服, 他拿给我一杯水, 朋友介绍给我一家饭馆. · Two iron rules: (1) ALWAYS put the PERSON before the THING (送给他一本书 ✓, NEVER 送给一本书他 ✗!). (2) Attach 了 right after 给 (送给了他一本书).","双宾语句2在传递类动词（送、拿、介绍等）后紧接“给”，构成“动词＋给＋人（宾语1）＋物（宾语2）”：我送给妈妈一件衣服、他拿给我一杯水、朋友介绍给我一家饭馆。 · 两条铁律：（1）先人后物，绝不说“送给一本书他”；（2）完成助词“了”紧跟在“给”后（送给了他一本书）。","Câu hai tân ngữ 2 ghép **给** sát sau động từ trao chuyển (送, 拿, 介绍): 'Động từ + 给 + Người + Vật' (我送给妈妈一件新衣服, 他拿给我一杯水, 朋友介绍给我一家饭馆). · Quy tắc thép: luôn đặt NGƯỜI trước VẬT (không nói 送给一本书他!).","二重目的語文2は授与・伝達動詞（送・拿・介绍）の直後に「给」を付け、「動詞＋给＋人＋物」の順で並べる：我送给妈妈一件新衣服、他拿给我一杯水、朋友介绍给我一家饭馆。 · 鉄則：必ず「人→物」の順（「送给一本书他」は不可）。"],"use":[{"ok":true,"zh":"我送给了妹妹一个新书包。","fix":"","py":"Wǒ sònggěile mèimei yī ge xīn shūbāo.","tr":["ฉันซื้อ/มอบกระเป๋านักเรียนใบใหม่ให้น้องสาวหนึ่งใบ","I gave my younger sister a new schoolbag as a gift.","Tôi đã tặng cho em gái một chiếc cặp sách mới.","妹に新しいかばんをプレゼントしました。"],"h":["กริยาโอนย้าย + 给 (+ 了) + ผู้รับ (人) + สิ่งของ (物)","Transfer verb + 给 (+ 了) + Recipient (Person) + Item (Thing)","“送给／拿给（＋了）＋人＋物”","Động từ trao + 给 (+ 了) + Người nhận + Đồ vật","「送给／拿给（＋了）＋人＋物」"],"w":["ทำได้และเป็นธรรมชาติ 100% โดยวาง 了 ติดหลัง 送给 แล้วเรียงผู้รับ 妹妹 ก่อนสิ่งของ 一个新书包","Works 100% cleanly: 了 attaches right after 送给, followed strictly by recipient 妹妹 then gift 一个新书包.","“送给了”后先接人称宾语“妹妹”，再接事物宾语“一个新书包”。","Đúng 100%: 了 gắn sau 送给, rồi xếp Người (妹妹) trước Vật (一个新书包).","「送给了」の後ろに「人（妹妹）→物（一个新书包）」の順で並んでいる。"],"ref":"HSK 3.0 g3-2-067"},{"ok":true,"zh":"朋友介绍给我一家不错的饭馆。","fix":"","py":"Péngyou jièshào gěi wǒ yī jiā bùcuò de fànguǎn.","tr":["เพื่อนแนะนำร้านอาหารดี ๆ ให้ฉันหนึ่งร้าน","My friend recommended a pretty good restaurant to me.","Bạn tôi giới thiệu cho tôi một quán ăn khá ổn.","友達がなかなか良いレストランを紹介してくれました。"],"h":["ใช้ 介绍给 + คน + สิ่งที่แนะนำ (หรือ 给我介绍 + สิ่งที่แนะนำ ก็ได้)","Use 介绍给 + Person + Thing (or pre-verbal 给我介绍 + Thing)","“介绍给＋人＋物”与“给＋人＋介绍＋物”两种语序均可","Dùng 介绍给 + Người + Vật (hoặc 给我介绍 + Vật đều được)","「介绍给＋人＋物」も「给我介绍＋物」も両方使える"],"w":["ทำได้ทั้ง 2 แบบที่มีความหมายเดียวกันเป๊ะ: 朋友介绍给我一家饭馆 (双宾语句2) และ 朋友给我介绍了一家饭馆 (介词 给)","Both orders work identically: 朋友介绍给我一家饭馆 (double object) or 朋友给我介绍了一家饭馆 (preposition 给).","“介绍给我一家饭馆”与“给我介绍了一家饭馆”均地道规范。","Cả hai cách 介绍给我… và 给我介绍… đều chuẩn và tự nhiên.","「介绍给我…」も「给我介绍…」もどちらも自然で正しい中国語。"],"ref":"HSK 3.0 g3-2-067 · g3-2-024"},{"ok":false,"zh":"我送给一个新书包妹妹。","fix":"我送给妹妹一个新书包。","py":"Wǒ sònggěi mèimei yī ge xīn shūbāo.","tr":["ฉันมอบกระเป๋านักเรียนใบใหม่ให้น้องสาวหนึ่งใบ","I give my younger sister a new schoolbag.","Tôi tặng em gái một chiếc cặp sách mới.","妹に新しいかばんを贈ります。"],"h":["ห้ามวาง 'สิ่งของ' ขึ้นหน้า 'ผู้รับ' หลัง 送给 / 拿给!","NEVER put the THING before the PERSON after 送给 / 拿给!","“送给／拿给”后绝不能先物后人（送给妹妹一个新书包）","Không bao giờ đặt VẬT trước NGƯỜI sau 送给 / 拿给!","「送给／拿给」の後ろで「物→人」にしてはいけない"],"w":["ไม่ได้ เพราะโครงสร้าง双宾语句บังคับเรียง 'คน (ผู้รับ) ก่อน → สิ่งของทีหลัง' เสมอ: 送给妹妹一个新书包","Wrong because double-object order is ALWAYS Person FIRST, Thing SECOND: 送给妹妹一个新书包.","不行，双宾语铁律是先人后物：我送给妹妹一个新书包。","Không được vì quy tắc cứng luôn là Người trước, Vật sau: 送给妹妹一个新书包.","二重目的語は必ず「人→物」の順。「我送给妹妹一个新书包」にする。"],"ref":"HSK 3.0 g3-2-067 · g3-1-058"}],"ex":[["我送给妈妈一件新衣服。","Wǒ sònggěi māma yī jiàn xīn yīfu.","ฉันมอบเสื้อใหม่ให้แม่หนึ่งตัว","I gave Mom a new piece of clothing.","Tôi tặng mẹ một chiếc áo mới.","母に新しい服を1着贈ります。","送给"],["我送给了妹妹一个新书包。","Wǒ sònggěile mèimei yī ge xīn shūbāo.","ฉันมอบกระเป๋านักเรียนใหม่ให้น้องสาวหนึ่งใบ","I gave my younger sister a new schoolbag.","Tôi đã tặng em gái một chiếc cặp mới.","妹に新しいかばんを贈りました。","送给了"],["他拿给我一杯热茶。","Tā nágěi wǒ yī bēi rè chá.","เขาหยิบชาร้อนมาส่งให้ฉันหนึ่งแก้ว","He handed me a cup of hot tea.","Anh ấy cầm đưa cho tôi một cốc trà nóng.","彼が熱いお茶を1杯取ってくれました。","拿给"],["朋友介绍给我一家不错的饭馆。","Péngyou jièshào gěi wǒ yī jiā bùcuò de fànguǎn.","เพื่อนแนะนำร้านอาหารดี ๆ ให้ฉันหนึ่งร้าน","My friend recommended a good restaurant to me.","Bạn tôi giới thiệu cho tôi một quán ăn khá ổn.","友達がなかなか良いレストランを紹介してくれました。","介绍给"],["爷爷送给我一块手表。","Yéye sònggěi wǒ yī kuài shǒubiǎo.","คุณปู่มอบนาฬิกาข้อมือให้ฉันหนึ่งเรือน","Grandpa gave me a wristwatch.","Ông nội tặng tôi một chiếc đồng hồ đeo tay.","おじいちゃんが腕時計を1つプレゼントしてくれました。","送给"]],"err":[["我送给一个新书包妹妹。","我送给妹妹一个新书包。","หลัง 送给 ต้องวาง 'คน (ผู้รับ)' ก่อน 'สิ่งของ' เสมอ","Always place Person before Thing after 送给.","“送给”后必须先人后物（送给妹妹一个新书包）。","Sau 送给 luôn đặt Người trước Vật.","「送给」の後ろは必ず「人→物」の順。"]],"rel":["g3-1-058","g3-2-024","g3-1-038"]},"g3-2-068":{"t":["ประโยคความซ้อนให้เลือก (选择复句): （是）……，还是……","Alternative compound sentences (选择复句): (是)……，还是……","复句·选择复句：（是）……，还是……","Câu ghép lựa chọn (选择复句): （是）……，还是……","選択複文（选择复句）：（是）……，还是……"],"f":["（是）+ 分句1，还是 + 分句2？（你是今天去，还是明天去？）"],"why":["选择复句 “（是）……，还是……” ใช้เชื่อมประโยคย่อย 2 ประโยคเพื่อให้เลือกตัดสินใจระหว่าง 2 แผนการหรือ 2 สถานการณ์ (เช่น 我们是去游泳，还是去打篮球？, 你是在家吃饭，还是去饭馆吃？) · ประโยชน์ของการเติม **是** หน้าประโยคย่อยแรก: ช่วยส่งสัญญาณให้คนฟังรู้ตัวตั้งแต่ต้นประโยคว่ากำลังจะเสนอ 2 ตัวเลือกให้เทียบกัน (คล้าย 'เอาเป็นว่า…หรือว่า…?') โดยละ 是 ออกก็ได้ · ข้อควรระวัง: (1) ห้ามเติม 吗 ปิดท้ายเด็ดขาด (2) ใช้ได้ทั้งในประโยคคำถามตรง ๆ และในประโยคย่อยที่ซ้อนหลัง 不知道 (เช่น 我不知道是坐地铁，还是打车 = ฉันไม่รู้ว่าจะนั่งรถไฟใต้ดินหรือแท็กซี่ดี)","Alternative compound sentences **(是)……，还是……** link two full clauses as competing options (我们是去游泳，还是去打篮球？). · Optional leading **是** signals right upfront that two choices are coming. · Cautions: (1) NEVER append 吗 at the end. (2) Works both as a direct question AND embedded after 不知道 (我不知道是坐地铁，还是打车).","选择复句“（是）……，还是……”连接两个并列分句供选择（我们是去游泳，还是去打篮球？）。前分句加“是”可提前标示选择焦点，也可省略。 · 注意：（1）句末绝不能加“吗”；（2）也可嵌在“不知道”等动词后作宾语（我不知道是坐地铁，还是打车）。","Câu ghép lựa chọn **（是）……，还是……** nối 2 mệnh đề phương án (我们是去游泳，还是去打篮球？). Thêm 是 ở vế 1 giúp báo trước sắp nêu lựa chọn (bỏ cũng được). · Lưu ý: KHÔNG thêm 吗 ở cuối; dùng được cả sau 不知道.","選択複文「（是）……，还是……」は2つの節を選択肢としてつなぐ（我们是去游泳，还是去打篮球？）。前の「是」で選択肢を予告でき省略も可。 · 注意：文末に「吗」不可。「不知道」の目的語としても使える。"],"use":[{"ok":true,"zh":"我们是去游泳，还是去打篮球？","fix":"","py":"Wǒmen shì qù yóuyǒng, háishi qù dǎ lánqiú?","tr":["พวกเราจะไปว่ายน้ำ หรือจะไปเล่นบาสเกตบอลดี","Should we go swimming, or go play basketball?","Chúng ta đi bơi hay là đi chơi bóng rổ?","泳ぎに行きますか、それともバスケをしに行きますか。"],"h":["เชื่อม 2 กิจกรรม/ประโยคย่อยให้เลือกด้วย 是……，还是……","Link two activity clauses with 是……，还是……","“（是）分句1，还是分句2？”提出两项方案供选择","Nối 2 mệnh đề kế hoạch bằng 是……，还是……","2つの案を「（是）節1，还是節2？」で並べる"],"w":["ทำได้และชัดเจนมาก เพราะ 是 หน้าประโยคย่อยแรกช่วยให้โครงสร้างสองฝั่ง (去游泳 vs 去打篮球) สมดุลและฟังง่ายทันที","Works super clearly: leading 是 frames the two clause options (去游泳 vs 去打篮球) in crisp balance.","前分句用“是”点出选择项，与“还是”前后呼应，语义醒目。","Đúng và rõ ràng nhờ 是 mở đầu cân xứng với 还是 ở vế sau.","「是」で最初の選択肢を際立たせ、「还是」とバランスよく呼応している。"],"ref":"HSK 3.0 g3-2-068"},{"ok":true,"zh":"我不知道是坐地铁去，还是打车去。","fix":"","py":"Wǒ bù zhīdao shì zuò dìtiě qù, háishi dǎchē qù.","tr":["ฉันไม่รู้ว่าจะนั่งรถไฟใต้ดินไป หรือเรียกแท็กซี่ไปดี","I don't know whether to go by subway or by taxi.","Tôi không biết nên đi tàu điện ngầm hay bắt taxi.","地下鉄で行くかタクシーで行くか分かりません。"],"h":["ซ้อนเป็นประโยคบอกเล่าหลัง 不知道 ('ไม่รู้ว่า…หรือ…') ได้ (จบด้วยจุด 。!)","Embed after 不知道 ('don't know whether…or…') ending with a period 。!","“不知道＋是……，还是……”作陈述句宾语，句末用句号“。”","Lồng sau 不知道 ('không biết…hay là…') kết bằng dấu chấm 。!","「不知道」の目的語として埋め込める（文末は「。」）"],"w":["ทำได้เพราะทั้งประโยคเป็นการบอกเล่าความไม่แน่ใจของฉัน (不知道…) จึงใช้ 还是 ได้แม้จบด้วยจุด 。 (ไม่ใช่คำถาม)","Works seamlessly: even though the outer sentence is a statement (ending in 。), 还是 expresses the embedded 'whether…or' choice.","整句是陈述“我不知道”，内部包含选择疑问，所以可用“还是”且句末用句号。","Đúng vì vế trong là lựa chọn phân vân nên dùng 还是 dù câu ngoài là câu trần thuật.","外側は平叙文だが内側に「〜か〜か」の疑問を含むため「还是」を使い文末は「。」になる。"],"ref":"HSK 3.0 g3-2-068"},{"ok":false,"zh":"我们是去游泳，还是去打篮球吗？","fix":"我们是去游泳，还是去打篮球？","py":"Wǒmen shì qù yóuyǒng, háishi qù dǎ lánqiú?","tr":["พวกเราจะไปว่ายน้ำ หรือจะไปเล่นบาสเกตบอลดี","Should we go swimming or play basketball?","Chúng ta đi bơi hay đi chơi bóng rổ?","泳ぎに行きますか、バスケに行きますか。"],"h":["ห้ามเติม 吗 ปิดท้ายประโยคความซ้อนให้เลือก 还是!","NEVER add 吗 at the end of a (是)…，还是… choice sentence!","选择复句末尾绝不能加“吗”","Tuyệt đối không thêm 吗 cuối câu ghép lựa chọn 还是!","選択複文「还是」の末尾に「吗」は付けない"],"w":["ไม่ได้ เพราะมี 还是 บอกคำถามแบบเลือกตอบอยู่แล้ว ห้ามใส่ 吗 ที่ใช้ถามใช่/ไม่ใช่เด็ดขาด","Wrong because 还是 already forms a choice question; adding yes/no 吗 is always ungrammatical.","不行，已有“还是”构成选择问，绝不能加“吗”。","Không được vì đã có 还是 rồi, thêm 吗 là sai ngữ pháp.","「还是」による選択疑問文なので「吗」を重ねてはいけない。"],"ref":"HSK 3.0 g3-2-068 · g3-2-056"}],"ex":[["我们是去游泳，还是去打篮球？","Wǒmen shì qù yóuyǒng, háishi qù dǎ lánqiú?","พวกเราจะไปว่ายน้ำ หรือไปเล่นบาสเกตบอลดี","Should we go swimming, or play basketball?","Chúng ta đi bơi hay đi chơi bóng rổ?","泳ぎに行きますか、バスケをしに行きますか。","还是"],["你是在家吃饭，还是去饭馆吃？","Nǐ shì zài jiā chīfàn, háishi qù fànguǎn chī?","คุณจะกินข้าวที่บ้าน หรือไปกินที่ร้านอาหาร","Are you eating at home, or going to a restaurant?","Bạn ăn ở nhà hay ra quán ăn?","家で食べますか、レストランで食べますか。","还是"],["我们明天去，还是星期天去？","Wǒmen míngtiān qù, háishi xīngqītiān qù?","พวกเราไปพรุ่งนี้ หรือไปวันอาทิตย์ดี","Should we go tomorrow, or on Sunday?","Chúng ta đi ngày mai hay Chủ nhật đi?","明日行きますか、日曜に行きますか。","还是"],["我不知道是坐地铁去，还是打车去。","Wǒ bù zhīdao shì zuò dìtiě qù, háishi dǎchē qù.","ฉันไม่รู้ว่าจะนั่งรถไฟใต้ดินไปหรือเรียกแท็กซี่ไปดี","I don't know whether to go by subway or taxi.","Tôi không biết nên đi tàu điện ngầm hay đi taxi.","地下鉄で行くかタクシーで行くか分かりません。","还是"],["这件事是你告诉他，还是我告诉他？","Zhè jiàn shì shì nǐ gàosu tā, háishi wǒ gàosu tā?","เรื่องนี้คุณจะบอกเขา หรือฉันจะบอกเขาดี","For this matter, will you tell him or should I tell him?","Chuyện này là bạn nói với anh ấy hay tôi nói?","この件はあなたが彼に伝えますか、私が伝えますか。","还是"]],"err":[["我们是去游泳，还是去打篮球吗？","我们是去游泳，还是去打篮球？","ประโยคให้เลือก (是)…，还是… ห้ามเติม 吗 ปิดท้าย","Never add 吗 to a (是)…，还是… choice question.","选择复句句末绝不能加“吗”。","Câu ghép lựa chọn không thêm 吗 ở cuối.","選択複文の文末に「吗」は付けない。"]],"rel":["g3-2-056","g3-2-042","g3-2-029"]},"g3-2-069":{"t":["ประโยคความซ้อนขัดแย้ง (转折复句): 虽然……，但是…… (ถึงแม้…แต่…)","Concessive compound sentences (转折复句): 虽然……，但是……","复句·转折复句：虽然……，但是……","Câu ghép chuyển ngoặt (转折复句): 虽然……，但是…… (tuy…nhưng…)","逆接複文（转折复句）：虽然……，但是……（〜だが、しかし…）"],"f":["主语相同：主语 + 虽然……，但是 / 但……（我虽然很累，但是很高兴）","主语不同：虽然 + 主语1……，但是 + 主语2……（虽然下雨了，但是他还是去了）"],"why":["转折复句 **虽然……，但是……** แปลว่า 'ถึงแม้ว่า…แต่…' ใช้ยอมรับข้อเท็จจริงในประโยคแรกก่อน แล้วหักมุมด้วยผลที่ตรงข้ามในประโยคหลัง · จุดต่างสำคัญกับภาษาอังกฤษ: ภาษาอังกฤษห้ามใช้ Although คู่กับ but ในประโยคเดียวกัน แต่ภาษาจีน **นิยมใช้ 虽然 คู่กับ 但是 / 但 พร้อมกันเสมอ!** (และละ 虽然 เหลือแต่ 但是 ก็ได้ แต่ไม่ค่อยละ 但是 ทิ้งตัวเดียวโดด ๆ) · กฎตำแหน่งประธานที่สวยเป็นธรรมชาติ: (1) ประธานทั้งสองท่อนเป็นคนเดียวกัน → วางประธานหน้า 虽然 ได้ (他虽然很忙，但是每天都运动) (2) ประธานคนละตัวกัน → วาง 虽然 ไว้ต้นประโยคหน้าประธานที่ 1 (虽然今天很冷，但是我还是去跑步了)","Concessive compound sentences **虽然……，但是……** ('although…[but]…') acknowledge a fact first, then pivot to a contrasting outcome. · Crucial difference from English: English forbids 'Although…but…', whereas Chinese **routinely pairs BOTH 虽然 and 但是/但 together!** · Subject placement tip: (1) Same subject → put subject before 虽然 (他虽然很忙，但是每天都运动); (2) Different subjects → put 虽然 before Subject 1 (虽然今天很冷，但是我还是去跑步了).","转折复句“虽然……，但是／但……”先承认前分句事实，再转折引出相反或出乎意料的结果。 · 与英语不同，汉语极常成对使用“虽然”和“但是”（也可单用“但是”，但一般不单用“虽然”而省“但是”）。 · 主语位置：前后同主语时主语常放“虽然”前；异主语时“虽然”放句首。","Câu ghép chuyển ngoặt **虽然……，但是……** ('tuy…nhưng…') — khác tiếng Anh, tiếng Trung rất hay dùng CẢ CẶP 虽然 và 但是 cùng lúc! · Vị trí chủ ngữ: cùng chủ ngữ thì chủ ngữ thường đứng TRƯỚC 虽然 (他虽然很忙，但是…); khác chủ ngữ thì 虽然 đứng đầu câu.","逆接複文「虽然……，但是／但……」は「〜だけれども、しかし…」。英語と違い中国語では両方ペアで使うのが標準！ · 主語の位置：前後で主語が同じなら主語を「虽然」の前（他虽然很忙，但是…）、主語が違うなら「虽然」を文頭に置く。"],"use":[{"ok":true,"zh":"他虽然很忙，但是每天都去跑步。","fix":"","py":"Tā suīrán hěn máng, dànshì měi tiān dōu qù pǎobù.","tr":["ถึงแม้เขาจะยุ่งมาก แต่ก็ไปวิ่งทุกวันเลย","Although he is very busy, he still goes jogging every day.","Tuy anh ấy rất bận nhưng ngày nào cũng đi chạy bộ.","彼はとても忙しいですが、毎日ジョギングに行きます。"],"h":["ประธานคนเดียวกัน วางประธานหน้า 虽然 ได้อย่างลื่นไหล","With the same subject, put the subject before 虽然","前后主语相同时，主语常放在“虽然”前面","Cùng chủ ngữ đặt chủ ngữ trước 虽然 rất mượt","同一主語なら主語を「虽然」の前に置くとすっきりする"],"w":["ทำได้และสละสลวยมาก เพราะ 他 คุมทั้งสองประโยคย่อย จึงวางไว้ต้นประโยคครั้งเดียวแล้วละประธานประโยคหลังได้ทันที","Works smoothly because 他 governs both clauses once upfront, letting the second clause omit repeating 他.","主语“他”统领前后两分句，放“虽然”前最简洁自然。","Đúng và gọn vì 他 làm chủ chung cả hai vế nên vế sau không cần lặp lại.","主語「他」を文頭に1回置けば第2節の主語を省けて非常に滑らか。"],"ref":"HSK 3.0 g3-2-069"},{"ok":true,"zh":"虽然这件衣服有点儿贵，但是非常舒服。","fix":"","py":"Suīrán zhè jiàn yīfu yǒudiǎnr guì, dànshì fēicháng shūfu.","tr":["ถึงแม้เสื้อตัวนี้จะแพงไปหน่อย แต่ใส่สบายมาก ๆ","Although this shirt is a bit expensive, it's extremely comfortable.","Tuy chiếc áo này hơi đắt nhưng mặc cực kỳ thoải mái.","この服は少し高いですが、とても着心地がいいです。"],"h":["ใช้ 虽然…但是 คู่กันเต็มรูป (ห้ามละ 但是 ไปใช้ 所以!)","Pair 虽然 with 但是/但 (never pair 虽然 with 所以!)","“虽然”必须与转折词“但是／但／可是”搭配","Kết hợp đúng cặp 虽然…但是 (không ghép nhầm 所以)","「虽然」は必ず逆接の「但是／但」とペアにする"],"w":["ทำได้และชัดเจนมาก เพราะประโยคแรกเป็นข้อเสีย (有点儿贵) แล้วหักมุมด้วยข้อดี (非常舒服) ที่เชื่อมด้วย 但是","Works crisply: the first clause concedes a drawback (有点儿贵), pivoting smoothly via 但是 to the upside (非常舒服).","前句让步说缺点，后句用“但是”转出优点，逻辑清晰。","Đúng vì vế đầu nêu nhược điểm rồi chuyển ngoặt sang ưu điểm bằng 但是.","欠点を認めてから「但是」で長所に転じる論理的な逆接文。"],"ref":"HSK 3.0 g3-2-069"},{"ok":false,"zh":"虽然今天很冷，所以我没出门。","fix":"因为今天很冷，所以我没出门。","py":"Yīnwèi jīntiān hěn lěng, suǒyǐ wǒ méi chūmén.","tr":["เพราะวันนี้หนาวมาก ฉันเลยไม่ได้ออกจากบ้าน","Because it's very cold today, I didn't go out.","Vì hôm nay rất lạnh nên tôi không ra ngoài.","今日はとても寒いので外出しませんでした。"],"h":["ห้ามเอา 虽然 (ถึงแม้) มาจับคู่กับ 所以 (ดังนั้น) ข้ามสาย!","NEVER mismatch 虽然 ('although') with 所以 ('so')!","绝不能把转折词“虽然”和因果词“所以”混搭","Tuyệt đối không ghép chéo 虽然 với 所以!","逆接の「虽然」と因果の「所以」を混ぜてはいけない"],"w":["ไม่ได้ เพราะ 'หนาวมาก → เลยไม่ออกนอกบ้าน' เป็นความสัมพันธ์เหตุและผล (ต้องใช้ 因为……，所以……) ไม่ใช่ความขัดแย้ง (ถ้าจะใช้ 虽然…但是 ต้องหักมุมเป็น 虽然今天很冷，但是我还是出门了!)","Wrong because 'cold → didn't go out' is cause-effect (因为…所以…), not contrast! Contrast requires an unexpected result (虽然很冷，但是我还是出门了).","不行，“冷”与“没出门”是顺理成章的因果关系，须用“因为……所以……”；用“虽然……但是……”须表意料之外的转折。","Không được vì lạnh → không ra ngoài là nhân quả (因为…所以…), không phải tương phản.","「寒い→外出しない」は因果関係なので「因为…所以…」。逆接なら「寒いのに外出した」となる。"],"ref":"HSK 3.0 g3-2-069 · g3-2-070"}],"ex":[["虽然今天很冷，但是天很晴。","Suīrán jīntiān hěn lěng, dànshì tiān hěn qíng.","ถึงแม้วันนี้จะหนาวมาก แต่ฟ้าโปร่งมาก","Although it's very cold today, the sky is very sunny.","Tuy hôm nay rất lạnh nhưng trời rất nắng đẹp.","今日はとても寒いですが、よく晴れています。","虽然"],["他虽然很忙，但是每天都跑步。","Tā suīrán hěn máng, dànshì měi tiān dōu pǎobù.","ถึงแม้เขาจะยุ่งมาก แต่ก็ไปวิ่งทุกวัน","Although he is very busy, he jogs every day.","Tuy anh ấy rất bận nhưng ngày nào cũng chạy bộ.","彼はとても忙しいですが毎日走ります。","但是"],["虽然这件衣服有点儿贵，但是非常舒服。","Suīrán zhè jiàn yīfu yǒudiǎnr guì, dànshì fēicháng shūfu.","ถึงแม้เสื้อตัวนี้จะแพงไปหน่อย แต่ใส่สบายมาก ๆ","Although this shirt is a bit pricey, it's extremely comfortable.","Tuy chiếc áo này hơi đắt nhưng rất thoải mái.","この服は少し高いですがとても快適です。","虽然"],["虽然路很远，但我还是喜欢走路。","Suīrán lù hěn yuǎn, dàn wǒ háishi xǐhuan zǒulù.","ถึงแม้ทางจะไกลมาก แต่ฉันก็ยังชอบเดินอยู่ดี","Although it's far, I still like walking.","Tuy đường xa nhưng tôi vẫn thích đi bộ.","道は遠いですが、やはり歩くのが好きです。","但"],["虽然昨天很累，但是我们都很快乐。","Suīrán zuótiān hěn lèi, dànshì wǒmen dōu hěn kuàilè.","ถึงแม้เมื่อวานจะเหนื่อยมาก แต่พวกเราทุกคนต่างมีความสุขมาก","Although we were very tired yesterday, we were all very happy.","Tuy hôm qua rất mệt nhưng chúng tôi đều rất vui.","昨日は疲れましたがみんな楽しかったです。","但是"]],"err":[["虽然今天很冷，所以我没出门。","因为今天很冷，所以我没出门。","เหตุ–ผลใช้ 因为…所以 (ห้ามจับคู่ 虽然 กับ 所以 ข้ามสาย)","Cause–effect takes 因为…所以; never mismatch 虽然 with 所以.","因果用“因为……所以……”，不能混搭“虽然……所以……”。","Nhân–quả dùng 因为…所以, không ghép chéo 虽然…所以.","因果は「因为…所以…」、「虽然」と「所以」を混ぜない。"]],"rel":["g3-2-070","g3-2-029"]},"g3-2-070":{"t":["ประโยคความซ้อนเหตุ–ผล (因果复句): 因为……，所以…… (เพราะ…ดังนั้น…)","Cause-and-effect sentences (因果复句): 因为……，所以……","复句·因果复句：因为……，所以……","Câu ghép nhân quả (因果复句): 因为……，所以…… (vì…nên…)","因果複文（因果复句）：因为……，所以……（〜なので、だから…）"],"f":["因为 + 原因分句，所以 + 结果分句（因为下雨了，所以我没出门）","主语相同：主语 + 因为……，所以……（我因为太累了，所以没去）"],"why":["因果复句 **因为……，所以……** แปลว่า 'เพราะว่า…ดังนั้น…' ใช้บอกสาเหตุในประโยคแรกแล้วสรุปผลลัพธ์ในประโยคหลัง · ต่างจากภาษาอังกฤษ (ที่ห้าม Because + so คู่กัน) ภาษาจีน **นิยมใช้ 因为 คู่กับ 所以 พร้อมกันอย่างเต็มรูปแบบ!** หรือจะใช้แค่ตัวใดตัวหนึ่ง (ละ 因为 เหลือแต่ 所以 ก็พบบ่อยมาก เช่น 下雨了，所以我没出门) · ข้อควรระวัง 2 ข้อ: (1) ลำดับปกติของจีนคือ **เหตุมาก่อน → ผลมาทีหลัง** (因为…，所以…) ต่างจากภาษาอังกฤษที่นิยมสลับผลขึ้นก่อน (2) ห้ามวาง 所以 ไว้ต้นประโยคหน้า 因为 (ห้ามพูด 所以我没出门，因为下雨了!)","Cause-and-effect sentences **因为……，所以……** ('because…so…') state the CAUSE first and the RESULT second. · Unlike English (which forbids pairing 'because' + 'so'), Chinese **happily pairs BOTH 因为 and 所以 together!** (Dropping 因为 to keep only 所以 is also common.) · Two cautions: (1) Standard Chinese puts Cause FIRST → Result SECOND. (2) NEVER start with 所以 before 因为 (never 所以我没出门，因为下雨了!).","因果复句“因为……，所以……”先说明原因，后得出结果。与英语不同，汉语常成对连用“因为”和“所以”（也可省略“因为”单用“所以”）。 · 注意：标准语序为前因后果，绝不能说“所以我没出门，因为下雨了”。","Câu ghép nhân quả **因为……，所以……** ('vì…nên…') — khác tiếng Anh, tiếng Trung dùng CẢ CẶP 因为 và 所以 rất tự nhiên! · Lưu ý: trật tự chuẩn luôn là Nguyên nhân TRƯỚC → Kết quả SAU; TUYỆT ĐỐI không đảo 所以 lên trước 因为!","因果複文「因为……，所以……」は「〜なので、だから…」。英語と違い中国語では両方ペアで使うのが標準（「因为」を省いて「所以」だけでも可）。 · 注意：常に「原因→結果」の順で、「所以…，因为…」と逆にはできない。"],"use":[{"ok":true,"zh":"因为这家饭馆菜好吃，所以人很多。","fix":"","py":"Yīnwèi zhè jiā fànguǎn cài hǎochī, suǒyǐ rén hěn duō.","tr":["เพราะร้านอาหารร้านนี้กับข้าวอร่อย ดังนั้นคนเลยเยอะมาก","Because the food at this restaurant is delicious, there are lots of people.","Vì đồ ăn quán này ngon nên rất đông người.","このレストランは料理がおいしいので、とても混んでいます。"],"h":["เชื่อม 2 ประโยคเหตุและผลคู่กันด้วย 因为……，所以……","Pair Cause clause and Result clause with 因为……，所以……","“因为……，所以……”成对呼应表因果","Nối 2 mệnh đề nhân–quả bằng cả cặp 因为……，所以……","原因節と結果節を「因为……，所以……」で呼応させる"],"w":["ทำได้และเป็นรูปมาตรฐานที่สุดของภาษาจีน เพราะเหตุ (กับข้าวอร่อย) นำหน้าผล (คนเยอะ) ชัดเจน","Works as the clearest standard Chinese pattern: cause upfront leads directly into the result.","前因后果、关联词成对呼应，清晰有力。","Đúng chuẩn tiếng Trung: nguyên nhân đi trước dẫn sang kết quả.","原因から結果へと「因为…所以…」で明快につながっている。"],"ref":"HSK 3.0 g3-2-070"},{"ok":true,"zh":"明天要考试，所以我今天晚上不看电影了。","fix":"","py":"Míngtiān yào kǎoshì, suǒyǐ wǒ jīntiān wǎnshang bù kàn diànyǐng le.","tr":["พรุ่งนี้ต้องสอบ ดังนั้นคืนนี้ฉันเลยไม่ดูหนังแล้ว","There's an exam tomorrow, so I won't watch a movie tonight.","Ngày mai phải thi nên tối nay tôi không xem phim nữa.","明日試験なので、今夜は映画を見ません。"],"h":["ละ 因为 ออก เหลือแค่ 所以 ตัวเดียวในประโยคหลังได้","You may omit 因为 and keep only 所以 in the second clause","口语常省略“因为”，只保留后分句的“所以”","Khẩu ngữ hay lược 因为, chỉ giữ 所以 ở vế sau","口語では「因为」を省いて「所以」だけ残すのも自然"],"w":["ทำได้และเป็นธรรมชาติมากในภาษาพูดประจำวัน เพราะประโยคแรกเป็นเหตุชัดเจนอยู่แล้ว","Works very naturally in everyday conversation when the first clause is obviously the reason.","前分句原因明确，单用“所以”简洁流畅。","Đúng và gọn trong giao tiếp hằng ngày.","前の文が明らかな理由なので「所以」だけで簡潔に結べる。"],"ref":"HSK 3.0 g3-2-070"},{"ok":false,"zh":"所以我没出门，因为下雨了。","fix":"因为下雨了，所以我没出门。","py":"Yīnwèi xià yǔ le, suǒyǐ wǒ méi chūmén.","tr":["เพราะฝนตกแล้ว ฉันเลยไม่ได้ออกจากบ้าน","Because it rained, I didn't go out.","Vì trời mưa nên tôi không ra ngoài.","雨が降ったので外出しませんでした。"],"h":["ห้ามเอา 所以 ขึ้นต้นประโยคไว้หน้า 因为 เด็ดขาด!","NEVER put 所以 at the start BEFORE 因为!","绝不能把“所以”放在“因为”前面（须先“因为”后“所以”）","Tuyệt đối không đặt 所以 lên trước 因为!","「所以」を「因为」の前に置いてはいけない"],"w":["ไม่ได้ เพราะในภาษาจีนกฎลำดับเหตุ–ผลบังคับให้ 因为 มาก่อนและ 所以 ตามหลังเสมอ (หากต้องการพูดผลก่อนจริง ๆ ต้องตัด 所以 ทิ้งเป็น 我没出门，因为下雨了)","Wrong because Chinese strictly orders 因为 BEFORE 所以 (if you ever state the result first as an afterthought, you MUST drop 所以).","不行，“所以”只能跟在原因后面；若想先说结果补说原因，绝不能用“所以”。","Không được vì 所以 luôn đứng sau nguyên nhân (muốn nói kết quả trước thì bỏ 所以).","「所以」は必ず原因の後ろに置く（「所以…，因为…」は文法誤り）。"],"ref":"HSK 3.0 g3-2-070"}],"ex":[["因为下雨了，所以我没出门。","Yīnwèi xià yǔ le, suǒyǐ wǒ méi chūmén.","เพราะฝนตก ฉันเลยไม่ได้ออกจากบ้าน","Because it rained, I didn't go out.","Vì trời mưa nên tôi không ra ngoài.","雨が降ったので外出しませんでした。","因为"],["因为这家饭馆菜好吃，所以人很多。","Yīnwèi zhè jiā fànguǎn cài hǎochī, suǒyǐ rén hěn duō.","เพราะร้านอาหารร้านนี้กับข้าวอร่อย คนเลยเยอะมาก","Because the food at this restaurant is delicious, there are many people.","Vì quán ăn này đồ ăn ngon nên rất đông người.","このレストランは料理がおいしいので人が多いです。","所以"],["因为路太远了，所以我们打车去了。","Yīnwèi lù tài yuǎn le, suǒyǐ wǒmen dǎchē qù le.","เพราะทางไกลเกินไป พวกเราเลยเรียกแท็กซี่ไป","Because it was too far, we took a taxi.","Vì đường xa quá nên chúng tôi đã bắt taxi đi.","道が遠すぎるのでタクシーで行きました。","所以"],["明天要考试，所以我今天晚上不看电影了。","Míngtiān yào kǎoshì, suǒyǐ wǒ jīntiān wǎnshang bù kàn diànyǐng le.","พรุ่งนี้ต้องสอบ คืนนี้ฉันเลยไม่ดูหนังแล้ว","There's an exam tomorrow, so I won't watch a movie tonight.","Ngày mai thi nên tối nay tôi không xem phim nữa.","明日試験なので今夜は映画を見ません。","所以"],["他因为身体不舒服，所以在家休息。","Tā yīnwèi shēntǐ bù shūfu, suǒyǐ zài jiā xiūxi.","เขาไม่สบาย ดังนั้นเลยพักผ่อนอยู่บ้าน","Because he isn't feeling well, he is resting at home.","Anh ấy vì không khỏe nên ở nhà nghỉ ngơi.","彼は体調が悪いので家で休んでいます。","因为"]],"err":[["所以我没出门，因为下雨了。","因为下雨了，所以我没出门。","ต้องวางเหตุ (因为) ไว้ก่อน ผล (所以) เสมอ","Always put Cause (因为) before Result (所以).","因果复句须前“因为”后“所以”。","Luôn đặt 因为 trước 所以.","必ず原因「因为」が先、結果「所以」が後。"]],"rel":["g3-2-027","g3-2-069","g3-2-006"]},"g3-2-071":{"t":["ประโยคกระชับติดกัน (紧缩复句): 一……就…… (พอ…ก็…ทันที)","Tightened compound sentences (紧缩复句): 一……就…… ('as soon as…')","复句·紧缩复句：一……就……","Câu ghép rút gọn (紧缩复句): 一……就…… (hễ/vừa…là…ngay)","緊縮複文（紧缩复句）：一……就……（〜するとすぐ…）"],"f":["同一主语：主语 + 一 + 动作1 + 就 + 动作2（我一下课就回家）","不同主语：主语1 + 一 + 动作1，主语2 + 就 + 动作2（天一冷，我就头疼）"],"why":["โครงสร้าง **一……就……** เป็นสำนวนกระชับที่คนจีนใช้บ่อยมาก มี 2 ความหมายที่เชื่อมกัน: (1) **พอทำสิ่งหนึ่งเสร็จปุ๊บ ก็ทำอีกสิ่งปั๊บ** ('as soon as…'): 我一下课就回家 (พอเลิกเรียนฉันก็กลับบ้านทันที), 我一到家就给妈妈打电话 (2) **เงื่อนไขธรรมชาติ — พอเกิด A ทีไร ก็เป็น B ทุกที** ('whenever…'): 天一冷，我就头疼 (พออากาศหนาวทีไร ฉันก็ปวดหัวทุกที), 他一喝咖啡就睡不着→他一吃饭就喝茶 · กฎเหล็กเรื่องตำแหน่งประธานที่คนเรียนพลาดบ่อยที่สุด: **一** และ **就** เป็นคำวิเศษณ์ ต้องอยู่ **หลังประธาน หน้ากริยา** ของท่อนตัวเองเสมอ!! (天一冷，我就头疼 ✓ — ห้ามพูด 一天冷，就我头疼 ✗!)","The tightened pattern **一……就……** expresses two closely linked ideas: (1) **Immediate sequence ('as soon as…')**: 我一下课就回家, 我一到家就给妈妈打电话; (2) **Automatic trigger ('whenever…')**: 天一冷，我就头疼 ('Whenever it gets cold, I get a headache'). · #1 learner trap: BOTH **一** and **就** are adverbs — place them AFTER their clause's subject and BEFORE its verb! (天一冷，我就头疼 ✓ — NEVER 一天冷，就我头疼 ✗!)","紧缩复句“一……就……”结构紧凑，表两种关系：（1）两动作紧接着发生（我一下课就回家）；（2）条件与自然结果（天一冷，我就头疼）。 · 第一易错点：“一”和“就”均作副词，必须放在各自的主语之后、动词／形容词之前！（说“天一冷，我就头疼”，绝不说“一天冷，就我头疼”）。","Cấu trúc **一……就……** diễn tả: (1) Vừa làm việc 1 liền làm việc 2 ngay (我一下课就回家); (2) Hễ xảy ra A là dẫn tới B (天一冷，我就头疼). · Lỗi hay gặp nhất: cả 一 và 就 đều phải đứng SAU chủ ngữ của vế mình (天一冷，我就头疼 — TUYỆT ĐỐI không nói 一天冷，就我头疼!).","緊縮複文「一……就……」は（1）「〜するとすぐ…」（我一下课就回家）、（2）「〜すると必ず…」（天一冷，我就头疼）を表す。 · 最重要注意：「一」も「就」も副詞なので必ずそれぞれの主語の後・動詞／形容詞の前に置く（天一冷，我就头疼、「一天冷，就我头疼」は不可！）。"],"use":[{"ok":true,"zh":"我一到家就给妈妈打电话。","fix":"","py":"Wǒ yī dào jiā jiù gěi māma dǎ diànhuà.","tr":["พอฉันถึงบ้านปุ๊บ ก็โทรหาแม่ทันที","As soon as I get home, I call Mom.","Tôi vừa về đến nhà là gọi điện cho mẹ ngay.","家に着いたらすぐ母に電話します。"],"h":["ประธานคนเดียวกัน: ประธาน + 一 + กริยา1 + 就 + กริยา2","Same subject: Subject + 一 + Verb 1 + 就 + Verb 2","同主语：主语＋一＋动作1＋就＋动作2","Cùng chủ ngữ: Chủ ngữ + 一 + Động từ 1 + 就 + Động từ 2","同一主語：「主語＋一＋動作1＋就＋動作2」"],"w":["ทำได้และกระชับฉับไวมาก โดยวางประธาน 我 ไว้หน้าสุดครั้งเดียวแล้วใช้ 一…就 เชื่อมสองกริยาติดกันโดยไม่ต้องมีจุลภาค","Works briskly: put shared subject 我 upfront once and link the two actions tightly with 一…就.","前后主语相同，“一……就……”紧缩在一句中，节奏明快。","Đúng và rất gọn vì chủ ngữ 我 đứng đầu rồi 一…就 nối sát 2 hành động.","同一主語「我」を先頭に置き、読点なしで「一…就…」とテンポよく結んでいる。"],"ref":"HSK 3.0 g3-2-071"},{"ok":true,"zh":"天一冷，我就头疼。","fix":"","py":"Tiān yī lěng, wǒ jiù tóu téng.","tr":["พออากาศหนาวทีไร ฉันก็ปวดหัวทุกที","Whenever the weather gets cold, I get a headache.","Trời hễ lạnh là tôi lại đau đầu.","寒くなるとすぐ頭が痛くなります。"],"h":["คนละประธาน: ประธาน1 + 一 + กริยา1，ประธาน2 + 就 + กริยา2","Different subjects: Subj 1 + 一 + V1, Subj 2 + 就 + V2","不同主语：主语1＋一……，主语2＋就……","Khác chủ ngữ: Chủ ngữ 1 + 一…, Chủ ngữ 2 + 就…","別主語：「主語1＋一…，主語2＋就…」"],"w":["ทำได้เพราะประธานท่อนแรกคือ 天 (อากาศ) จึงวาง 一 หลัง 天 ส่วนประธานท่อนสองคือ 我 (ฉัน) จึงวาง 就 หลัง 我 ถูกต้อง 100%","Works 100% cleanly: 一 sits after Subject 1 (天), and 就 sits after Subject 2 (我).","“一”在主语1“天”后，“就”在主语2“我”后，语序完全正确。","Đúng 100%: 一 đứng sau 天, 就 đứng sau 我.","「一」は主語1「天」の後ろ、「就」は主語2「我」の後ろに置く正確な語順。"],"ref":"HSK 3.0 g3-2-071"},{"ok":false,"zh":"一天冷，就我头疼。","fix":"天一冷，我就头疼。","py":"Tiān yī lěng, wǒ jiù tóu téng.","tr":["พออากาศหนาว ฉันก็ปวดหัวทันที","Whenever it gets cold, I get a headache.","Hễ trời lạnh là tôi đau đầu.","寒くなるとすぐ頭が痛くなります。"],"h":["ห้ามวาง 一 หรือ 就 ไว้หน้าประธานเด็ดขาด!","NEVER put 一 or 就 BEFORE a subject!","“一”和“就”绝不能放在主语前面（天一冷，我就头疼）","Tuyệt đối không đặt 一 hay 就 TRƯỚC chủ ngữ!","「一」も「就」も主語の前に置けない（天一冷，我就头疼）"],"w":["ไม่ได้ เพราะทั้ง 一 และ 就 เป็นคำวิเศษณ์ ต้องอยู่หลังประธานของแต่ละท่อนเสมอ (天一冷 ไม่ใช่ 一天冷 ที่แปลว่า 'หนาวหนึ่งวัน'! และ 我就 ไม่ใช่ 就我!)","Wrong because 一天冷 means 'cold for one day'! Both 一 and 就 must follow their subjects: 天一冷，我就头疼.","不行，“一天冷”意思完全不对，“一”和“就”都必须放在主语后：天一冷，我就头疼。","Không được vì 一天冷 sẽ thành 'lạnh một ngày'! Phải đặt 一 và 就 SAU chủ ngữ: 天一冷，我就头疼.","「一天冷」だと「1日寒い」になってしまう。「一」「就」は必ず主語の後ろに置く。"],"ref":"HSK 3.0 g3-2-071 · g3-2-019"}],"ex":[["我一下课就回家。","Wǒ yī xiàkè jiù huí jiā.","พอเลิกเรียนฉันก็กลับบ้านทันที","As soon as class ends, I go straight home.","Tôi vừa tan học là về nhà ngay.","授業が終わるとすぐ帰ります。","一"],["我一到家就给妈妈打电话。","Wǒ yī dào jiā jiù gěi māma dǎ diànhuà.","พอถึงบ้านปุ๊บฉันก็โทรหาแม่ทันที","As soon as I get home, I call Mom.","Tôi vừa về đến nhà là gọi điện cho mẹ ngay.","家に着くやいなや母に電話します。","就"],["天一冷，我就头疼。","Tiān yī lěng, wǒ jiù tóu téng.","พออากาศหนาวทีไร ฉันก็ปวดหัวทุกที","Whenever it gets cold, I get a headache.","Trời hễ lạnh là tôi đau đầu.","寒くなるとすぐ頭が痛くなります。","一"],["老师一进来，大家就不说话了。","Lǎoshī yī jìnlai, dàjiā jiù bù shuōhuà le.","พอคุณครูเดินเข้ามาปุ๊บ ทุกคนก็เงียบไม่คุยกันทันที","As soon as the teacher walked in, everyone stopped talking.","Thầy giáo vừa bước vào, mọi người liền im lặng ngay.","先生が入って来るとすぐ、みんな静かになりました。","就"],["他一看见小猫就笑了。","Tā yī kànjiàn xiǎo māo jiù xiào le.","พอเขาเห็นลูกแมวปุ๊บก็ยิ้มออกมาทันที","As soon as he saw the kitten, he smiled.","Anh ấy vừa thấy mèo con là mỉm cười ngay.","彼は子猫を見るなり笑顔になりました。","就"]],"err":[["一天冷，就我头疼。","天一冷，我就头疼。","ทั้ง 一 และ 就 ต้องวางหลังประธานของท่อนตัวเองเสมอ","Put both 一 and 就 AFTER their respective subjects.","“一”和“就”都必须放在主语后面。","Cả 一 và 就 đều phải đứng SAU chủ ngữ.","「一」も「就」も必ず主語の後ろに置く。"]],"rel":["g3-2-019","g3-2-070"]},"g3-2-072":{"t":["การณ์ลักษณะต่อเนื่อง 1 (持续态1): กริยา + 着 (สภาพที่ยังคงค้างอยู่)","Continuous aspect 1 (持续态1): Verb + 着 (ongoing state)","动作的态·持续态（1）：动词+着（表示状态的持续）","Thể duy trì 1 (持续态1): Động từ + 着 (trạng thái tiếp diễn)","持続アスペクト1（持续态1）：動詞＋着（状態の持続）"],"f":["肯定：主语 + 动词 + 着（+ 宾语）（门开着 / 他手里拿着一本书）","否定：主语 + 没（有）+ 动词 + 着（门没开着）"],"why":["持续态 แบบที่ 1 (表示状态的持续) ใช้ **กริยา + 着** เพื่อบรรยาย 'ภาพนิ่ง / ผลลัพธ์ที่ค้างอยู่' หลังจากการกระทำนั้นเกิดขึ้นแล้ว (ไม่ใช่กำลังขยับมือทำเหมือน 正在!) · ตัวอย่างเปรียบเทียบให้เห็นภาพชัด 100%: (1) 他正在开门 = เขากำลังจับลูกบิดเปิดประตูอยู่เดี๋ยวนี้ (กำลังเคลื่อนไหว) vs 门开着 = ประตูเปิดอ้าค้างอยู่แล้ว (ภาพนิ่ง) (2) 他正在拿书 = เขากำลังเอื้อมมือหยิบหนังสือ vs 他手里拿着书 = เขาถือหนังสือค้างอยู่ในมือ · ข้อควรระวัง: ปฏิเสธสภาพใช้ **没 + กริยา + 着** (门没开着) และคำถามใช้ **…着吗？ / …着没有？** (电视开着吗？)","Continuous aspect 1 (**Verb + 着**) describes a STILL, PERSISTING STATE left behind by an action — sharply distinct from dynamic 正在! · Crystal-clear contrast: (1) 他正在开门 ('he is in the act of opening the door') vs 门开着 ('the door is standing open'); (2) 他手里拿着一本书 ('he is holding a book in his hand'). · Caution: negate with **没 + Verb + 着** (门没开着), and ask with **…着吗？** (电视开着吗？).","持续态（1）“动词＋着”描写动作完成后所遗留状态的静态持续，区别于“正在”的动态进行：门开着（静态敞开）vs 正在开门（正在推开）；手里拿着书（静态持握）。 · 否定用“没（有）＋动词＋着”，疑问用“……着吗？”。","Thể duy trì (1) **Động từ + 着** miêu tả TRẠNG THÁI TĨNH còn lưu lại sau hành động — khác hẳn 正在 đang cử động: 门开着 (cửa đang mở sẵn) vs 正在开门 (đang đẩy cửa ra); 手里拿着书 (đang cầm sẵn sách trên tay). · Phủ định dùng 没 + động từ + 着.","持続アスペクト（1）「動詞＋着」は動作の結果生じた静的な状態の持続を描写し、動的な「正在」と区別される：门开着（ドアが開いている）vs 正在开门（今ドアを開けている最中）。 · 否定は「没（有）＋動詞＋着」。"],"use":[{"ok":true,"zh":"电视开着呢，谁在看电视？","fix":"","py":"Diànshì kāizhe ne, shéi zài kàn diànshì?","tr":["ทีวีเปิดค้างอยู่นะ ใครกำลังดูทีวีอยู่เหรอ","The TV is on — who is watching TV?","TV đang bật kìa, ai đang xem TV thế?","テレビがついていますよ、誰が見ているんですか。"],"h":["สภาพเปิดค้างอยู่ ใช้ 开着 (+ 呢) คู่กับประโยค 正在/在 ที่กำลังทำได้ชัด","Use 开着 (+ 呢) for 'left on', contrasting cleanly with 在 + verb ('watching')","“开着”表状态持续，“在看”表动作进行，分工清晰","开着 chỉ trạng thái đang bật sẵn, đối chiếu rõ với 在看 đang xem","状態の持続「开着」と動作の進行「在看」を見事に使い分けている"],"w":["ทำได้และเห็นความต่างของ 着 กับ 在 ในประโยคเดียวชัดเลย: 电视开着 (ทีวีอยู่ในสภาพเปิดอยู่) ส่วน 谁在看电视 (ใครกำลังดูอยู่)","Works brilliantly showing both aspects side-by-side: 电视开着 (static state 'is on') vs 在看电视 (ongoing action).","同句对比“开着”（静态开启）与“在看”（动态观看），一目了然。","Đúng và minh họa rõ sự khác biệt giữa 着 (tĩnh) và 在 (động) ngay trong một câu.","「开着」（電源が入っている状態）と「在看」（見ている動作）の対比が一目瞭然。"],"ref":"HSK 3.0 g3-2-072"},{"ok":true,"zh":"他穿着一件白色的衣服。","fix":"","py":"Tā chuānzhe yī jiàn báisè de yīfu.","tr":["เขาสวมเสื้อสีขาวตัวหนึ่งอยู่","He is wearing a white shirt.","Anh ấy đang mặc một chiếc áo màu trắng.","彼は白い服を着ています。"],"h":["บรรยายเสื้อผ้าที่สวมใส่อยู่บนตัว ใช้ 穿着 (ไม่ใช้ 正在穿!)","Describe what someone is WEARING with 穿着 (NOT 正在穿!)","描写穿着打扮的状态用“穿着”，正在穿衣服才用“正在穿”","Miêu tả bộ đồ đang mặc trên người dùng 穿着 (không dùng 正在穿)","服を着ている状態は「穿着」（今袖を通している最中が「正在穿」）"],"w":["ทำได้และเป็นจุดแยกที่สำคัญมาก: 他穿着白色衣服 = เขาสวมเสื้อขาวอยู่ (ใส่เสร็จแล้ว) ส่วน 他正在穿衣服 = เขากำลังแต่งตัวสวมเสื้ออยู่!","Works as a classic textbook distinction: 穿着 = wearing (already on), whereas 正在穿 = putting clothes on right now!","“穿着”指已穿在身上的状态，“正在穿”指正在往身上套衣服的动作。","Đúng và là điểm phân biệt kinh điển: 穿着 (đang mặc trên người) vs 正在穿 (đang xỏ tay vào áo).","「穿着」は着用している状態、「正在穿」は今まさに着替えている動作。"],"ref":"HSK 3.0 g3-2-072"},{"ok":false,"zh":"他正在穿一件白色的衣服，在教室里上课。","fix":"他穿着一件白色的衣服，在教室里上课。","py":"Tā chuānzhe yī jiàn báisè de yīfu, zài jiàoshì lǐ shàngkè.","tr":["เขาสวมเสื้อสีขาวตัวหนึ่งเรียนอยู่ในห้องเรียน","He is wearing a white shirt, attending class in the classroom.","Anh ấy mặc một chiếc áo màu trắng, đang học trong lớp.","彼は白い服を着て教室で授業を受けています。"],"h":["บรรยายชุดที่ใส่อยู่ขณะทำอย่างอื่น ใช้ 穿着 ห้ามใช้ 正在穿!","To describe what someone is wearing while doing something, use 穿着 — NOT 正在穿!","描写已穿在身上的衣服用“穿着”，不能用“正在穿”","Miêu tả đồ mặc sẵn trên người dùng 穿着, không dùng 正在穿!","着ている服装の描写に「正在穿」は不可（必ず「穿着」）"],"w":["ไม่ได้ เพราะ 正在穿 แปลว่าเขากำลังถอด/สวมเสื้อผ้ากลางห้องเรียน! ถ้าหมายถึง 'ใส่เสื้อสีขาวอยู่' ต้องใช้ 穿着 เท่านั้น","Wrong because 正在穿 means he is actively getting dressed in the middle of class! Use 穿着 for 'wearing'.","不行，“正在穿”变成正在教室里穿衣的动作；表示身上穿着必须用“穿着”。","Không được vì 正在穿 nghĩa là đang xỏ áo giữa lớp! Phải dùng 穿着.","「正在穿」だと教室で着替えている最中になってしまう。「穿着」にする。"],"ref":"HSK 3.0 g3-2-072"}],"ex":[["门开着呢。","Mén kāizhe ne.","ประตูเปิดค้างอยู่นะ","The door is open.","Cửa đang mở đấy.","ドアが開いていますよ。","开着"],["他穿着一件白色的衣服。","Tā chuānzhe yī jiàn báisè de yīfu.","เขาสวมเสื้อสีขาวตัวหนึ่งอยู่","He is wearing a white shirt.","Anh ấy đang mặc một chiếc áo trắng.","彼は白い服を着ています。","穿着"],["他手里拿着一本书。","Tā shǒu lǐ názhe yī běn shū.","ในมือเขาถือหนังสืออยู่หนึ่งเล่ม","He is holding a book in his hand.","Trong tay anh ấy đang cầm một cuốn sách.","彼は手に本を1冊持っています。","拿着"],["电视开着，谁在看？","Diànshì kāizhe, shéi zài kàn?","ทีวีเปิดค้างอยู่ ใครกำลังดูเหรอ","The TV is on; who's watching?","TV đang bật, ai đang xem vậy?","テレビがついていますが誰が見ていますか。","开着"],["教室的门没开着。","Jiàoshì de mén méi kāizhe.","ประตูห้องเรียนไม่ได้เปิดอยู่","The classroom door is not open.","Cửa phòng học không mở.","教室のドアは開いていません。","没开着"]],"err":[["教室的门不开着。","教室的门没开着。","ปฏิเสธสภาพต่อเนื่อง 着 ใช้ 没 + กริยา + 着 ไม่ใช้ 不","Negate ongoing state 着 with 没, never 不.","否定状态持续用“没＋动词＋着”。","Phủ định trạng thái 着 dùng 没, không dùng 不.","状態の持続「着」の否定は「不」ではなく「没」。"]],"rel":["g3-2-032","g3-2-073","g3-2-060"]},"g3-2-073":{"t":["การณ์ลักษณะต่อเนื่อง 2 (持续态2): กริยา1 + 着 + กริยา2 (ทำควบคู่/ดำเนินต่อเนื่อง)","Continuous aspect 2 (持续态2): Verb 1 + 着 + Verb 2 (ongoing / accompanying action)","动作的态·持续态（2）：动词+着（表示动作的持续）","Thể duy trì 2 (持续态2): Động từ 1 + 着 + Động từ 2 (hành động song song)","持続アスペクト2（持续态2）：動詞＋着（動作の持続・付帯状況）"],"f":["方式伴随：主语 + 动词1 + 着 +（宾语1）+ 动词2（他笑着说 / 坐着看书 / 走着去）","动作持续：主语 + 动词 + 着 +（宾语）+ 呢（我在门口等着你呢）"],"why":["持续态 แบบที่ 2 (表示动作的持续) ใช้ **กริยา + 着** ใน 2 สถานการณ์หลัก: (1) **ทำกริยา 2 โดยอยู่ในอาการ/วิธีการของกริยา 1 ควบคู่ไปด้วย** (`V1 + 着 + V2`): เช่น 他笑着说 (เขาพูดพลางยิ้มไป), 别站着说话，坐着说吧 (อย่ายืนคุยเลย นั่งคุยกันเถอะ), 我们走着去学校 (พวกเราเดินไปโรงเรียน — เน้นวิธีเดินทาง), 听着音乐学习→拿着手机看书 (2) **กริยาที่ดำเนินค้างรออยู่ต่อเนื่อง**: 我在门口等着你呢 (ฉันยืนรอคุณอยู่ที่หน้าประตูนะ) · ข้อควรระวังเด็ดขาด: ลำดับกริยาใน `V1 + 着 + V2` ห้ามสลับผิดหน้าที่! **กริยาที่เป็น 'ท่าทาง/อาการประกอบ' อยู่หน้าพร้อม 着** ส่วน **กริยาหลักที่ตั้งใจทำอยู่หลัง** (坐着看书 = นั่งอ่านหนังสือ ✓ — ถ้าสลับเป็น 看着书坐 จะกลายเป็น 'นั่งลงไปพร้อมจ้องหนังสือ' ความหมายเปลี่ยนทันที!)","Continuous aspect 2 (**Verb + 着**) covers two active uses: (1) **Accompanying manner (`V1 + 着 + V2`)** — doing main action V2 while maintaining posture/manner V1: 他笑着说 ('said while smiling'), 坐着看书 ('read sitting down'), 走着去 ('go on foot'); (2) **Sustained action**: 我在门口等着你呢 ('I'm waiting for you at the door'). · Key rule: NEVER swap V1 and V2! Put the accompanying posture/manner FIRST with 着, and the MAIN action SECOND (坐着看书 ✓).","持续态（2）“动词＋着”表示动作本身的持续，主要有两种用法：（1）“动词1＋着＋动词2”表伴随方式，动词1是次要方式或姿态，动词2是主要动作（他笑着说、坐着看书、走着去）；（2）表示动作持续进行中（我在门口等着你呢）。 · 注意：“V1着＋V2”中方式姿态在前、主要动作在后，顺序不能颠倒。","Thể duy trì (2) **Động từ + 着** dùng trong 2 trường hợp: (1) `Động từ 1 + 着 + Động từ 2` chỉ tư thế/cách thức đi kèm (他笑着说 = vừa cười vừa nói, 坐着看书 = ngồi đọc sách, 走着去 = đi bộ đến); (2) Hành động đang tiếp diễn chờ đợi (我在门口等着你呢). · Lưu ý: tư thế/cách thức + 着 đứng TRƯỚC, hành động chính đứng SAU.","持続アスペクト（2）「動詞＋着」は動作の持続を表す：（1）付帯状況「動詞1＋着＋動詞2」（他笑着说＝笑いながら話す、坐着看书＝座って本を読む、走着去＝歩いて行く）、（2）動作の継続（我在门口等着你呢）。 · 注意：姿勢・手段（V1＋着）が先、主動作（V2）が後。"],"use":[{"ok":true,"zh":"别站着说话了，请坐着说吧。","fix":"","py":"Bié zhànzhe shuōhuà le, qǐng zuòzhe shuō ba.","tr":["อย่ายืนคุยกันอยู่เลย เชิญนั่งคุยกันเถอะ","Don't talk standing up — please sit down and talk.","Đừng đứng nói chuyện nữa, mời ngồi nói đi.","立ったまま話さないで、座って話しましょう。"],"h":["ท่าทางประกอบ + 着 + กริยาหลัก (站着说 / 坐着说 / 笑着说)","Posture/manner + 着 + Main verb (站着说 / 坐着说 / 笑着说)","姿态动作加“着”放主要动词前：站着说、坐着说、笑着说","Tư thế + 着 + động từ chính (站着说 / 坐着说 / 笑着说)","姿勢・様子＋「着」＋主動作（站着说・坐着说・笑着说）"],"w":["ทำได้และเป็นธรรมชาติมาก โดย 站着 (ยืนอยู่) กับ 坐着 (นั่งอยู่) เป็นท่าทางประกอบกริยาหลัก 说 (พูด)","Works super naturally: 站着 (standing) and 坐着 (sitting) specify the posture for the main verb 说.","“站着、坐着”标示“说话”时的身体姿态，地道自然。","Đúng và cực tự nhiên: 站着 / 坐着 chỉ tư thế khi thực hiện động từ chính 说.","「站着」「坐着」が主動作「说」の姿勢を自然に修飾している。"],"ref":"HSK 3.0 g3-2-073"},{"ok":true,"zh":"学校很近，我每天走着去。","fix":"","py":"Xuéxiào hěn jìn, wǒ měi tiān zǒuzhe qù.","tr":["โรงเรียนใกล้มาก ฉันเดินไปทุกวันเลย","The school is very close; I go on foot every day.","Trường rất gần, ngày nào tôi cũng đi bộ tới.","学校はとても近いので毎日歩いて行きます。"],"h":["บอกวิธีเดินทางด้วยกริยา 走着去 / 跑着去","Express travel manner with 走着去 ('go on foot') / 跑着去","“走着去／跑着去”表移动方式","Chỉ cách di chuyển bằng 走着去 (đi bộ tới) / 跑着去","移動手段としての「走着去」（歩いて行く）"],"w":["ทำได้เพราะ 走着 (เดินไปเรื่อย ๆ) เป็นวิธีการเคลื่อนที่ที่ขยายกริยาหลัก 去 (ไป) ได้กระชับและเป็นธรรมชาติ","Works idiomatically because 走着 expresses the sustained manner ('on foot') modifying 去.","“走着”修饰“去”，表示步行前往的方式。","Đúng vì 走着 chỉ cách thức đi bộ bổ nghĩa cho 去.","「走着」が「去」の手段（徒歩で）を表す自然な表現。"],"ref":"HSK 3.0 g3-2-073"},{"ok":false,"zh":"我坐看书着。","fix":"我坐着看书。","py":"Wǒ zuòzhe kàn shū.","tr":["ฉันนั่งอ่านหนังสือ","I sit and read a book.","Tôi ngồi đọc sách.","私は座って本を読みます。"],"h":["着 ต้องเกาะติดกริยาท่าทางตัวแรก (坐着) ห้ามย้ายไปท้ายประโยค!","着 MUST attach directly to V1 (坐着), NEVER at the end of the sentence!","“着”必须紧贴第一动词（坐着看书），绝不能放到句尾","着 bắt buộc bám sát động từ 1 (坐着看书), không đẩy ra cuối câu!","「着」は必ず動詞1（坐着）の直後に付け、文末に置かない"],"w":["ไม่ได้ เพราะ 着 เกาะติดกริยาที่บอกท่าทางประกอบ (坐 → 坐着) แล้วค่อยต่อด้วยกริยาหลัก 看书 เสมอ: 我坐着看书","Wrong because 着 attaches directly to the posture verb 坐 (坐着) BEFORE main verb 看书: 我坐着看书.","不行，“着”只能紧跟姿态动词“坐”后面：我坐着看书。","Không được vì 着 gắn sát động từ tư thế 坐 (坐着) rồi mới đến 看书.","「着」は必ず姿勢動詞「坐」の直後に付けて「我坐着看书」にする。"],"ref":"HSK 3.0 g3-2-073"}],"ex":[["他笑着对我说你好。","Tā xiàozhe duì wǒ shuō nǐ hǎo.","เขายิ้มพลางพูดสวัสดีกับฉัน","He smiled and said hello to me.","Anh ấy vừa cười vừa chào tôi.","彼は笑いながら私にこんにちはと言いました。","笑着"],["别站着说话，坐着说吧。","Bié zhànzhe shuōhuà, zuòzhe shuō ba.","อย่ายืนคุยเลย นั่งคุยกันเถอะ","Don't talk standing up; sit down and talk.","Đừng đứng nói chuyện, ngồi nói đi.","立ったまま話さないで座って話そう。","站着"],["学校很近，我每天走着去。","Xuéxiào hěn jìn, wǒ měi tiān zǒuzhe qù.","โรงเรียนใกล้มาก ฉันเดินไปทุกวัน","School is very close; I walk there every day.","Trường rất gần, ngày nào tôi cũng đi bộ tới.","学校は近いので毎日歩いて行きます。","走着"],["我在门口等着你呢。","Wǒ zài ménkǒu děngzhe nǐ ne.","ฉันรอคุณอยู่ที่หน้าประตูนะ","I'm waiting for you at the doorway.","Tôi đang đợi bạn ở cửa đấy.","入口であなたを待っていますよ。","等着"],["他手里拿着咖啡走进来了。","Tā shǒu lǐ názhe kāfēi zǒu jìnlai le.","เขาถือแก้วกาแฟอยู่ในมือเดินเข้ามาแล้ว","He walked in holding a cup of coffee.","Anh ấy tay cầm cà phê bước vào rồi.","彼は手にコーヒーを持って入って来ました。","拿着"]],"err":[["我坐看书着。","我坐着看书。","着 ต้องติดหลังกริยาท่าทางตัวแรกเสมอ (坐着看书)","Always attach 着 directly to V1 (坐着看书).","“着”紧跟第一动词后：我坐着看书。","着 luôn gắn sát động từ 1: 我坐着看书.","「着」は必ず動詞1の直後に置く（我坐着看书）。"]],"rel":["g3-2-072","g3-2-032","g3-2-060"]},"g3-2-074":{"t":["การณ์ลักษณะประสบการณ์ (经历态): กริยา + 过 (เคยทำมาแล้ว)","Experiential aspect (经历态): Verb + 过 ('have ever experienced')","动作的态·经历态：用动态助词“过”表示","Thể kinh nghiệm (经历态): Động từ + 过 (đã từng trải qua)","経験アスペクト（经历态）：動詞＋过（〜したことがある）"],"f":["肯定：主语 + 动词 + 过 +（数量/宾语）：我去过两次北京","否定：主语 + 没（有）+ 动词 + 过 +（宾语）：我没去过北京","疑问：主语 + 动词 + 过 + 宾语 + 吗 / 没有？（你吃过吗？）"],"why":["经历态 ใช้ **กริยา + 过** เพื่อบอกว่าประธาน 'เคยผ่านประสบการณ์นั้นมาแล้วอย่างน้อย 1 ครั้งในอดีต' และเหตุการณ์นั้นจบลงไปแล้วไม่ค้างถึงปัจจุบัน · เทียบให้ขาดระหว่าง **了1 (完成态)** กับ **过 (经历态)**: (1) 他去了北京 = เขาไปปักกิ่งแล้ว (ตอนนี้อาจยังอยู่ที่ปักกิ่ง!) vs 他去过北京 = เขาเคยไปปักกิ่ง (เป็นประสบการณ์ ตอนนี้กลับมาแล้วไม่ได้อยู่ที่นั่น!) (2) ปฏิเสธ **了1** ต้องตัด 了 ออก (没去) แต่ปฏิเสธ **过** ต้องเก็บ 过 ไว้เสมอ (没去过!) · ข้อควรระวัง: (1) ห้ามใช้ 过 คู่กับกริยาที่เกิดได้ครั้งเดียวในชีวิต (2) หากมีจำนวนครั้ง (一次 / 两次) วางไว้หลัง 过 ทันที (我去过两次北京)","Experiential aspect (**Verb + 过**) states that the subject has had that life experience at least once before, and it is NO LONGER ongoing now. · Crucial contrast — **了1** vs **过**: (1) 他去了北京 ('He went to Beijing' — might still be there!) vs 他去过北京 ('He has been to Beijing' — already back!). (2) Negating 了1 drops 了 (没去), whereas negating 过 ALWAYS keeps 过 (没去过!). · Number of times follows 过 directly: 我去过两次北京.","经历态“动词＋过”表示过去曾经有过某种经历，且该状态现已结束。 · 与“了1”对比：（1）“他去了北京”（现在可能还在北京）vs“他去过北京”（曾有经历，现在不在北京）；（2）否定“了1”去“了”，否定“过”必须保留“过”（没去过）。 · 动量词紧跟“过”后（去过两次北京）。","Thể kinh nghiệm (**Động từ + 过**) chỉ trải nghiệm từng có trong quá khứ và đã kết thúc. · So sánh 了1 vs 过: 他去了北京 (có thể giờ vẫn ở Bắc Kinh) vs 他去过北京 (từng đi, giờ không ở đó nữa); phủ định 过 LUÔN giữ 过 (没去过!).","経験アスペクト（動詞＋过）は過去にその経験があり、現在はすでに終了していることを表す。 · 「了1」との決定的な違い：「他去了北京」（今北京にいるかも）vs「他去过北京」（行った経験があるが今はそこにいない）。否定では必ず「过」を残す（没去过）。"],"use":[{"ok":true,"zh":"我去过两次北京，那里很漂亮。","fix":"","py":"Wǒ qùguo liǎng cì Běijīng, nàlǐ hěn piàoliang.","tr":["ฉันเคยไปปักกิ่งสองครั้ง ที่นั่นสวยมาก","I have been to Beijing twice; it's very pretty there.","Tôi đã từng đi Bắc Kinh hai lần, ở đó rất đẹp.","北京へ2回行ったことがあります、あそこはとてもきれいです。"],"h":["เล่าประสบการณ์พร้อมจำนวนครั้ง: กริยา + 过 + จำนวนครั้ง + สถานที่","Share past experience + count: Verb + 过 + count + place","经历态带次数：“动词＋过＋数词＋次＋宾语”","Kể kinh nghiệm kèm số lần: Động từ + 过 + số + 次 + nơi chốn","経験＋回数：「動詞＋过＋数詞＋次＋場所」"],"w":["ทำได้เพราะ 过 บอกชัดเจนว่าเคยไปมาแล้วและกลับมาแล้ว จึงสามารถบอกความประทับใจได้ว่า ที่นั่นสวยมาก","Works naturally because 过 frames Beijing as a completed past trip, letting you comment on how pretty it was.","“去过两次北京”表明曾到访过两次，自然引出评价。","Đúng vì 去过两次北京 khẳng định từng đi 2 lần nên nhận xét được nơi đó rất đẹp.","「2回行った経験がある」ことを「去过两次北京」で表し感想につなげている。"],"ref":"HSK 3.0 g3-2-074 · g3-2-013"},{"ok":true,"zh":"你看过那个电影没有？","fix":"","py":"Nǐ kànguo nàge diànyǐng méiyǒu?","tr":["คุณเคยดูหนังเรื่องนั้นหรือยัง","Have you ever seen that movie?","Bạn đã từng xem bộ phim đó chưa?","あの映画を見たことがありますか。"],"h":["ถามประสบการณ์ได้ทั้ง …过…吗？ และ …过…没有？","Ask about experience using either …过…吗？ or …过…没有？","经历态疑问可用“动词＋过＋宾语＋吗／没有？”","Hỏi kinh nghiệm dùng …过…吗？ hoặc …过…没有？","経験の疑問文は「…过…吗？」または「…过…没有？」"],"w":["ทำได้และเป็นรูปคำถามภาษาพูดที่คนจีนใช้บ่อยมาก ตอบสั้น ๆ ว่า 看过 หรือ 没看过 ได้เลย","Works as a super-common spoken question form; reply simply 看过 or 没看过.","口语常用“……过……没有？”提问，答“看过／没看过”。","Đúng và rất phổ biến trong khẩu ngữ (đáp gọn: 看过 / 没看过).","口語でよく使う疑問形で、返答は「看过／没看过」でOK。"],"ref":"HSK 3.0 g3-2-074"},{"ok":false,"zh":"我没吃过这个菜了。","fix":"我没吃过这个菜。","py":"Wǒ méi chīguo zhège cài.","tr":["ฉันไม่เคยกินอาหารจานนี้มาก่อน","I have never eaten this dish.","Tôi chưa từng ăn món này.","この料理は食べたことがありません。"],"h":["ปฏิเสธประสบการณ์ (没 + กริยา + 过) ห้ามใส่ 了 ปิดท้ายซ้อน!","Do NOT add completed 了 onto negative 没 + Verb + 过!","否定经历态说“没吃过……”，句尾不加表完成的“了”","Phủ định kinh nghiệm (没吃过) không thêm 了 thừa ở cuối!","経験の否定「没＋動詞＋过」に完了の「了」を重ねない"],"w":["ไม่ได้ เพราะ 没吃过 แปลว่าไม่เคยมีประสบการณ์กินมาก่อนเลย จึงขัดกับการเติม 了 ท้ายประโยค ต้องตัด 了 ออกเป็น 我没吃过这个菜","Wrong because 没吃过 states you have never eaten it — drop trailing 了 → 我没吃过这个菜.","不行，“没吃过”表从未经历，不能与“了”搭配。","Không được vì 没吃过 (chưa từng ăn) không đi chung với 了.","「没吃过」は一度も経験がないという意味なので文末の「了」を省く。"],"ref":"HSK 3.0 g3-2-074"}],"ex":[["我去过两次北京。","Wǒ qùguo liǎng cì Běijīng.","ฉันเคยไปปักกิ่งสองครั้ง","I have been to Beijing twice.","Tôi đã từng đi Bắc Kinh hai lần.","北京へ2回行ったことがあります。","过"],["我没吃过这个菜。","Wǒ méi chīguo zhège cài.","ฉันไม่เคยกินอาหารจานนี้","I have never eaten this dish.","Tôi chưa từng ăn món này.","この料理は食べたことがありません。","没吃过"],["你看过那个电影没有？","Nǐ kànguo nàge diànyǐng méiyǒu?","คุณเคยดูหนังเรื่องนั้นไหม","Have you ever seen that movie?","Bạn từng xem bộ phim đó chưa?","あの映画を見たことがありますか。","看过"],["他学过两年汉语。","Tā xuéguo liǎng nián Hànyǔ.","เขาเคยเรียนภาษาจีนมาสองปี (ตอนนี้ไม่ได้เรียนแล้ว)","He studied Chinese for two years before.","Anh ấy từng học tiếng Trung hai năm.","彼は以前中国語を2年学んだことがあります。","学过"],["我找过他一次。","Wǒ zhǎoguo tā yī cì.","ฉันเคยไปหาเขาครั้งหนึ่ง","I looked for him once before.","Tôi đã từng tìm anh ấy một lần.","彼を一度訪ねたことがあります。","找过"]],"err":[["我没吃过这个菜了。","我没吃过这个菜。","ปฏิเสธประสบการณ์ใช้ 没 + กริยา + 过 เฉย ๆ ไม่ใส่ 了 ท้ายประโยค","Negate experience with 没 + Verb + 过 without trailing 了.","否定经历态用“没＋动词＋过”，不加“了”。","Phủ định kinh nghiệm dùng 没 + động từ + 过, không thêm 了.","経験の否定「没＋動詞＋过」に「了」を付けない。"]],"rel":["g3-2-031","g3-1-062","g3-2-013"]},"g3-2-075":{"t":["วิธีบอกลำดับที่ 2 (序数表示法2): ตัวเลข + ลักษณนาม/นาม (ไม่ใส่ 第)","Ordinals 2 (序数表示法2): ordinals without 第 (一楼 / 二班 / 三号)","特殊表达法·数的表达法：序数表示法2：数词+量词","Số thứ tự 2 (序数表示法2): Số từ + đơn vị (không cần 第)","序数の表し方2（序数表示法2）：「第」を使わない序数"],"f":["数词 + 楼 / 班 / 月 / 号 / 路（二楼 / 二班 / 二月 / 二号，绝不用“两”！）"],"why":["นอกจากใช้ **第 + ตัวเลข** (HSK 1) แล้ว ในชีวิตประจำวันของจีนมีหมวดคำที่เป็น 'เลขลำดับ/หมายเลขประจำตัว' โดยอัตโนมัติและ **ไม่ต้องเติม 第** เลย! ได้แก่: · ชั้นอาคาร: 一楼 (ชั้น 1), 二楼 (ชั้น 2), 三楼 (ชั้น 3) · ห้องเรียน/รุ่น: 一班 (ห้อง 1), 二班 (ห้อง 2) · เดือนและวันที่: 二月 (กุมภาพันธ์), 八号 (วันที่ 8) · สายรถเมล์/หมายเลข: 二路公交车 (รถเมล์สาย 2) · กฎเหล็กเด็ดขาดที่คนไทยพลาดบ่อยสุด ๆ: (1) เมื่อเป็นเลขลำดับหมายเลข 2 แบบนี้ **บังคับใช้ 二 เสมอ ห้ามใช้ 两 เด็ดขาด!!** (二楼 = ชั้น 2 ✓ vs 两层楼 = อาคารสูง 2 ชั้น; 二班 = ห้อง 2 ✓ vs 两个班 = สองห้องเรียน) (2) ห้ามเติม 第 เข้าไปหน้าคำกลุ่มนี้โดยไม่จำเป็น (พูด 二楼 ไม่ใช่ 第二楼)","Beyond 第 + Number (HSK 1), Chinese routinely forms everyday ordinals/identifiers WITHOUT 第: · Floors: 一楼 (1st floor), 二楼 (2nd floor); · Classes: 一班 (Class 1), 二班 (Class 2); · Calendar: 二月 (Feb), 八号 (the 8th); · Bus routes: 二路公交车 (Bus #2). · Iron rule for '2': ALWAYS use **二** — NEVER **两** — for ordinals/labels! (二楼 '2nd floor', 二班 'Class 2', 二月 'February' — whereas 两个班 means 'two classes' quantity!).","除“第＋数词”外，汉语许多固定领域直接用“数词＋量词／名词”表示序数编号，不加“第”：二楼、二班、二月、八号、二路公交车。 · 铁律：表示编号序数的“2”一律用“二”，绝不能用“两”（二楼＝第2层，二班＝第2班；表数量才用“两个班”）。","Ngoài 第 + số, tiếng Trung có nhiều trường hợp dùng thẳng 'Số + đơn vị' chỉ thứ tự KHÔNG cần 第: 二楼 (tầng 2), 二班 (lớp 2), 二月 (tháng 2), 二路公交车 (xe buýt số 2). · Quy tắc thép: số 2 chỉ số thứ tự/số hiệu LUÔN dùng **二**, tuyệt đối KHÔNG dùng 两 (二楼, 二班, 二月)!","「第」を付けずに「数詞＋単位」だけで序数・番号を表す定番分野：二楼（2階）、二班（2組）、二月（2月）、八号（8日）、二路公交车（2番バス）。 · 鉄則：番号・序数の「2」は必ず「二」を使い「两」は絶対不可（二楼・二班・二月）。数量を数えるときだけ「两个班」。"],"use":[{"ok":true,"zh":"教室在二楼，我们上去吧。","fix":"","py":"Jiàoshì zài èr lóu, wǒmen shàngqu ba.","tr":["ห้องเรียนอยู่ชั้นสอง พวกเราขึ้นไปกันเถอะ","The classroom is on the second floor; let's go up.","Phòng học ở tầng 2, chúng ta lên đi.","教室は2階にあります、上がりましょう。"],"h":["เลขชั้น (二楼) และเลขห้องเรียน (二班) ใช้ 二 ไม่ใส่ 第 และไม่ใช้ 两","Floors (二楼) and classes (二班) use 二 — no 第 and never 两","楼层、班级编号直接用“二楼、二班”，不用“两”也不用“第”","Số tầng (二楼) và số lớp (二班) dùng 二, không dùng 两 hay 第","階数（二楼）・クラス番号（二班）は「第」不要で必ず「二」"],"w":["ทำได้และเป็นมาตรฐานของจีน 100%: 二楼 (ชั้น 2), 三楼 (ชั้น 3), 二班 (ห้อง 2), 三班 (ห้อง 3)","Works 100% natively: 二楼 (2nd floor), 三楼 (3rd floor), 二班 (Class 2), 三班 (Class 3).","“二楼、二班、二月”均为固定序数表达，直接用“二”。","Đúng 100% chuẩn tiếng Trung: 二楼, 三楼, 二班, 三班.","「二楼」「二班」「二月」は番号・序数の定番表現で必ず「二」。"],"ref":"กลุ่มเทียบคำ g9 · HSK 3.0 g3-2-075"},{"ok":true,"zh":"我们高中二班有三十名学生。","fix":"","py":"Wǒmen gāozhōng èr bān yǒu sānshí míng xuésheng.","tr":["ห้อง ม.ปลาย 2 ของพวกเรามีนักเรียนสามสิบคน","Our high school Class 2 has thirty students.","Lớp 2 cấp ba của chúng tôi có 30 học sinh.","私たちの高校の2組には30名の生徒がいます。"],"h":["แยกให้ขาด: 二班 (ห้อง 2 = ลำดับ) vs 两个班 (สองห้อง = จำนวน)","Contrast 二班 ('Class 2' = ordinal) vs 两个班 ('two classes' = quantity)","区分序数“二班”与数量“两个班”","Phân biệt 二班 (lớp số 2) với 两个班 (hai lớp học)","序数「二班」（2組）と数量「两个班」（2クラス）の区別"],"w":["ทำได้ชัดเจนมาก เพราะ 二班 ชี้เฉพาะ 'ห้องหมายเลข 2' (ไม่ใส่ 个 และใช้ 二) ต่างจาก 两个班 ที่นับจำนวนว่ามีทั้งหมด 2 ห้อง","Works with crystal clarity: 二班 labels 'Class #2' (no 个, uses 二), whereas 两个班 counts 'two classes'.","“二班”指编号第二的班（用“二”无“个”）；“两个班”指班的数量。","Đúng và rõ ràng: 二班 là tên lớp số 2, còn 两个班 là đếm số lượng 2 lớp.","「二班」は2番のクラス、「两个班」はクラスの数（2つ）と明確に分かれる。"],"ref":"HSK 3.0 g3-2-075"},{"ok":false,"zh":"洗手间在两楼。","fix":"洗手间在二楼。","py":"Xǐshǒujiān zài èr lóu.","tr":["ห้องน้ำอยู่ชั้นสอง","The restroom is on the second floor.","Nhà vệ sinh ở tầng 2.","トイレは2階にあります。"],"h":["ห้ามพูด 两楼 / 两班 / 两月 สำหรับเลขลำดับที่ 2!","NEVER say 两楼 / 两班 / 两月 for ordinal #2!","楼层、班级、月份序数绝不能用“两”，必须用“二”","TUYỆT ĐỐI không nói 两楼 / 两班 / 两月 — phải dùng 二!","階数・クラス・月の2番目に「两」は絶対不可（必ず「二」）"],"w":["ไม่ได้ เพราะชั้น 2 (二楼), ห้อง 2 (二班), เดือน 2 (二月), วันที่ 2 (二号) ล้วนเป็น 'หมายเลขลำดับ' ที่บังคับใช้ 二 เท่านั้น","Wrong because 2nd floor (二楼), Class 2 (二班), February (二月), and the 2nd (二号) are all ordinals requiring 二.","不行，表编号序数的2必须用“二”：二楼、二班、二月、二号。","Không được vì tầng 2 (二楼), lớp 2 (二班), tháng 2 (二月) đều là số thứ tự bắt buộc dùng 二.","階・クラス・月・日付の2はすべて序数・番号なので必ず「二」を使う。"],"ref":"กลุ่มเทียบคำ g9 · HSK 3.0 g3-2-075"}],"ex":[["教室在二楼，我们上去吧。","Jiàoshì zài èr lóu, wǒmen shàngqu ba.","ห้องเรียนอยู่ชั้นสอง พวกเราขึ้นไปกันเถอะ","The classroom is on the second floor; let's go up.","Phòng học ở tầng 2, chúng ta lên đi.","教室は2階です、上がりましょう。","二楼"],["洗手间在一楼右边。","Xǐshǒujiān zài yī lóu yòubian.","ห้องน้ำอยู่ทางขวาของชั้นหนึ่ง","The restroom is on the right on the first floor.","Nhà vệ sinh ở bên phải tầng 1.","トイレは1階の右側にあります。","一楼"],["我在高中二班学习。","Wǒ zài gāozhōng èr bān xuéxí.","ฉันเรียนอยู่ชั้น ม.ปลาย ห้อง 2","I study in high school Class 2.","Tôi học ở lớp 2 cấp ba.","私は高校の2組で勉強しています。","二班"],["二月天很冷。","Èr yuè tiān hěn lěng.","เดือนกุมภาพันธ์อากาศหนาวมาก","The weather is very cold in February.","Tháng Hai trời rất lạnh.","2月はとても寒いです。","二月"],["我坐二路公交车去学校。","Wǒ zuò èr lù gōngjiāochē qù xuéxiào.","ฉันนั่งรถเมล์สาย 2 ไปโรงเรียน","I take Bus No. 2 to school.","Tôi đi xe buýt tuyến số 2 đến trường.","2番バスで学校へ行きます。","二路"]],"err":[["洗手间在两楼。","洗手间在二楼。","ชั้น 2 / ห้อง 2 / เดือน 2 เป็นเลขลำดับ ใช้ 二 เสมอ ห้ามใช้ 两","Ordinal #2 (二楼 / 二班 / 二月) ALWAYS uses 二, never 两.","序数编号“二楼、二班、二月”一律用“二”，不用“两”。","Thứ tự số 2 (二楼 / 二班 / 二月) luôn dùng 二, không dùng 两.","序数番号の2（二楼・二班・二月）は常に「二」で「两」は不可。"]],"rel":["g3-1-068","g3-1-011","g3-1-069"]},"g3-2-076":{"t":["วิธีบอกจำนวนโดยประมาณ 1 (概数1): ใช้ 几 บอกจำนวนคร่าว ๆ (ไม่กี่ / สิบกว่า)","Approximate numbers 1 (概数1): using 几 ('several / a few / -teen')","特殊表达法·概数表达法1（1）：用“几”表示概数","Số ước lượng 1 (概数1): dùng 几 ('vài / mười mấy')","概数の表し方1（概数1）：「几」で「数〜・十数〜」"],"f":["几 + 量词 + 名词（几天 / 几个人 / 几本书 = 2–9 概数）","十几 / 二十几 + 量词（十几个苹果 / 二十几岁 = 11–19 / 21–29）"],"why":["นอกจากใช้ถาม ('กี่…?') แล้ว ในประโยคบอกเล่า **几** ยังใช้บอก 'จำนวนโดยประมาณที่ไม่เกิน 10' (ราว 2–9) แปลว่า 'ไม่กี่… / สองสาม…' เช่น 我买了几个苹果 (ฉันซื้อแอปเปิลมาไม่กี่ลูก), 我在北京住了几天 (ฉันอยู่ปักกิ่งสองสามวัน) · และเมื่อวางหลังเลขหลักสิบ (**十几 / 二十几 / 三十几**) แปลว่า 'สิบกว่า / ยี่สิบกว่า / สามสิบกว่า' (เช่น 二十几岁 = อายุยี่สิบกว่าปี, 十几块钱 = สิบกว่าหยวน) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) 几 + คำนามทั่วไปต้องมี **ลักษณนาม** คั่นเสมอ (几个人 ✓ ห้ามพูด 几人 ✗!) ยกเว้น 天/年/岁 (几天, 几年) (2) 几 ที่วาง 'หน้า' 十 (几十 = หลายสิบ, เช่น 几十个人 = คนหลายสิบคน) ต่างจาก 几 ที่วาง 'หลัง' 十 (十几 = สิบกว่า, 11–19) อย่าสลับตำแหน่งกัน!","Beyond questions ('how many?'), **几** in statements expresses an approximate small number ('several / a few', roughly 2–9): 几个苹果, 几天. · Placed after tens (**十几 / 二十几**), it means 'ten-odd / twenty-something' (十几块钱, 二十几岁). · Two key cautions: (1) Always include a measure word before ordinary nouns (几个人 ✓, except self-measuring 几天/几年). (2) Watch the huge difference in order: **十几** = 11–19 ('a dozen+'), while **几十** = 20–99 ('dozens of')!","“几”在陈述句中表示 10 以内的不确定概数（相当于“几个／若干”）：几个苹果、几天；置于整十数后表十几、二十几（十几块钱、二十几岁）。 · 两条注意：（1）修饰一般名词须加量词（几个人）；（2）严格区分“十几”（11～19）与“几十”（20～99，几十个人）。","Trong câu trần thuật, **几** chỉ số ước lượng dưới 10 ('vài': 几个苹果, 几天); đặt sau hàng chục là 'mười mấy / hai mươi mấy' (十几块钱, 二十几岁). · 2 lưu ý: (1) Cần lượng từ trước danh từ thường (几个人); (2) Phân biệt rõ **十几** (11–19) với **几十** (vài chục: 20–99)!","平叙文の「几」は10未満の概数「数〜・いくつか」（几个苹果・几天）、十の位の後では「十数〜・二十数〜」（十几块钱・二十几岁）。 · 注意：（1）一般名詞の前に量詞が必要（几个人）。（2）「十几」（11〜19）と「几十」（数十・20〜99）の語順の違いに注意！"],"use":[{"ok":true,"zh":"我在北京住了几天。","fix":"","py":"Wǒ zài Běijīng zhùle jǐ tiān.","tr":["ฉันอยู่ปักกิ่งสองสามวัน (ไม่กี่วัน)","I stayed in Beijing for a few days.","Tôi ở Bắc Kinh vài ngày.","北京に数日滞在しました。"],"h":["บอกจำนวนไม่กี่วัน/ไม่กี่คนในประโยคบอกเล่า ใช้ 几 (+ ลักษณนาม) และจบด้วยจุด 。","Use 几 (+ CL) in a statement for 'a few / several', ending with 。","陈述句用“几＋量词”表少数概数（几天、几本书）","Câu trần thuật dùng 几 + lượng từ chỉ 'vài' (几天, 几本书)","平叙文で「几＋量詞」＝「数〜・いくつか」（几天・几本书）"],"w":["ทำได้เพราะประโยคนี้ไม่ได้ถามว่ากี่วัน แต่บอกเล่าคร่าว ๆ ว่าพักอยู่ประมาณ 2–5 วัน (สังเกตจบด้วยจุด 。 ไม่ใช่ ？)","Works clearly as a statement ('a few days', ending in 。) rather than a question ('how many days?').","句末用句号表陈述，“几天”指不确切的两三天到五六天。","Đúng vì câu kể kết thúc bằng dấu chấm 。, 几天 nghĩa là 'vài ngày'.","文末が「。」の平叙文なので疑問ではなく「数日間」という概数を表す。"],"ref":"HSK 3.0 g3-2-076"},{"ok":true,"zh":"教室里有几十个学生。","fix":"","py":"Jiàoshì lǐ yǒu jǐshí ge xuésheng.","tr":["ในห้องเรียนมีนักเรียนหลายสิบคน","There are dozens of students in the classroom.","Trong lớp có mấy chục học sinh.","教室に数十人の学生がいます。"],"h":["แยกความต่าง: 几十 = หลายสิบ (20–99) vs 十几 = สิบกว่า (11–19)","Contrast 几十 ('dozens / tens of', 20–99) vs 十几 ('a dozen+', 11–19)","区分“几十”（20～99）与“十几”（11～19）","Phân biệt 几十 (vài chục) với 十几 (mười mấy)","「几十」（数十）と「十几」（十数）の違い"],"w":["ทำได้เพราะวาง 几 ไว้ 'หน้า' 十 (几十 = กี่สิบ → หลายสิบคน) ถ้าวางหลัง 十 เป็น 十几个学生 จะลดลงเหลือแค่ 11–19 คน!","Works accurately: 几 BEFORE 十 (几十) means 20–99 ('dozens'), whereas 几 AFTER 十 (十几) means only 11–19!","“几”在“十”前表几十（数十）；在“十”后表十几（十几个人）。","Đúng: 几 đứng trước 十 là 'mấy chục' (20–99), đứng sau 十 là 'mười mấy' (11–19).","「几」が「十」の前なら数十（20〜99）、後ろなら十数（11〜19）と数が大きく変わる。"],"ref":"HSK 3.0 g3-2-076"},{"ok":false,"zh":"我买了几个书。","fix":"我买了几本书。","py":"Wǒ mǎile jǐ běn shū.","tr":["ฉันซื้อหนังสือมาสองสามเล่ม","I bought a few books.","Tôi mua vài cuốn sách.","本を数冊買いました。"],"h":["หลัง 几 ต้องใช้ลักษณนามให้ตรงชนิดคำนามด้วย (几本书 ไม่ใช่ 几个书)","Match the right measure word after 几 (几本书, not 几个书)","“几”后仍须搭配正确量词（几本书、几条鱼）","Sau 几 vẫn phải chọn đúng lượng từ (几本书, không phải 几个书)","「几」の後も名詞に合った正しい量詞を使う（几本书）"],"w":["ไม่ได้ เพราะแม้ 几 จะเป็นจำนวนโดยประมาณ แต่กฎลักษณนามยังเหมือนตัวเลขปกติทุกประการ (หนังสือใช้ 本, เสื้อใช้ 件, กางเกงใช้ 条)","Wrong because approximate 几 still requires the noun's proper classifier: 几本书, 几件衣服, 几条裤子.","不行，概数“几”与名词间同样须配专用量词：几本书。","Không được vì 几 vẫn cần đúng lượng từ riêng của danh từ: 几本书.","概数の「几」でも名詞の専用量詞（本・件・条）を正しく選ぶ必要がある。"],"ref":"HSK 3.0 g3-2-076 · g3-1-012"}],"ex":[["我在北京住了几天。","Wǒ zài Běijīng zhùle jǐ tiān.","ฉันอยู่ปักกิ่งสองสามวัน","I stayed in Beijing for a few days.","Tôi đã ở Bắc Kinh vài ngày.","北京に数日滞在しました。","几天"],["我买了几本有意思的书。","Wǒ mǎile jǐ běn yǒuyìsi de shū.","ฉันซื้อหนังสือที่น่าสนใจมาสองสามเล่ม","I bought a few interesting books.","Tôi mua vài cuốn sách thú vị.","面白い本を数冊買いました。","几本"],["这杯奶茶十几块钱。","Zhè bēi nǎichá shíjǐ kuài qián.","ชานมแก้วนี้สิบกว่าหยวน","This cup of milk tea costs ten-odd yuan.","Cốc trà sữa này mười mấy tệ.","このミルクティーは十数元です。","十几"],["他今年二十几岁。","Tā jīnnián èrshíjǐ suì.","ปีนี้เขาอายุยี่สิบกว่าปี","He is in his twenties this year.","Năm nay anh ấy ngoài hai mươi tuổi.","彼は今年20代です。","二十几"],["教室里有几十个学生。","Jiàoshì lǐ yǒu jǐshí ge xuésheng.","ในห้องเรียนมีนักเรียนหลายสิบคน","There are dozens of students in the classroom.","Trong lớp có mấy chục học sinh.","教室に数十人の学生がいます。","几十"]],"err":[["我买了几个书。","我买了几本书。","หลัง 几 ต้องใช้ลักษณนามให้ตรงคำนาม (几本书)","Use the proper measure word after 几 (几本书).","“几”后搭配正确量词（几本书）。","Dùng đúng lượng từ sau 几 (几本书).","「几」の後ろも正しい量詞を使う（几本书）。"]],"rel":["g3-2-077","g3-2-078","g3-1-008"]},"g3-2-077":{"t":["วิธีบอกจำนวนโดยประมาณ 2 (概数2): ตัวเลขลงท้ายศูนย์ + 多 + ลักษณนาม","Approximate numbers 2 (概数2): Round Ten/Hundred + 多 + Measure Word","特殊表达法·概数表达法1（2）：数词+多+量词","Số ước lượng 2 (概数2): Số tròn chục/trăm + 多 + Lượng từ","概数の表し方2（概数2）：十の倍数以上＋多＋量詞"],"f":["整十 / 整百 / 整千 + 多 + 量词 + 名词（十多个人 / 二十多块钱 / 一百多本书）"],"why":["โครงสร้าง **数词 + 多 + 量词** ('…กว่า') ใช้เมื่อตัวเลขเป็น **เลขกลมที่ลงท้ายด้วย 0** เช่น 十 (10), 二十 (20), 三十 (30), 一百 (100), 一千 (1,000), 一万 (10,000) เท่านั้น! · ความหมาย: 十多个人 = 11–19 คน, 三十多岁 = 31–39 ปี, 一百多本书 = 101–199 เล่ม · กฎเหล็กที่ต้องจำคู่กับบทถัดไป (`g3-2-078`) ให้ขึ้นใจ: **ลงท้าย 0 → 多 อยู่ 'หน้า' ลักษณนาม** (`十多个人`, `二十多块钱`, `三十多岁`) · **ห้ามใช้กับเลข 1–9!** (ห้ามพูด 五多个人 หรือ 三多本书 เด็ดขาด!)","The pattern **Number + 多 + Measure Word** ('more than / over…') is used **ONLY after round numbers ending in 0** (十, 二十, 三十, 一百, 一千, 一万)! · Examples: 十多个人 (11–19 people), 三十多岁 (31–39 years old), 一百多本书 (101–199 books). · Golden contrast with the next lesson (`g3-2-078`): **Ends in 0 → 多 goes BEFORE the measure word!** NEVER put 多 before a measure word after 1–9 (never 五多个人!).","“数词＋多＋量词”只用于个位为 0 的整数（十、二十、三十、一百、一千、一万等）：十多个人（11～19）、三十多岁（31～39）、一百多本书（101～199）。 · 铁律：末尾是 0，“多”放量词前面；1～9 绝不能用此格式（不说“五多个人”）。","Mẫu **Số + 多 + Lượng từ** ('hơn…') CHỈ dùng sau số tròn có số 0 ở cuối (十, 二十, 三十, 一百, 一千, 一万): 十多个人 (11–19 người), 三十多岁 (31–39 tuổi), 一百多本书. · Quy tắc thép: kết bằng 0 → 多 đứng TRƯỚC lượng từ; KHÔNG dùng cho số 1–9 (không nói 五多个人!).","「数詞＋多＋量詞」（〜余り）は一の位が0のキリのいい数（十・二十・三十・一百・一千・一万）専用！ · 例：十多个人（11〜19人）、三十多岁（31〜39歳）、一百多本书（101〜199冊）。 · 鉄則：0で終わる数なら「多」は量詞の前。1〜9では絶対不可（五多个人×）。"],"use":[{"ok":true,"zh":"我们班有三十多名学生。","fix":"","py":"Wǒmen bān yǒu sānshí duō míng xuésheng.","tr":["ห้องพวกเรามีนักเรียนสามสิบกว่าคน","Our class has over thirty students.","Lớp chúng tôi có hơn 30 học sinh.","私たちのクラスには30人余りの学生がいます。"],"h":["เลขลงท้าย 0 (十 / 二十 / 三十 / 一百) วาง 多 ไว้ 'หน้า' ลักษณนาม","After round tens/hundreds (十/二十/三十/一百), put 多 BEFORE the measure word","整十／整百数后“多”放量词前：三十多名／十多个","Sau số tròn chục/trăm đặt 多 TRƯỚC lượng từ (三十多名)","十の倍数・百の倍数の後は「多」を量詞の前に置く（三十多名）"],"w":["ทำได้และถูกต้อง 100% เพราะ 三十 ลงท้ายด้วย 0 จึงวาง 多 หน้าลักษณนาม 名 เพื่อบอกว่ามีประมาณ 31–39 คน","Works 100% accurately because 三十 ends in 0, placing 多 before 名 to mean roughly 31–39 students.","“三十”为整十数，“多”放在量词“名”前面，表 31～39 人。","Đúng 100% vì 三十 là số tròn chục nên 多 đứng trước lượng từ 名.","「三十」は0で終わるため量詞「名」の前に「多」を置き31〜39人を表す。"],"ref":"HSK 3.0 g3-2-077"},{"ok":true,"zh":"王老师今年四十多岁了。","fix":"","py":"Wáng lǎoshī jīnnián sìshí duō suì le.","tr":["ปีนี้อาจารย์หวังอายุสี่สิบกว่าปีแล้ว","Teacher Wang is in his/her forties this year.","Năm nay thầy Vương hơn 40 tuổi rồi.","王先生は今年40代です。"],"h":["บอกอายุหลักสิบขึ้นไปใช้ 二十多岁 / 三十多岁 / 四十多岁","Express approximate age in tens with 二十多岁 / 三十多岁 / 四十多岁","估算十几岁以上年龄用“二十多岁／四十多岁”","Ước lượng tuổi tròn chục dùng 二十多岁 / 四十多岁","年代の概数は「二十多岁・四十多岁」"],"w":["ทำได้และสุภาพเป็นธรรมชาติมาก เพราะ 岁 เป็นลักษณนามเวลาในตัวจึงวาง 多 หน้า 岁 ได้ทันที (四十多岁 = 41–49 ปี)","Works cleanly because self-measuring 岁 follows 多 directly (四十多岁 = 41–49 years old).","“岁”本身作量词，“四十多岁”即 41～49 岁，自然地道。","Đúng vì 岁 tự là lượng từ nên 四十多岁 nghĩa là từ 41 đến 49 tuổi.","「岁」自体が量詞なので「四十多岁」で41〜49歳を自然に表せる。"],"ref":"HSK 3.0 g3-2-077"},{"ok":false,"zh":"我买了五多本书。","fix":"我买了十多本书。","py":"Wǒ mǎile shí duō běn shū.","tr":["ฉันซื้อหนังสือมาสิบกว่าเล่ม","I bought over ten books.","Tôi đã mua hơn mười cuốn sách.","本を十数冊買いました。"],"h":["ห้ามใช้ เลข 1–9 + 多 + ลักษณนาม (五多本书 ผิด 100%!)","NEVER put 多 before a measure word after 1–9 (五多本书 is 100% wrong!)","1～9 后面绝不能接“多＋量词”（五多本书×）","TUYỆT ĐỐI không dùng số 1–9 + 多 + lượng từ (五多本书×)","1〜9の後ろに「多＋量詞」は絶対不可（五多本书×）"],"w":["ไม่ได้ เพราะ 五 เป็นเลขหลักเดียว (1–9) ที่ไม่ลงท้ายด้วย 0 และหนังสือเป็นชิ้นนับเต็มเล่ม (ไม่มี 5.3 เล่ม) จึงห้ามวาง 多 หน้า 本! ต้องเป็นเลขหลักสิบขึ้นไปอย่าง 十多本书 (หรือถ้าประมาณ 5 เล่มพูด 五六本书)","Wrong because 5 doesn't end in 0 and books aren't fractional! Use round tens for 多+CL (十多本书), or adjacent numbers (五六本书) for ~5.","不行，“五”不是整十数，绝不能说“五多本”；整十数才说“十多本”，约五本说“五六本”。","Không được vì 五 không tròn chục; tròn chục mới dùng 十多本, còn khoảng 5 cuốn nói 五六本.","「五」は0で終わらないため不可。十の倍数以上なら「十多本」、5冊前後なら「五六本」と言う。"],"ref":"HSK 3.0 g3-2-077 · g3-2-078"}],"ex":[["我们班有三十多名学生。","Wǒmen bān yǒu sānshí duō míng xuésheng.","ห้องพวกเรามีนักเรียนสามสิบกว่าคน","Our class has over thirty students.","Lớp chúng tôi có hơn 30 học sinh.","私たちのクラスには30人余りの学生がいます。","三十多"],["王老师今年四十多岁了。","Wáng lǎoshī jīnnián sìshí duō suì le.","ปีนี้อาจารย์หวังอายุสี่สิบกว่าปีแล้ว","Teacher Wang is over forty this year.","Năm nay thầy Vương hơn 40 tuổi rồi.","王先生は今年40代です。","四十多"],["这里有一百多本书。","Zhèlǐ yǒu yībǎi duō běn shū.","ที่นี่มีหนังสือร้อยกว่าเล่ม","There are over a hundred books here.","Ở đây có hơn một trăm cuốn sách.","ここには100冊余りの本があります。","一百多"],["这件衣服八十多块钱。","Zhè jiàn yīfu bāshí duō kuài qián.","เสื้อตัวนี้แปดสิบกว่าหยวน","This shirt costs over eighty yuan.","Chiếc áo này hơn 80 tệ.","この服は80元余りです。","八十多"],["我等了二十多分钟了。","Wǒ děngle èrshí duō fēnzhōng le.","ฉันรอมาตั้งยี่สิบกว่านาทีแล้ว","I've been waiting for over twenty minutes.","Tôi đã đợi hơn 20 phút rồi.","もう20分余り待っています。","二十多"]],"err":[["我买了五多本书。","我买了十多本书。","โครงสร้าง ตัวเลข + 多 + ลักษณนาม ใช้ได้เฉพาะเลขลงท้าย 0 (十/二十/一百)","Number + 多 + Measure Word ONLY works after round numbers ending in 0 (十/二十/一百).","“数词＋多＋量词”仅限整十、整百数（十多本）。","Số + 多 + Lượng từ chỉ dùng với số tròn chục/trăm (十多本).","「数詞＋多＋量詞」は十・百の倍数専用（十多本）。"]],"rel":["g3-2-078","g3-2-076","g3-2-010"]},"g3-2-078":{"t":["วิธีบอกจำนวนโดยประมาณ 3 (概数3): ตัวเลข + ลักษณนาม + 多 (เศษของหน่วย)","Approximate numbers 3 (概数3): Number + Measure Word + 多 (fractional 'plus')","特殊表达法·概数表达法1（3）：数词+量词+多","Số ước lượng 3 (概数3): Số từ + Lượng từ + 多 (số lẻ vượt đơn vị)","概数の表し方3（概数3）：数詞＋量詞＋多（端数あり）"],"f":["数词（1–9 或非整十）+ 可分量词 + 多（两年多 / 三个多小时 / 五块多 / 十点多）"],"why":["โครงสร้าง **数词 + 量词 + 多** แปลว่า '…กว่า (มีเศษไม่ถึง 1 หน่วยถัดไป)' ใช้กับเลข 1–9 (หรือเลขที่ไม่ลงท้าย 0 อย่าง 十二) และใช้ได้เฉพาะกับ **หน่วยที่แบ่งเป็นเศษทศนิยมได้** เท่านั้น! เช่น เวลา (两年多 = สองปีกว่า, 三个多小时 = สามชั่วโมงกว่า, 十点多 = สิบโมงกว่า), เงิน (五块多 = ห้าหยวนกว่า), เดือน (两个多月 = สองเดือนกว่า) · กฎเหล็กเด็ดขาด 2 ข้อที่ออกสอบบ่อยที่สุดใน HSK 2: (1) สังเกตตำแหน่งในคำที่มี 个: **三个多小时 / 两个多月** (วาง 多 ไว้หลัง 个 หน้าคำนาม 小时/月!) (2) ห้ามใช้โครงสร้างนี้กับสิ่งที่แบ่งเศษไม่ได้! (เช่น คน/หนังสือ/เก้าอี้ — ห้ามพูด 两个人多 หรือ 三本书多 เพราะไม่มีคนครึ่งคน!)","The pattern **Number + Measure Word + 多** means 'just over [N] units' (less than +1 full unit) and works ONLY with **divisible/continuous units** like time and money: 两年多 ('2+ years'), 三个多小时 ('3+ hours'), 两个多月 ('2+ months'), 五块多 ('5+ yuan'), 十点多 ('past 10 o'clock'). · Two top HSK 2 exam rules: (1) With 个 + noun, put 多 RIGHT AFTER 个: **三个多小时**, **两个多月**! (2) NEVER use this with indivisible items (NEVER 两个人多 or 三本书多 — you can't have 2.5 people!).","“数词＋量词＋多”表示超出该数字但不足下一个整数单位的零头，仅限可分割连续计量单位（时间、货币等）：两年多、三个多小时、两个多月、五块多、十点多。 · 两条必考铁律：（1）“小时、月、星期”带“个”时，“多”放“个”后：三个多小时、两个多月；（2）不可分割的个体绝不能用此格式（不说“两个人多”“三本书多”）。","Mẫu **Số + Lượng từ + 多** chỉ phần lẻ vượt qua mốc (chưa tới đơn vị kế tiếp), CHỈ dùng cho đơn vị chia lẻ được như thời gian, tiền bạc: 两年多 (hơn 2 năm), 三个多小时 (hơn 3 tiếng), 五块多 (hơn 5 tệ), 十点多 (hơn 10 giờ). · 2 quy tắc vàng: (1) Với 小时/月/星期 đặt 多 SAU 个: **三个多小时**, **两个多月**; (2) KHÔNG dùng cho vật không chia lẻ được (không nói 两个人多!).","「数詞＋量詞＋多」は次の整数に満たない端数「〜余り」を表し、時間・金額など分割できる単位専用：两年多（2年余り）、三个多小时（3時間余り）、两个多月（2か月余り）、五块多（5元余り）、十点多（10時過ぎ）。 · 鉄則：（1）「小时・月・星期」は「个」の後ろに「多」（三个多小时）。（2）分割できない人や本には不可（两个人多×）。"],"use":[{"ok":true,"zh":"我坐火车坐了三个多小时。","fix":"","py":"Wǒ zuò huǒchē zuòle sān ge duō xiǎoshí.","tr":["ฉันนั่งรถไฟไปสามชั่วโมงกว่า","I rode the train for over three hours.","Tôi ngồi tàu hỏa hơn ba tiếng đồng hồ.","電車に3時間余り乗りました。"],"h":["ชั่วโมง / เดือน / สัปดาห์: ตัวเลข + 个 + 多 + 小时 / 月 / 星期","Hours / months / weeks: Number + 个 + 多 + 小时 / 月 / 星期","“小时、月、星期”把“多”放“个”后（三个多小时、两个多月）","Giờ / tháng / tuần đặt 多 SAU 个 (三个多小时, 两个多月)","時間・月・週は「个」の後ろに「多」（三个多小时・两个多月）"],"w":["ทำได้และแม่นยำ 100% เพราะ 个 คือลักษณนาม จึงวาง 多 ไว้หลัง 个 และหน้าคำนาม 小时 เป็น 三个多小时 (ไม่ใช่ 三多个小时 หรือ 三个小时多!)","Works 100% accurately because 个 is the measure word, so 多 goes right after 个 before 小时: 三个多小时.","“个”是量词，“多”紧跟在量词“个”后面、名词“小时”前面：三个多小时。","Đúng 100% vì 个 là lượng từ nên 多 đứng ngay sau 个, trước 小时.","「个」が量詞なので、その直後・名詞「小时」の前に「多」を置く（三个多小时）。"],"ref":"HSK 3.0 g3-2-078"},{"ok":true,"zh":"这包红茶五块多钱。","fix":"","py":"Zhè bāo hóngchá wǔ kuài duō qián.","tr":["ชาแดงห่อนี้ราคาห้าหยวนกว่า","This pack of black tea costs a bit over five yuan.","Gói hồng trà này giá hơn năm tệ.","この紅茶のパックは5元余りです。"],"h":["ราคา 1–9 หยวนกว่า วาง 多 หลัง 块 (五块多 / 五块多钱)","For 1–9+ yuan, put 多 right after 块 (五块多 / 五块多钱)","个位钱数“多”放“块”后（五块多／五块多钱）","Giá 1–9 tệ hơn đặt 多 SAU 块 (五块多钱)","1〜9元余りは「块」の後ろに「多」（五块多钱）"],"w":["ทำได้เพราะเงินหยวนมีเศษเหมา/เฟินแบ่งย่อยได้ (เช่น 5.20 หยวน) จึงวาง 多 หลัง 块 เป็น 五块多钱 (ต่างจาก 50 กว่าหยวนที่วางหน้า 块 เป็น 五十多块钱!)","Works cleanly because yuan splits into fractional amounts (e.g., 5.20), so 五块多钱 (vs 50+ yuan: 五十多块钱!).","5元多有角分零头（5.1～5.9元），“多”在“块”后；区别于“五十多块钱”（51～59元）。","Đúng vì tiền có số lẻ hào/xu nên 多 sau 块: 五块多钱 (khác 五十多块钱 = 51–59 tệ).","5.1〜5.9元は「五块多钱」、51〜59元は「五十多块钱」と明確に使い分ける。"],"ref":"HSK 3.0 g3-2-078 · g3-2-077"},{"ok":false,"zh":"我等了三多个小时。","fix":"我等了三个多小时。","py":"Wǒ děngle sān ge duō xiǎoshí.","tr":["ฉันรอไปสามชั่วโมงกว่า","I waited for over three hours.","Tôi đã đợi hơn ba tiếng đồng hồ.","3時間余り待ちました。"],"h":["เลข 1–9 หน้า 个小时 / 个月 ห้ามวาง 多 หน้า 个! (ต้องเป็น 三个多小时)","For 1–9 hours/months, NEVER put 多 before 个 — ALWAYS 三个多小时!","1～9小时／月绝不能说“三多个小时”，必须说“三个多小时”","Với 1–9 tiếng/tháng KHÔNG nói 三多个小时 — phải nói 三个多小时!","1〜9時間／か月で「三多个小时」は不可、必ず「三个多小时」"],"w":["ไม่ได้ เพราะ 三 เป็นเลข 1–9 (ไม่ลงท้าย 0) จึงต้องวาง 多 หลังลักษณนาม 个 เสมอ: 三个多小时, 两个多月, 两个多星期","Wrong because 3 doesn't end in 0 — 多 MUST follow measure word 个: 三个多小时, 两个多月.","不行，“三”不是整十数，“多”必须放在量词“个”后面：三个多小时。","Không được vì 三 không tròn chục nên 多 bắt buộc đặt SAU 个: 三个多小时.","「三」は0で終わらないため、量詞「个」の後ろに「多」を置き「三个多小时」にする。"],"ref":"HSK 3.0 g3-2-078"},{"ok":false,"zh":"教室里有两个人多。","fix":"教室里有十多个人。","py":"Jiàoshì lǐ yǒu shí duō ge rén.","tr":["ในห้องเรียนมีคนสิบกว่าคน","There are over ten people in the classroom.","Trong phòng học có hơn mười người.","教室には十数人の人がいます。"],"h":["ห้ามใช้ ตัวเลข + ลักษณนาม + 多 กับสิ่งของ/คนที่แบ่งเป็นเศษไม่ได้!","NEVER use Number + CL + 多 with indivisible things/people (no 2.5 people!)","人、书等不可分割的个体绝不能说“两个人多／三本书多”","KHÔNG dùng Số + Lượng từ + 多 cho người/vật không thể chia lẻ!","分割できない人・本に「两个人多」は絶対不可"],"w":["ไม่ได้ เพราะคนแบ่งเป็น 2.5 คนไม่ได้! โครงสร้าง `ตัวเลข + ลักษณนาม + 多` ใช้ได้เฉพาะหน่วยที่แบ่งทศนิยมได้ (เช่น 两年多, 三个多小时, 五块多) เท่านั้น","Wrong because you can't have 2.5 people! Number + CL + 多 only applies to divisible units (两年多, 三个多小时, 五块多).","不行，人不能论小数（没有2.5个人），只有时间、金钱等可分单位才能用“数词＋量词＋多”。","Không được vì người không thể chia lẻ (không có 2,5 người)! Chỉ dùng cho thời gian, tiền bạc…","人は2.5人と分割できないため誤用。時間・金額など分割可能な単位専用。"],"ref":"HSK 3.0 g3-2-078"}],"ex":[["我在中国住了两年多。","Wǒ zài Zhōngguó zhùle liǎng nián duō.","ฉันอยู่ประเทศจีนมาสองปีกว่าแล้ว","I lived in China for over two years.","Tôi đã sống ở Trung Quốc hơn hai năm.","中国に2年余り住みました。","两年多"],["我坐火车坐了三个多小时。","Wǒ zuò huǒchē zuòle sān ge duō xiǎoshí.","ฉันนั่งรถไฟไปสามชั่วโมงกว่า","I rode the train for over three hours.","Tôi ngồi tàu hỏa hơn ba tiếng đồng hồ.","電車に3時間余り乗りました。","三个多小时"],["他来北京两个多月了。","Tā lái Běijīng liǎng ge duō yuè le.","เขามาปักกิ่งได้สองเดือนกว่าแล้ว","He has been in Beijing for over two months.","Anh ấy đến Bắc Kinh hơn hai tháng rồi.","彼は北京に来て2か月余りになります。","两个多月"],["这包红茶五块多钱。","Zhè bāo hóngchá wǔ kuài duō qián.","ชาแดงห่อนี้ราคาห้าหยวนกว่า","This pack of black tea costs a bit over five yuan.","Gói hồng trà này hơn năm tệ.","この紅茶は5元余りです。","五块多"],["现在已经十点多了，快睡吧。","Xiànzài yǐjīng shí diǎn duō le, kuài shuì ba.","ตอนนี้สิบโมง/สี่ทุ่มกว่าแล้ว รีบนอนเถอะ","It's already past ten o'clock — hurry and sleep.","Bây giờ đã hơn 10 giờ rồi, mau ngủ đi.","もう10時過ぎだよ、早く寝なさい。","十点多"]],"err":[["我等了三多个小时。","我等了三个多小时。","เลข 1–9 กับ 小时 / 月 ต้องวาง 多 หลัง 个 เสมอ (三个多小时)","For 1–9 hours/months, place 多 AFTER 个 (三个多小时).","1～9小时／月，“多”放在“个”后面（三个多小时）。","Với 1–9 tiếng/tháng, đặt 多 SAU 个 (三个多小时).","1〜9時間／か月は「个」の後ろに「多」（三个多小时）。"],["我住了两多年。","我住了两年多。","เลข 1–9 วาง 多 หลังหน่วยเวลา 年 เสมอ (两年多)","For 1–9 years, put 多 AFTER 年 (两年多).","个位数加“年”时，“多”放“年”后（两年多）。","Số 1–9 đặt 多 SAU 年 (两年多).","1〜9年は「年」の後ろに「多」（两年多）。"]],"rel":["g3-2-077","g3-2-076","g3-2-010"]}};
if(window.OFFY_ON_GBOOK_PACK)window.OFFY_ON_GBOOK_PACK(2);
